ClinicalChunks.register("data/templates-040.js",[{"id":"templates-cfe435e7925308d9e21b","key":"v1-c9ccc21dfe2a3058|templates-cfe435e7925308d9e21b","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"Paget病","category":"门诊病历模板","raw":{"name":"Paget病","category":"门诊病历模板","case":{"case_name":"门诊病历331","templates":{"主诉":"骨痛、骨畸形伴头颅增大5年","现病史":"患者（中老年，>50岁多见）于____年前渐出现骨痛（深部酸痛：负重骨/骨盆/颅骨/脊柱）、骨骼畸形（颅骨增大（帽围增大）、长骨弯曲（胫骨弓形：股骨：皮温升高：血管增多）、脊柱后凸）、头颅增大、听力下降（颅骨受累：听神经受压，传导性/感音性耳聋）、病理性骨折（畸形骨脆性增加），有无高输出性心力衰竭（广泛血管丰富病灶：血流增加：心排增加）、骨肉瘤变（病灶痛加剧、肿块、ALP急剧升高：<1%，需警惕）：____。有无家族史（遗传倾向）：____。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P72次/分，R18次/分，BP120/80mmHg。神志清楚。头颅增大、额部隆起，长骨（胫骨前弓、股骨）弯曲畸形、表面皮温升高（血管丰富）、压痛，脊柱后凸、驼背，身高变矮，听力粗测下降，心脏听诊呈高排状态（心界可增大、脉压增大）。","辅助检查":"【必做】血碱性磷酸酶（显著升高，骨转换活跃指标：监测疗效核心）、血钙磷（正常，区别于甲旁亢）、肝肾功能；【影像】X线（骨溶解与骨硬化并存：棉絮样骨、骨皮质增厚、颅骨地图颅、长骨弯曲）、骨扫描（核素，多灶浓聚，评估病变范围，敏感）、CT/MRI（特定部位：颅底/椎体压迫症状评估）；【其他】尿羟脯氨酸/骨吸收标志物（骨转换监测，必要时）、病理活检（疑肉瘤变）。","初步诊断":"1. 畸形性骨炎（Paget骨病，多骨性）\n（注：治疗指征为有症状骨痛、畸形、颅面受累、高钙尿或结石、准备手术（减少出血）、病灶位于负重或神经压迫部位；无症状低活动性者可观察并定期复查ALP；药物治疗（抑制骨转换，核心）：双膦酸盐（唑来膦酸5mg单次静滴，最有效，首选，注意首次输注流感样反应，需预处理；或口服阿仑膦酸钠40mg每日1次×6个月，需监测肾功能）、降钙素（二线）；监测：ALP（治疗后下降50%以上，3~6个月复查）、症状（骨痛缓解）、必要时骨扫描；双膦酸盐治疗期间补充钙剂及维生素D（防低钙）；并发症处理：听力下降予助听器、骨关节炎予镇痛（NSAIDs）、骨折予固定（Paget骨血供丰富，术前用双膦酸盐减少出血）；疑肉瘤变（疼痛加重、肿块、ALP骤升）行活检+影像（CT/MRI），预后差；由风湿科、内分泌科及骨科多学科随访。）","处理方案":"【药物治疗】\n1. 阿仑膦酸钠片（双膦酸盐类，抑制破骨细胞活性，Paget病首选治疗）70mg，每周1次，晨起空腹以200ml清水送服，服药后保持直立位至少30分钟并禁食30分钟，疗程至少6个月\n2. 碳酸钙D3片（基础补钙，配合双膦酸盐防治低钙血症）1片（含元素钙600mg）qd po；骨化三醇软胶囊0.25μg bid po（或维生素D3 800~1000IU qd），长期服用\n3. 布洛芬缓释胶囊（骨痛明显时短期镇痛）0.3g bid po，疼痛缓解后停用；老年或肾功能减退者改用对乙酰氨基酚片0.5g，必要时口服，间隔不少于6小时，每日不超过2g\n\n【一般治疗及生活指导】\n1. 避免患肢负重、剧烈运动及跌倒，降低病理性骨折风险；髋、膝、脊柱等承重骨受累者建议使用手杖或助行器，必要时佩戴支具保护，并加强下肢肌力训练\n2. 均衡饮食，保证每日钙摄入1000~1200mg及足量优质蛋白，戒烟、限酒；避免长期使用糖皮质激素等影响骨代谢的药物\n\n【随诊要求】\n双膦酸盐疗程结束后3~6个月复查血清碱性磷酸酶（ALP）、骨转换标志物（如PINP）及血钙、肾功能以评估疗效，ALP未降至正常或疗程后复升者需评估再次治疗；此后每1~2年复查病变部位X线或核素骨扫描观察病情进展；如出现新发或加重的骨痛、畸形加重、病理性骨折、神经受压表现（下肢麻木无力、感觉异常）或听力下降等，应随时复诊，并长期随访警惕恶性变可能。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":466,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"abad70445b66c0451014019a8c2dbea56780218b08cfda47ff4076a2d5aacd19","pinyin":"Pagetbing","initials":"Pb","setting":"out","caseName":"门诊病历331","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历331",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-a0b696b6a00f00330bb9","key":"v1-c9ccc21dfe2a3058|templates-a0b696b6a00f00330bb9","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"毛囊炎","category":"门诊病历模板","raw":{"name":"毛囊炎","category":"门诊病历模板","case":{"case_name":"门诊病历332","templates":{"主诉":"毛囊性丘疹、脓疱伴疼痛3天","现病史":"患者于5天前在头面颈部（毛发丰富部位）出现毛囊性红色小丘疹，渐变为脓疱（中央有毛发贯穿），伴轻度疼痛或瘙痒，有无糖尿病、长期外用糖皮质激素或免疫抑制、多汗、搔抓、不洁、摩擦、湿热及职业接触矿物油等易感因素：无上述易感因素，无发热，无全身不适。有无反复发作史：无反复发作史。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P72次/分，R18次/分，BP120/80mmHg。头面颈部可见散在毛囊性红色丘疹、脓疱（直径约0.2~0.5cm），中央有毛发穿过，周围红晕，脓疱未破溃，局部压痛阳性，未见深部炎性结节及痈（未融合成大脓肿）。","辅助检查":"检查计划：患者头面颈部毛发丰富部位出现毛囊性红色丘疹并渐变为中央有毛发贯穿的脓疱，伴轻度疼痛，结合无发热及全身不适，临床诊断浅表性细菌性毛囊炎，本病一般以临床诊断为主，无需常规实验室检查即可启动局部抗菌治疗。但患者需评估有无易感因素，故完善血糖检查，筛查糖尿病，明确有无糖代谢异常这一反复发作的根本诱因，因高血糖会削弱皮肤抗感染能力；患者本次为初发、无反复发作史，暂不常规培养，若局部治疗5~7天后无效、皮损反复发作或范围扩大，则完善脓液细菌培养及药敏试验，明确是否为金黄色葡萄球菌感染及其耐药情况，指导口服抗生素选择，避免盲目用药。此外，完善血常规及CRP检查，评估有无白细胞及中性粒细胞升高，明确感染是否向深部扩散形成疖或痈；完善肝肾功能检查，为需要口服抗生素者评估用药安全性；对皮损广泛、伴发热或疑有免疫抑制者，完善免疫球蛋白及空腹血糖、糖化血红蛋白检测，评估机体免疫状态及血糖控制水平，指导基础病治疗与随访复查。\n\n（检查清单）\n【必做】一般以临床诊断为主；【其他】脓液细菌培养+药敏（反复发作、治疗无效或疑金黄色葡萄球菌感染时）、血糖（反复发作者筛查糖尿病）。","初步诊断":"1. 毛囊炎（浅表性细菌性）\n（注：轻症予局部治疗：外用抗菌药物（莫匹罗星软膏或夫西地酸乳膏，每日2次×5~7天）、2%碘酊或氯己定溶液涂擦；保持皮肤清洁干燥、避免搔抓摩擦、勤换衣物；反复或广泛发作者口服抗生素（头孢氨苄0.5g每日3次或克林霉素，根据培养结果选择）；深部毛囊炎（疖）形成脓肿时切开引流；治疗基础病（控制糖尿病、停用不合理糖皮质激素）；注意个人卫生（毛巾衣物消毒）。）","处理方案":"【药物治疗】\n1. 外用抗菌药物（首选，适用于浅表孤立性皮损）：莫匹罗星软膏（百多邦）适量外用患处，bid×5-7天；或夫西地酸乳膏适量外用患处，bid×7天，涂药前后注意手卫生。\n2. 口服抗菌药物（皮损广泛、反复发作或外用疗效不佳时）：头孢呋辛酯片0.25g bid，餐后口服×7天；或多西环素片0.1g qd×7-14天（服药后多饮水，避免睡前卧位服药）。\n3. 马拉色菌性毛囊炎：2%酮康唑洗剂涂于患处，保留5分钟后清水冲洗，qd×2周；皮损广泛者可加用伊曲康唑胶囊0.2g qd，餐后口服×1-2周。\n4. 瘙痒明显者：氯雷他定片10mg qd口服，缓解瘙痒，避免搔抓继发感染。\n\n【一般治疗及生活指导】\n1. 保持皮肤清洁干燥，勤换内衣、枕巾及毛巾，避免搔抓、挤压皮损，防止感染扩散及遗留瘢痕。\n2. 饮食清淡，减少高糖、高脂及辛辣刺激性食物摄入，戒烟限酒。\n3. 作息规律，避免熬夜及久坐出汗后未及时清洁；加强锻炼，提高机体免疫力，糖尿病及免疫力低下者应积极控制基础疾病。\n4. 避免使用油性化妆品及穿透气性差的衣物，减少剃须、刮毛等机械刺激，避免热水烫洗及碱性肥皂过度清洗。\n\n【随诊要求】\n用药后1周复诊评估疗效；若治疗3-5天症状无缓解、皮损增多、出现发热或脓肿波动明显等加重表现，应及时复诊或就诊；反复发作者建议行血糖检测及皮损分泌物培养+药敏，明确诱因并调整治疗方案。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":467,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"1c38b3fb23f43f34512b830631cc1c3c0f11f48e785e1a3df439446b2b32bb5b","pinyin":"maonangyan","initials":"mny","setting":"out","caseName":"门诊病历332","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历332",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-b62aee69fe8ba1883fe4","key":"v1-c9ccc21dfe2a3058|templates-b62aee69fe8ba1883fe4","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"疖痈","category":"门诊病历模板","raw":{"name":"疖痈","category":"门诊病历模板","case":{"case_name":"门诊病历333","templates":{"主诉":"皮肤硬结红肿疼痛伴发热3天","现病史":"患者于5天前在后颈部（毛囊丰富、易摩擦部位）出现炎性硬结，红肿疼痛渐加重，中心化脓坏死形成脓栓，表现为痈（多个相邻毛囊融合，范围大、表面多个脓头呈蜂窝状、疼痛剧烈，常伴发热、畏寒、乏力），有无糖尿病、免疫抑制、营养不良、卫生差、局部摩擦挤压等易感因素：无上述易感因素。面部（危险三角区）疖有无挤压史：无挤压史（挤压可致海绵窦血栓及颅内感染，重要）。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P72次/分，R18次/分，BP120/80mmHg。后颈部可见炎性肿块（直径约4cm），红肿明显、皮温升高、触痛剧烈（+++），中心可见多个脓头（痈，表面呈蜂窝状），有波动感（提示脓肿形成），周围组织水肿，区域淋巴结肿大压痛，面部无疖肿，无眼睑水肿及眼球突出（无海绵窦血栓征象）。","辅助检查":"【必做】血常规（白细胞及中性粒细胞升高，痈时明显）、CRP、血糖（反复疖痈者筛查糖尿病，重要）、脓液细菌培养+药敏（痈伴系统感染时）；【影像】超声（脓肿定位评估，必要时）。","初步诊断":"1. 痈（后颈部）\n（注：早期未化脓者予局部热敷或红外线照射、外用鱼石脂软膏或莫匹罗星；已化脓（有波动感）者行切开引流（痈行十字切开，贯通各脓腔）；全身抗生素（痈或多发疖或伴发热者：头孢氨苄、阿莫西林克拉维酸0.625g每日3次或克林霉素（青霉素耐药金黄色葡萄球菌时），疗程7~10天）；重要警示：面部危险三角区疖严禁挤压（防海绵窦血栓性静脉炎，出现高热、头痛、眼睑水肿、眼球突出立即急诊）；治疗基础病（糖尿病，反复疖痈者必查必控）；注意个人卫生。）","处理方案":"【药物治疗】\n1. 抗菌药物（首选β-内酰胺类）：阿莫西林胶囊0.5g po tid×5~7天；对青霉素过敏者选用克林霉素胶囊0.3g po bid×5~7天，或多西环素片0.1g po bid×5~7天。\n2. 局部用药：未成脓期外涂莫匹罗星软膏（百多邦）bid×7天，或鱼石脂软膏外敷qd；已成脓且波动明显者行切开引流，术后每日换药，引流条视脓液引流量适时拔除。\n3. 对症治疗：疼痛明显者加用布洛芬缓释胶囊0.3g po bid（必要时）；合并糖尿病者规范监测并控制血糖，以提高抗感染疗效。\n【一般治疗及生活指导】\n1. 充分休息，避免劳累及熬夜；严禁挤压、搔抓疖痈及周围皮肤，面部危险三角区疖痈尤其禁止挤压，防止感染经海绵窦扩散引起颅内感染。\n2. 保持皮肤清洁干燥，勤洗澡、勤换内衣，剪短指甲；出汗后及时清洁，避免搔抓破损处再次感染。\n3. 清淡饮食，多饮水，忌辛辣刺激及油腻食物，戒烟限酒，适量补充富含蛋白质和维生素的食物以促进愈合。\n【随诊要求】\n1. 服药后3~5天复诊评估疗效；若用药后局部红肿扩大、疼痛加剧，或出现发热（体温≥38℃）、寒战及局部波动感，应立即就诊。\n2. 切开引流者每1~2日复诊换药，直至创口愈合；反复发作（≥3次/年）或合并糖尿病者建议查空腹血糖，必要时转皮肤科或普外科进一步诊治。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":468,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"55349959083f4191f09b8325c08ace448aeb5a2c5985166d4dbbed6ba16d7b42","pinyin":"jieyong","initials":"jy","setting":"out","caseName":"门诊病历333","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历333",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-3dcc11f7a77817db26d3","key":"v1-c9ccc21dfe2a3058|templates-3dcc11f7a77817db26d3","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"丹毒","category":"门诊病历模板","raw":{"name":"丹毒","category":"门诊病历模板","case":{"case_name":"门诊病历334","templates":{"主诉":"小腿皮肤红肿热痛伴发热3天","现病史":"患者于3天前在小腿（最常见，多与足癣及皮肤破损相关；面部多与鼻前庭炎及抠鼻相关）出现片状红斑，界限清楚、表面紧张发亮、灼热、疼痛，向周边扩展，伴发热（体温最高38.7℃）、畏寒、乏力、头痛，有无局部水疱（大疱性丹毒）、局部淋巴结肿大、既往反复发作史（慢性丹毒可致象皮肿），有无足癣、皮肤皲裂破损、糖尿病等诱因：有足癣。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P72次/分，R18次/分，BP120/80mmHg。左小腿可见大片鲜红色斑片（范围约10cm×8cm），边界清楚、稍隆起，表面紧张发亮，皮温升高、触痛阳性，未见水疱及大疱，局部无破溃及明显化脓（区别于蜂窝织炎，丹毒皮损边界清、位置浅），左腹股沟区可触及肿大压痛淋巴结（下肢丹毒时）。","辅助检查":"检查计划：患者左小腿红肿热痛伴发热3天，体温最高38.7℃，伴畏寒、乏力，完善血常规检查了解白细胞及中性粒细胞计数，明确有无细菌感染及感染严重程度；CRP为炎症急性期指标，查CRP评估炎症反应程度并协助判断抗菌治疗疗效；本次发病考虑A组β溶血性链球菌感染，查抗链球菌溶血素O（ASO）寻找链球菌感染证据，恢复期复查ASO了解抗体滴度有无动态升高以支持诊断；患者高热、寒战，为排除菌血症、败血症，完善血培养（高热寒战或疑菌血症时，于抗菌药物使用前采血）明确病原菌，指导抗菌药物选择；患者有足癣，为明确感染入口，完善足癣真菌检查（趾间鳞屑10%KOH涂片）明确有无真菌感染，指导抗真菌治疗以防丹毒复发。小腿红肿热痛需与下肢深静脉血栓、蜂窝织炎鉴别，完善下肢静脉彩超排除深静脉血栓形成。丹毒需用青霉素等抗菌药物足疗程治疗，用药前完善肝肾功能检查评估肝肾功能，指导药物选择与剂量调整；查血糖筛查有无糖尿病等易感因素；查电解质了解内环境情况。治疗期间定期复查血常规、CRP，观察炎症指标动态变化，判断疗效及有无病情进展。\n\n（检查清单）\n【必做】血常规（白细胞及中性粒细胞升高）、CRP、抗链球菌溶血素O（ASO，为A组链球菌感染证据，恢复期升高）；【其他】血培养（高热寒战或疑菌血症时）、足癣真菌检查（下肢丹毒，寻找感染入口）。","初步诊断":"1. 丹毒（左小腿，A组β溶血性链球菌感染）\n（注：抗菌治疗首选青霉素（青霉素G 80万~160万U肌注或静滴每6小时1次，或阿莫西林0.5g每日3次×10~14天；青霉素过敏者用克林霉素、红霉素或一代头孢）；局部：抬高患肢、急性红肿期冷敷、外用抗生素软膏（莫匹罗星）；处理感染入口（治疗足癣予抗真菌药、处理皮肤破损，为防复发关键）；对症：退热（对乙酰氨基酚）、卧床休息；疗程需足够（10~14天，防复发，复发常见于未处理足癣者）；反复发作者予长期预防性青霉素（苄星青霉素120万U肌注每月1次）；警惕并发症（败血症，表现为寒战高热不退、局部坏死，需住院）。）","处理方案":"【药物治疗】\n1. 青霉素V钾片0.5g（80万U）口服 qid×10天（首选，覆盖溶血性链球菌）；或阿莫西林胶囊0.5g口服 tid×7～10天\n2. 青霉素过敏者：阿奇霉素片0.5g口服 qd×5天；或患者霉素胶囊0.15g口服 bid×10天\n3. 局部处理：50%硫酸镁溶液冷湿敷患处，tid，每次20～30分钟；红肿明显处可外用如意金黄散调敷\n\n【一般治疗及生活指导】\n1. 卧床休息，抬高患肢（下肢丹毒尤需抬高超过心脏水平），避免久站、久行及过度活动，待红肿消退、皮温正常后再逐步恢复活动\n2. 清淡饮食，多饮水，忌辛辣刺激、海鲜及饮酒；注意皮肤清洁卫生，勤剪指甲，禁止搔抓、挤压皮损\n3. 积极治疗足癣、皮肤破损等诱因（下肢丹毒最常见诱因为足趾间糜烂），及时处理蚊虫叮咬及外伤，并控制糖尿病等基础疾病\n\n【随诊要求】\n治疗3天症状无缓解或发热不退、红肿范围继续扩大者，应及时复诊或急诊就诊；疗程结束后1周复诊评估皮损消退情况；反复发作（1年内≥3次）者建议皮肤科随访，根据患者具体情况制定个体化方案预防性使用长效青霉素（苄星青霉素120万U肌注，每月1次）。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":469,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"6a7af4ac4d041467cc4abb4bd0415d771fbbe95c0aa17cda0fa2cf1c4df71b3d","pinyin":"dandu","initials":"dd","setting":"out","caseName":"门诊病历334","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历334",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-6367460f015f3fe8d03e","key":"v1-c9ccc21dfe2a3058|templates-6367460f015f3fe8d03e","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"蜂窝织炎","category":"门诊病历模板","raw":{"name":"蜂窝织炎","category":"门诊病历模板","case":{"case_name":"门诊病历335","templates":{"主诉":"下肢皮肤弥漫红肿热痛伴发热3天","现病史":"患者于4天前在小腿（最多见，亦可见于面部及上肢，多经皮肤破损如外伤、溃疡、足癣裂隙、静脉穿刺、虫咬处感染）出现皮肤及皮下弥漫性红肿、灼热、疼痛，边界不清、向周围扩散，伴发热（体温最高38.8℃）、畏寒、乏力，有无皮肤坏死及大疱（需排除坏死性筋膜炎，表现为剧烈疼痛超过体征、快速进展、全身中毒重）、局部麻木、皮肤颜色暗紫，有无糖尿病、免疫抑制、周围血管病及淋巴水肿等基础病：无上述基础病。今日来我院急诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P72次/分，R18次/分，BP120/80mmHg。左小腿皮肤及皮下弥漫性红肿（范围较丹毒大而边界不清）、皮温升高、明显压痛阳性、皮肤紧张，未见水疱、大疱及坏死斑片（警惕坏死性筋膜炎），无捻发感（产气菌感染如坏死性筋膜炎及气性坏疽为急症），左腹股沟区可触及肿大淋巴结，心率偏快（提示中毒表现）。","辅助检查":"【必做】血常规（白细胞升高）、CRP、血培养（发热或全身症状明显时，蜂窝织炎约20%可阳性）、血糖（筛查及控制糖尿病）、肝肾功能；【影像】超声（深部脓肿及筋膜炎评估）、MRI（疑深部感染或坏死性筋膜炎时，可见筋膜水肿增厚，为关键检查）；【手术探查】疑诊坏死性筋膜炎者急诊手术清创探查（勿等影像，高度怀疑即手术）。","初步诊断":"1. 蜂窝织炎（左小腿）\n（注：轻症（无全身中毒、无基础病）予口服抗生素（阿莫西林克拉维酸0.625g每日3次或头孢氨苄0.5g每日4次，覆盖链球菌及金黄色葡萄球菌，疗程7~10天）；重症（发热、范围广、有基础病如糖尿病及免疫抑制）需住院静脉抗生素（头孢唑林、苯唑西林或万古霉素（MRSA高危）±哌拉西林他唑巴坦，覆盖革兰阳性及阴性菌）；局部：抬高患肢；对症退热镇痛；密切观察，若疼痛与体征不符、出现水疱坏死、快速蔓延、捻发感或全身中毒重，应考虑坏死性筋膜炎，急诊清创（勿延误，死亡率高）；治疗基础病（糖尿病、淋巴水肿）、处理皮肤破损（足癣）以防复发；疗程至红肿消退后3~5天。）","处理方案":"【药物治疗】\n1. 阿莫西林胶囊 0.5g po tid，连用7天（β-内酰胺类不过敏者首选，宜与克拉维酸联合以覆盖产酶菌，如阿莫西林克拉维酸钾片0.625g po tid×7天）。\n2. 头孢呋辛酯片 0.25g po bid，连用7天（对青霉素轻度过敏或门诊口服二线选择）。\n3. 青霉素过敏者：克林霉素胶囊 0.3g po qid，连用7天；或阿奇霉素片 0.5g po qd，连用5天（覆盖链球菌及部分金葡菌）。\n4. 局部处理：50%硫酸镁溶液湿敷患处 bid，每次20分钟；红肿局限无波动感时勿切开，已化脓需外科切开引流并加用甲硝唑片0.4g po tid×5天。\n\n【一般治疗及生活指导】\n1. 患肢制动并抬高（高于心脏水平），卧床休息，减少行走及剧烈活动，以利静脉回流、减轻肿胀。\n2. 清淡饮食，保证充足蛋白质及维生素摄入（如瘦肉、蛋、奶、新鲜蔬果），多饮水，忌辛辣刺激及海鲜发物。\n3. 保持患处皮肤清洁干燥，切勿挤压、搔抓或自行刺破红肿部位，防止感染扩散；注意足癣、皮肤破损等诱因的处理。\n4. 合并糖尿病者严格控制血糖，戒烟酒，注意体温及红肿范围变化。\n\n【随诊要求】\n1. 用药48～72小时复诊评估疗效，复查血常规、CRP；若红肿范围扩大、疼痛加剧或伴寒战高热，应立即就诊，必要时收住院静脉抗感染治疗。\n2. 疗程结束后1周复查血常规及炎症指标至正常；症状完全消退后仍应完成足量疗程，避免自行停药导致复发。\n3. 反复发作或迁延不愈者，建议查血糖、下肢血管彩超及免疫指标，排除糖尿病、血管病变等基础病因。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":470,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"e04e6e8504b0ebd943c793ac254fae2e6254b4c2ebd1390bea4dcdfe004b9f40","pinyin":"fengwozhiyan","initials":"fwzy","setting":"out","caseName":"门诊病历335","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历335",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-e91dad9a0db48b948411","key":"v1-c9ccc21dfe2a3058|templates-e91dad9a0db48b948411","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"传染性软疣","category":"门诊病历模板","raw":{"name":"传染性软疣","category":"门诊病历模板","case":{"case_name":"门诊病历336","templates":{"主诉":"皮肤散在蜡样光泽丘疹1月","现病史":"患儿于1个月前出现皮肤散在丘疹，好发于躯干及四肢（儿童多见；成人可经性接触传播，见于下腹、生殖器及大腿内侧，需注意），丘疹米粒至绿豆大小、呈半球形、蜡样光泽、中央脐凹状、可挤出白色乳酪样物质（软疣小体），有无瘙痒、搔抓后自身接种增多、洗澡游泳等接触史（传染性，经密切接触、共用毛巾、公共浴池传播）、局部有无继发感染（红、痛、脓，搔抓后），有无免疫抑制（HIV感染，成人泛发难治性软疣需警惕）：无免疫抑制病史。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P72次/分，R18次/分，BP120/80mmHg。躯干及四肢可见散在多个（约15个）半球形丘疹，直径3~5mm，表面蜡样光泽、中央脐凹，可挤出白色软疣小体，周边无红晕，无继发感染及结痂。","辅助检查":"检查计划：患儿皮肤散在蜡样光泽丘疹1月，中央呈脐凹状、可挤出白色乳酪样物质（软疣小体），依据典型皮损即可临床诊断，一般无需特殊辅助检查；为进一步确认软疣小体及皮损结构，必要时完善皮肤镜检查了解中央脐凹及血管形态，辅助诊断；如皮损不典型、短期内明显增大、溃破或疑有恶变，完善皮肤病理检查（必要时组织活检）明确诊断，排除其他皮肤肿瘤性病变；如局部出现红、肿、痛、脓等继发感染表现，完善血常规检查了解白细胞及中性粒细胞水平，明确有无继发细菌感染，必要时查CRP评估炎症程度；患儿搔抓后皮损可自身接种增多，需与扁平疣、丘疹性荨麻疹等鉴别，必要时完善皮肤镜检查协助鉴别诊断，避免误诊误治。成人泛发、难治性软疣或生殖器部位皮损存在性传播可能，需完善HIV检测筛查免疫抑制状态，本例为儿童、无免疫抑制病史，暂不作为常规检查，若皮损泛发迁延则完善HIV检测及性病相关筛查明确有无免疫缺陷。治疗期间每2~4周随诊，观察新发皮损（潜伏期2~7周）及有无继发感染。\n\n（检查清单）\n【必做】一般临床诊断为主（典型皮损即可诊断）；【其他】皮肤病理（不典型/疑恶变时）、HIV检测（成人泛发/难治性）。","初步诊断":"1. 传染性软疣\n（注：治疗以物理去除为首选：刮匙刮除、液氮冷冻或激光（挤出软疣小体，消毒防感染，数目多者分次进行）；外用药：咪喹莫特乳膏（免疫调节，儿童慎用，局部刺激）、维A酸类（0.1%维A酸乳膏，刺激免疫）；注意：免疫功能正常儿童多数可自行消退（6~18个月），少量皮损可观察（避免瘢痕），但具传染性，建议治疗防扩散；避免搔抓（自身接种）、不共用毛巾浴巾、公共浴池注意防护；成人生殖器部位软疣有性传播可能，建议性病筛查（HIV等）；继发感染予莫匹罗星外用；治疗期间随访新发皮损（潜伏期2~7周）。）","处理方案":"【药物治疗】\n1. 咪喹莫特乳膏（5%）外用：每晚取适量涂于疣体表面并轻轻按摩至吸收，每周3次（隔日1次），涂后保留6～10小时用清水洗去，疗程8～12周；通过诱导局部干扰素等细胞因子发挥抗病毒及免疫调节作用，为软疣治疗的一线外用药。\n2. 0.1%维A酸乳膏外用：每晚1次薄涂于皮损处，可促进表皮剥脱、使疣体脱落，疗程4～8周；用药期间注意避光、防晒，局部出现明显红斑、灼痛时减量或暂停。\n3. 5%氢氧化钾溶液点涂：每日1～2次，以棉签蘸取少量仅点于疣体表面，避免触及周围正常皮肤，出现明显灼痛、糜烂时立即停药并清洁创面。\n\n【一般治疗及生活指导】\n1. 严禁搔抓、挤压或自行挑除疣体，以免病毒沿抓痕自身接种造成皮损线状播散；剪短指甲，勤洗手，保持皮损处清洁干燥。\n2. 毛巾、浴巾、内衣及床单单独使用并煮沸消毒或日光暴晒，不与他人共用洗浴用品，避免去公共浴池、游泳馆等潮湿公共场所；有性接触者建议使用避孕套，性伴侣如有皮损应同时就诊治疗。\n3. 注意规律作息、均衡营养、避免熬夜劳累以维持正常免疫功能；合并糖尿病、HIV感染或长期使用免疫抑制剂者应积极治疗原发疾病并加强皮损护理。\n\n【随诊要求】\n治疗后2～4周复诊评估疣体消退情况及有无新发皮损；治疗期间若出现局部继发感染（红肿、疼痛、化脓）、糜烂溃疡或皮疹迅速增多，应随时就诊；皮损全部消退后建议随访2～3个月确认无复发，免疫功能低下者延长随访至6个月。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":471,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"48aa90faa3ebdfb5a55f92c327f9baca7cf281b0c4fd457b2305f88d0181c63e","pinyin":"chuanranxingruanyou","initials":"crxry","setting":"out","caseName":"门诊病历336","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历336",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-18bc23a5688f713bc4be","key":"v1-c9ccc21dfe2a3058|templates-18bc23a5688f713bc4be","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"寻常疣","category":"门诊病历模板","raw":{"name":"寻常疣","category":"门诊病历模板","case":{"case_name":"门诊病历337","templates":{"主诉":"手足角化性丘疹逐渐增多6月","现病史":"患者于6个月前在手背及手指（外伤处易发）出现单个角化性丘疹，渐增大呈乳头瘤样（菜花状或刺状，表面粗糙、角化），呈灰褐色，无痛或轻微压痛（受压处如足底可有行走痛），数目渐增多（自身接种，与搔抓及摩擦有关），有无甲周疣（甲变形）、跖疣（足底，与鸡眼鉴别）、性病疣（外阴，需排查性病），有无免疫功能低下：无免疫功能低下。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P72次/分，R18次/分，BP120/80mmHg。手背及手指可见5个黄豆至蚕豆大小丘疹及结节，表面粗糙角化呈乳头瘤样、灰褐色，质硬，边界清，无甲周疣（甲周无增厚变形）；足底未见跖疣（无削去表面角质后见黑点的表现，可与鸡眼鉴别，鸡眼中心有角质栓、压痛局限）。","辅助检查":"【必做】一般临床诊断为主；【其他】皮肤病理（不典型，疑恶变：老年/快速增大/色深者：注意与鳞癌、脂溢性角化鉴别）。","初步诊断":"1. 寻常疣（HPV感染，人类乳头瘤病毒）\n（注：治疗采用局部破坏或免疫疗法：液氮冷冻（常用，每1~2周1次，需数次至十余次）、激光或电灼（较大者）、外用角质剥脱剂（水杨酸贴剂或溶液，每日使用，削去角化层，为家庭治疗可选）、5-氟尿嘧啶软膏（顽固性）、免疫调节（咪喹莫特，难治性）；免疫功能正常者部分可自行消退（尤其儿童，可观察）；避免搔抓及直接接触（HPV传染）；跖疣治疗较顽固，予冷冻联合角质剥脱，避免行走痛影响，穿软底鞋；甲周疣治疗困难，防甲变形，应尽早治疗；数目多、顽固或免疫低下者转皮肤科专科治疗，注意排查HPV相关恶变风险（高危型、外生殖器疣需性病排查）。）","处理方案":"【药物治疗】\n1. 角质剥脱剂：水杨酸溶液/贴剂（15%~26%，如高浓度水杨酸软膏）外用，先用温水浸泡患处10~15分钟软化角质并轻轻刮除表面角质层，再涂药或贴敷，每日1次，连用8~12周。\n2. 细胞毒类药物：0.5%鬼臼毒素酊外用，每日2次（早晚各1次）涂于疣体，连用3天、停药4天为1个疗程，必要时重复2~3个疗程（孕妇禁用，避免涂于正常皮肤）。\n3. 免疫调节剂：5%咪喹莫特乳膏外用，每周3次（如隔日晚）睡前涂于疣体，保留6~10小时后以清水洗净，疗程8~16周。\n4. 抗病毒辅助：重组人干扰素α-2b凝胶外用，每日2~3次涂于疣体，可与上述药物错开时间使用，疗程4~8周。\n【一般治疗及生活指导】\n1. 避免搔抓、摩擦及自行修剪、撕扯疣体，防止HPV自身接种扩散，引发\"卫星状\"新疣。\n2. 注意个人卫生，勤洗手，不与他人共用毛巾、指甲剪、浴巾、拖鞋等个人物品；足部寻常疣者穿宽松透气鞋袜，保持足部干燥，避免长期浸水。\n3. 疣体未消退前避免与家人（尤其儿童）直接皮肤接触；规律作息、均衡饮食、适当锻炼，增强机体免疫力，戒烟限酒。\n4. 接受冷冻、激光等物理治疗者，创面保持清洁干燥，3天内避免沾水，结痂后待其自然脱落，勿强行撕除。\n【随诊要求】\n1. 治疗期间每2~4周复诊1次，评估疣体消退情况及局部不良反应（红肿、水疱、色素沉着等），必要时调整治疗方案。\n2. 疣体完全消退后继续观察3~6个月，期间如出现新发疣体或原有皮损增大、增多，及时复诊。\n3. 若规律局部治疗2~3个月疣体无明显消退，或疣体多发、顽固、反复复发，建议复诊评估改用冷冻、激光、电灼等物理治疗或联合免疫调节治疗。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":472,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"9600218dc4d5893d837d615697bd75660a851aebaec51e00658bf5dd5acdcc90","pinyin":"xunchangyou","initials":"xcy","setting":"out","caseName":"门诊病历337","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历337",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-d1a199f0e89c5e1a218f","key":"v1-c9ccc21dfe2a3058|templates-d1a199f0e89c5e1a218f","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"扁平疣","category":"门诊病历模板","raw":{"name":"扁平疣","category":"门诊病历模板","case":{"case_name":"门诊病历338","templates":{"主诉":"面部扁平丘疹渐增多伴瘙痒3月","现病史":"患者（青少年及青年多见）于3个月前在面部（额部及颊部最常见，也见于手背及前臂）出现米粒至黄豆大扁平丘疹，呈肤色或淡褐色、表面光滑、境界清楚、圆形或多角形，数目较多可呈线状排列（沿抓痕分布，为同形反应即Koebner现象，具特征性），轻度瘙痒或无自觉症状，搔抓后可增多（自身接种），有无皮肤外伤史、免疫功能状态（妊娠期或免疫低下可增多）：无特殊诱因。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P72次/分，R18次/分，BP120/80mmHg。面部（额、颊、下颌）及手背可见散在多个扁平丘疹（米粒至黄豆大、肤色或淡褐色、表面光滑、圆形或多角形、境界清），部分呈线状排列（搔抓后同形反应）。","辅助检查":"检查计划：患者面部米粒至黄豆大扁平丘疹渐增多伴瘙痒3月，皮损沿抓痕呈线状排列（同形反应，Koebner现象），青少年及青年多见，依据典型皮损即可临床诊断，一般无需辅助检查；为观察皮损表面点状血管及色素结构、协助与汗管瘤等鉴别，必要时完善皮肤镜检查明确诊断；如皮损不典型、顽固难治或疑有其他病变，完善皮肤病理检查（必要时组织活检）明确诊断，排除扁平苔藓等其他皮肤病；搔抓后皮损增多提示自身接种，如继发感染出现红肿、渗出，完善血常规检查了解白细胞及中性粒细胞水平，明确有无细菌感染；患者拟予维A酸类、咪喹莫特等药物治疗并需评估免疫状态，若皮损泛发、反复难愈，完善HIV检测及淋巴细胞亚群检查评估免疫功能，排除免疫低下所致，本例无特殊诱因、既往体健，暂不作为常规筛查。治疗期间每4~8周皮肤科随诊，复查皮损数目及形态并照相记录，评估疗效、判断有无自行消退及复发。\n\n（检查清单）\n【必做】一般临床诊断为主；【其他】皮肤病理（不典型时）。","初步诊断":"1. 扁平疣（HPV-3型等感染）\n（注：治疗以外用药为首选，面部避免损伤性治疗：0.1%维A酸乳膏或阿达帕林凝胶（每晚1次，4~8周，注意刺激反应）、5-氟尿嘧啶软膏（顽固性，面部慎用）、咪喹莫特乳膏（免疫调节）；物理治疗（数目少或外用药无效者予冷冻、激光，面部慎用激光以防色素沉着）；数目多或顽固者予免疫调节（卡介菌多糖核酸肌注，辅助）、中药（板蓝根、薏苡仁，可配合）；避免搔抓（自身接种扩散）；部分可自行消退（病程自限，儿童多见）；治疗期间避免使用刺激性化妆品；复发常见，需坚持疗程，皮肤科随访。）","处理方案":"【药物治疗】\n1. 0.1%维A酸乳膏：每晚睡前温水清洁患处后薄涂一层，避开口、眼、鼻黏膜，次晨清水洗净，连用4-8周；用药初期可能出现局部红斑、脱屑，属正常反应，可先小面积试用、隔日晚用1次建立耐受。用药期间严格避光，白天外出需防晒。\n2. 5%咪喹莫特乳膏：每周3次（如周一、三、五），睡前取少量涂于疣体表面轻揉至吸收，保留6-10小时后晨起用清水洗去，疗程8-12周；如局部出现明显红肿、糜烂，应暂停用药待炎症消退后减量续用。\n3. 重组人干扰素α-2b凝胶：每日涂患处4次，薄涂即可，连续4周为一疗程；可与维A酸乳膏分时（如早晚各一种）交替使用，协同增效。\n4. 泛昔洛韦片0.25g bid口服，连用2-4周（用于皮损多发、泛发或顽固复发者，辅助抗病毒、抑制病毒复制）；免疫功能低下或妊娠、哺乳期妇女慎用，需在医师指导下用药。\n【一般治疗及生活指导】\n1. 避免搔抓、摩擦、刮剃及自行挤压疣体，防止\"同形反应\"致病毒沿抓痕自体接种扩散；修剪指甲、保持手部清洁。\n2. 毛巾、面巾、剃须刀、枕巾等个人用品专人专用并定期煮沸消毒，避免与家人共用，防止交叉传染；面部皮损处避免使用去角质产品及刺激性化妆品。\n3. 忌辛辣、刺激性及高糖饮食，戒烟限酒；规律作息，保证充足睡眠，避免熬夜及精神紧张，适度锻炼，增强机体免疫力有助于皮损消退。\n4. 面部用药后注意防晒（维A酸类有光敏性），外出使用防晒霜或戴遮阳帽；如皮损出现红肿、渗液、疼痛或感染征象，暂停局部用药并及时就医。\n【随诊要求】\n1. 治疗期间每2-4周复诊1次，由医师评估疗效及用药不良反应，根据患者具体情况制定个体化方案调整药物种类与浓度。\n2. 若疣体数目增多、范围扩大，或出现明显红肿、糜烂、感染等不适，应及时复诊。\n3. 连续治疗3个月皮损无消退者，建议复诊评估是否联合物理治疗（如冷冻、激光）；皮损完全消退后1-2个月复查1次，确认无复发方可停药观察。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":473,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"7898f4be1dc046e01ada7742ca79e50853c76cfd0b642da7eff648078cf641c4","pinyin":"bianpingyou","initials":"bpy","setting":"out","caseName":"门诊病历338","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历338",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-3546377677a92fb58d69","key":"v1-c9ccc21dfe2a3058|templates-3546377677a92fb58d69","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"跖疣","category":"门诊病历模板","raw":{"name":"跖疣","category":"门诊病历模板","case":{"case_name":"门诊病历339","templates":{"主诉":"足底角化斑块伴行走压痛3月","现病史":"患者于3个月前在足底（承重部位，足跟及跖骨头）出现角化性丘疹，渐增大融合成斑块，表面粗糙、灰黄，行走或受压时疼痛（侧方挤压痛，区别于鸡眼，鸡眼为垂直压痛），有无出血点（削去角质见小黑点，为乳头血管破裂）、多发（镶嵌疣）、公共场所赤足史、足部多汗，有无免疫功能低下：无免疫功能低下。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P72次/分，R18次/分，BP120/80mmHg。足底（承重区）可见3个黄豆至蚕豆大角化性丘疹及斑块，表面粗糙、边界较清，削去表面角质后可见黑色出血点（特征性，与鸡眼鉴别：鸡眼中心有半透明角质栓、皮纹连续、以垂直压痛为主）。","辅助检查":"【必做】一般临床诊断为主（削刮检查：见出血点）；【其他】皮肤病理（不典型：疑鳞癌/黑素瘤，足底，罕见但需警惕，快速增大/溃疡/出血者）、足部X线（需排除骨病变，少见）。","初步诊断":"1. 跖疣（足底HPV感染）\n（注：治疗较顽固，需耐心：外用角质剥脱剂（40%水杨酸硬膏或贴剂，先用温水浸泡、削去角化层后贴敷，每日或隔日1次，持续数周至数月，为家庭治疗基础）、液氮冷冻（每2~3周1次，需多次，足底血供差、复发率高）、激光或电灼、5-氟尿嘧啶软膏（配合角质剥脱）；免疫治疗（难治性者予疣体抗原注射、咪喹莫特）；穿软底宽松鞋（减压，缓解行走痛）、避免赤足于公共场所（防传染）、足部保持干燥；糖尿病及周围血管病者慎用损伤性治疗（溃疡风险，愈合差）；顽固性（>1年）者转皮肤科专科治疗（多方法联合）；多数需4~6个月以上治疗周期，需与患者充分沟通。）","处理方案":"【药物治疗】\n1. 角质剥脱剂：25%水杨酸火棉胶，每日1次外用。用药前先温水浸泡患足10~15分钟，用钝刀片或指甲锉轻轻刮除疣体表面增厚角质，再涂药并封包（医用胶布），疗程4~12周，至疣体脱落。\n2. 免疫调节剂：5%咪喹莫特乳膏，每周3次（隔晚1次）睡前涂于疣体并轻揉至吸收，次晨清洗，疗程8~16周。\n3. 维A酸类：0.1%维A酸乳膏，每晚1次外用，涂于疣体（避免涂及周围正常皮肤），配合角质剥脱剂使用，疗程4~8周。\n4. 局部注射：顽固性、多发性或经上述治疗无效者，可予平阳霉素8mg加2%利多卡因1ml局部疣体内注射，每次0.1~0.2ml/点，每2周1次，连用3~4次。\n【一般治疗及生活指导】\n1. 避免搔抓、自行用刀修剪或撕剥疣体，防止HPV自体接种播散至足部其他部位及传染他人。\n2. 穿宽松、透气、软底鞋袜，避免挤压摩擦患处；汗足者每日更换鞋袜，保持足部清洁干燥。\n3. 不赤脚行走于公共浴室、游泳池、健身房等潮湿公共场所，洗浴时勿与他人共用毛巾、拖鞋。\n4. 治疗期间规律作息、适当锻炼，忌辛辣刺激饮食及饮酒，避免局部外伤。\n【随诊要求】\n1. 每2~4周复诊1次评估疣体变化及药物疗效，按医嘱规律用药，不可随意停药。\n2. 冷冻、激光等物理治疗后按治疗间隔复诊，直至疣体完全消退。\n3. 疣体消退后建议随访观察1~3个月；若出现局部红肿、疼痛、渗液、继发感染，或疣体增大、增多、治疗4周无效、12周仍未愈者，应及时复诊调整治疗方案。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":474,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"3968b0d9fdbf06626cb436fbb5644415dbeb6e92fbfba7d59da1907d821b7d9a","pinyin":"zhiyou","initials":"zy","setting":"out","caseName":"门诊病历339","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历339",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-1005127f575043d11a09","key":"v1-c9ccc21dfe2a3058|templates-1005127f575043d11a09","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"尖锐湿疣","category":"门诊病历模板","raw":{"name":"尖锐湿疣","category":"门诊病历模板","case":{"case_name":"门诊病历340","templates":{"主诉":"外阴菜花状赘生物渐增多1月","现病史":"患者于2个月前在外生殖器（冠状沟、龟头、大小阴唇、阴道口及肛周为最常见部位）出现淡红色小丘疹，渐增大增多、融合呈菜花状或鸡冠状赘生物，表面湿润、易出血，无痛或轻微痒，有无不洁性接触史（性传播疾病，主要传播途径，潜伏期1~8月）、配偶及性伴侣情况、肛交史（肛周）及口交史（口腔），有无免疫功能低下（HIV、移植、免疫抑制，致难治性复发），有无其他性传播疾病（梅毒、HIV，需性病筛查）：有婚外不洁性接触史。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P72次/分，R18次/分，BP120/80mmHg。外生殖器（阴茎冠状沟）可见散在或融合的乳头瘤样及菜花样赘生物（大小约0.5~1.5cm，数目约6个），表面湿润、灰白或淡红，醋酸白试验阳性（涂5%醋酸后变白，辅助诊断），无破溃出血及恶臭（无继发感染），双侧腹股沟淋巴结未触及肿大。","辅助检查":"【必做】临床诊断为主（典型菜花状赘生物）；醋酸白试验（辅助）；【病原学】HPV核酸检测或分型（区分高危型（16、18等，与宫颈癌相关）与低危型（6、11，为尖锐湿疣主要型别），取生殖道标本）、宫颈细胞学检查（女性，HPV感染需常规宫颈癌筛查）；【性病排查】梅毒血清学、HIV抗体、淋球菌及衣原体（性伴侣评估）。","初步诊断":"1. 尖锐湿疣（肛门生殖器疣，HPV感染，多为低危型6及11型）\n（注：治疗以去除疣体加防复发为原则：外用药（患者自行或医生指导下使用：咪喹莫特乳膏5%（每周3次睡前，局部免疫，防复发）、鬼臼毒素酊（0.5%，每日2次×3天停4天，孕妇禁用）、干扰素凝胶）；物理去除（冷冻、激光、电灼，快速去除，适用于数目多、体积大者）；手术切除（巨大疣或药物及物理治疗无效者）；治疗期间禁性生活（防传播）、性伴侣同治及筛查（重要，防再感染）；女性需行宫颈HPV筛查及随访（防宫颈病变）；孕妇妊娠期疣可暂观察（部分产后消退），治疗需权衡（禁用鬼臼毒素及咪喹莫特）；随访（复发常见，治疗后2周、1月、3月复查，常需多疗程治疗，免疫低下者更顽固）；HPV疫苗（预防，建议接种）。）","处理方案":"【药物治疗】\n1. 外用首选：5%咪喹莫特乳膏，每周3次（隔日1次）睡前涂于疣体及周围1cm正常皮肤，轻揉至吸收，次日晨起用肥皂水清洗，疗程8～12周，最长不超过16周，适用于疣体较小（直径<1cm）者；疣体较大或数目较多时先行激光/冷冻等物理去除，再外用本药防复发。\n2. 替代外用：0.5%鬼臼毒素酊，每日早晚各涂1次，连续3天，停药4天为1个疗程，疣体直径≤10mm、单个疣体数目<20个者适用，最多重复4个疗程，涂药后待干燥再穿衣，避免接触正常皮肤及黏膜。\n3. 物理治疗（CO₂激光、液氮冷冻、电灼）术后创面外用重组人干扰素α-2b凝胶，每日4次，涂于创面及周围，连用2～4周，减少复发。\n4. 免疫调节：复发或疣体广泛者予重组人干扰素α-2b注射液300万IU皮下注射，隔日1次，疗程4周，与局部治疗联合患者。\n【一般治疗及生活指导】\n1. 治疗期间及停药随访期内避免性生活；确需同房应全程使用避孕套，性伴侣须同时检查并同治，防止交叉再感染。\n2. 保持外生殖器及肛周清洁干燥，穿宽松棉质内裤并勤更换，内衣裤煮沸或阳光下暴晒消毒，避免搔抓、摩擦疣体以防自身接种扩散。\n3. 注意休息、避免熬夜劳累，戒烟限酒，保证营养均衡，适当锻炼，提高机体免疫力以降低复发率。\n4. 妊娠期及哺乳期禁用鬼臼毒素和咪喹莫特，孕期尖锐湿疣须由专科医师评估后处理，忌自行用药。\n【随诊要求】\n1. 治疗期间每1～2周复诊1次，评估疣体消退情况、有无新发疣体及药物不良反应。\n2. 物理治疗或药物疗程结束后分别于1个月、3个月、6个月复查，连续随访6个月无新发疣体视为临床治愈。\n3. 用药部位出现明显红肿、糜烂、疼痛、继发感染，或疣体增大增多、渗液出血时，随时复诊，勿自行增加用药频次。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":475,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"cf2a4da7ab614248a14425fa68c6c05211dc7db01e3243e9f6dd3815093b646f","pinyin":"jianruishiyou","initials":"jrsy","setting":"out","caseName":"门诊病历340","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历340",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-d8b877d9fa858d1d7d54","key":"v1-c9ccc21dfe2a3058|templates-d8b877d9fa858d1d7d54","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"头癣","category":"门诊病历模板","raw":{"name":"头癣","category":"门诊病历模板","case":{"case_name":"门诊病历341","templates":{"主诉":"头皮鳞屑、断发伴瘙痒1月","现病史":"患儿于2月前出现头皮鳞屑、瘙痒，头发折断，表现为断发、灰白色鳞屑斑片，斑片内头发稀疏、折断呈黑点状（黑点癣）；或表现为脓癣，即炎性肿块结节、毛囊化脓，可致永久性脱发瘢痕。发病以来有无接触患病猫狗（犬小孢子菌为动物源头癣常见病原）、共用梳子帽子毛巾、托幼机构或学校接触史（人传人），有无发热、淋巴结肿大（脓癣即Kerion，炎性反应重）：无上述接触史，无发热及淋巴结肿大。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.8℃，P96次/分，R22次/分，BP90/60mmHg。头皮可见鳞屑性斑片，边界清、灰白色、断发呈黑点状；或炎性肿块，即脓癣，表现为脓肿样结节、压痛、挤压溢脓、表面断发松动。颈后、耳后淋巴结肿大（脓癣时），其余皮肤及甲无体癣、甲癣并存。","辅助检查":"检查计划：患儿头皮鳞屑、断发伴瘙痒1月，斑片内头发稀疏、折断呈黑点状，考虑头癣，完善真菌镜检（取断发及鳞屑行10%KOH涂片）寻找孢子及菌丝，明确有无真菌感染，为确诊首选检查；完善伍德灯检查了解有无亮绿色荧光，辅助判断致病菌种类及感染类型；完善真菌培养检查明确病原菌种（菌种鉴定），指导抗真菌药物选择并具流行病学意义；如表现为脓癣、炎性肿块结节伴毛囊化脓，或皮损不典型难以确诊，完善皮肤病理检查明确诊断，排除其他肉芽肿性病变。头癣必须口服抗真菌药物（灰黄霉素、特比萘芬等），疗程6~8周，用药前完善肝肾功能检查评估基线水平，用药期间定期复查肝功能，警惕药物性肝损伤；患儿有无发热及淋巴结肿大需评估炎症程度，查血常规了解白细胞及中性粒细胞水平，必要时查CRP明确有无继发细菌感染。疗程结束复查真菌镜检，连续3次阴性方判断为治愈；治疗期间定期随访，观察新发皮损及有无瘢痕性脱发。\n\n（检查清单）\n【必做】真菌镜检（断发/鳞屑10%KOH涂片：见孢子和/或菌丝，发内或发外孢子，确诊）、伍德灯检查（发内感染，亮绿色荧光，大小孢子菌感染，辅助）；【确诊】真菌培养（菌种鉴定，治疗及流行病学意义）；【其他】皮肤病理（脓癣/不典型）。","初步诊断":"1. 头癣（黑点癣型：白癣（发外型，犬小孢子菌）/黑点癣（发内型，毛癣菌）/黄癣/脓癣）\n（注：治疗必须口服抗真菌药（外用药不能透入毛囊，故无法根治，此为关键）：灰黄霉素微粒型15~20mg/kg/d×6~8周（儿童一线用药，对犬小孢子菌疗效佳）或特比萘芬250mg qd（成人发内感染、黑点癣）或伊曲康唑；脓癣需口服抗真菌药加短期糖皮质激素（减轻炎症反应，防止瘢痕秃发；化脓时勿切开引流）；辅助治疗：外用抗真菌洗剂（2%酮康唑洗剂洗头，每日1次，减少传染）、外涂抗真菌药膏（头皮，辅助）；处理传染源（患病宠物予兽医治疗或隔离）、消毒（梳子帽子毛巾煮沸或丢弃）、学校托幼机构排查接触者（人传人）；疗程结束复查真菌镜检（连续3次阴性为治愈）；治愈后遗留瘢痕性脱发（脓癣）需美容评估。）","处理方案":"【药物治疗】\n1. 口服抗真菌药（首选）：盐酸特比萘芬片 250mg qd po，疗程6周；或灰黄霉素微粒型片 0.5g bid po，疗程6-8周（服药期间嘱高脂餐后服用以增加吸收）。\n2. 抗真菌洗剂：2%酮康唑洗剂洗头，每日1次，泡沫停留5-10分钟后冲洗，连续使用8周。\n3. 外用药：1%盐酸特比萘芬乳膏或联苯苄唑乳膏涂搽患处，每日2次，连续4-8周，与口服药联合使用。\n\n【一般治疗及生活指导】\n1. 剃发：治疗前剪短或剃净病发，此后每周剃发1次，连续4周，以利于药物渗透并去除带菌病发。\n2. 消毒隔离：患者毛巾、枕巾、帽子、梳子及理发工具每周煮沸或日光暴晒消毒1-2次；不与他人共用上述物品，避免交叉感染。\n3. 饮食与休息：均衡营养，保证优质蛋白及B族维生素摄入；规律作息，避免熬夜劳累，增强机体免疫力以利康复。\n4. 禁忌：避免搔抓患处，防止继发细菌感染；家中猫、犬等宠物如患皮肤癣病应同步治疗，防止人畜互传。\n\n【随诊要求】\n1. 治疗第2、4、6周及疗程结束复诊，复查真菌镜检，连续2次镜检阴性方可判定临床治愈，治愈后建议再随诊1-2次以确认无复发。\n2. 口服灰黄霉素或特比萘芬期间，如出现恶心、上腹不适、皮疹、肝区不适等，及时复诊并复查肝功能。\n3. 家庭成员及密切接触者如有类似脱发、断发或头皮鳞屑，应同时就诊筛查，同步治疗以防反复传染。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":476,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"183e079030c0805d537d420570680216cf669ca56b4c88896c839c8cc59ecb59","pinyin":"touxuan","initials":"tx","setting":"out","caseName":"门诊病历341","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历341",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-cfe29a2d6052bca14b9e","key":"v1-c9ccc21dfe2a3058|templates-cfe29a2d6052bca14b9e","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"念珠菌病","category":"门诊病历模板","raw":{"name":"念珠菌病","category":"门诊病历模板","case":{"case_name":"门诊病历342","templates":{"主诉":"口腔黏膜白色假膜伴疼痛3天","现病史":"患者于3天前出现口腔损害，即鹅口疮：颊黏膜、舌面白色凝乳样假膜，拭去后见潮红糜烂面，常见于婴幼儿、免疫低下者、长期广谱抗生素使用者或吸入激素后；皮肤皱褶损害即间擦疹：腋窝、腹股沟、乳房下红斑糜烂，周边卫星状丘疹脓疱；外阴阴道损害：外阴瘙痒灼痛、白带豆腐渣样；龟头损害：包皮龟头炎。有无糖尿病（未控制者为重要易感因素，反复念珠菌感染必查）、长期抗生素/糖皮质激素/免疫抑制剂使用、HIV/免疫低下、HIV感染（口咽念珠菌病为重要线索）、妊娠（阴道念珠菌病常见）、卫生习惯：无糖尿病及免疫低下，近期无抗生素、糖皮质激素及免疫抑制剂使用，否认妊娠，卫生习惯良好。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T37.4℃，P88次/分，R20次/分，BP115/75mmHg。口腔：颊黏膜、舌面、咽部可见白色凝乳样假膜，拭去见潮红糜烂面；皮肤皱褶：红斑、浸渍、糜烂，周边卫星状丘疹脓疱；外阴阴道：外阴红斑水肿、阴道黏膜充血、白带豆腐渣样凝块；龟头：红斑、白色分泌物。","辅助检查":"【必做】真菌镜检（假膜/白带/皮屑KOH涂片，见假菌丝和孢子，可确诊）、真菌培养（菌种及药敏，用于治疗无效或系统感染）；【基础病】血糖（糖尿病筛查，反复感染者必查）、HIV检测（口咽念珠菌病或顽固性者免疫评估）、血常规（中性粒细胞减少）。","初步诊断":"1. 念珠菌病（口腔念珠菌病/皮肤念珠菌病/外阴阴道念珠菌病）\n（注：口腔念珠菌病予制霉菌素混悬液含漱或涂布（儿童用克霉唑含片）、氟康唑100~200mg qd（免疫低下或重症者口服）；皮肤皱褶念珠菌病予保持干燥加抗真菌乳膏（克霉唑/咪康唑乳膏bid×1~2周）；外阴阴道念珠菌病予克霉唑栓（500mg单次或100mg×7天）或口服氟康唑150mg单剂（非妊娠者），妊娠者予局部唑类（克霉唑，勿口服）；反复发作（>4次/年）者予强化加维持（氟康唑150mg每周1次×6个月），并治疗诱因（糖尿病控制、停用抗生素）；治疗基础病（免疫低下者必要时系统抗真菌）；注意交叉感染（伴侣同治，龟头炎）；婴儿鹅口疮需母亲乳头及奶瓶消毒防再感染；疗效不佳者行药敏及菌种鉴定（光滑念珠菌、克柔念珠菌耐药，对氟康唑天然耐药，需棘白菌素/两性霉素（系统感染））。）","处理方案":"【药物治疗】\n1. 氟康唑胶囊150mg qd，首日加倍至300mg，疗程7-14天（适用于口腔、食管及皮肤黏膜念珠菌病）；单纯性外阴阴道念珠菌病可予氟康唑150mg单剂口服。\n2. 制霉菌素片50万U po qid×7-14天，或制霉菌素混悬液局部含漱/涂布（适用于口腔、消化道念珠菌病，不吸收入血，局部疗效佳）。\n3. 克霉唑阴道片500mg每晚1次置阴道深部×1天，或150mg每晚1次×7天；外阴皮肤损害可加用克霉唑乳膏外涂bid×7-14天。\n4. 伊曲康唑胶囊200mg bid×1天（顿服疗法），或200mg qd×7天（适用于氟康唑耐药或不能耐受氟康唑者）。\n【一般治疗及生活指导】\n1. 保持患处及会阴部清洁干燥，勤换纯棉内衣裤，内衣裤及毛巾煮沸消毒或阳光暴晒；治疗期间避免性生活，性伴侣如有症状需同时治疗。\n2. 糖尿病患者务必严格控制血糖，将空腹血糖及餐后血糖控制在目标范围；避免长期、滥用广谱抗生素、糖皮质激素及免疫抑制剂。\n3. 饮食清淡均衡，减少甜食及高糖饮料摄入，适当增加富含B族维生素食物；规律作息，保证充足睡眠，避免熬夜、过度劳累，适当运动增强免疫力。\n4. 口腔念珠菌病者注意口腔卫生，勤漱口、更换牙刷，义齿者睡前取下并清洁浸泡。\n【随诊要求】\n1. 治疗结束后7-14天复诊评估疗效；症状无缓解或加重者及时复诊，必要时行真菌培养及药敏试验。\n2. 反复发作（1年内≥4次）或难治性念珠菌病需复诊，进一步排查糖尿病、免疫缺陷、HIV感染、恶性肿瘤等基础疾病并调整方案。\n3. 孕妇、肝肾功能异常者，以及合并使用华法林、磺脲类降糖药等药物者，按医嘱定期复查肝肾功能、监测INR及血糖。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":477,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"279d8ef58b6d17efd6d4959d9ea4698669bc99b46507e35bec1f9665cd219253","pinyin":"nianzhujunbing","initials":"nzjb","setting":"out","caseName":"门诊病历342","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历342",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-ada0111ca62f0957be33","key":"v1-c9ccc21dfe2a3058|templates-ada0111ca62f0957be33","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"隐球菌病","category":"门诊病历模板","raw":{"name":"隐球菌病","category":"门诊病历模板","case":{"case_name":"门诊病历343","templates":{"主诉":"头痛、发热伴意识改变2周","现病史":"患者（免疫低下者，如HIV/AIDS（CD4<100最常见）、器官移植、长期糖皮质激素、血液病，或免疫功能正常者）于2周前出现下列表现：中枢型为亚急性起病头痛、发热、恶心呕吐、颈强、视力模糊、意识改变，以脑膜炎最常见；肺型为咳嗽、胸痛、低热、呼吸困难，酷似结核/肿瘤；皮肤型为丘疹、脓疱、溃疡、皮下结节，脐凹样皮疹可似传染性软疣。有无鸽粪、鸟类接触史：无鸽粪及鸟类接触史。有无HIV及其他免疫抑制因素：否认HIV感染及其他免疫抑制因素。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T38.2℃，P88次/分，R20次/分，BP120/75mmHg。神志嗜睡（中枢受累），颈抵抗（+）（脑膜刺激征），眼底视乳头水肿（颅高压），皮肤散在脐凹样丘疹、结节（躯干及四肢），肺部听诊可闻及湿啰音，神经系统检查示颅神经受累，外展麻痹可因颅高压所致。","辅助检查":"【必做】脑脊液检查（中枢型予墨汁染色找隐球菌（阳性率约50~70%）、隐球菌抗原（CrAg，乳胶凝集法，患者感高特异，血清及脑脊液）、脑脊液常规生化（淋巴细胞为主、糖降低，为结核/隐球菌特征）、脑脊液培养）；血清隐球菌抗原（肺型或筛查，免疫低下者重要）；【影像】头颅CT/MRI（脑膜强化、隐球菌瘤、胶样假性囊肿）、胸部CT（肺隐球菌见结节、实变、空洞）；【其他】HIV检测（隐球菌病免疫低下评估，必须）、T细胞亚群（CD4计数）。","初步诊断":"1. 隐球菌病（中枢神经系统型（隐球菌脑膜炎）/肺型/播散型）\n（注：中枢隐球菌病需住院，诱导期予两性霉素B脂质体（0.7~1mg/kg/d）联合氟胞嘧啶100mg/kg/d分4次×2周（首选，需肾功能监测），巩固期予氟康唑400mg qd×8周，维持期予氟康唑200mg qd（≥1年，免疫低下者长期）；颅高压处理（反复腰穿放液或腰大池引流，必要时降颅压，此为关键，防失明及脑疝）；肺隐球菌（免疫正常轻症）予氟康唑400mg qd×6~12个月；治疗原发免疫缺陷（HIV者启动抗反转录病毒治疗，注意免疫重建炎症综合征）；监测（脑脊液隐球菌抗原滴度、肾功能、肝功能，注意两性霉素肾毒性）；重症及免疫低下者由多学科（感染科/神经科）管理。）","处理方案":"【药物治疗】\n1. 氟康唑胶囊（大扶康）400mg 口服 每日1次（首日可予800mg负荷量），疗程6-12个月；为非HIV、非移植患者轻中度肺隐球菌病的首选及巩固/维持期治疗，门诊常规使用。\n2. 伏立康唑片 200mg 口服 每日2次（首日负荷400mg每12小时1次共2次），用于氟康唑耐药、不能耐受或难治性病例，疗程6-12个月，用药期间监测肝功及血药浓度。\n3. 氟胞嘧啶片 25mg/kg 口服 每日4次，与氟康唑联合用于重症或播散性隐球菌病诱导期（建议住院评估），门诊联用须每周监测血常规、肝肾功能。\n4. 高度怀疑或确诊隐球菌脑膜炎者不属门诊单纯用药范围，应住院予两性霉素B+氟胞嘧啶诱导治疗，病情稳定、脑脊液培养转阴后方可转门诊氟康唑巩固维持。\n\n【一般治疗及生活指导】\n1. 注意休息，避免劳累、熬夜及重体力活动，保证充足睡眠，提高机体免疫力；有发热或病灶明显者建议卧床休息。\n2. 避免接触鸽粪、鸟禽排泄物及发霉尘土等隐球菌污染源，清理鸽舍、鸟笼、老旧房屋时须佩戴口罩及手套并做好通风。\n3. 均衡营养，进食高蛋白、高维生素易消化饮食，保证充足饮水，忌烟酒及辛辣刺激食物。\n4. 每日监测体温，若出现发热、头痛、恶心呕吐、视物模糊或意识改变等提示中枢感染或播散的征象，立即就医。\n\n【随诊要求】\n1. 每2-4周门诊复诊，复查血常规、肝肾功能、电解质，长期服用氟康唑者重点监测肝功能。\n2. 治疗期间每1-3个月复查胸部CT评估肺内病灶吸收情况，疗程一般不少于6-12个月，停药前复查胸部CT及隐球菌荚膜多糖抗原。\n3. 定期复查血清（必要时脑脊液）隐球菌抗原滴度，直至转阴；治疗结束后继续随访至少1年，每3-6个月复查1次。\n4. 治疗中出现新发头痛、呕吐、视力障碍、颈项强直或原有症状加重者，须立即复诊并完善头颅MRI、腰椎穿刺检查以排除中枢感染。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":478,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"db2c432399db2ed6c2f1d6b996f62a91ee0f4ce1cc7d731766db73095d609774","pinyin":"yinqiujunbing","initials":"yqjb","setting":"out","caseName":"门诊病历343","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历343",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-8a3216c2e39439d26dad","key":"v1-c9ccc21dfe2a3058|templates-8a3216c2e39439d26dad","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"孢子丝菌病","category":"门诊病历模板","raw":{"name":"孢子丝菌病","category":"门诊病历模板","case":{"case_name":"门诊病历344","templates":{"主诉":"皮肤结节破溃流脓1月","现病史":"患者于1月前在手部（手/前臂最常见，园艺/农业劳动者，接触带刺植物（玫瑰/荆棘）、泥土、苔藓，属接种性真菌病）外伤后出现单个结节，初为无痛性炎性结节，渐增大破溃流脓，不易愈合，此后沿引流淋巴管向近端出现成串排列的新结节（淋巴管型，最常见，为特征性表现）。有无固定型（原发部位单个慢性溃疡/斑块）、播散型（免疫低下者多部位皮肤及内脏受累）：无固定型及播散型表现。无发热或低热，一般情况可。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.9℃，P80次/分，R18次/分，BP118/76mmHg。手背可见原发结节及溃疡，呈暗红色、边缘隆起、表面结痂或脓性渗出，沿淋巴管走行方向可见3个串珠状排列的皮下结节（直径约1~2cm、活动度可、轻压痛），区域淋巴结可肿大但无痛。","辅助检查":"【必做】真菌镜检（脓液/组织KOH涂片：孢子少见，阳性率低，不能排除）、真菌培养（25~30℃沙保培养基，双相真菌，见孢子丝菌，确诊金标准，需2~4周）、组织病理（PAS染色：孢子及星状体，肉芽肿性炎症）；【其他】免疫低下者，播散评估（胸片、关节、脑脊液：疑播散时）。","初步诊断":"1. 孢子丝菌病（淋巴管型/固定型/播散型）\n（注：治疗以口服抗真菌为首选：伊曲康唑200mg qd（餐后服，吸收好）或碘化钾饱和溶液（10%，从5滴tid渐增，有效但副作用多，可见胃肠刺激、皮疹），疗程至皮损消退后继续2~4周（常需2~6个月，淋巴管型疗程长）；重症/播散/免疫低下者予两性霉素B脂质体（诱导）后伊曲康唑维持；局部予热敷（孢子丝菌不耐热，辅助）、避免挤压；皮损多或深部者可外科清创（不单独依赖，需配合抗真菌）；注意防再感染（劳作时戴防护手套）；免疫低下者（HIV/移植）需长期维持治疗；随访至皮损完全消退、培养转阴。）","处理方案":"【药物治疗】\n1. 抗真菌药（唑类，首选）：伊曲康唑胶囊200mg qd口服，餐后服用，疗程2～4个月（皮损完全消退后继续服用2～4周以防复发）；淋巴管型或疗效欠佳者可增至200mg bid。\n2. 抗真菌药（丙烯胺类，替代）：盐酸特比萘芬片250mg qd口服，疗程2～4个月，用于不能耐受伊曲康唑者。\n3. 碘化钾（传统治疗，用于固定型及淋巴管型、无碘过敏者）：10%碘化钾溶液口服，自5ml tid起始，每3～5日递增1ml至10ml tid，疗程6～12周；出现流涎、流涕、皮疹等碘中毒表现时减量或停药。\n【一般治疗及生活指导】\n1. 注意休息，避免劳累；加强营养，保证优质蛋白及新鲜蔬果摄入，增强机体免疫力，促进皮损愈合。\n2. 保持皮损局部清洁干燥，勿搔抓、勿自行挤压排脓，防止继发细菌感染及自体接种扩散；换药物品及敷料集中处理，避免污染环境。\n3. 减少接触可能带菌的土壤、腐木、苔藓及玫瑰、芦苇等植物；从事园艺、农林业等作业时戴手套、穿长袖衣，皮肤外伤后及时清洁消毒。\n4. 治疗期间禁酒，避免与伊曲康唑相互作用的药物（如利福平、卡马西平、苯妥英钠等）同用，以免影响疗效或加重肝损伤。\n【随诊要求】\n1. 每2～4周门诊复诊，评估结节、溃疡及淋巴管串珠样皮损消退情况，依据疗效调整剂量与疗程。\n2. 服用伊曲康唑期间每月复查肝功能；出现恶心、食欲减退、乏力或皮肤巩膜黄染者及时就诊。\n3. 皮损消退后再服药2～4周可停药，停药后随访观察2～3个月确认无复发。\n4. 治疗中出现皮损增多、新发结节、发热或咳嗽、骨关节疼痛等全身症状者，立即复诊排查播散性感染。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":479,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"4ab411422eb6675923e37068bf2ada283ac49d57eb1d1a0f862bd68815caf1ec","pinyin":"baozisijunbing","initials":"bzsjb","setting":"out","caseName":"门诊病历344","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历344",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-e9923fe41cf9c1e7c14a","key":"v1-c9ccc21dfe2a3058|templates-e9923fe41cf9c1e7c14a","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"着色真菌病","category":"门诊病历模板","raw":{"name":"着色真菌病","category":"门诊病历模板","case":{"case_name":"门诊病历345","templates":{"主诉":"下肢疣状增生性斑块逐渐扩大1年","现病史":"患者（农民/户外劳动者，赤足工作者多见）于1年前在足部（足/小腿，下肢最常见，外伤（木刺/植物刺伤）后）出现丘疹，渐增大为暗红色疣状增生性斑块/结节，表面角化、覆鳞屑痂皮，缓慢扩大、中央可瘢痕化，周围可见卫星灶（自体接种）。有无继发感染、溃疡、疼痛（晚期可致淋巴水肿、象皮肿等慢性并发症）：无继发感染、溃疡及疼痛，无淋巴水肿。一般情况可，无发热。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.7℃，P78次/分，R18次/分，BP120/78mmHg。足背可见5cm疣状增生性斑块（暗红色/灰褐色、表面角化增生、覆鳞屑及痂皮、质硬、边界清），部分区域破溃、渗出及瘢痕化，周围可见卫星状小结节，患肢无肿胀及淋巴水肿。","辅助检查":"检查计划：患者为农民、户外劳动者，1年前足部外伤后出现暗红色疣状增生性斑块并缓慢扩大，表面角化、覆鳞屑痂皮，周围见卫星灶，考虑着色真菌病，完善真菌镜检（取痂皮及组织行10%KOH涂片）寻找棕色厚壁分隔孢子（硬壳小体），此为特征性确诊线索；完善真菌培养检查（着色霉、瓶霉等，需3~4周）明确病原菌种，指导抗真菌药物选择，因培养周期长需耐心等待结果；完善组织病理检查了解表皮假上皮瘤样增生、真皮肉芽肿伴棕色厚壁孢子等特征性改变，明确诊断并与皮肤结核、鳞状细胞癌等鉴别。本病需长疗程口服伊曲康唑、特比萘芬等抗真菌药物，用药前完善肝肾功能检查评估基线水平，治疗期间每1~3个月复查肝功能，警惕药物性肝损伤，同时查血常规了解有无骨髓抑制；皮损表面角化、覆痂皮，为评估有无继发感染，查血常规及CRP了解炎症程度；为明确深部组织及骨骼有无受累，必要时完善病变部位MRI检查明确侵犯范围，必要时完善下肢静脉彩超评估有无淋巴水肿。治疗期间每2~3个月复查真菌镜检并皮损照相，评估疗效及有无复发。\n\n（检查清单）\n【必做】真菌镜检（痂皮/组织KOH涂片：见棕色厚壁分隔孢子（硬壳小体：铜币状）：特征性，确诊线索）、真菌培养（着色真菌，需3~4周）；【确诊】组织病理（表皮假上皮瘤样增生、真皮肉芽肿伴棕色厚壁孢子，棕色真菌（着色霉/瓶霉/枝孢霉），确诊）。","初步诊断":"1. 着色真菌病（暗色丝孢霉病型，病原为着色霉/瓶霉等）\n（注：治疗困难，需长疗程：口服抗真菌予伊曲康唑200~400mg/d（一线用药，疗程6~12个月以上，皮损消退后继续数月）或特比萘芬250mg bid、泊沙康唑（难治性）；联合治疗（顽固者予伊曲康唑加特比萘芬或5-氟胞嘧啶（参考药敏））；物理治疗（配合）：手术切除（早期小病灶，完整切除）、液氮冷冻、温热疗法（局部加热，着色真菌不耐热，42℃，辅助）、激光；并发症处理（继发感染予抗感染；淋巴水肿予抬高患肢/弹力袜）；防再感染（劳作时防护，防外伤）；疗程长易复发，需耐心随访（每2~3个月评估，皮损照相、真菌复查），由皮肤科专科管理。）","处理方案":"【药物治疗】\n1．伊曲康唑胶囊200mg bid口服（随餐服用），为首选系统抗真菌药；疗程6～12个月，皮损完全消退后再巩固治疗2～4周，治疗期间每1～3个月监测肝功能。\n2．联合方案：伊曲康唑胶囊200mg bid＋特比萘芬片250mg qd口服，适用于难治、复发或深部受累病例，疗程延长至12个月以上，注意复查肝肾功能及血常规。\n3．局部治疗：对孤立小病灶可先行手术切除、CO2激光或液氮冷冻去除皮损，术后继续口服抗真菌药巩固；浅表斑块可外用咪康唑乳膏或酮康唑乳膏涂患处bid，涂药范围根据患者具体情况制定个体化方案超出皮损边缘。\n【一般治疗及生活指导】\n1．保持皮损局部清洁干燥，避免搔抓、摩擦及外伤，防止病灶自体接种扩散和继发细菌感染。\n2．避免赤脚在潮湿土壤、腐木及农田环境中行走或劳作，田间作业时穿长筒胶靴、戴防护手套，减少再次接触病原菌。\n3．坚持规律服药、足量足疗程，不得自行减量或停药；服药期间禁酒，避免同时服用其他肝毒性药物。\n4．注意休息、均衡饮食、增强体质；长期户外及农业劳动者应加强皮肤防护，发现新发皮损及时就医。\n【随诊要求】\n治疗期间每2～4周复诊，评估皮损消退情况及药物不良反应；口服抗真菌药期间每1～3个月复查肝功能、血常规；疗程结束停药后仍需随访6～12个月，观察有无复发，若原部位或邻近区域再次出现结节、斑块应及时复诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":480,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"898c70c36e9024a6834114dd72bbb832a6f116e995e1193257b3528d02d39cbc","pinyin":"zhuosezhenjunbing","initials":"zszjb","setting":"out","caseName":"门诊病历345","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历345",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-277f3bae9a0b02f11bfa","key":"v1-c9ccc21dfe2a3058|templates-277f3bae9a0b02f11bfa","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"神经性皮炎","category":"门诊病历模板","raw":{"name":"神经性皮炎","category":"门诊病历模板","case":{"case_name":"门诊病历346","templates":{"主诉":"颈项苔藓样斑块伴剧烈瘙痒1年","现病史":"患者于1年前在颈后、颈侧（颈后颈侧最常见/肘窝腘窝伸侧/腰骶/眼睑/外阴，属易摩擦搔抓部位）出现瘙痒，反复搔抓后皮肤渐增厚呈苔藓样变，形成边界清楚的肥厚性斑块，阵发性剧烈瘙痒（夜间及情绪紧张时加重，形成瘙痒-搔抓-增厚循环）。有无精神紧张焦虑、失眠、生活压力等诱因（心身因素重要）；有无湿疹/特应性皮炎/接触过敏等原发皮肤病（继发性苔藓样变）：有精神紧张及失眠诱因，无原发皮肤病。无发热。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.8℃，P76次/分，R18次/分，BP120/80mmHg。颈后部位可见境界清楚的苔藓样变斑块（皮纹加深、皮嵴隆起呈菱形或多角形、表面干燥覆少量鳞屑、色素沉着，大小约5cm×4cm），周围可见抓痕及血痂，无渗出、无糜烂，其他部位皮肤正常。","辅助检查":"【必做】一般临床诊断为主；【其他】过敏原检测（排除特应性皮炎，疑合并过敏时）、真菌镜检（排除体癣：边界清环形皮损）、皮肤病理（苔藓样变不典型或疑恶变时，少见）。","初步诊断":"1. 神经性皮炎（局限性，慢性单纯性苔藓）\n（注：核心为止痒及打断搔抓循环：①外用糖皮质激素（中强效：糠酸莫米松/卤米松乳膏，肥厚苔藓样变需强效（倍他米松），顽固小灶可皮损内注射（曲安奈德））；②口服抗组胺药（止痒助眠，氯雷他定10mg qd或西替利嗪，夜间瘙痒明显者用第一代（扑尔敏/羟嗪）睡前）；③心理行为干预（缓解压力，焦虑明显者抗焦虑治疗，此点重要，本病与精神紧张密切相关）；④避免搔抓（剪短指甲、冷敷替代）、避免刺激（辛辣、酒精、化纤毛织、热水烫洗）；⑤保湿护肤；⑥窄谱中波紫外线（顽固泛发者光疗）；治疗原发皮肤病（继发性者）；多数可控制，但易复发，需坚持用药至皮损消退后渐减并持续保湿，随访。）","处理方案":"【药物治疗】\n1. 口服抗组胺止痒药：氯雷他定片10mg qd，或西替利嗪片10mg qd，睡前服，连用2周。\n2. 外用糖皮质激素：糠酸莫米松乳膏（艾洛松）外用患处qd，连续2周，苔藓化明显者可夜间封包治疗；皮损增厚顽固者改用卤米松乳膏外用qd，疗程不超过4周，症状缓解后逐渐减量或换用弱效激素。\n3. 止痒润肤辅助：多塞平乳膏外用患处bid（单日不超过15g），配合保湿剂（如尿素软膏）外用bid修复皮肤屏障。\n【一般治疗及生活指导】\n1. 严格避免搔抓、摩擦及热水烫洗，瘙痒时轻拍或冷敷缓解，剪短指甲。\n2. 忌食辛辣刺激食物，戒除烟酒，避免浓茶、咖啡及海鲜等易致痒饮食。\n3. 保持情绪稳定，规律作息，保证充足睡眠，避免精神紧张、焦虑及过度劳累；压力大时建议心理疏导。\n4. 穿宽松纯棉衣物，避免化纤、羊毛等材质直接接触皮损，减少局部刺激。\n【随诊要求】\n用药2周后复诊评估皮损及瘙痒改善情况；若瘙痒加重、皮损扩大或出现红肿渗液、继发感染（脓疱、发热等），应立即复诊。停用激素后如1个月内复发，需复诊调整治疗方案；长期反复发作者建议定期随访，排除合并其他皮肤病，必要时行皮肤活检明确诊断。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":481,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"74bcab1a7a7d947f4a6108f9d312edd392f8bef3af471143104fc83f699faf9f","pinyin":"shenjingxingpiyan","initials":"sjxpy","setting":"out","caseName":"门诊病历346","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历346",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-5010d2c730f25f43642a","key":"v1-c9ccc21dfe2a3058|templates-5010d2c730f25f43642a","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"瘙痒症","category":"门诊病历模板","raw":{"name":"瘙痒症","category":"门诊病历模板","case":{"case_name":"门诊病历347","templates":{"主诉":"全身皮肤瘙痒无皮疹1月","现病史":"患者于1月前出现全身皮肤瘙痒，无皮疹（抓后可出现抓痕等继发改变，但无原发性皮损，符合瘙痒症定义），夜间及脱衣后加重，热水烫洗暂缓解后更痒（洗烫依赖，常见行为）。有无皮肤干燥（老年性瘙痒，皮脂减少、冬季加重）、系统疾病线索（糖尿病、肝胆疾病（胆汁淤积性瘙痒）、慢性肾病（尿毒症瘙痒）、甲状腺功能异常、贫血、血液病（真红/淋巴瘤，霍奇金病瘙痒显著）、恶性肿瘤（副肿瘤性瘙痒）、药物（阿片类/氯喹）、精神紧张）；有无新用药及洗护习惯改变：有皮肤干燥及糖尿病病史，无新用药及洗护习惯改变。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.6℃，P74次/分，R18次/分，BP126/80mmHg。皮肤干燥脱屑，无原发疹，可见抓痕、线状表皮剥脱、血痂、色素沉着（继发于搔抓），皮肤黄染（-）、贫血貌（-）、浅表淋巴结（-肿大）。","辅助检查":"【必做】血常规（贫血/嗜酸粒细胞增多/白血病）、血糖、肝肾功能（胆红素及ALP，查肝病）、甲状腺功能、铁蛋白、总胆红素及胆汁酸（胆汁淤积）；【肿瘤筛查】胸部X线/CT、肿瘤标志物（不明原因顽固瘙痒、年龄大者，筛查副肿瘤性瘙痒）；【其他】HIV检测（高危者）、皮肤活检（疑原发性皮肤病但无疹时，少用）、疥疮排除（夜间痒，查疥虫，仔细检查指缝）。","初步诊断":"1. 皮肤瘙痒症（老年性/全身性/局限性，病因待查）\n（注：①病因治疗（核心，查明并治疗基础病：糖尿病控糖、肝病利胆（熊去氧胆酸，胆汁淤积）、尿毒症（透析优化/加巴喷丁）、缺铁补铁、甲功纠正）；②对症止痒：口服抗组胺药（西替利嗪/氯雷他定白天用；羟嗪/多塞平夜间用，兼助眠）、外用止痒（薄荷脑/樟脑乳膏、多塞平乳膏、辣椒素乳膏（局限性神经性瘙痒））；③皮肤护理（避免热水烫洗及碱性皂，温水浴后即涂保湿剂（尿素软膏/凡士林，老年干燥性瘙痒关键）、穿着纯棉宽松）；④物理治疗（UVB光疗，用于尿毒症/顽固性）；⑤严重顽固者：加巴喷丁/普瑞巴林（尿毒症/胆汁淤积，一线证据）、阿片受体调节剂（纳呋拉啡，尿毒症瘙痒）、抗抑郁药（SSRI/米氮平，精神因素）；⑥戒酒、避免辛辣咖啡因；随访评估病因及疗效。）","处理方案":"【药物治疗】\n1. 抗组胺药：依巴斯汀片10mg po qd×2周（或氯雷他定片10mg po qd）；瘙痒剧烈、影响夜间睡眠者，可加用赛庚啶片2mg 睡前口服×1周。\n2. 外用止痒剂：复方樟脑乳膏外用瘙痒部位 bid×2周；皮肤干燥明显者，配合10%尿素软膏外用 qd，浴后全身涂抹。\n3. 外用糖皮质激素（有抓痕、苔藓化等皮损时）：丁酸氢化可的松乳膏外用 bid，连用≤2周，皮损消退即停；避免用于面部及皮肤皱褶部位，勿长期大面积使用。\n4. 顽固性瘙痒（老年性瘙痒或伴慢性肾病、胆汁淤积等基础病）：加巴喷丁胶囊100mg 睡前口服，每3-5天增加100mg，最大300mg 睡前口服（肾功能不全者需调整剂量，首次服药后勿驾驶）。\n【一般治疗及生活指导】\n1. 洗浴：温水（37℃左右）淋浴，每次5-10分钟，避免热水烫洗、碱性肥皂及搓澡巾用力搓擦；浴后3分钟内涂抹保湿乳。\n2. 保湿：每日全身涂抹保湿乳/润肤霜1-2次，冬季及干燥环境适当增加次数，保持皮肤滋润。\n3. 饮食：忌辛辣刺激、海鲜、酒、浓茶咖啡等易诱发或加重瘙痒的食物，多饮水，保持大便通畅。\n4. 起居：穿宽松纯棉衣物，避免化纤、毛织品直接接触皮肤；勤剪指甲，避免搔抓，痒时以冷敷或轻拍替代；保持情绪稳定、规律作息。\n【随诊要求】\n治疗2周后复诊评估疗效及不良反应。若瘙痒持续不缓解或加重，或出现皮疹、皮肤继发感染、体重明显下降、乏力、发热、黄疸、多饮多尿等表现，应及时复诊，进一步完善血常规、肝肾功能、血糖、甲状腺功能及肿瘤相关筛查，排除系统性疾病所致瘙痒。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":482,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"3ba3979c34f2695bc6505d63d80056a7b04070df7fe6f2e52a671a1e94e8e231","pinyin":"saoyangzheng","initials":"syz","setting":"out","caseName":"门诊病历347","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历347",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-7b451cdd82441c32679c","key":"v1-c9ccc21dfe2a3058|templates-7b451cdd82441c32679c","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"痒疹","category":"门诊病历模板","raw":{"name":"痒疹","category":"门诊病历模板","case":{"case_name":"门诊病历348","templates":{"主诉":"四肢伸侧瘙痒性丘疹、结节1年","现病史":"患者于1年前在四肢伸侧（四肢伸侧/躯干，对称分布）出现散在丘疹，剧烈瘙痒，反复搔抓后丘疹增大形成结节（痒疹结节），部分消退留色素沉着，新疹不断出现，瘙痒以夜间为甚。有无昆虫叮咬后（丘疹性荨麻疹，儿童）、过敏体质/特应性皮炎史、精神紧张、胃肠道功能紊乱、肝肾疾病、糖尿病、淋巴瘤等系统病（痒疹可为系统病皮肤表现）：有昆虫叮咬史，无其他系统疾病。搔抓后无继发感染。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.7℃，P78次/分，R18次/分，BP118/74mmHg。四肢伸侧及躯干可见散在米粒至黄豆大丘疹及结节，质硬、表面抓痕血痂、色素沉着、部分顶部光滑发亮（结节性痒疹特征），数目约20个，新旧皮损并存，可见抓痕、血痂，无继发脓疱及感染。","辅助检查":"【必做】一般临床诊断为主；【其他】血常规（嗜酸性粒细胞，寄生虫/过敏）、大便虫卵（寄生虫，儿童）、过敏原检测（特应性皮炎，相关痒疹）、肝肾功能血糖（系统病筛查，顽固泛发者）、皮肤病理（结节性痒疹：表皮角化过度棘层肥厚排除其他肿瘤性结节）。","初步诊断":"1. 痒疹（急性（丘疹性荨麻疹，虫咬）/慢性（单纯性痒疹/结节性痒疹））\n（注：①止痒为核心：口服抗组胺药（西替利嗪/氯雷他定；夜间剧烈者予羟嗪/多塞平）；②外用：糖皮质激素（结节性者用强效，卤米松/倍他米松，封包或皮损内注射曲安奈德，结节消退快）、止痒剂（薄荷脑/辣椒素，用于结节）；③避免搔抓（剪甲、冷敷，打断痒-抓循环）；④治疗诱因：驱虫防叮咬（蚊帐/驱避剂，丘疹性荨麻疹）、治寄生虫、控制基础病（糖尿病/肝肾）、心理干预；⑤顽固泛发者予窄谱中波紫外线（光疗）、沙利度胺（结节性痒疹，难治性，需避孕，有周围神经病变风险，专科处方）、环孢素（重症）；⑥继发感染予莫匹罗星/抗生素；皮肤科随访，结节消退后可留色素沉着，需告知预后。）","处理方案":"【药物治疗】\n1. 口服抗组胺药：氯雷他定片10mg qd po，或依巴斯汀片10mg qd po，连用2～4周；瘙痒明显影响夜间睡眠者可睡前加用赛庚啶片2mg qn（或氯苯那敏片4mg qn），疗程同上。\n2. 局部外用糖皮质激素：糠酸莫米松乳膏（艾洛松）适量涂于皮损处 bid，连用1～2周，症状缓解后减为qd并逐渐停用；瘙痒剧烈、丘疹密集处可短期加用炉甘石洗剂外用止痒。\n3. 瘙痒顽固或皮疹广泛者：加用复方甘草酸苷片50mg tid po，连用2～4周；皮损严重、泛发且口服药效果不佳者，可予泼尼松片20～30mg qd po，晨起顿服，症状控制后每3～5天减量5mg，总疗程不超过2周，并注意监测血压、血糖。\n4. 继发感染者：外用莫匹罗星软膏涂于破溃、渗出处 bid，连用5～7天；感染明显伴红肿热痛者，加用阿莫西林胶囊0.5g tid po×5～7天（青霉素过敏者改用头孢呋辛酯片0.25g bid po）。\n\n【一般治疗及生活指导】\n1. 严格避免搔抓、热水烫洗及碱性皂刺激，洗澡水温不宜过高，浴后及时涂抹润肤霜（如尿素软膏、凡士林）保持皮肤保湿。\n2. 饮食忌辛辣、腥发及刺激性食物（如辣椒、酒、海鲜、牛羊肉等），多饮水，保持大便通畅。\n3. 穿宽松纯棉衣物，避免化纤、毛织品直接接触皮肤；避免精神紧张、劳累及熬夜，保证充足睡眠。\n4. 注意查找并规避可疑诱因（虫咬、药物、尘螨等），勤换洗床单被褥并暴晒，减少环境致敏因素。\n\n【随诊要求】\n1. 服药后2周复诊，评估瘙痒程度及皮疹消退情况，根据患者具体情况制定个体化方案调整抗组胺药及外用药方案。\n2. 治疗期间若出现皮疹泛发、瘙痒加剧、破溃流脓或伴发热等，应及时就诊；长期反复发作（病程超过6个月）者，建议复诊时完善血常规、血糖、肝肾功能等检查，排查潜在系统性疾病，必要时转诊皮肤专科。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":483,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"5345683e8d57f16c1685aa587fd6a88f9f9ce379d3ca3240e932f32708160525","pinyin":"yangzhen","initials":"yz","setting":"out","caseName":"门诊病历348","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历348",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-6586e3dba593fa9cac68","key":"v1-c9ccc21dfe2a3058|templates-6586e3dba593fa9cac68","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"结节性痒疹","category":"门诊病历模板","raw":{"name":"结节性痒疹","category":"门诊病历模板","case":{"case_name":"门诊病历349","templates":{"主诉":"四肢散在坚实结节伴剧烈瘙痒1年","现病史":"患者于1年前在四肢伸侧（四肢伸侧/小腿，躯干也可）出现散在坚实性结节（黄豆至蚕豆大、灰褐色、表面角化粗糙或光滑发亮），剧烈瘙痒（阵发性，难以忍受），搔抓/抠挖后不缓解反加重（痒-抓循环），结节渐增多融合，部分消退留色素沉着或瘢痕。有无精神紧张焦虑、昆虫叮咬史、特应性皮炎/湿疹史、肝肾疾病、糖尿病、甲状腺病、HIV/淋巴瘤等系统病（顽固性结节性痒疹需排查）：有昆虫叮咬史，无其他系统疾病。夜不能寐。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.8℃，P80次/分，R18次/分，BP120/76mmHg。四肢伸侧可见散在、密集约15个坚实性结节（大小约0.5~1.5cm、半球形、表面角化增厚或光滑、色灰褐/暗红、境界清），部分表面覆抓痕血痂、色素沉着，结节间皮肤可见抓痕、苔藓样变，无糜烂渗出（继发感染时可有脓痂）。","辅助检查":"【必做】一般临床诊断为主；【其他】皮肤病理（表皮角化过度棘层肥厚、真皮神经增生：结节性痒疹，排除其他结节性疾病，淋巴瘤等）、血常规嗜酸性粒细胞、肝肾功能血糖甲状腺功能（系统病：顽固者筛查）、HIV检测（高危者）、过敏原（特应性体质评估）。","初步诊断":"1. 结节性痒疹（特发性/继发于系统病/虫咬后）\n（注：治疗顽固，需多管齐下：①强效糖皮质激素外用（卤米松/氯倍他索，封包疗法，或结节内注射曲安奈德，每周1次×数次，结节明显缩小）；②口服抗组胺药（西替利嗪/氯雷他定，夜间用第一代），瘙痒重者加用加巴喷丁/普瑞巴林（神经性瘙痒，有效）、多塞平（抗抑郁，止痒）；③打破痒-抓循环（患者教育、剪甲、冷敷、心理治疗，此为关键的行为干预）；④物理治疗：液氮冷冻（结节）、窄谱中波紫外线/光动力（泛发者）、激光；⑤系统药物（难治性）：沙利度胺50~100mg qn（难治结节性痒疹，疗效好，需严格避孕及神经病变监测）、环孢素、度普利尤单抗（IL-4/13单抗，近年获批，用于中重度结节性痒疹，疗效显著）、JAK抑制剂（乌帕替尼，新选择）；⑥治疗基础病（糖尿病/肾/肝，需控制）；⑦继发感染予抗感染；由皮肤科专科长期管理，多数需综合治疗数月至数年。）","处理方案":"【药物治疗】\n1. 外用强效糖皮质激素：0.05%卤米松乳膏外用患处，每日2次，连续2周后改为每日1次，疗程4周；结节肥厚、苔藓化明显者每晚涂药后保鲜膜封包1次，每次封包不超过8小时。\n2. 口服第二代抗组胺药：氯雷他定片10mg，每日1次口服，疗程2～4周，瘙痒缓解后逐渐减量至停药；夜间瘙痒明显者睡前加用第一代抗组胺药氯苯那敏片4mg。\n3. 常规治疗瘙痒控制不佳者：加巴喷丁胶囊起始0.1g，每日3次口服，每3日递增0.1g/次，渐增至0.3g，每日3次，疗程4周，注意头晕、嗜睡等不良反应，肾功能不全者需调整剂量。\n\n【一般治疗及生活指导】\n1. 严格避免搔抓、摩擦及热水烫洗，勤剪指甲，夜间可佩戴棉质手套，减少抓挠致结节加重及感染。\n2. 清淡饮食，忌食辛辣刺激食物及海鲜、牛羊肉等易致敏食物，戒烟戒酒，避免饮用浓茶、咖啡。\n3. 穿宽松柔软纯棉衣物，减少局部摩擦刺激；每日外用润肤剂保持皮肤保湿，修复皮肤屏障。\n4. 保持情绪稳定、作息规律，避免精神紧张、焦虑及劳累，因精神因素可加重瘙痒。\n\n【随诊要求】\n每2～4周复诊1次，评估瘙痒程度及结节消退情况、观察有无外用激素不良反应；若连续治疗4周瘙痒仍无缓解或结节持续增大、反复破溃渗液不愈，应及时复诊，必要时行皮肤活检排除皮肤淋巴瘤等继发性结节性痒疹相关疾病，并在医师指导下调整治疗方案；长期使用糖皮质激素者需遵医嘱逐渐减量停药，不可突然中断。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":484,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"d7636022d6b099994388fc6c31c7cf41b0b3ff51c8a3a7bb75d0bf58e511a68c","pinyin":"jiejiexingyangzhen","initials":"jjxyz","setting":"out","caseName":"门诊病历349","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历349",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-f033b6fe4c9d2b055b74","key":"v1-c9ccc21dfe2a3058|templates-f033b6fe4c9d2b055b74","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"扁平苔藓","category":"门诊病历模板","raw":{"name":"扁平苔藓","category":"门诊病历模板","case":{"case_name":"门诊病历350","templates":{"主诉":"四肢紫红色扁平丘疹伴瘙痒3月","现病史":"患者于3月前在腕屈侧（腕屈侧/前臂/小腿胫前/腰，屈侧好发；口腔黏膜为颊黏膜白色网状条纹（Wickham纹），最常见黏膜部位；外阴/头皮可受累）出现紫红色多角形扁平丘疹，表面有蜡样光泽（Wickham纹，即细白色网状条纹，为特征性表现），伴瘙痒（轻重不一，可剧烈），口腔黏膜可见白色网状条纹/糜烂（进食刺激痛）。有无用药（金制剂/抗疟药/噻嗪类/卡托普利，可致苔藓样药疹，对称泛发）、丙肝感染（与扁平苔藓相关，需筛查）、精神紧张、牙科材料接触（苔藓样接触反应）：无相关用药史，无丙肝感染，有精神紧张，无牙科材料接触史。头皮未受累，无脱发（瘢痕性脱发，假斑秃）。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.7℃，P76次/分，R18次/分，BP118/76mmHg。四肢屈侧可见散在、密集紫红色多角形扁平丘疹（直径0.2~0.5cm、境界清、表面蜡样光泽，可见Wickham纹），部分融合成斑块，表面有抓痕，指甲可见甲板纵嵴、甲剥离（甲扁平苔藓，为特征），口腔黏膜双颊可见白色网状条纹（Wickham纹）及糜烂，呈对称分布。","辅助检查":"【必做】一般临床诊断为主（典型皮损+Wickham纹）；【确诊】皮肤病理（表皮角化过度、颗粒层楔形增厚、基底细胞液化变性、真皮带状淋巴细胞浸润：特征性，诊断不明确/口腔糜烂型，活检）；【筛查】丙肝抗体（扁平苔藓：丙肝相关，常规筛查，我国重要）、口腔糜烂型，定期口腔科随访（恶变风险：约1%：糜烂型较常见）；药物史排查（苔藓样药疹）。","初步诊断":"1. 扁平苔藓（皮肤型/黏膜型/甲型/泛发型）\n（注：皮肤型（瘙痒）予外用糖皮质激素（中强效，糠酸莫米松/氟轻松）、口服抗组胺止痒；泛发/顽固者予口服维A酸（阿维A 20~30mg qd）、糖皮质激素短程（泼尼松30mg/d×2~4周渐减，重症）、窄谱中波紫外线（光疗，有效）；口腔型予0.1%他克莫司软膏或糖皮质激素（曲安奈德口腔软膏，用于糜烂型），口腔糜烂明显者予漱口（地塞米松含漱），顽固者予免疫抑制剂（羟氯喹200mg bid）；避免刺激（口腔忌辛辣烟酒，定期口腔随访防恶变，糜烂型/萎缩型每6~12个月复查）；甲型予甲周激素注射；停用可疑药物（药疹型，停药后消退）；治疗丙肝（相关者）；多数6~18个月自行消退（口腔型及泛发型病程长），需随访管理。）","处理方案":"【药物治疗】\n1. 局部糖皮质激素（首选）：0.1%曲安奈德口腔软膏涂于口腔白纹及糜烂处，每日2~3次，餐后涂药，疗程2~4周；皮肤型可予糠酸莫米松乳膏（艾洛松）外用，每日1次，疗程2~4周。\n2. 抗组胺药：氯雷他定片10mg qd口服（或西替利嗪片10mg qd），疗程2~4周，用于缓解皮肤瘙痒。\n3. 维A酸类：0.1%维A酸软膏外用丘疹、斑块处，每晚1次（口腔黏膜部位刺激性大，慎用）；泛发型或顽固型可口服阿维A胶囊30mg qd，餐中服，疗程4~8周，育龄期女性禁用。\n4. 免疫调节（顽固/糜烂反复者）：羟氯喹片0.2g bid口服，疗程8~12周；用药前及用药期间每3个月检查眼底、肝肾功能及血常规。\n\n【一般治疗及生活指导】\n1. 忌辛辣、过烫、过酸及坚硬粗糙食物，戒烟戒酒，避免浓茶、咖啡等刺激性饮品，减少对黏膜的物理化学刺激。\n2. 保持口腔清洁，使用软毛牙刷，饭后用复方氯己定含漱液漱口，每日2~3次；及时处理尖锐牙尖及不合适的义齿。\n3. 规律作息，避免熬夜、精神紧张及过度劳累，保持情绪稳定（精神应激为本病重要诱因）。\n4. 皮肤型避免搔抓及热水烫洗，贴身衣物选择纯棉宽松材质，避免摩擦刺激皮损。\n\n【随诊要求】\n1. 糜烂型每2~4周复诊1次，白纹型每1~3个月复诊1次，评估疗效并调整用药。\n2. 治疗期间若出现糜烂面扩大、出血、疼痛加重或新发水疱，应立即就诊。\n3. 糜烂型病程超过6个月不愈者，建议每3~6个月复查，必要时行病理活检排除恶变。\n4. 口服阿维A者需定期监测血脂及肝功能；口服羟氯喹者每3个月复查眼底及肝肾功能。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":485,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"2ce07d67e6160bd455455e39b7727c57017ccebb0f8c4d9758853aae6a52e5bb","pinyin":"bianpingtaixian","initials":"bptx","setting":"out","caseName":"门诊病历350","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历350",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-061e7ab8e1ae011a457c","key":"v1-c9ccc21dfe2a3058|templates-061e7ab8e1ae011a457c","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"副银屑病","category":"门诊病历模板","raw":{"name":"副银屑病","category":"门诊病历模板","case":{"case_name":"门诊病历351","templates":{"主诉":"躯干四肢散在暗红色斑疹1年","现病史":"患者于1年前在躯干及四肢近端（躯干及四肢近端，屈侧为主）出现散在暗红色/红褐色斑疹或斑块，表面覆细薄鳞屑，多无自觉症状或轻微瘙痒，缓慢增多。分型：点滴型（小斑疹，似银屑病但鳞屑薄、无银屑病三联征）、斑块型（较大斑块，境界清，需随访，少数可进展为蕈样肉芽肿（皮肤T细胞淋巴瘤），长期随访重要）、苔藓样型、痘疮样型。有无消退史及病程变化，有无系统症状（发热、淋巴结肿大，需排除淋巴瘤）：无消退史，无发热及淋巴结肿大。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.6℃，P74次/分，R18次/分，BP120/78mmHg。躯干四肢可见散在暗红色斑疹及斑块（大小0.3~5cm、境界清、表面覆细薄鳞屑，刮除鳞屑无薄膜现象及点状出血（区别于银屑病）、无浸润感，斑块型可轻度浸润），数目约10处，分布以屈侧为主。","辅助检查":"【必做】皮肤病理（表皮轻度角化不全、真皮浅层血管周围淋巴细胞浸润，无银屑病特征，但需与早期蕈样肉芽肿鉴别，斑块型/不典型者病理及随访）；【其他】血常规、外周血涂片（Sezary细胞：疑MF少见）、淋巴结超声（疑淋巴瘤）。","初步诊断":"1. 副银屑病（点滴型/斑块型/苔藓样型/痘疮样型）\n（注：点滴型多数可自行消退（数月至数年），治疗予润肤剂、弱效激素（丁酸氢化可的松）短期、窄谱中波紫外线（光疗，有效促消退）；斑块型对治疗抵抗，需长期随访（少数（约10%）可进展为蕈样肉芽肿，即皮肤T细胞淋巴瘤，每6~12个月皮肤科随访复查；出现皮损浸润增厚/扩大/瘙痒加重/淋巴结肿大时复查活检，以早期诊断MF）；治疗予光疗（窄谱中波紫外线，一线）、外用药（糖皮质激素/维A酸）、顽固者予补骨脂素加长波紫外线（光化学疗法）；避免过度日晒（光疗需专业进行）、随访皮损变化（照相记录对比，重要）；痘疮样型为急性，必要时予系统性抗炎治疗（顽固者甲氨蝶呤/环孢素）；由皮肤科专科随访。）","处理方案":"【药物治疗】\n1. 糖皮质激素类外用药：糠酸莫米松乳膏0.1%，每日1次薄涂患处，连续2～4周后评估，皮损消退后减为隔日1次维持1～2周；面部、颈及间擦部位可短期选用0.1%丁酸氢化可的松乳膏每日1～2次外用，连续使用不超过1周。\n2. 维生素D3衍生物外用药：卡泊三醇软膏（或他卡西醇软膏）每日2次外用，可与糖皮质激素联合或序贯使用（如白天卡泊三醇、睡前糖皮质激素），疗程8～12周，注意单日全身总用量不超过15g。\n3. 窄谱中波紫外线（NB-UVB）光疗：起始剂量0.3～0.5 J/cm²，每周2～3次，每次递增10%～20%，疗程8～12周，适用于皮损广泛、外用药疗效欠佳者；光疗期间外用药可减量。\n4. 口服抗组胺药（瘙痒明显者）：氯雷他定片10mg每日1次，睡前口服，连用2周，症状缓解后停药。\n\n【一般治疗及生活指导】\n1. 皮肤保湿护理：每日沐浴后3分钟内全身涂抹保湿霜（如尿素软膏、凡士林），减少鳞屑与瘙痒；避免热水烫洗、肥皂过度清洁及搓澡巾用力搓擦。\n2. 生活方式调节：规律作息，避免熬夜、精神紧张与焦虑；戒烟限酒，忌辛辣刺激性及高脂饮食，适当运动增强体质。\n3. 避免诱因与防晒：户外活动注意防晒，穿宽松纯棉衣物，避免搔抓皮损以防继发感染；抓破处可外涂莫匹罗星软膏每日2次，连续3～5天。\n4. 自我观察皮损：注意皮损有无增厚、浸润加深、融合成斑块、破溃或出现新发皮疹，如有变化及时就医。\n\n【随诊要求】\n1. 每4～8周复诊1次，评估皮损消退程度及药物疗效，据此调整治疗方案；糖皮质激素类外用药连续使用超过8周者复诊时评估局部皮肤萎缩、毛细血管扩张等副作用。\n2. 大斑块型副银屑病建议每3～6个月复诊并行皮肤镜检查，必要时行皮肤活检，监测有无向早期蕈样肉芽肿进展的征象。\n3. 接受NB-UVB光疗者治疗期间遵医嘱定期随访，累积照射次数较多者注意光老化及皮肤肿瘤风险；治疗中出现红斑、灼痛或皮损扩大应立即复诊。\n4. 治疗期间若瘙痒加重、出现继发感染或新发皮疹，随时复诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":486,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"af0e920050420ffc55d0ca04b30ea7e8b70aecdd1b172e28a6eb0b49de98d839","pinyin":"fuyinxiebing","initials":"fyxb","setting":"out","caseName":"门诊病历351","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历351",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-3c8ef74d685a45147a17","key":"v1-c9ccc21dfe2a3058|templates-3c8ef74d685a45147a17","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"玫瑰痤疮","category":"门诊病历模板","raw":{"name":"玫瑰痤疮","category":"门诊病历模板","case":{"case_name":"门诊病历352","templates":{"主诉":"面部阵发性潮红、丘疹脓疱2年","现病史":"患者于2年前开始面部（鼻部、面颊、前额、下颌等面中部）阵发性潮红（遇热、饮酒、辛辣、情绪激动后诱发，伴灼热感），渐发展持续性红斑、毛细血管扩张，并出现丘疹脓疱（眼周不受累，区别于痤疮），分型为红斑毛细血管扩张型（其他类型参考：丘疹脓疱型；鼻赘型表现为鼻部肥大增生，男性多见，见于晚期；眼型可有眼干、异物感及睑缘炎，约50%患者受累，常被忽视），无粉刺（区别于寻常痤疮），日晒后加重，否认护肤品及外用激素使用史（激素性玫瑰痤疮多因长期外用糖皮质激素，停用后可反跳加重）。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.8℃，P78次/分，R18次/分，BP120/80mmHg。面中部（鼻、颊、额、颏）可见持续性红斑及毛细血管扩张（可见树枝状扩张血管），散在丘疹、脓疱（无粉刺），鼻部未见皮脂腺增生肥大及鼻赘（为晚期表现），眼睑结膜充血（需裂隙灯检查排除眼型）。","辅助检查":"【必做】一般临床诊断为主；【鉴别】皮肤病理（肉芽肿性玫瑰痤疮：不典型时）、毛囊虫（蠕形螨）镜检（挤取皮脂，蠕形螨增多，可辅助治疗选择，甲硝唑对蠕形螨有效）；【眼型】眼科会诊（裂隙灯，眼表评估）。","初步诊断":"1. 玫瑰痤疮（红斑毛细血管扩张型）\n（注：①一般护理（基础）：温和清洁保湿、严格防晒（广谱防晒为重要防护）、避免诱因（热饮、辛辣、酒精、情绪激动、过热环境）；②红斑毛细血管扩张型：外用溴莫尼定凝胶（收缩血管，可临时退红）、他克莫司（抗炎）；毛细血管扩张明显者予激光或强脉冲光（封闭血管，有效）；③丘疹脓疱型：外用甲硝唑凝胶（每日2次）、伊维菌素乳膏（每晚，针对蠕形螨）、壬二酸（15%凝胶）；中重度口服多西环素40~100mg 每日1次（抗炎剂量，疗程8~12周）或米诺环素；疗效不佳者用小剂量异维A酸（10~20mg 每日1次，鼻赘型首选）；④眼型：眼睑卫生+人工泪液+多西环素（抗炎，需眼科协作）；⑤鼻赘型：异维A酸+激光或手术（磨削成形）；⑥避免外用糖皮质激素（可加重）；皮肤科随访，本病为慢性病，以控制为主。）","处理方案":"【药物治疗】\n1. 甲硝唑凝胶（0.75%）外用，每日早晚各1次，薄涂于红斑及丘疹脓疱处，避开眼周，疗程8-16周。\n2. 多西环素胶囊 0.1g 每日1次，餐后口服，疗程8-12周，服药期间严格避光防晒，注意胃肠道反应及光敏副作用。\n3. 壬二酸凝胶（15%）外用，每日2次，适用于以丘疹脓疱为主者，可与甲硝唑联合或交替使用，疗程至少12周。\n4. 眼型玫瑰痤疮（眼部受累）者：红霉素眼膏每晚1次涂于睑缘及睫毛根部，疗程4-8周。\n\n【一般治疗及生活指导】\n1. 严格防晒：每日使用SPF≥30、PA+++广谱防晒霜，配合遮阳帽、口罩等物理遮挡；避免日晒、热浴、桑拿及高温闷热环境，防止面部潮红加重。\n2. 饮食禁忌：避免饮酒、辛辣刺激性食物、热饮、咖啡及过烫饮食；保持情绪稳定，避免紧张激动、压力过大诱发阵发性潮红。\n3. 皮肤护理：选用温和无刺激的洁面及保湿修复类产品，修复皮肤屏障；禁用含酒精、酸类去角质、糖皮质激素类外用制剂及彩妆类刺激性化妆品。\n4. 规律作息，避免熬夜、剧烈运动及长时间佩戴口罩等导致面部充血的因素。\n\n【随诊要求】\n用药2-4周后复诊，评估疗效及耐受性；完成8-12周疗程后复诊，评价是否继续维持治疗或调整方案；治疗期间若出现面部持续潮红加重、脓疱增多或药物不良反应（光敏、胃肠道不适等），随时复诊。反复发作、红斑毛细血管扩张明显者建议每3-6个月定期复诊，评估是否联合光电治疗（如强脉冲光、染料激光）。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":487,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"27e1e90a1d87d5b2dbd9a18479bbac47f4b9f444e238803d011089cee2dbd3ca","pinyin":"meiguicuochuang","initials":"mgcc","setting":"out","caseName":"门诊病历352","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历352",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-35c01dfa869d6695d485","key":"v1-c9ccc21dfe2a3058|templates-35c01dfa869d6695d485","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"口周皮炎","category":"门诊病历模板","raw":{"name":"口周皮炎","category":"门诊病历模板","case":{"case_name":"门诊病历353","templates":{"主诉":"唇患者斑、丘疹伴瘙痒2月","现病史":"患者于3周前在口周（唇红缘外5mm环形区域，唇缘留有一条正常皮肤带，为本病特征）出现红斑、密集小丘疹（针尖至米粒大）、脓疱及少量鳞屑，轻度瘙痒或灼热感，可扩散至鼻唇沟及下睑下方（眼周皮炎），有长期外用糖皮质激素史（面霜、药膏，为最常见诱因，停用后可反跳），无含氟牙膏、化妆品、防晒霜刺激及精神紧张等诱因，停用激素后皮损加重。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.8℃，P78次/分，R18次/分，BP120/80mmHg。口周可见红斑基础上密集分布针尖至米粒大丘疹（唇红缘留正常皮肤带），表面细薄鳞屑，鼻唇沟及颏部受累，口腔黏膜正常（区别于口角炎、单纯疱疹）。","辅助检查":"【必做】一般临床诊断为主；【其他】毛囊虫（蠕形螨）镜检（挤取皮脂，蠕形螨相关，为甲硝唑治疗依据）、真菌镜检（排除口角炎念珠菌感染，后者位于口角）。","初步诊断":"1. 口周皮炎\n（注：首要措施为停用所有外用糖皮质激素（关键，可先过渡到弱效制剂或他克莫司以防反跳）；治疗：外用药（甲硝唑凝胶bid或他克莫司0.1%软膏bid，抗炎，疗程数周）、中重度口服四环素类（多西环素50~100mg qd×6~12周，抗炎有效，注意光敏）、壬二酸（15%凝胶）；避免诱因（含氟牙膏、刺激性化妆品、激素面霜）；保湿修复皮肤屏障（温和清洁+保湿霜）；多数需6~8周缓解，停药后防复发（避免再滥用激素），随访皮肤科。）","处理方案":"【药物治疗】\n1. 外用甲硝唑凝胶（0.75%）涂于口周皮损处，早晚各1次，bid，疗程4~8周，为本病一线外用药物。\n2. 外用1%吡美莫司乳膏涂于皮损处，bid，用于甲硝唑外用2周疗效欠佳或炎性丘疹明显者（非激素类免疫调节剂，可替代激素且无激素依赖性），疗程2~4周起，据情延长。\n3. 盐酸多西环素胶囊100mg po qd，餐后口服，疗程4~8周（四环素类为口服首选）；对四环素类过敏或禁用者改用阿奇霉素片0.25g po qd，疗程2周。\n\n【一般治疗及生活指导】\n1. 立即停用口周一切外用糖皮质激素制剂（含含激素的祛痘膏、药妆及\"消字号\"产品），并避免面部任何部位的激素反复外用，此为治疗成败关键；洗脸、涂抹护肤品时避免用力摩擦口周。\n2. 停用口红、唇部遮瑕类彩妆及含氟牙膏，改用成分简单、无香料、无酒精的温和洁面与保湿产品，减少口周刺激。\n3. 饮食清淡，忌辛辣、过烫食物，忌烟酒及浓咖啡；保持规律作息，避免熬夜和精神紧张。\n4. 外出时使用温和物理防晒（遮阳帽、口罩），避免日光暴晒及过热环境对面部的刺激。\n\n【随诊要求】\n1. 治疗2~4周复诊评估疗效，如皮损无明显消退或加重，复诊调整治疗方案。\n2. 疗程结束后随访4~8周，观察有无复发及是否出现激素依赖反跳；如治疗中出现红肿加重、渗出、脓疱增多或疑有继发感染，应提前复诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":488,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"36bc1edc9f4b1d535cfc630b6c14aff8349b0307e0b06a721464098e87da7fea","pinyin":"kouzhoupiyan","initials":"kzpy","setting":"out","caseName":"门诊病历353","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历353",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-c022259f1194866085d1","key":"v1-c9ccc21dfe2a3058|templates-c022259f1194866085d1","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"特应性皮炎","category":"门诊病历模板","raw":{"name":"特应性皮炎","category":"门诊病历模板","case":{"case_name":"门诊病历354","templates":{"主诉":"皮肤干燥、反复皮损伴瘙痒3年","现病史":"患者为成人期发病，于3年前起反复出现湿疹样皮损（婴儿期多见于面颊、额部、头皮；儿童期多见于肘窝、腘窝、颈前；成人期多见于屈侧、手部、眼睑、乳头等），皮肤干燥、剧烈瘙痒（夜间为著，影响睡眠），搔抓后渗液、结痂，冬重夏轻，无明确个人及家族过敏史（过敏性鼻炎、哮喘、过敏性结膜炎提示特应性体质，为诊断支持），无明确食物或环境过敏诱发因素，无皮肤感染史（金黄色葡萄球菌定植感染常见，渗出后可结黄痂），瘙痒-搔抓-皮损循环明显。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.8℃，P78次/分，R18次/分，BP120/80mmHg。皮肤干燥（+），四肢屈侧部位可见皮肤增厚、苔藓样变及色素沉着（慢性期皮损），皮肤皱褶处（肘窝、腘窝）受累（+），眼睑可见皮炎，手部可见角化、皲裂（手部皮炎），毛周角化、掌纹增粗（特应性特征），浅表淋巴结未肿大（搔抓感染时可肿大）。","辅助检查":"【必做】一般临床诊断为主（Williams标准：皮肤瘙痒+屈侧皮炎、个人或家族特应性疾病史、皮肤干燥等）；【其他】血清总IgE及特异性IgE（过敏原评估，不作为诊断必需）、血常规（嗜酸性粒细胞升高，支持诊断）、过敏原检测（食物或吸入性过敏原，明确加重因素时）、皮肤细菌培养（渗出感染时）。","初步诊断":"1. 特应性皮炎（中度，SCORAD评估）\n（注：基础护理（基石）：足量润肤保湿（每日2~3次，浴后3分钟内全身涂）、温水短浴（<10分钟）、避免刺激（过热、化纤、香料）；抗炎阶梯：外用糖皮质激素（急性期用丁酸氢化可的松或糠酸莫米松，短期规范）、钙调磷酸酶抑制剂（他克莫司或吡美莫司，用于面颈皱褶及激素依赖部位，维持治疗）、必要时湿包裹（重度急性）；系统治疗（中重度）：抗组胺药（止痒助眠）、光疗（窄谱中波紫外线，用于青少年及成人中重度）、免疫抑制剂（环孢素，重度短程）、生物制剂（度普利尤单抗，IL-4/13单抗，中重度首选，疗效显著、安全性好）或JAK抑制剂（乌帕替尼或阿布昔替尼）；感染时用莫匹罗星或系统性抗生素（针对金黄色葡萄球菌）；教育及心理支持（慢性病，依从性关键）；避免已知过敏食物（儿童，明确相关时）；长期管理，控制复发，随访。）","处理方案":"【药物治疗】\n1. 外用糖皮质激素：糠酸莫米松乳膏（艾洛松）0.1%，每日1次涂于皮损处，连续使用不超过2周；面颈及皮肤褶皱等薄嫩部位选用弱效制剂丁酸氢化可的松乳膏（尤卓尔）1%，每日2次，短期（≤1周）使用。\n2. 外用钙调神经磷酸酶抑制剂：他克莫司软膏（普特彼）0.1%（成人）或0.03%，每日2次，适用于面部、颈部及褶皱部位，或激素控制后序贯维持，连用2-4周。\n3. 口服抗组胺药：氯雷他定片10mg 每日1次，或西替利嗪片10mg 每日1次；夜间瘙痒剧烈影响睡眠者加用酮替芬片1mg 每晚睡前口服，疗程2-4周。\n4. 保湿修复：医学润肤剂（含神经酰胺保湿霜、凡士林或尿素软膏）全身足量涂抹，每日至少2次，长期坚持作为基础治疗。\n\n【一般治疗及生活指导】\n1. 洗浴：温水（32-37℃）洗浴，每日1次，每次5-10分钟，禁用热水烫洗及碱性肥皂、刺激性沐浴液，浴后3分钟内全身涂抹润肤剂锁水。\n2. 皮肤护理：穿宽松纯棉衣物，避免羊毛、化纤及紧身衣物直接接触皮肤；勤剪指甲，避免搔抓、摩擦皮损。\n3. 饮食：忌酒及辛辣刺激食物；仅对明确过敏原（如牛奶、鸡蛋、花生等）所致者回避相应食物，不盲目长期忌口，以免营养不良。\n4. 环境：保持居室凉爽通风，室内湿度维持在50%-60%，定期除螨，避免尘螨、花粉、宠物皮屑等过敏原及汗液浸渍。\n\n【随诊要求】\n治疗2周后复诊评估疗效及皮损改善情况；瘙痒加重、皮损扩大或出现渗出、脓疱等继发感染征象者随时复诊；外用糖皮质激素连续使用超过2周医师指导下调整或换用非激素类药膏，防止激素依赖性及不良反应；中重度反复发作、外用治疗效果不佳者建议专科随访，评估是否需系统治疗（如度普利尤单抗、免疫抑制剂），每月复诊评估病情控制情况。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":489,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"99cf567ab8e84cffb003cf98ab4135179a89a16c55676ebc601e485f148ae64e","pinyin":"teyingxingpiyan","initials":"tyxpy","setting":"out","caseName":"门诊病历354","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历354",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-2b01721f7fd2668090cc","key":"v1-c9ccc21dfe2a3058|templates-2b01721f7fd2668090cc","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"淤积性皮炎","category":"门诊病历模板","raw":{"name":"淤积性皮炎","category":"门诊病历模板","case":{"case_name":"门诊病历355","templates":{"主诉":"小腿色素沉着、水肿伴瘙痒1年","现病史":"患者有下肢静脉曲张（下肢静脉功能不全）病史，于2年前开始小腿下1/3及内踝上方皮肤褐色色素沉着（含铁血黄素沉积）、水肿（下午及久站后加重）、皮肤变薄发亮，渐出现湿疹样皮损（红斑、丘疹、水疱、渗液，符合淤积性皮炎）、剧烈瘙痒，搔抓后糜烂结痂，反复发作，有静脉曲张病史，无既往深静脉血栓及溃疡史（静脉性溃疡好发于内踝上方，外伤后难愈），久站久坐职业史。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.8℃，P78次/分，R18次/分，BP120/80mmHg。双下肢可见静脉曲张（蚓状迂曲扩张），小腿下1/3及内踝皮肤可见褐色色素沉着、凹陷性水肿、皮肤萎缩变薄及脱屑，可见湿疹样红斑、丘疹伴糜烂渗液结痂（急性期），未见溃疡（静脉性溃疡好发于内踝上方，边缘不规则，基底可见肉芽或渗液，周围色素沉着），足背动脉搏动正常。","辅助检查":"【必做】下肢静脉彩色多普勒超声（评估静脉功能不全，包括深静脉通畅性及反流，为核心检查）；【其他】踝肱指数（ABI，排除动脉疾病，用于溃疡鉴别）、皮肤细菌培养（渗液感染时）、皮肤活检（皮损不典型时，排除其他皮肤病，较少患者）。","初步诊断":"1. 淤积性皮炎（下肢静脉功能不全相关湿疹）\n（注：①治疗静脉功能不全（根本措施）：抬高患肢（休息时高于心脏）、医用弹力袜（压力治疗，关键，日间穿戴）、避免久站久坐；静脉曲张可予硬化剂或手术（大隐静脉剥脱或激光，需专科处理）；②皮炎治疗：外用糖皮质激素（急性渗液时先湿敷（硼酸溶液）收敛，再用弱效激素；慢性肥厚时用中强效激素，短期使用）、保湿护肤（尿素软膏，用于干燥）、止痒（口服抗组胺药）；③继发感染时抗感染（莫匹罗星或抗生素）；④溃疡者行创面处理（清创、湿性敷料、压力治疗，促进愈合；久治不愈者活检排除恶变及动脉性溃疡，转血管外科）；⑤避免搔抓及外伤；皮肤科与血管外科协作随访。）","处理方案":"【药物治疗】\n1. 外用糖皮质激素：糠酸莫米松乳膏（0.1%）涂患处 qd，连用1~2周，皮疹消退后逐渐减量或改为隔日/每周2次维持；皮损渗出明显时，先用3%硼酸溶液湿敷（bid，每次15~20分钟），待渗液减少后再外用激素软膏。\n2. 抗组胺药止痒：氯雷他定片10mg qd 或西替利嗪片10mg qd，瘙痒明显者口服，疗程1~2周。\n3. 继发感染时加用抗菌药物：头孢呋辛酯片0.25g bid×7天（青霉素过敏者改阿奇霉素片0.25g qd×5天）；配合莫匹罗星软膏外用涂患处 bid。\n【一般治疗及生活指导】\n1. 休息时抬高患肢（高于心脏水平20~30cm）并做踝泵运动，避免久站久坐，减少下肢静脉淤血。\n2. 日间穿戴医用弹力袜（Ⅱ级压力梯度）或弹力绷带，夜间取下，促进静脉回流；弹力袜需白天穿戴、定期更换。\n3. 避免搔抓、热水烫洗及碱性皂刺激，浴后立即涂保湿润肤剂（如凡士林、尿素软膏）修复皮肤屏障；禁止自行挑破水疱或撕脱痂皮。\n4. 控制体重、戒烟，适量步行锻炼；合并下肢静脉曲张或深静脉瓣膜功能不全者，建议血管外科会诊评估，择期处理静脉病变。\n【随诊要求】\n1. 用药1~2周后复诊，评估皮损消退与瘙痒缓解情况，调整外用激素强度及疗程，避免长期滥用。\n2. 治疗中出现皮损范围扩大、红肿加重、渗液增多、发热或下肢明显肿胀疼痛时，立即复诊。\n3. 症状缓解后每3~6个月随访1次，监测皮肤状况及下肢静脉功能；长期穿弹力袜者随访时评估皮肤有无新的淤积性改变或溃疡发生。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":490,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"3eb479c77590621574837223ce1832838269961d7f3e98c73055062c29123ee2","pinyin":"yujixingpiyan","initials":"yjxpy","setting":"out","caseName":"门诊病历355","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历355",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-c6ea9e7667b2f65d0033","key":"v1-c9ccc21dfe2a3058|templates-c6ea9e7667b2f65d0033","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"钱币状湿疹","category":"门诊病历模板","raw":{"name":"钱币状湿疹","category":"门诊病历模板","case":{"case_name":"门诊病历356","templates":{"主诉":"四肢圆形红斑丘疱疹伴瘙痒1月","现病史":"患者于3周前在四肢伸侧出现钱币状（硬币大小、圆形）红斑丘疱疹，边界清楚，表面可见小水疱、渗液、结痂（急性期），剧烈瘙痒，反复发作，有皮肤干燥（冬季加重，见于干性皮肤者）、搔抓及化学刺激、热水烫洗后加重，无精神紧张、饮酒及上呼吸道感染等诱发因素，无药物诱发，无特应性皮炎或湿疹病史，无明确真菌感染证据（足癣可致自体敏感，需排除）。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.8℃，P78次/分，R18次/分，BP120/80mmHg。四肢可见散在钱币状圆形红斑（直径1~5cm）、边界清、表面丘疹、水疱、渗液、结痂（急性期），数目及分布：散在分布，以四肢伸侧为主，抓痕（+），足部未见足癣皮损（已行足癣检查）。","辅助检查":"【必做】一般临床诊断为主；【其他】真菌镜检（排除体癣，后者为边界清楚的环形皮损、有活动性边缘，需鉴别，真菌检查重要）、皮肤细菌培养（渗出感染时）、斑贴试验（疑接触过敏，尤其慢性手部皮损者）。","初步诊断":"1. 钱币状湿疹（盘状湿疹）\n（注：治疗：①外用药：急性渗液时先湿敷（3%硼酸溶液，收敛）后用弱中效糖皮质激素（丁酸氢化可的松或糠酸莫米松乳膏）；慢性干燥时用强效激素短期加保湿（尿素软膏）；②口服抗组胺药（止痒，可选西替利嗪或氯雷他定；夜间瘙痒明显者睡前用第一代抗组胺药）；③皮肤护理（保湿护肤，对皮肤干燥者尤为关键；温水浴、避免刺激及热水烫洗、穿纯棉衣物）；④系统治疗（顽固泛发者）：窄谱中波紫外线光疗、短期口服激素（泼尼松30mg/d，用于急性重症，逐渐减量，防复发，不长期使用）、免疫抑制剂（环孢素，用于难治性，较少使用）；⑤继发感染时用抗生素；⑥避免搔抓，剪短指甲；⑦去除诱因（治疗足癣、避免酒精及辛辣）；病程慢性、易复发，需随访管理。）","处理方案":"【药物治疗】\n1. 外用糖皮质激素（首选）：糠酸莫米松乳膏0.1%（艾洛松）适量涂于皮损处，每日1次，连续2周；皮损消退后减为隔日1次维持1～2周，总疗程4周左右。面部、颈部及间擦部位宜选用弱效制剂如丁酸氢化可的松乳膏（尤卓尔）每日2次。\n2. 口服抗组胺药：氯雷他定片10mg 每晚1次，连服2周；瘙痒明显或夜间加重者可改用或联用西替利嗪片10mg 每日1次，疗程2～4周。\n3. 保湿修复：尿素软膏或医用保湿霜（如凡士林、玉泽屏障修护霜）涂于皮损及周围皮肤，每日2～3次，与激素间隔30分钟使用，需长期坚持以修复皮肤屏障、减少复发。\n4. 顽固或反复发作皮损：可加用0.1%他克莫司软膏每日2次外用（避开激素长期使用部位），疗程2～4周；若皮损出现红肿、渗液增多、脓疱等继发感染表现，加用莫匹罗星软膏每日2～3次外用，连用5～7天。\n\n【一般治疗及生活指导】\n1. 皮肤护理：避免热水烫洗、过度搔抓及肥皂、碱性浴液等刺激；洗澡水温以37℃左右为宜，时间不超过10分钟，浴后3分钟内全身涂抹润肤剂锁水。\n2. 衣物选择：穿宽松纯棉衣物，避免羊毛、化纤等粗糙织物直接接触皮损处；勤剪指甲，夜间瘙痒明显者戴棉手套防抓伤。\n3. 饮食与生活：忌辛辣刺激食物、海鲜、酒精及咖啡浓茶，避免可疑致敏食物（注意个体观察）；保证充足睡眠，避免熬夜、精神紧张及过度劳累，适度运动增强体质。\n4. 环境管理：保持居住环境清洁、通风，避免尘螨、宠物毛发等刺激；干燥季节室内可加湿（湿度40%～60%），外出注意防晒和保湿。\n\n【随诊要求】\n1. 用药2周后复诊评估疗效及皮损变化，由医师决定激素减量或调整方案；用药期间如皮损扩大、渗液增多、剧烈瘙痒或出现发热，应立即复诊。\n2. 出现继发感染表现（红肿热痛、脓性渗出、脓疱）及时就诊，必要时查血常规及分泌物细菌培养。\n3. 反复发作超过6个月者，建议行过敏原检测或斑贴试验查找病因，并遵医嘱定期（每1～3个月）复诊随访，评估病情与用药安全性。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":491,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"63c5c87f5043f1257ef9d072a7e5c4a4f9b86d3320667bf6effaaa2572699ad2","pinyin":"qianbizhuangshizhen","initials":"qbzsz","setting":"out","caseName":"门诊病历356","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历356",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-3c6d82240c95a1d1e056","key":"v1-c9ccc21dfe2a3058|templates-3c6d82240c95a1d1e056","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"汗疱疹","category":"门诊病历模板","raw":{"name":"汗疱疹","category":"门诊病历模板","case":{"case_name":"门诊病历357","templates":{"主诉":"手掌、足底水疱伴瘙痒2周","现病史":"患者于1周前在手掌、手指侧缘、足底出现深在性粟粒大小水疱（即汗疱疹，又称出汗不良性湿疹，并非汗腺疾病，实际为湿疹的特殊类型），水疱壁厚、内容清亮，伴瘙痒或灼热感，水疱可自行吸收脱屑或破裂（继发感染时出现红肿、疼痛、脓疱），有季节发作史（春末夏初多见），无明显精神紧张或压力（为重要诱因）、手足多汗、真菌感染（足癣，常并存，可致自体敏感）、金属过敏（镍、铬，斑贴试验部分相关）及特应性皮炎史，反复发作病史。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.8℃，P78次/分，R18次/分，BP120/80mmHg。双手掌、指侧缘及足底可见粟粒至米粒大深在性水疱（壁厚、透亮、散在分布），部分水疱吸收后脱屑，未见继发感染征象（无脓疱、红肿；足背淋巴管炎为继发感染表现），指（趾）甲正常。","辅助检查":"【必做】一般临床诊断为主；【其他】真菌镜检（排除手癣/足癣：水疱型足癣：重要鉴别）、斑贴试验（疑金属/接触过敏，慢性顽固者）、皮肤病理（少见，排除其他水疱病：大疱性类天疱疮/掌跖脓疱病，注意掌跖脓疱病鉴别：无菌性脓疱+银屑病样甲改变）。","初步诊断":"1. 汗疱疹（出汗不良性湿疹）\n（注：治疗：①外用糖皮质激素（早期水疱期用丁酸氢化可的松或糠酸莫米松乳膏，有效；注意掌跖皮肤较厚，需用较强效制剂如氟轻松）、炉甘石洗剂（收敛止痒）；②干燥脱屑期：保湿加弱效激素（尿素软膏加激素）；③口服抗组胺药（止痒）；④精神紧张者予心理疏导，必要时抗焦虑治疗（控制重要诱因）；⑤避免刺激（避免肥皂等洗剂，温水洗手，戴手套做家务、避免接触化学物）；⑥继发感染时用莫匹罗星或抗生素；⑦顽固者：窄谱中波紫外线光疗、短程口服激素（急性重症）、他克莫司软膏（长期维持，替代激素，减少激素依赖）；⑧治疗并存的足癣（减少自体敏感）；避免抓挠，水疱破裂时防感染；多数呈季节性发作，缓解期注意防护，随访。）","处理方案":"【药物治疗】\n1. 外用糖皮质激素：糠酸莫米松乳膏，每日1次外用患处，连续使用7-14天；水疱破溃、渗液明显者先予3%硼酸溶液湿敷，每次15-20分钟，每日2-3次，待干燥后再涂激素乳膏。\n2. 口服抗组胺药止痒：氯雷他定片10mg，每日1次，睡前口服，连用7-14天（瘙痒明显者可选西替利嗪片10mg，每日1次）。\n3. 重症顽固病例：水疱广泛、瘙痒剧烈影响生活者，可短期口服醋酸泼尼松片30mg，每日1次晨服，症状控制后每3-5天减量5mg，总疗程不超过2周，需监测血压、血糖。\n【一般治疗及生活指导】\n1. 避免接触肥皂、洗衣粉、洗洁精等碱性洗涤剂及镍、铬等金属饰品，洗手洗脚后立即涂保湿霜（如凡士林、尿素软膏）修复皮肤屏障。\n2. 忌搔抓、挤压或挑破水疱，防止继发细菌感染；注意保持手足部皮肤干燥透气，避免长时间浸水、出汗过多。\n3. 饮食清淡，少食辛辣刺激性食物及海鲜、酒精等易诱发或加重瘙痒之品，多饮水，规律作息，避免精神紧张和焦虑。\n【随诊要求】\n1. 用药7-14天后复诊评估疗效，皮疹未消退或反复发作者复诊调整治疗方案。\n2. 治疗期间如出现患处红肿、疼痛、脓疱或发热等继发感染征象，应立即就诊。\n3. 每年复发≥2次者，建议皮肤科门诊定期随访，评估是否需长期维持治疗（如他克莫司软膏间歇维持）及排查接触性过敏原。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":492,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"9122038bf9da7be91c277cf603d01972250f148fc2601da716fc5059e4fc28ec","pinyin":"hanpaozhen","initials":"hpz","setting":"out","caseName":"门诊病历357","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历357",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-ed8e15fbba5ac258ea20","key":"v1-c9ccc21dfe2a3058|templates-ed8e15fbba5ac258ea20","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"掌跖脓疱病","category":"门诊病历模板","raw":{"name":"掌跖脓疱病","category":"门诊病历模板","case":{"case_name":"门诊病历358","templates":{"主诉":"手掌、足底反复脓疱伴脱屑1年","现病史":"患者于2年前在手掌（大小鱼际）反复成批出现无菌性小脓疱（黄白色、直径2~5mm，数天内干涸脱屑，反复成批、周期性发作），基底红斑，伴瘙痒或灼热，缓解期皮肤干燥脱屑、皲裂（疼痛，影响行走及握物），有长期吸烟史（为重要相关因素，戒烟可改善），无上呼吸道感染或扁桃体炎史（链球菌为诱因）、无精神紧张、无药物（锂盐等）诱发因素，无银屑病家族史，但有甲改变（点状凹陷；掌跖脓疱病与银屑病相关，属脓疱型银屑病局限型），无发热，脓疱为无菌性（区别于感染性脓疱疮）。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.8℃，P78次/分，R18次/分，BP120/80mmHg。手掌可见对称性红斑基础上成批黄白色小脓疱（直径2~5mm，未破），部分干涸形成黄褐色痂皮，皮肤增厚、皲裂，指甲可见点状凹陷（银屑病甲），身体其他部位皮肤未见银屑病斑块（约1/4患者可并存）。","辅助检查":"【必做】脓疱内容物细菌培养（无菌生长：排除感染性脓疱疮，关键鉴别）；【其他】皮肤病理（表皮内Kogoj海绵状脓疱：特征，不典型时）、链球菌检测（咽拭子，疑链球菌诱因）、血常规（白细胞：感染鉴别：掌跖脓疱病不高）。","初步诊断":"1. 掌跖脓疱病（掌型）\n（注：治疗（顽固，需耐心）：①外用药：强效糖皮质激素（氯倍他索，脓疱期封包）、卡泊三醇软膏（维生素D3衍生物，用于红斑鳞屑期，可联合激素）、他扎罗汀；②光疗（窄谱中波紫外线或补骨脂素加长波紫外线，有效）；③系统药物（中重度）：阿维A（10~30mg 每日1次，为维A酸类一线药，需监测血脂、肝功，育龄期避孕）、环孢素（快速控制，短程）、甲氨蝶呤（用于顽固者）；④生物制剂（难治性：IL-23/IL-17抑制剂，如司库奇尤单抗或古塞奇尤单抗，疗效好）；⑤对症（润肤防皲裂用尿素软膏，皲裂疼痛者镇痛）；⑥戒烟（重要，可改善预后）、控制感染（扁桃体炎反复发作者行扁桃体切除可改善部分患者）；⑦避免刺激（减少手部摩擦，戴手套）；皮肤科专科管理，为慢性病程，以控制症状为主，随访。）","处理方案":"【药物治疗】\n1. 外用强效糖皮质激素：丙酸氯倍他索乳膏（0.05%）适量外涂患处 bid×2周，皮损消退后减为qd并逐渐减少频次，或改用他卡西醇软膏维持，疗程4-8周；注意封包可增强疗效但不宜长期大面积封包。\n2. 口服维A酸类：阿维A胶囊 20mg qd（饭后顿服）口服，起效后视耐受情况调整剂量（10-30mg/d），疗程8-12周，需严格避孕并定期监测肝肾功能与血脂。\n3. 系统免疫抑制剂（二线，上述效果不佳时选用）：甲氨蝶呤片 7.5mg 每周1次口服，次日加服叶酸片 5mg qd×1天，疗程8-12周，用药前及疗程中监测血常规、肝肾功能；或秋水仙碱片 0.5mg bid 口服，疗程4-8周，腹泻明显时减量或停药。\n4. 重症顽固者可选用生物制剂（如司库奇尤单抗 300mg 皮下注射，每周1次×5周，之后每4周1次维持），需在专科评估排除结核、乙肝等活动性感染后启用。\n【一般治疗及生活指导】\n1. 戒烟并避免被动吸烟，积极防治上呼吸道及咽部感染（如反复扁桃体炎可考虑专科评估），减少情绪紧张与劳累，保持规律作息。\n2. 忌食辛辣、油腻及海鲜等刺激性食物，限制饮酒及浓茶咖啡，饮食清淡、多饮水，多吃新鲜蔬菜水果。\n3. 避免手足部摩擦、外伤及压迫，洗衣、洗碗及接触洗涤剂、消毒剂、化学试剂时戴手套，避免热水烫洗及搔抓疱面，保持局部清洁干燥。\n4. 患处可每日温水泡洗后擦干再涂药，鞋袜选择透气、宽松、吸汗材质，避免长时间穿密闭胶鞋。\n【随诊要求】\n1. 用药期间每2-4周复诊1次，评估皮疹消退情况及用药反应；症状明显改善后遵医嘱逐渐减量或换用维持方案，切勿自行停药以防复发。\n2. 口服阿维A者每4周复查肝肾功能、血脂；服甲氨蝶呤者定期复查血常规、肝肾功能；长期用药者按医嘱复查血糖及血尿酸。\n3. 若出现脓疱新发增多、发热、皮肤感染扩散或药物相关不良反应（如肝功能异常、严重腹泻、视物模糊、黏膜糜烂等），应及时复诊或急诊就诊。\n4. 病情稳定后每1-3个月复诊1次，长期随访监测复发及远期药物安全性，育龄期女性用药期间及停药后一定时间内严格避孕并告知医生。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":493,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"5349b7ef3303c62e5d4fd0e86f8e21a94113bebbe466f64104ad7e88f82fe5e5","pinyin":"zhangzhinongpaobing","initials":"zznpb","setting":"out","caseName":"门诊病历358","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历358",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-e5174eb454bca0c250b7","key":"v1-c9ccc21dfe2a3058|templates-e5174eb454bca0c250b7","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"连续性肢端皮炎","category":"门诊病历模板","raw":{"name":"连续性肢端皮炎","category":"门诊病历模板","case":{"case_name":"门诊病历359","templates":{"主诉":"指趾末端脓疱、糜烂1周","现病史":"患者1周前无明显诱因出现连续性肢端皮炎相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者指趾末端出现脓疱、糜烂1周，考虑连续性肢端皮炎，查血常规了解白细胞及中性粒细胞水平，明确有无细菌感染及炎症程度；完善真菌镜检加真菌培养排除手癣、足癣等浅表真菌感染所致的脓疱性损害；本病属脓疱型银屑病的局限型，必要时完善皮肤病理检查（皮肤活检）明确诊断，与掌跖脓疱病、IgA天疱疮等鉴别；必要时完善免疫荧光检查（直接免疫荧光）了解有无免疫球蛋白沉积，鉴别天疱疮、类天疱疮等自身免疫性大疱性皮肤病；如疑接触性皮炎或过敏因素所致，完善过敏原检测及斑贴试验明确致敏物质，指导避免接触可疑致敏原；指端脓疱需与二期梅毒疹鉴别，必要时完善性病相关检测（梅毒血清学）明确诊断；为协助观察脓疱及甲损害特征，必要时完善皮肤镜检查辅助诊断。因后续可能予维A酸类、免疫抑制剂或生物制剂治疗，用药前完善肝肾功能、血糖、血脂及电解质检查评估基线水平，治疗期间定期复查血常规、肝肾功能，监测药物不良反应。\n\n（检查清单）\n【必做检查】\n血常规、过敏原检测、真菌镜检+培养\n\n【影像学检查】\n皮肤镜、皮肤活检（必要时）\n\n【其他检查】\n免疫荧光、斑贴试验、性病相关检测（必要时）","初步诊断":"1. 连续性肢端皮炎\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 外用强效糖皮质激素：卤米松乳膏（如澳能）或丙酸氯倍他索乳膏，涂患处及甲周，每日2次，连用2～4周，皮损好转后减为每日1次维持，避免长期大面积使用。\n2. 外用维生素D3衍生物：卡泊三醇软膏（或他卡西醇软膏），每日1～2次，与外用激素序贯或联合使用，疗程4～8周。\n3. 口服阿维A胶囊：起始剂量10mg每日2次（20mg/d），2周后根据疗效及耐受情况增至20～30mg/d，疗程4～8周；用药期间及停药后2年内避孕，定期监测肝功能和血脂。\n4. 继发细菌感染时：头孢呋辛酯片0.25g每日2次×7天，或加用莫匹罗星软膏外用每日2次。\n\n【一般治疗及生活指导】\n1. 保持患处清洁干燥，避免搔抓、撕剥甲周及过度修剪指（趾）甲；接触水、清洁剂、消毒液时佩戴防护手套。\n2. 忌烟酒及辛辣刺激、高脂饮食，适量补充优质蛋白和维生素，保证足量饮水。\n3. 注意休息，保证充足睡眠，避免劳累、精神紧张及患肢负重、反复摩擦。\n4. 禁忌：急性期避免热水烫洗、碱性肥皂及刺激性药液浸泡，不宜自行长时间封包外用药物。\n\n【随诊要求】\n每2周门诊复诊1次，评估疗效与不良反应并调整用药；口服阿维A者每2～4周复查肝功能、血脂，育龄期女性严格避孕；如脓疱泛发、发热或皮损累及其他部位，立即就诊；皮损消退后巩固治疗2～4周，缓慢减量停药，避免突然停药导致复发。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":494,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"24c9a494deb060c22b851c8fc0ec59e9bcb5121fc1fea8b67355e679e7429429","pinyin":"lianxuxingzhiduanpiyan","initials":"lxxzdpy","setting":"out","caseName":"门诊病历359","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历359",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-65a35b08bc7d6c67d221","key":"v1-c9ccc21dfe2a3058|templates-65a35b08bc7d6c67d221","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"红皮病","category":"门诊病历模板","raw":{"name":"红皮病","category":"门诊病历模板","case":{"case_name":"门诊病历360","templates":{"主诉":"全身皮肤弥漫潮红、脱屑1周","现病史":"患者1周前无明显诱因出现红皮病相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者全身皮肤弥漫潮红、脱屑1周，伴乏力，红皮病时机体代谢亢进、皮肤屏障功能丧失，完善血常规检查了解有无感染、贫血及嗜酸性粒细胞升高，为寻找病因提供线索；查尿常规、便常规了解有无肾脏受累及消化道情况，排查潜在诱因；患者皮肤广泛脱屑、蛋白丢失明显，查肝肾功能了解肝脏合成功能及有无低白蛋白血症，评估营养状态并指导支持治疗，同时为后续用药提供基线；查血糖、血脂了解代谢状况，指导糖皮质激素等药物使用及监测；查电解质了解有无低钠、低钾等电解质紊乱，及时纠正；因红皮病可致高排血量性心力衰竭，完善心电图检查了解心律及心肌供血情况，必要时查NT-ProBNP评估心功能；完善胸部X线片检查了解有无肺部感染及肺门淋巴结肿大，为排查淋巴瘤等提供线索；完善腹部超声检查了解肝脾及腹腔淋巴结有无肿大；必要时完善皮肤活检明确病因，鉴别药疹、银屑病及皮肤T细胞淋巴瘤；必要时查外周血涂片寻找Sézary细胞、完善淋巴结超声排查淋巴瘤。治疗期间定期复查血常规、肝肾功能、电解质及白蛋白。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 红皮病\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 系统糖皮质激素（首选）：泼尼松片 40mg qd晨起顿服，病情控制后每1～2周递减5～10mg，总疗程4～8周，减量宜缓、防反跳；用药期间监测血压、血糖及电解质。\n2. 口服抗组胺药止痒：氯雷他定片 10mg qd×2周（或西替利嗪片 10mg qd），瘙痒明显时睡前可加用赛庚啶片 2mg qn。\n3. 局部外用：0.1%糠酸莫米松乳膏涂患处 bid，配合凡士林或尿素软膏保湿护肤；面部、皮肤薄嫩处避免长期强效激素。\n4. 继发细菌感染者：阿莫西林胶囊 0.5g tid×5～7天（青霉素过敏者改用头孢呋辛酯片 0.25g bid）；若为银屑病型红皮病可加用阿维A胶囊 20～30mg qd。\n【一般治疗及生活指导】\n1. 卧床休息，减少活动，注意保暖、避免受凉，防止低体温及呼吸道感染。\n2. 饮食宜清淡、高蛋白、高维生素、易消化，多饮水，禁酒及辛辣刺激性食物。\n3. 穿宽松棉质衣物，勤剪指甲，避免搔抓及热水烫洗，禁用碱性肥皂，洗浴后立即涂抹保湿剂。\n4. 保持环境温度湿度适宜，密切观察体温、精神状态及皮疹面积变化。\n【随诊要求】\n1. 每1～2周复诊1次，评估皮疹消退情况及激素减量进度。\n2. 复诊时复查血常规、肝肾功能、血糖、电解质，长期用药者定期监测血压、血脂。\n3. 出现发热、畏寒、精神萎靡、血压下降或皮疹面积扩大时随时急诊就诊；激素减停过程中病情反复应立即复诊。\n4. 明确原发病（药物过敏、银屑病、淋巴瘤等）者，按原发病专科要求随访，完成皮肤活检及影像学等检查。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":495,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"a9aaec66aabd7630d8496ed170612e7c6c3464500abfa2f27bedab762151aa04","pinyin":"hongpibing","initials":"hpb","setting":"out","caseName":"门诊病历360","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历360",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-52691f110198beab9431","key":"v1-c9ccc21dfe2a3058|templates-52691f110198beab9431","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"剥脱性皮炎","category":"门诊病历模板","raw":{"name":"剥脱性皮炎","category":"门诊病历模板","case":{"case_name":"门诊病历361","templates":{"主诉":"全身皮肤潮红伴大片脱屑1周","现病史":"患者1周前无明显诱因出现剥脱性皮炎相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者全身皮肤潮红伴大片脱屑1周，考虑剥脱性皮炎（红皮病型药疹可能），完善血常规检查了解有无感染、贫血及嗜酸性粒细胞升高；查过敏原检测寻找可疑致敏药物及食物，指导避免再次接触；完善斑贴试验明确接触性致敏原，协助判断病因；完善真菌镜检加真菌培养排除皮肤癣菌等泛发浅表真菌感染所致的红皮病样皮损；为明确皮损性质、鉴别药疹、银屑病及皮肤T细胞淋巴瘤，必要时完善皮肤镜检查及皮肤活检（组织病理）明确诊断；必要时完善免疫荧光检查排除自身免疫性大疱性皮肤病；如疑二期梅毒等性传播疾病所致皮疹，必要时完善性病相关检测（梅毒血清学）明确诊断。患者皮肤广泛脱屑、屏障受损，完善肝肾功能检查评估基线及有无低白蛋白血症，为糖皮质激素等治疗提供依据；查电解质、血糖、血脂了解内环境及代谢状况；因高代谢状态可加重心脏负担，完善心电图检查了解心律及心肌供血情况，必要时查NT-ProBNP评估心功能；完善胸部X线片、腹部超声排查感染及肿瘤等潜在病因。治疗期间定期复查血常规、肝肾功能及电解质。\n\n（检查清单）\n【必做检查】\n血常规、过敏原检测、真菌镜检+培养\n\n【影像学检查】\n皮肤镜、皮肤活检（必要时）\n\n【其他检查】\n免疫荧光、斑贴试验、性病相关检测（必要时）","初步诊断":"1. 剥脱性皮炎\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1.糖皮质激素（首选）：泼尼松片30mg qd晨起顿服，病情控制后每1~2周减量5mg，维持量10mg qd，总疗程4~8周；\n2.抗组胺药止痒：氯雷他定片10mg qd口服×2周，或西替利嗪片10mg qd口服×2周；\n3.外用治疗：无渗出期予糠酸莫米松乳膏涂患处bid，并配合凡士林等保湿润肤剂每日涂抹；糜烂渗出期予3%硼酸溶液湿敷bid，每次15~20分钟；\n4.辅助支持：维生素C片0.2g tid口服、葡萄糖酸钙片1.0g tid口服、维生素E软胶囊100mg bid口服，连用2周。\n【一般治疗及生活指导】\n1.卧床休息，注意保暖，避免受凉感冒；广泛脱屑者监测体温及生命体征，防止低体温和继发感染；\n2.饮食予高蛋白、高维生素、易消化饮食，多饮水，禁食辛辣刺激食物、海鲜、牛羊肉及酒类；\n3.皮肤护理：穿宽松柔软棉质衣物，温水轻柔洗浴，避免热水烫洗、搔抓及使用刺激性肥皂；修剪指甲，勤换床单衣物，保持床铺清洁干燥；\n4.避免接触可疑致敏药物及化学品，告知今后就医时主动说明药物过敏史。\n【随诊要求】\n1.治疗期间每周门诊复诊1次，评估皮损消退、脱屑程度及有无发热、感染等并发症；\n2.糖皮质激素减量阶段遵医嘱每周复诊，严格按方案缓慢减量，不可自行停药或减量过快；\n3.若出现高热、寒战、心悸、呼吸困难、皮肤破溃化脓或病情反跳，应立即就近急诊就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":496,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"d9418dafd328407507d5aa7abfd845749d44e6325f6dc14a813bd070cf376317","pinyin":"baotuoxingpiyan","initials":"btxpy","setting":"out","caseName":"门诊病历361","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历361",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-715c397a4f78dd1c13e4","key":"v1-c9ccc21dfe2a3058|templates-715c397a4f78dd1c13e4","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"多形红斑","category":"门诊病历模板","raw":{"name":"多形红斑","category":"门诊病历模板","case":{"case_name":"门诊病历362","templates":{"主诉":"手足靶形红斑伴水疱1周","现病史":"患者于5天前，在诱因（单纯疱疹病毒HSV感染最常见，与多形红斑复发相关，为重要诱因；支原体肺炎感染多见于儿童及青年，常继发于呼吸道感染后；药物如磺胺类、抗癫痫药、非甾体抗炎药、别嘌醇、抗生素；真菌感染）作用下出现靶形损害（为本病特征性皮损：圆形水肿性红斑，中央呈暗红或紫红色，可有水疱或坏死，形似靶心，故称靶形或虹膜样损害，皮损呈多形性为重要特点），部位以四肢伸侧、手足背、掌跖为主，面部及躯干少见，自觉症状较轻，可有瘙痒或疼痛，分型为轻型（多形红斑仅皮肤受累，无或轻度黏膜受累），有黏膜受累（口唇糜烂、出血、结痂，眼部结膜或角膜炎）、中央水疱（可呈出血性）、低热等前驱表现，有复发倾向（与HSV相关，可反复发作，部位固定），有HSV感染史（近期唇疱疹），无明确药物史及支原体等呼吸道感染接触史。今日来我院皮肤科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T37.8℃，P88次/分，R18次/分，BP120/80mmHg。皮肤可见靶形皮损（分布于手、足及四肢伸侧，中央呈暗红、水疱或坏死，呈虹膜样或环状，数目较多），黏膜可见口唇糜烂、血痂，颊黏膜及生殖器、眼部黏膜充血，水疱紧张，内容清亮，尼氏征阴性（符合多形红斑），全身浅表淋巴结肿大，伴发热。","辅助检查":"【必做】以临床诊断为主（依据典型靶形皮损、病史及诱因）；【病因】HSV检测（复发型HSV可查PCR或血清学抗体）、支原体抗体或核酸检测（多见于儿童及青年，常继发于呼吸道感染后）、胸片（排查支原体肺炎）、药物史（评估致敏药物）、血常规及CRP（评估感染）、肝肾功能；【确诊】必要时活检（不典型或重症者可见表皮坏死、界面皮炎、血管周围淋巴细胞浸润，用于排除其他疾病，与SJS/TEN、荨麻疹、血管炎、冻疮鉴别）、皮肤直接免疫荧光（排除自身免疫性大疱病及疱疹样皮炎）；【其他】血沉、自身抗体（排查结缔组织病，用于反复或不典型者）、病毒血清学（EBV、巨细胞病毒）。","初步诊断":"1. 多形红斑（轻型：单纯皮肤受累，HSV相关常见；靶形损害；诱因考虑HSV、支原体或药物；需复发评估）\n（注：治疗（依轻重程度，去除诱因，对症处理）：①轻型：本病自限（3~6周可自行消退），对症治疗（止痒用抗组胺药、炉甘石洗剂；止痛用非甾体抗炎药；水疱予保护，防破溃感染，可消毒包扎）；HSV相关者予抗病毒治疗（阿昔洛韦，在疱疹发作时使用可减少多形红斑复发），长期抑制治疗（复发频繁者予阿昔洛韦400mg bid长期抑制HSV，对减少多形红斑发作重要）；②重型或黏膜受累者：按Stevens-Johnson综合征处理（糖皮质激素全身短程患者，尚有争议，多支持用于轻中症；重症需住院；黏膜护理（口腔漱口、眼部润滑及抗生素眼膏防角膜损伤、生殖器护理）、支持治疗（补液、营养），重症住院）；③去除诱因（停用可疑药物，重要，并记录过敏药；治疗支原体感染（大环内酯类阿奇霉素）；HSV感染予抗病毒）；④随访（皮损消退情况（2~3周消退，可遗留色素沉着，后逐渐消退）、复发情况（HSV相关复发者评估长期抑制抗病毒治疗）、重症恢复后黏膜及眼部后遗症随访）；皮肤科处理原则：轻型自限，对症治疗；HSV相关者抗病毒及抑制治疗；药物诱因者停用并避免再接触，甚为重要。）","处理方案":"【药物治疗】\n1. 抗组胺药止痒抗炎：氯雷他定片 10mg 口服 qd×7天（或西替利嗪片 10mg qd）。\n2. 中重度皮损系统抗炎：泼尼松片 30mg 晨起顿服 qd，皮损控制后每3～5天减量5mg，疗程10～14天，不可骤停。\n3. 局部外治：糠酸莫米松乳膏（艾洛松）涂于红斑、丘疹处 bid×7～10天；口腔黏膜糜烂者予复方氯己定含漱液含漱 tid，每次含漱1～2分钟。\n4. 反复发作且与单纯疱疹病毒感染相关者：伐昔洛韦片 0.3g 口服 bid×5～7天，预防复发可于前驱期（局部麻刺感时）起始用药。\n\n【一般治疗及生活指导】\n1. 病因防治：积极寻找并去除诱因，停用可疑致敏药物，治疗潜在感染（尤其是单纯疱疹病毒）；既往药物过敏者永久禁用同类药物并记录过敏史。\n2. 休息与活动：急性期适当休息，避免劳累、熬夜及精神紧张；避免剧烈运动，洗澡水温不宜过高，禁用热水烫洗、搓擦皮损。\n3. 饮食：清淡易消化饮食，忌辛辣刺激、海鲜、牛羊肉及酒精等可能加重病情的食物；口腔黏膜糜烂者进温凉流质或半流质，避免过热、过硬、酸性食物刺激。\n4. 皮肤护理：保持皮损处清洁干燥，穿宽松棉质衣物；避免搔抓以防继发感染，糜烂渗出处可用生理盐水或硼酸溶液湿敷后再涂药。\n\n【随诊要求】\n1. 用药后1周复诊，评估皮损消退及瘙痒缓解情况，调整外用药与口服药方案。\n2. 使用泼尼松者减量期间每周复诊，监测血压、血糖及有无消化道不适等激素不良反应；疗程结束后巩固观察2周。\n3. 若出现皮损迅速扩大、水疱大疱增多、口腔及眼生殖器黏膜广泛糜烂、发热或全身症状加重，需立即复诊或急诊就医；反复发作（每年≥2次）者建议完善HSV抗体等检查，评估抗病毒预防治疗。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":497,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"d656dce61d73c8ec7f95b9389e7373a45edb78619a0a634b0cc895ad571ee86c","pinyin":"duoxinghongban","initials":"dxhb","setting":"out","caseName":"门诊病历362","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历362",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-d3e2fd8ca0ba92e374b7","key":"v1-c9ccc21dfe2a3058|templates-d3e2fd8ca0ba92e374b7","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"重症多形红斑","category":"门诊病历模板","raw":{"name":"重症多形红斑","category":"门诊病历模板","case":{"case_name":"门诊病历363","templates":{"主诉":"皮肤红斑、水疱伴口腔黏膜糜烂5天","现病史":"患者于5天前（用药后10天；常见致敏药物：别嘌醇、抗癫痫药（卡马西平或苯妥英）、磺胺类、NSAIDs、抗生素，或感染（支原体或单纯疱疹）诱发）出现高热（体温最高39.5℃）、乏力，皮肤出现暗红色斑疹并渐融合，中央坏死呈靶形（多形红斑样），出现水疱及大疱（Nikolsky征可阳性，提示表皮松解），口腔、眼结膜、外生殖器黏膜糜烂、血痂、疼痛（至少2处黏膜受累，为SJS及重症多形红斑特征），伴吞咽痛、眼痛畏光、排尿痛，有进行性表皮剥脱（面积按体表面积评估：SJS<10%、SJS/TEN重叠10~30%、TEN>30%）。今日来我院急诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T38.8℃，P110次/分，R22次/分，BP100/65mmHg。神志清楚。皮肤广泛暗红色斑丘疹融合、靶形损害、水疱大疱、表皮松解（Nikolsky征+，轻推表皮即剥离）、糜烂面渗液，累计体表面积约8%，口腔黏膜糜烂、血痂（张口困难），双眼结膜充血糜烂（假膜形成），外阴糜烂，生命体征提示血流动力学不稳定（休克早期可有心率快、血压低，需补液评估）。","辅助检查":"【必做】血常规（白细胞升高或降低、嗜酸性粒细胞增多）、CRP、肝肾功能（警惕药物性肝损伤，尤其别嘌醇及抗癫痫药）、电解质、血气分析、血糖、血培养（发热时排除脓毒症，用于鉴别）；【影像】胸部X线（肺炎，可为支原体相关或吸入性肺炎）；【其他】皮肤活检（表皮全层坏死可确诊，急诊快速冰冻有助于诊断）、眼部分泌物培养、HSV及支原体检测（查找诱因）。","初步诊断":"1. 重症多形红斑/Stevens-Johnson综合征（SJS，药物相关可能，累计体表面积约8%）\n（注：SJS/TEN为皮肤科急危重症（死亡率高，SJS 5~10%、TEN 30%以上），应立即急诊住院（烧伤科或皮肤科ICU模式）：①立即停用所有可疑药物（关键，记录致敏药，终身禁用同类药物）；②支持治疗（核心，类似烧伤）：液体复苏、保温、无菌隔离、创面护理（银离子敷料或油纱，防感染）、营养支持（肠内）；③眼部护理（眼科急会诊，人工泪液加抗生素眼膏加激素眼膏，防角膜损害及粘连，此为最重要的远期并发症，可致失明）；④口腔及外阴护理（漱口、润滑）；⑤药物治疗（有争议但常用）：大剂量糖皮质激素（甲泼尼龙冲击，早期使用或持反对意见，需权衡）、静脉免疫球蛋白（IVIG，用于TEN）、环孢素（近年证据支持用于SJS/TEN，可改善预后）；⑥抗感染（继发感染时按培养结果指导）；⑦并发症防治（败血症、水电解质紊乱、多器官衰竭，需ICU监测）；由皮肤科、眼科、ICU、烧伤科多学科协作，死亡率高，应转有条件医院。）","处理方案":"【药物治疗】\n1. 糖皮质激素：泼尼松片30~40mg qd晨起顿服×7天，症状控制后每3~5天减量5mg，直至停药，总疗程2~4周（门诊成人常规剂量，需监测血压、血糖）。\n2. 抗组胺药：氯雷他定片10mg qd×14天；或西替利嗪片10mg qd×14天，用于止痒及减轻炎症反应。\n3. 外用药：未破溃皮损外用炉甘石洗剂适量 bid×7~14天；干燥脱屑处外用糠酸莫米松乳膏适量 qd；糜烂破溃处外用莫匹罗星软膏适量 bid预防继发感染。\n4. 辅助支持：维生素C片0.2g tid、葡萄糖酸钙片0.5g tid×14天；伴口腔黏膜糜烂者加用复方氯己定含漱液漱口 tid，伴眼部受累者予红霉素眼膏睡前涂眼。\n\n【一般治疗及生活指导】\n1. 卧床休息，减少活动；病情进展迅速、黏膜广泛受累或伴持续高热者建议转住院治疗，门诊治疗期间密切观察病情变化。\n2. 清淡、高蛋白流质或半流质饮食，禁食辛辣、海鲜、酒类等刺激性及易致敏食物，保证饮水。\n3. 加强皮肤及黏膜护理：口腔糜烂者用温凉流质饮食，饭后漱口；眼部用生理盐水冲洗后涂红霉素眼膏，防止睑球粘连；保持会阴部清洁干燥。\n4. 立即停用并终生避免可疑致敏药物，避免再次接触致敏原；穿宽松棉质衣物，避免搔抓、热水烫洗及日晒刺激皮损。\n\n【随诊要求】\n1. 用药后3~5天复诊，评估皮损消退及黏膜愈合情况，糖皮质激素需遵医嘱逐步减量，不可自行停药或减量过快。\n2. 治疗期间每周复查血常规、肝肾功能及电解质；如出现新发水疱大疱、口腔黏膜糜烂加重、高热不退、眼痛畏光或呼吸困难，立即就近急诊就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":498,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"41e8c213605fa265c893d018f79841cc280141771150bd65635d3e99af4dee9f","pinyin":"zhongzhengduoxinghongban","initials":"zzdxhb","setting":"out","caseName":"门诊病历363","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历363",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-d4a0bfcd91ca8b29de63","key":"v1-c9ccc21dfe2a3058|templates-d4a0bfcd91ca8b29de63","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"中毒性表皮坏死松解症","category":"门诊病历模板","raw":{"name":"中毒性表皮坏死松解症","category":"门诊病历模板","case":{"case_name":"门诊病历364","templates":{"主诉":"皮肤红斑、水疱伴大面积剥脱5天","现病史":"患者于4天前（用药后1~3周；常见致敏药物：别嘌醇、卡马西平、苯妥英、磺胺、奈韦拉平、NSAIDs，或感染诱发）出现高热（>39℃）及流感样前驱症状（乏力、咽痛、眼痛），随后皮肤出现暗红色斑并迅速融合，伴疼痛，出现水疱大疱及大面积表皮松解（Nikolsky征强阳性，轻推或轻擦表皮即大片剥脱，露出红色糜烂创面，类似烫伤），口、眼、生殖器、肛门黏膜广泛糜烂（疼痛，不能进食，伴眼痛、尿痛），表皮剥脱面积40%（>30%，符合TEN），有呼吸困难（呼吸道黏膜受累，气管支气管上皮脱落，有窒息风险），伴少尿（提示肾损伤）。今日来我院急诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T39.0℃，P120次/分（增快），R24次/分，BP95/60mmHg。神志清楚。全身皮肤可见广泛融合的暗红色斑疹，大量松解水疱，表皮大面积剥脱（累计面积约40%体表面积，糜烂创面渗液、触痛剧烈）、Nikolsky征（+），口腔、眼结膜、鼻腔、外生殖器黏膜广泛糜烂血痂（眼睑粘连、角膜浑浊，病情严重）、指趾甲可脱落，生命体征及尿量提示休克、少尿（需评估）。","辅助检查":"【必做】血常规、CRP、肝肾功能、电解质、血气分析、血糖、血培养及创面培养（感染为死亡主因之一）、凝血功能；【确诊】皮肤活检加冰冻（可见表皮全层坏死，用于急诊快速诊断，可与葡萄球菌性烫伤样综合征鉴别；SSSS多见于儿童，为表皮浅层剥脱，Nikolsky征阳性但黏膜不受累，以抗生素治疗）；【影像】胸部X线或CT（评估呼吸道受累，如黏膜脱落或肺炎）；【其他】眼科评估（裂隙灯查角膜，急会诊）。","初步诊断":"1. 中毒性表皮坏死松解症（TEN，药物相关高度可能，剥脱面积>30%体表面积）\n（注：TEN为致死性皮肤急症（死亡率30~50%），应立即收入烧伤科或ICU：①即刻停用全部可疑药物（永久记录）；②烧伤式支持治疗（核心，决定预后）：隔离无菌、液体复苏（按烧伤补液原则）、创面护理（生物敷料或银敷料，减少感染及体液丢失）、营养（早期肠内）、体温维持、镇痛；③眼科急会诊（防角膜损害及粘连致失明，及时处理，长期眼表护理）；④药物：环孢素（有证据支持，可降低死亡率，早期使用）、大剂量糖皮质激素（早期使用，有争议）、IVIG（疗效不确切）；⑤抗感染（按培养结果指导，不预防性常规使用，防耐药）；⑥多器官支持（ICU：呼吸方面如黏膜脱落、肺炎；肾方面如肌红蛋白、药物损伤；DIC方面监测凝血）；⑦并发症（脓毒症、消化道出血、电解质紊乱，可致多器官衰竭，为死亡主因）；由皮肤科、烧伤科、ICU、眼科多学科救治，有条件者转专科中心。）","处理方案":"【药物治疗】\n根据病情紧急处理，具体用药根据诊断和生命体征决定。\n\n【一般治疗及生活指导】\n卧床休息，密切监测生命体征，保持呼吸道通畅，建立静脉通路。\n\n【随诊要求】\n根据病情决定是否住院或留观，如症状加重立即就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":499,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"cbeda1da13f0af196ac11fc89baf96f85a6f95cbaf896b4d23d6243e481beffc","pinyin":"zhongduxingbiaopihuaisisongjiezheng","initials":"zdxbphssjz","setting":"out","caseName":"门诊病历364","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历364",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-513ac14c9da60d91decf","key":"v1-c9ccc21dfe2a3058|templates-513ac14c9da60d91decf","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"天疱疮","category":"门诊病历模板","raw":{"name":"天疱疮","category":"门诊病历模板","case":{"case_name":"门诊病历365","templates":{"主诉":"口腔黏膜及皮肤水疱、糜烂2月","现病史":"患者于2周前出现口腔黏膜（颊、腭，常为首发）水疱易破、疼痛性糜烂、经久不愈、进食困难，及皮肤（躯干头面）水疱壁薄、松弛易破，破后形成糜烂面、疼痛，水疱大疱易破裂形成糜烂结痂、不易愈合、向周围扩展，Nikolsky征阳性（推压水疱处表皮分离扩展，为特征性表现），（分型为寻常型，最常见，皮肤黏膜均有受累；其余为落叶型，表浅、糜烂结痂、似剥脱性皮炎、黏膜少受累，以及增殖型、红斑型），无发热或低热，无药物诱发因素（青霉胺/卡托普利可诱导性天疱疮），无胸腺瘤/重症肌无力（副肿瘤性天疱疮，少见），无肿瘤，一般情况渐差（广泛皮损致蛋白丢失、感染）。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.8℃，P78次/分，R18次/分，BP120/80mmHg。口腔黏膜可见多处糜烂面及残存水疱壁，皮肤可见松弛性水疱大疱（疱壁薄易破，内含清亮液体）、糜烂面（鲜红渗液）、结痂，多处分布，Nikolsky征（+），无甲脱落，无眼结膜受累，全身皮肤受累面积约30%。","辅助检查":"【必做】皮肤/黏膜活检（组织病理：棘层松解（表皮内水疱）、Tzanck细胞：寻常型：基底层上棘层松解；落叶型：颗粒层/角层下：确诊组织学）；【免疫病理】直接免疫荧光（DIF：皮损周围正常皮肤：IgG/C3沉积于表皮细胞间（网状/鱼网样）：确诊金标准）、间接免疫荧光（血清抗表皮细胞间抗体（抗桥粒芯蛋白：Dsg1/Dsg3抗体：ELISA：寻常型抗Dsg3为主/落叶型抗Dsg1，分型及监测）；【其他】血常规、肝肾功能、血糖（激素前基线）、肿瘤筛查（副肿瘤性，顽固者）。","初步诊断":"1. 天疱疮（寻常型，自身免疫性大疱病）\n（注：治疗（免疫抑制为核心，皮肤科专科，病程长）：①糖皮质激素（一线，泼尼松1~1.5mg/kg/d，足量控制，皮损停止出现新疱后渐减，疗程常1~2年以上，缓慢减量防复发，注意激素不良反应，监测血糖、血压、骨密度）；②免疫抑制剂（激素减量困难或难治者联合）：硫唑嘌呤（查TPMT）、吗替麦考酚酯、环磷酰胺（重症）、利妥昔单抗（抗CD20，中重度，近年一线联合或激素不佳者，疗效好）；③局部护理（口腔：激素软膏/漱口；皮肤糜烂：湿敷+抗菌，防感染）；④抗Dsg抗体滴度监测（疗效及复发预测）；⑤防治并发症（感染（创面，葡萄球菌）、水电解质紊乱（大面积糜烂按烧伤管理）、激素不良反应）；⑥避免诱发药物；治疗目标为控制皮损、渐减激素至最小维持量（部分可停药）；预后较前改善，但需长期随访，警惕复发及治疗并发症，多学科（皮肤科/口腔科/营养）管理。）","处理方案":"【药物治疗】\n1. 糖皮质激素（首选）：泼尼松片40-60mg/d（0.75-1.0mg/kg/d）晨起顿服，皮损控制（无新发水疱、糜烂面干燥）后维持2-3周再开始减量，每1-2周减5mg，至维持量10-15mg/d长期维持。\n2. 免疫抑制剂（与激素联用以减少激素用量及不良反应）：霉酚酸酯胶囊0.5g bid；或硫唑嘌呤片50mg bid（用药前检查血常规、肝肾功能及TPMT活性）。若激素疗效不佳或减量困难，可改用环磷酰胺50mg qd。\n3. 局部治疗：糜烂面外用夫西地酸乳膏涂于皮损处 bid，预防继发感染；口腔糜烂者予复方氯己定含漱液10ml含漱 tid，糜烂面涂曲安奈德口腔软膏 tid。\n4. 对症支持：糜烂面广泛伴渗出或继发感染者，加用头孢克肟胶囊0.1g bid×7天抗感染。\n\n【一般治疗及生活指导】\n1. 休息：皮损广泛、糜烂面大者应卧床休息，减少摩擦与压迫，避免体力活动。\n2. 饮食：高蛋白、高热量、富含维生素的软食或半流质；口腔糜烂者进食温凉流质，避免辛辣、过热、粗糙及过酸食物刺激。\n3. 皮肤护理：保持创面清洁干燥，穿着宽松柔软的纯棉衣物，勤剪指甲，避免搔抓、搓擦及热水烫洗；大疱未破者避免挤压。\n4. 禁忌：避免使用含巯基等可能诱发或加重本病的药物（如青霉胺、卡托普利、苯巴比妥等）；严格遵医嘱用药，切勿自行增减或突然停用糖皮质激素。\n\n【随诊要求】\n1. 治疗初期每周复诊1次，评估新发水疱及糜烂面愈合情况，监测血压、血糖、血常规、肝肾功能及电解质。\n2. 激素减量期每2-4周复诊1次，根据皮损控制情况调整激素及免疫抑制剂剂量，监测血常规、肝肾功能及免疫抑制剂不良反应。\n3. 维持期每1-3个月复诊1次，定期监测血糖、血脂、骨密度及感染情况，防治激素长期患者相关并发症。\n4. 如出现新发水疱明显增多、糜烂面扩大、发热或感染征象，应立即就诊，不可拖延。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":500,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"ee5305603481d0966ac045ea2efc2d7dee871cecc3fc1a2351dd3f1527e0b1a3","pinyin":"tianpaochuang","initials":"tpc","setting":"out","caseName":"门诊病历365","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历365",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-7a1833d45650fc6cd7d4","key":"v1-c9ccc21dfe2a3058|templates-7a1833d45650fc6cd7d4","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"大疱性类天疱疮","category":"门诊病历模板","raw":{"name":"大疱性类天疱疮","category":"门诊病历模板","case":{"case_name":"门诊病历366","templates":{"主诉":"四肢躯干水疱伴瘙痒2月","现病史":"患者（老年，>60岁）于2个月前在四肢屈侧、躯干下腹出现紧张性大疱（疱壁厚、紧张、不易破裂，区别于天疱疮的松弛性薄壁疱），疱液清亮或血性，周围红斑/荨麻疹样皮损，伴瘙痒（可先出现瘙痒性荨麻疹样/湿疹样皮损数周至数月（前驱期），后出现大疱），水疱破裂后形成糜烂面（较天疱疮浅，愈合较快），口腔黏膜受累少见（约10~30%，为轻型糜烂），无神经系统疾病（痴呆/脑血管病/帕金森，可相关），无药物诱发因素（袢利尿剂/螺内酯/抗生素/DPP-4抑制剂（西格列汀），药物相关），无恶性肿瘤（少见相关），一般情况尚可，瘙痒影响睡眠。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.6℃，P76次/分，R18次/分，BP130/80mmHg。四肢屈侧、下腹、躯干可见数个至数十个紧张性大疱（直径1~3cm，疱壁厚、疱液清/血性）、周围红斑，部分破裂后可见糜烂面（较浅）、结痂，Nikolsky征阴性（重要鉴别点，区别于天疱疮），口腔黏膜可见少数糜烂，瘙痒抓痕。","辅助检查":"【必做】皮肤活检（组织病理：表皮下水疱、真皮嗜酸性粒细胞浸润，区别于天疱疮：表皮内）；【免疫病理】直接免疫荧光（DIF：皮损周围：基底膜带IgG/C3线状沉积：确诊）、间接免疫荧光（抗基底膜带抗体）及ELISA（抗BP180/BP230抗体：特异性：诊断及监测）；【其他】血常规（嗜酸性粒细胞可升高）、肝肾功能血糖（激素基线）、药物史评估（疑药源性）。","初步诊断":"1. 大疱性类天疱疮（老年性类天疱疮，自身免疫性表皮下大疱病）\n（注：治疗（较天疱疮预后好，多数可控制）：①外用强效糖皮质激素（氯倍他索乳膏，局限性/轻中度可单独控制；大面积者以外用为主，避免系统激素）；②系统激素（广泛者）：泼尼松0.5~0.75mg/kg/d（较天疱疮剂量低，老年患者注意骨质疏松/血糖/感染，补钙及维生素D）；③免疫抑制剂（激素减量时）：硫唑嘌呤/吗替麦考酚酯/甲氨蝶呤；④四环素+烟酰胺（多西环素200mg/d+烟酰胺1.5g/d，轻中度，抗炎，老年可接受）；⑤利妥昔单抗（难治性）、静脉免疫球蛋白（重症，少用）；⑥局部护理（大疱：无菌抽液保留疱壁；糜烂面：抗菌软膏，防感染；老年卧床者压疮预防）；⑦并发症防治（感染（金黄色葡萄球菌，创面）、激素不良反应、血栓（老年+激素，活动/抗凝评估））；⑧疗程（多数需1~2年，缓慢减药，定期随访，抗BP180抗体监测，皮肤科专科管理）。）","处理方案":"【药物治疗】\n1. 泼尼松片（系统糖皮质激素）：30～40mg qd（按0.5～1mg/kg/d）晨起顿服，为轻中度BP一线用药；新疱停止出现、瘙痒明显缓解后每1～2周减量5mg，减至15～20mg/d后放慢减量速度（每2～4周减2.5mg），以5～10mg/d小剂量维持6～12个月，总疗程1～2年，务必缓慢减量以防复发。\n2. 0.05%丙酸氯倍他索乳膏（强效外用糖皮质激素）：外涂皮损处bid，适用于局限型或轻症患者，亦可作为系统激素减量期的辅助治疗，皮损控制后逐渐减少涂药频次。\n3. 盐酸米诺环素胶囊100mg bid + 烟酰胺片0.5g tid，适用于轻中度患者或激素减量期联合用药，疗程4～8周后据疗效调整，注意米诺环素头晕、色素沉着等不良反应。\n4. 硫唑嘌呤片50mg bid（1～2mg/kg/d），用于中重度患者激素疗效不佳或为减少激素用量时联合患者，用药前及用药期间定期检测血常规、肝肾功能及TPMT活性。\n\n【一般治疗及生活指导】\n1. 注意休息，皮损广泛者卧床休息；穿宽松棉质衣物，勤剪指甲，避免搔抓、摩擦及热水烫洗皮损，防止水疱破裂继发感染。\n2. 大疱疱液较多时可在无菌操作下低位穿刺抽吸疱液并保留疱顶，外涂碘伏或莫匹罗星软膏预防感染；口腔、眼、外阴等黏膜受累时加强清洁护理。\n3. 饮食宜高蛋白、高维生素、易消化，激素治疗期间适量补钙及维生素D，限制钠盐及糖摄入；忌辛辣刺激及可能诱发过敏的饮食。\n4. 避免暴晒、外伤及使用可能诱发或加重病情的药物（如呋塞米、螺内酯、某些抗生素及生物制剂），预防跌倒，皮肤破损处注意防感染。\n\n【随诊要求】\n1. 治疗初期每1～2周复诊1次，评估新疱出现情况、瘙痒程度及皮损愈合情况，监测血压、血糖、电解质、肝肾功能及血常规（尤以使用硫唑嘌呤者）；病情稳定后每2～4周复诊1次。\n2. 长期系统激素治疗者每3～6个月复查骨密度、眼压、血脂，定期监测血糖，注意防治激素相关不良反应；出现发热、皮损化脓、糜烂扩大、呼吸困难或吞咽困难时立即就诊。\n3. 激素减量期间若出现新发水疱或瘙痒加重，及时复诊调整方案，不可自行停药或骤减激素；停药后建议随访至少6个月观察有无复发。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":501,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"01ec7221f11185ad1ae51aca68b7ad5121e2c99fb9a7e596f762c6382b870b63","pinyin":"dapaoxingleitianpaochuang","initials":"dpxltpc","setting":"out","caseName":"门诊病历366","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历366",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-d05c603b4fe3d7dc2988","key":"v1-c9ccc21dfe2a3058|templates-d05c603b4fe3d7dc2988","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"疱疹样皮炎","category":"门诊病历模板","raw":{"name":"疱疹样皮炎","category":"门诊病历模板","case":{"case_name":"门诊病历367","templates":{"主诉":"肘膝伸侧丘疹、水疱伴瘙痒1月","现病史":"患者于1年前在肘、膝伸侧、臀部、肩胛（伸侧对称，为特征）出现成簇分布的瘙痒性小丘疹、水疱（疱疹样排列，簇状），剧烈瘙痒（烧灼感），搔抓后水疱破裂结痂、色素沉着，反复发作，伴乳糜泻/谷胶敏感性肠病（疱疹样皮炎与乳糜泻密切相关，小肠活检可见绒毛萎缩，但多数肠道症状轻微或无症状），进食面食（麸质）后加重，接触碘化物后加重，伴甲状腺疾病（自身免疫性甲状腺病，相关）。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.7℃，P86次/分，R20次/分，BP110/70mmHg。肘膝伸侧、臀部、肩胛可见对称分布的成簇丘疹、小水疱（直径0.2~0.5cm，疱壁厚，完整或破溃结痂）、抓痕、色素沉着，口腔黏膜不受累（区别于天疱疮）。","辅助检查":"【必做】皮肤活检（组织病理：真皮乳头层中性粒细胞微脓肿、表皮下分离）；【免疫病理】皮损周围正常皮肤直接免疫荧光（DIF：真皮乳头颗粒状IgA沉积：确诊金标准：诊断必需）；【乳糜泻筛查】血清抗组织转谷氨酰胺酶抗体（tTG-IgA）及抗肌内膜抗体（EMA）、十二指肠活检（确诊乳糜泻，合并评估，与皮肤病相关）；【其他】血常规（嗜酸性）、甲状腺功能及抗体（自身免疫甲状腺病筛查）。","初步诊断":"1. 疱疹样皮炎（Duhring病，谷胶敏感性肠病皮肤表现）\n（注：①无麸质饮食（终身，核心治疗，去除谷胶后皮损及肠病均改善，需坚持3~6个月见效，饮食咨询）；②药物治疗（桥接，无麸质饮食起效前）：氨苯砜（50~100mg qd，疗效迅速，数天至2周控制瘙痒及新疱，注意溶血（G6PD缺乏者禁用，查G6PD）、高铁血红蛋白血症、粒细胞缺乏，用药前及定期查血常规肝功，需专科处方）；③局部：外用糖皮质激素（止痒）、抗组胺药；④补碘限制（海产品碘可加重，以无麸质饮食为主时不必严格限碘）；⑤治疗甲状腺疾病（并存者）；⑥随访（皮肤科+消化科，无麸质饮食依从性，小肠及营养监测，乳糜泻相关并发症，淋巴瘤风险（未治疗乳糜泻者低））。）","处理方案":"【药物治疗】\n1. 氨苯砜片（一线首选药物）50mg bid口服，首周自25mg qd起始逐渐加量，皮损控制后渐减至25～50mg qd长期维持；用药前须筛查G6PD缺乏症，治疗期间监测血常规。\n2. 氯雷他定片10mg qd口服×2～4周，瘙痒明显时联合使用以控制症状。\n3. 糠酸莫米松乳膏适量外用bid×2周，涂于皮损处抗炎止痒，消退后停用。\n4. 炉甘石洗剂适量外用tid，用于丘疱疹处收敛干燥；破溃糜烂处改用莫匹罗星软膏外用bid×5～7天预防继发感染。\n【一般治疗及生活指导】\n1. 严格无麸质饮食（终身执行）：禁食小麦、大麦、黑麦及其制品（面包、面条、馒头、啤酒、麦芽等），可进食大米、玉米、大豆、土豆、薯类，可减轻小肠病变并减少皮损复发。\n2. 限制高碘饮食：少食海带、紫菜、海鱼、海虾等海产品及含碘食盐，避免使用含碘药物，碘可诱发或加重皮损。\n3. 生活起居：注意休息、避免劳累及精神紧张；穿宽松棉质内衣，避免搔抓及热水烫洗，保持皮损处清洁干燥，防止继发感染。\n4. 禁忌：治疗期间禁酒；服用氨苯砜期间避免驾驶及高空作业（可引起头晕、乏力）；妊娠期慎用氨苯砜，育龄期注意避孕。\n【随诊要求】\n1. 用药后2～4周复诊，评估皮损消退及瘙痒改善情况，据此调整氨苯砜至最小有效维持量。\n2. 氨苯砜治疗期间每周复查血常规及网织红细胞，每1～3个月复查肝肾功能，监测溶血性贫血、粒细胞减少及药物性肝损伤等不良反应。\n3. 建议转诊消化内科评估伴发乳糜泻（检测血清抗肌内膜抗体、抗组织转谷氨酰胺酶抗体，必要时行小肠黏膜活检），确诊后长期随访。\n4. 长期随访中注意监测甲状腺功能及伴发其他自身免疫性疾病，定期复查评估病情活动度。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":502,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"fbcd9e5ef5821ead17dfb9f23b3f088092dfff4c5dd533a1245d91f4feec6ad6","pinyin":"paozhenyangpiyan","initials":"pzypy","setting":"out","caseName":"门诊病历367","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历367",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-d175de9f34df42c27455","key":"v1-c9ccc21dfe2a3058|templates-d175de9f34df42c27455","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"获得性大疱性表皮松解症","category":"门诊病历模板","raw":{"name":"获得性大疱性表皮松解症","category":"门诊病历模板","case":{"case_name":"门诊病历368","templates":{"主诉":"摩擦部位水疱、糜烂6月","现病史":"患者（成人发病，为获得性，区别于遗传性大疱性表皮松解症的婴幼儿发病）于6个月前在手背、指关节、肘膝、踝等摩擦/外伤部位出现水疱大疱（轻微外伤即出现，机械性脆性皮肤）、糜烂，愈合后遗留萎缩性瘢痕、粟丘疹（为特征，与类天疱疮区别，后者愈合不留瘢痕），伴口腔黏膜糜烂（瘢痕性，类似于瘢痕性类天疱疮，可累及眼/食管/肛门黏膜）、甲营养不良/脱落，无炎症性肠病（克罗恩病与EBA相关），无系统性红斑狼疮（SLE可并发EBA），无副蛋白血症，无或轻度瘙痒。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.6℃，P78次/分，R18次/分，BP118/76mmHg。手背、指节、肘膝、踝等摩擦部位可见非炎症性水疱大疱（疱壁紧张）、糜烂面、萎缩性瘢痕、粟丘疹（白色小丘疹，特征性）、色素改变，口腔黏膜可见糜烂/瘢痕（重症），眼结膜可见瘢痕（重症，瘢痕性类天疱疮样）。","辅助检查":"【必做】皮肤活检（组织病理：表皮下大疱、真皮浅层炎症轻）；【免疫病理】直接免疫荧光（DIF：基底膜带IgG线状沉积，但此与类天疱疮相同，需盐裂皮肤间接免疫荧光（IIF：IgG沉积于盐裂皮肤真皮侧（基底板下），区别于类天疱疮（表皮侧、半桥粒），关键鉴别）或免疫电镜（锚原纤维、Ⅶ型胶原）、ELISA（抗Ⅶ型胶原抗体）；【其他】血常规、肝肾功能、ANA（SLE相关，筛查）、炎症性肠病评估（肠道症状者）。","初步诊断":"1. 获得性大疱性表皮松解症（EBA，抗Ⅶ型胶原自身免疫性表皮下大疱病）\n（注：治疗（顽固，预后较类天疱疮差）：①糖皮质激素（泼尼松0.5~1mg/kg/d）+免疫抑制剂（硫唑嘌呤/吗替麦考酚酯/环磷酰胺联合，多数需联合）；②秋水仙碱（部分患者0.5mg bid，相对有效且安全，可尝试）；③利妥昔单抗（难治性，近年用于EBA）、静脉免疫球蛋白（重症）；④氨苯砜（部分炎症型）；⑤对症及护理：避免外伤摩擦（保护性穿戴）、创面护理（防感染，糜烂面）、甲护理、口腔及眼护理（瘢痕性黏膜受累及眼受累者防失明，眼科随访）；⑥治疗相关疾病（克罗恩病、SLE、副蛋白血症）；⑦疗程长，缓慢减药防复发，皮肤科专科（大疱病中心）管理，长期随访（瘢痕、功能障碍、慢性溃疡处继发鳞癌，极少数）。）","处理方案":"【药物治疗】\n1. 醋酸泼尼松片 40mg（0.5～1mg/kg）晨起顿服，每日1次，皮损控制后每2～4周递减5mg，疗程3～6个月，激素减量过程中密切观察皮损反弹。\n2. 秋水仙碱片 0.5mg 口服 每日2～3次（每日总量1～1.5mg），疗程至少3个月，用药期间监测血常规及肝肾功能，出现腹泻、恶心等胃肠道反应时减量或停用。\n3. 氨苯砜片 50mg 口服 每日1次（无效时可渐加至100mg/d），用药前须筛查葡萄糖-6-磷酸脱氢酶缺乏症，定期复查血常规，监测溶血及高铁血红蛋白血症，疗程视病情而定。\n4. 吗替麦考酚酯胶囊 0.5g 口服 每日2次，用于糖皮质激素疗效不佳或需减少激素用量者，疗程3～6个月，用药期间监测血常规、肝肾功能并注意预防感染。\n【一般治疗及生活指导】\n1. 休息与防护：避免外伤、摩擦、搔抓及剧烈活动，穿宽松柔软的纯棉衣物，剪短指甲，避免佩戴粗糙饰品，减少对皮肤的机械刺激。\n2. 皮损护理：小水疱让其自行吸收，大疱在无菌操作下穿刺减压并保留疱壁；糜烂创面以碘伏消毒后外涂莫匹罗星软膏并覆盖凡士林纱布或无菌敷料，保持清洁干燥，预防继发感染。\n3. 饮食：高蛋白、高维生素、易消化饮食（如鸡蛋、瘦肉、鱼肉、新鲜蔬果），加强营养促进创面愈合，忌辛辣、过烫及易致敏食物。\n4. 用药禁忌：服药期间避免饮酒及服用光敏性药物；氨苯砜及部分抗生素可加重光敏反应，外出注意防晒；禁止自行搔抓、撕剥痂皮及疱壁。\n【随诊要求】\n1. 每2周门诊复诊1次，评估水疱、糜烂及新发皮损情况，动态调整激素用量。\n2. 长期患者糖皮质激素者每2～4周监测血压、血糖、血电解质、肝肾功能及血常规，并定期行骨密度检查，必要时加用钙剂和维生素D预防骨质疏松。\n3. 患者氨苯砜者每2周复查血常规，监测溶血性贫血及高铁血红蛋白血症；患者免疫抑制剂者每月复查肝肾功能及血常规。\n4. 每3～6个月复查抗Ⅶ型胶原抗体（间接免疫荧光或ELISA）滴度评估病情活动度；出现发热、创面红肿化脓、脓性分泌物等继发感染征象时及时就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":503,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"28d4a0071b4210aa5eff73220c51048893d0d79088139886e5e9a0db90941856","pinyin":"huodexingdapaoxingbiaopisongjiezheng","initials":"hdxdpxbpsjz","setting":"out","caseName":"门诊病历368","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历368",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-3daa6c4d3c8c28ba41a2","key":"v1-c9ccc21dfe2a3058|templates-3daa6c4d3c8c28ba41a2","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"线状IgA大疱性皮病","category":"门诊病历模板","raw":{"name":"线状IgA大疱性皮病","category":"门诊病历模板","case":{"case_name":"门诊病历369","templates":{"主诉":"躯干、臀部水疱伴瘙痒2周","现病史":"患儿于1周前在臀部、口周、躯干下部出现瘙痒性水疱大疱，排列呈环形/匐行性（水疱沿红斑边缘排列，呈珍珠串样/玫瑰花环样，为特征），疱壁紧张，破溃结痂，无用药史（万古霉素为药物相关线状IgA病的常见诱因，成人多见），无感染前驱史，无口腔黏膜受累，瘙痒程度不一。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.8℃，P120次/分，R28次/分，BP90/60mmHg。臀部、口周可见环形/匐行性红斑边缘排列成串的小水疱大疱（疱壁紧张）、糜烂结痂，口腔黏膜无受累。","辅助检查":"检查计划：患儿躯干、臀部及口周出现瘙痒性水疱大疱2周，排列呈环形、匐行性，疱壁紧张、破溃结痂，为明确水疱性质并与其他表皮下水疱病鉴别，入院后即完善皮肤活检，行组织病理检查了解有无表皮下大疱及真皮乳头中性粒细胞微脓肿；本病确诊依赖免疫病理，故同时于皮损周围皮肤完善直接免疫荧光（DIF）检查，明确有无基底膜带IgA线状沉积，以区别于疱疹样皮炎的颗粒状IgA沉积；为评估有无循环抗体，完善间接免疫荧光检查，了解血清中IgA抗基底膜抗体情况；患儿本次起病无感染前驱史，完善血常规检查排除感染、贫血所致；因计划首选氨苯砜治疗，用药前需完善G6PD活性检测以排除葡萄糖-6-磷酸脱氢酶缺乏，避免溶血风险；氨苯砜经肝肾代谢，完善肝肾功能检查排除肝肾功能不全；病程中需长期监测血液学毒性，完善网织红细胞计数及高铁血红蛋白测定了解有无溶血及高铁血红蛋白血症；患儿水疱面积较广、瘙痒明显，完善电解质及白蛋白检查评估营养及内环境状态；为鉴别儿童其他大疱性疾病，查抗BP180、BP230抗体以排除大疱性类天疱疮；氨苯砜治疗期间定期复查血常规、肝肾功能，监测药物不良反应并指导用药剂量调整。\n\n（检查清单）\n【必做】皮肤活检（组织病理：表皮下大疱、真皮乳头中性粒细胞微脓肿，与疱疹样皮炎相似）；【确诊】直接免疫荧光（DIF：基底膜带IgA线状沉积，区别于疱疹样皮炎的颗粒状IgA沉积，确诊关键）；【其他】间接免疫荧光（循环IgA抗基底膜抗体，部分）、血常规。","初步诊断":"1. 线状IgA大疱性皮病（儿童良性慢性大疱病）\n（注：①氨苯砜（50~100mg qd，首选，疗效显著，数天至1周控制，注意溶血（查G6PD）、高铁血红蛋白血症、粒细胞减少，监测血常规）；②磺胺吡啶（氨苯砜不耐受者的替代）；③无麸质饮食（部分成人谷胶相关者尝试，儿童多为自限性）；④局部：糖皮质激素外用（辅助止痒）；⑤药物相关（万古霉素诱发）者停药后多自行缓解，避免再用；⑥儿童型多数2~3年自行缓解（青春期前），但需治疗控制瘙痒防瘢痕；成人型为慢性，需长期维持（最小有效氨苯砜剂量）；⑦口腔受累者予激素含漱/软膏；皮肤科随访（氨苯砜监测，血常规肝功初始每1~2周，后每月）。）","处理方案":"【药物治疗】\n1. 氨苯砜片50mg bid口服（必要时可加至100mg bid），为本病一线治疗药物，一般2~4周起效；病情控制后渐减至最小有效维持量，疗程常需3~6个月以上。用药前务必筛查葡萄糖-6-磷酸脱氢酶（G6PD）缺乏症，用药第1个月内每周复查血常规及网织红细胞，此后每2~4周复查肝肾功能。\n2. 对氨苯砜不耐受或疗效不佳者，可联合或换用磺胺吡啶片500mg qid口服（1~2g/d）；或烟酰胺片500mg tid联合米诺环素胶囊100mg bid口服。\n3. 皮损广泛、病情较重者，加用泼尼松片0.5~1mg/kg/d晨起顿服，与氨苯砜联用，待新疱停止出现、糜烂面愈合后每1~2周减量，逐渐减停。\n4. 皮损局限或辅助治疗：外用糖皮质激素乳膏（如糠酸莫米松乳膏）涂患处bid；大疱张力高者由医师无菌操作穿刺抽液减压、保留疱壁，糜烂面外涂莫匹罗星软膏bid预防感染。\n\n【一般治疗及生活指导】\n1. 急性期适当休息，避免剧烈运动、皮肤摩擦与搔抓；穿宽松柔软的纯棉衣物，勤剪指甲，减少外伤诱发新疱。\n2. 注意皮损护理：水疱避免自行挑破，张力大者由医生无菌操作减压并保留疱壁；糜烂面保持清洁干燥、及时更换敷料，防止继发细菌感染。\n3. 饮食宜高蛋白、富含维生素且易消化，促进创面愈合；忌辛辣、过烫及刺激性食物，戒烟戒酒。\n4. 线状IgA大疱性皮病可被药物诱发（如万古霉素、青霉素类、非甾体抗炎药等），避免自行服用上述药物；遵医嘱规律服药，不可自行停药、减量或加量，服药期间出现发热、咽痛、乏力、贫血、口唇发绀等及时就诊。\n\n【随诊要求】\n治疗初期每1~2周复诊1次，评估皮疹消退情况与药物不良反应；服用氨苯砜期间按医嘱定期复查血常规、网织红细胞、肝肾功能及尿常规（第1个月每周查血常规，病情稳定后每2~4周复查）。病情稳定后每1~3个月复诊1次以调整维持剂量；减量或停药后仍需随访3~6个月观察有无复发，若出现新发水疱、糜烂扩大或发热等感染征象，随时就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":504,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"8154f92233b94a571d1894ada2ca4755d986e085d07b3db83d9187a438b92c0f","pinyin":"xianzhuangIgAdapaoxingpibing","initials":"xzIdpxpb","setting":"out","caseName":"门诊病历369","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历369",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-cf7f3e0579d13c143bbf","key":"v1-c9ccc21dfe2a3058|templates-cf7f3e0579d13c143bbf","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"妊娠疱疹","category":"门诊病历模板","raw":{"name":"妊娠疱疹","category":"门诊病历模板","case":{"case_name":"门诊病历370","templates":{"主诉":"腹部瘙痒性红斑、水疱3周","现病史":"孕妇（初产妇）于妊娠28周（多在中晚期，也可产后即刻）开始于脐周/腹部出现剧烈瘙痒、荨麻疹样红斑丘疹，渐发展水疱大疱（妊娠疱疹，为自身免疫性表皮下大疱病，与妊娠相关，复发性，再次妊娠可更早更重）、环形红斑，向四肢扩散，瘙痒剧烈（影响睡眠），部分水疱破裂，无口腔黏膜受累（少见），既往无妊娠疱疹发作史，无甲状腺疾病（自身免疫甲状腺病，相关），无口服避孕药诱发史。今日来我院产科/皮肤科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.7℃，P88次/分，R18次/分，BP110/70mmHg。腹部（脐周为主）及四肢可见荨麻疹样斑块、环形红斑基础上紧张性水疱大疱（疱壁厚）、糜烂结痂、抓痕，口腔黏膜无受累。","辅助检查":"【必做】皮肤活检（组织病理：表皮下大疱、嗜酸性粒细胞浸润）；【免疫病理】直接免疫荧光（DIF：基底膜带C3线状沉积（100%）伴IgG，确诊）、间接免疫荧光/ELISA（抗BP180抗体，妊娠疱疹，与类天疱疮同靶抗原）；【其他】血常规（嗜酸性粒细胞升高）、肝肾功能、甲状腺抗体（自身免疫甲状腺病相关，产后甲功监测，重要：妊娠疱疹患者产后甲状腺炎风险高，需随访）；产科超声（胎儿评估，多数预后好，小胎龄/早产风险略增）。","初步诊断":"1. 妊娠疱疹（妊娠期类天疱疮，自身免疫性表皮下大疱病）\n（注：①局部治疗（轻中度）：外用中强效糖皮质激素（糠酸莫米松，针对瘙痒及水疱）、口服抗组胺药（氯雷他定/西替利嗪，妊娠相对安全，止痒）；②系统激素（广泛/重度）：泼尼松20~40mg/d（妊娠期相对安全，控制后渐减至最低有效量）；③围产期管理（产科协作）：监测胎儿生长（小胎龄风险略增）、早产风险；分娩后皮损多自行缓解（部分产后加重）；④产后随访：产后甲状腺炎风险评估（抗TPO抗体阳性者，产后3~6个月查甲功）；再次妊娠可复发（常更早更重），应告知；哺乳期用药（泼尼松可哺乳，剂量<20mg/d安全）；⑤新生儿：极少数有暂时性水疱（母体抗体被动转移，数周自愈）；皮肤科+产科多学科管理。）","处理方案":"【药物治疗】\n1. 系统糖皮质激素（首选）：醋酸泼尼松片0.5~1mg/kg（成人一般30~40mg）每日晨起顿服；皮损控制后每1~2周减量5mg，至每日5~10mg维持，总疗程一般4~12周，减量宜缓慢以防病情反跳。\n2. 外用糖皮质激素：糠酸莫米松乳膏（艾洛松）适量涂于局限性轻中度皮损处，每日2次，连续使用一般不超过2周，避免长期用于面部及皮肤皱褶部位。\n3. 口服抗组胺药止痒：西替利嗪片10mg每晚1次（孕期B类，相对安全），瘙痒明显者可换用或加用氯雷他定片10mg每日1次，两者选其一常规患者。\n4. 辅助治疗：碳酸钙D3片600mg每日1次，配合维生素D口服，预防长期激素治疗所致骨质疏松；可根据患者具体情况制定个体化方案加用维生素C片0.2g每日3次辅助抗炎。\n\n【一般治疗及生活指导】\n1. 休息与活动：保证充足睡眠与休息，避免劳累；可适当活动，避免剧烈运动及外力摩擦、压迫皮损部位。\n2. 皮肤护理：保持皮肤清洁干燥，洗澡水温不宜过高，选用温和无刺激沐浴产品；穿宽松、柔软棉质衣物，勤剪指甲，避免搔抓以防继发细菌感染。\n3. 饮食：清淡均衡饮食，多饮水，适量补充优质蛋白；忌辛辣刺激性食物、海鲜及易致敏食物，戒烟酒。\n4. 禁忌与监测：禁止自行使用成分不明的外用药及可能致畸药物；系统使用激素期间监测血压、血糖，注意预防感染，避免接种活疫苗及接触呼吸道感染患者。\n\n【随诊要求】\n1. 皮肤科复诊：用药后1~2周复诊评估疗效及皮损变化，皮损控制后每2~4周复诊至停药；若出现新发水疱、破溃渗液、皮损感染或发热，随时就诊。\n2. 产科联合随诊：全程高危妊娠管理，定期产科检查，监测血压、尿蛋白、胎动及胎儿超声，警惕妊娠期高血压、胎儿生长受限及早产。\n3. 产后随访：产后需继续随访至皮损完全消退（部分患者产后复发或加重，需按医嘱继续或调整用药）；本病再次妊娠复发率高，备孕前应咨询皮肤科与产科医师。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":505,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"b467551304619c89043a25f0abc719e856269125edfdbdacd1b109e64f331bff","pinyin":"renshenpaozhen","initials":"rspz","setting":"out","caseName":"门诊病历370","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历370",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-1f60b0377a188764aa4a","key":"v1-c9ccc21dfe2a3058|templates-1f60b0377a188764aa4a","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"瘢痕性类天疱疮","category":"门诊病历模板","raw":{"name":"瘢痕性类天疱疮","category":"门诊病历模板","case":{"case_name":"门诊病历371","templates":{"主诉":"口腔、眼结膜糜烂伴瘢痕6月","现病史":"患者（中老年）于6个月前开始出现口腔黏膜损害（牙龈最常见，表现为脱屑性龈炎、红斑糜烂）、眼结膜损害（慢性结膜炎，异物感、眼干，进行性结膜瘢痕、睑球粘连、倒睫、角膜损害，可致失明，为最重要致残表现）、鼻/咽/食管/生殖器黏膜损害（瘢痕性黏膜类天疱疮，以黏膜慢性进行性瘢痕为特征），皮肤水疱少见（约1/3，紧张性大疱，愈合留萎缩瘢痕，区别于类天疱疮），伴吞咽困难（食管狭窄，黏膜瘢痕）、声音嘶哑、排尿困难（尿道狭窄），进行性加重。今日来我院眼科/皮肤科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.6℃，P76次/分，R18次/分，BP125/78mmHg。口腔：牙龈可见红斑、糜烂、脱屑（剥脱性龈炎），颊黏膜可见糜烂、瘢痕、水疱残壁；眼：结膜可见充血、瘢痕、睑球粘连（下穹隆缩短）、倒睫、角膜新生血管/浑浊，视力下降；皮肤可见少数紧张性大疱/萎缩瘢痕；鼻/外阴可见糜烂瘢痕。","辅助检查":"【必做】黏膜/皮肤活检（组织病理：表皮下大疱、慢性炎症、纤维化）；【免疫病理】直接免疫荧光（DIF：基底膜带C3/IgG线状沉积，确诊）、盐裂间接免疫荧光/ELISA（抗BP180/整合素α6β4抗体，分型）；【多学科评估】眼科（裂隙灯+Schirmer试验+睑球粘连分级，核心，防失明，定期）、耳鼻喉（鼻咽狭窄评估）、消化（吞咽困难，食管镜）、妇科/泌尿（狭窄）；【其他】血常规、肝肾功能、ANA（排除SLE/其他自身免疫病）。","初步诊断":"1. 瘢痕性类天疱疮（黏膜类天疱疮，自身免疫性表皮下大疱病）\n（注：治疗（需积极，防黏膜瘢痕及失明）：①氨苯砜（50~100mg qd，轻中度口腔受累一线，监测溶血）；②糖皮质激素（系统，用于进展性/眼/食管受累：泼尼松0.5~1mg/kg/d）+免疫抑制剂（环磷酰胺/硫唑嘌呤/吗替麦考酚酯，眼及严重黏膜受累者联合）；③利妥昔单抗/IVIG（难治性、重症眼受累）；④眼科处理（核心，防失明）：人工泪液、睑球粘连分离术/倒睫矫正（瘢痕稳定后）、角膜移植（严重者，成功率低，需在免疫抑制下进行）；⑤食管狭窄予内镜扩张；⑥局部护理（口腔：激素软膏/含漱；眼：润滑及抗生素，防继发感染）；⑦定期多学科随访（眼科每3~6个月，黏膜评估，控制炎症防进行性瘢痕，此为治疗关键，即使无症状也需维持免疫抑制，防失明及吞咽困难进展）；皮肤科牵头多学科（眼科/口腔/消化）长期管理。）","处理方案":"【药物治疗】\n1. 一线首选：氨苯砜片 50mg po bid（或100mg po qd），连用4-8周评估疗效；用药前筛查G6PD缺乏症，治疗期间每2-4周复查血常规及肝肾功能。\n2. 中重度或氨苯砜疗效欠佳：醋酸泼尼松片 30-40mg po qd（按0.5-1mg/kg/d折算），病情控制后每2-4周减量5mg至最小维持量；效果仍不佳者可联合吗替麦考酚酯胶囊0.5-1g po bid。\n3. 局部治疗：0.05%丙酸氯倍他索乳膏或曲安奈德口腔软膏涂搽口腔黏膜糜烂面及皮肤水疱、糜烂处 bid，餐后睡前使用，适用于轻症或配合全身用药。\n【一般治疗及生活指导】\n1. 口腔受累者予温凉软食，避免辛辣、过热、粗糙坚硬食物及烟酒刺激；餐后以生理盐水或复方氯己定含漱液漱口，保持口腔清洁。\n2. 注意眼、鼻、咽喉、食管及生殖器黏膜的早期症状，出现异物感、分泌物增多、吞咽不适及时就诊；眼部受累者避免揉眼，可配合人工泪液润滑。\n3. 皮肤损害避免搔抓、摩擦及热水烫洗，穿宽松棉质衣物，防止糜烂面继发感染及瘢痕形成，创面外涂莫匹罗星软膏预防感染。\n【随诊要求】\n1. 每1-2周复诊评估皮损及黏膜糜烂愈合情况，调整治疗方案；氨苯砜及糖皮质激素长期使用期间遵医嘱定期复查血常规、肝肾功能、血糖、血压。\n2. 眼部受累者每3-6个月于眼科复查，监测睑球粘连、角膜病变及视力变化；病情稳定后逐渐延长复诊间隔。\n3. 治疗期间如新发水疱增多、眼部刺激疼痛、视物模糊或吞咽困难加重，应立即复诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":506,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"e8bf0ce7e8d27548fdcb3be59609e536023666da60613a10728228ccce292937","pinyin":"banhenxingleitianpaochuang","initials":"bhxltpc","setting":"out","caseName":"门诊病历371","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历371",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-5b60a6629f585e2e6c1d","key":"v1-c9ccc21dfe2a3058|templates-5b60a6629f585e2e6c1d","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"白癜风","category":"门诊病历模板","raw":{"name":"白癜风","category":"门诊病历模板","case":{"case_name":"门诊病历372","templates":{"主诉":"乳白色色素脱失斑渐扩大1年","现病史":"患者于6个月前在面（眼周口周）、颈、肢端（手足）、外阴、骨突等摩擦部位出现乳白色色素脱失斑，境界清楚，渐扩大增多，可对称或局限（节段型沿皮节单侧分布，发病早、进展快），有同形反应（外伤/摩擦/日晒后新发，即Koebner现象），白斑内毛发变白（毛囊型，预示治疗反应差），无甲状腺疾病（自身免疫性甲状腺病，相关且常见），无其他自身免疫病（斑秃/恶性贫血/Addison病），无家族史，无明显精神应激，日晒后白斑更明显（周围皮肤晒黑形成对照），无自觉症状。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P76次/分，R18次/分，BP115/75mmHg。皮肤可见大小不等的乳白色色素脱失斑（边界清、周边色素加深环），分布为局限型，白斑内毛发色素脱失、变白，无鳞屑无萎缩（区别于花斑癣，后者有糠状鳞屑），伍德灯下呈亮蓝白色荧光、边界更清（用于活动期评估）。","辅助检查":"【必做】伍德灯检查（色素脱失范围精确评估、随访对比、活动性判断）；【相关筛查】甲状腺功能及抗体（自身免疫甲状腺病，常规筛查，甲状腺功能减退/亢进，治疗）；【其他】自身抗体谱（疑合并其他自身免疫病，症状提示时）、皮肤病理（不典型，排除其他色素减退病：白色糠疹/花斑癣/无色素痣，必要时）。","初步诊断":"1. 白癜风（寻常型（局限/散在/泛发），活动期）\n（注：治疗（疗程长，需耐心，早期治疗效果好，尤其面颈部）：①外用药：糖皮质激素（中效，糠酸莫米松，面部短期使用）、钙调磷酸酶抑制剂（他克莫司/吡美莫司，面部颈部一线，无激素副作用）、维生素D3衍生物（卡泊三醇，联合激素/光疗）；②光疗（核心，稳定期）：中波紫外线窄谱（NB-UVB）每周2~3次或308nm准分子激光（局限），疗程长（6个月~2年）；③光化学疗法（PUVA，泛发，已少用）；④系统治疗（进展快/广泛）：口服小剂量激素（泼尼松15~20mg/d短程，控制活动期，注意副作用）或免疫调节（他克莫司口服，少用）；⑤移植（稳定期局限，自体表皮移植/黑素细胞移植，面部小面积）；⑥脱色治疗（泛发>50%、大部分白斑，脱色乳膏（氢醌单苄醚），为美容选择）；⑦遮盖及防晒（物理防晒，防晒伤及周围皮肤过黑）、心理支持（外观影响）；⑧治疗甲状腺疾病（并存者，甲状腺治疗对白癜风本身无直接作用但改善整体健康）；皮肤科随访，每3~6个月评估（伍德灯，评估疗效，调整方案）。）","处理方案":"【药物治疗】\n1. 外用糖皮质激素：糠酸莫米松乳膏0.1%每日1次外用，涂于白斑处并轻柔按摩，连续使用3个月（每用1个月可间歇1-2周）；适用于躯干、四肢等部位皮损，面部、颈部及皱褶部位慎用强效制剂，用药期间注意观察局部皮肤萎缩、毛细血管扩张、毛囊炎等不良反应。\n2. 外用钙调神经磷酸酶抑制剂：他克莫司软膏0.1%每日2次外用，尤其适用于面部、颈部等薄嫩部位及眼周皮损，连续使用3-6个月，用药后避免暴晒并注意防晒，活动期白斑亦可使用。\n3. 光疗：窄谱中波紫外线（NB-UVB）每周照射2-3次，起始剂量0.1-0.2 J/cm²，根据红斑反应每次递增10%-20%，单次最大剂量约3 J/cm²，总疗程至少6个月；进展期白斑慎用，需在稳定期或联合药物控制下进行。\n4. 维生素D3衍生物：卡泊三醇软膏0.005%每日2次外用，可单独使用或与外用糖皮质激素联合患者，注意局部轻度刺激反应，面部慎用。\n【一般治疗及生活指导】\n1. 防晒：白斑处缺乏黑素保护，禁止日光暴晒，外出需使用SPF30+广谱防晒霜并配合衣物、遮阳伞等物理遮挡，避免晒伤诱发或加重皮损。\n2. 饮食：无需特殊忌口，均衡营养即可，可适当增加富含酪氨酸及铜、锌的食物（瘦肉、蛋类、豆制品、坚果），不宜盲目大量补充维生素C。\n3. 避免诱发因素：避免精神紧张、焦虑、熬夜及过度劳累，保持规律作息；避免外伤、摩擦、压迫及化学刺激，防止同形反应导致新发皮损，穿着宽松柔软的棉质衣物。\n4. 心理疏导：本病病程长、影响外观，应正确认识病情，坚持规范治疗，必要时寻求心理支持，树立治疗信心。\n【随诊要求】\n1. 治疗期间每2-4周复诊1次，评估白斑消退及新发情况，据此调整药物用量与光疗参数。\n2. 外用糖皮质激素连续使用期间每1-2个月复诊评估局部不良反应，必要时更换或间歇用药。\n3. 规范治疗3-6个月无改善或皮损进展者，及时复诊评估病情，考虑调整治疗方案（如系统用药、点阵激光或自体表皮移植等）。\n4. 稳定期患者建议每3-6个月复诊随访1次，长期观察病情变化，预防复发。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":507,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"091c1a0fd0d0097ada7639de851ec7bedf335d2baf0c1ee00e184872b338c9e4","pinyin":"baidianfeng","initials":"bdf","setting":"out","caseName":"门诊病历372","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历372",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-642851a42f9bfb3a2d91","key":"v1-c9ccc21dfe2a3058|templates-642851a42f9bfb3a2d91","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"黄褐斑","category":"门诊病历模板","raw":{"name":"黄褐斑","category":"门诊病历模板","case":{"case_name":"门诊病历373","templates":{"主诉":"面部黄褐色斑片日晒后加深1年","现病史":"患者（育龄女性）于1年前在面部（颧部、颊部、前额、上唇，呈蝶形分布）出现对称性黄褐色/深褐色斑片，边界不清，日晒后加深，冬季减轻，无妊娠（妊娠斑，产后部分消退），无口服避孕药/激素替代史，有日晒（核心诱因，紫外线）、无遗传（家族史）、无化妆品刺激、无甲状腺功能异常、无肝脏疾病、无光敏药物、无明显睡眠精神压力，无自觉症状。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.6℃，P74次/分，R18次/分，BP112/72mmHg。双颧颊部可见对称性黄褐色/深褐色斑片（边界不清、表面光滑、无鳞屑），呈蝶形分布（颧颊额鼻唇），伍德灯下呈表皮型（色素加深明显；混合型/真皮型者加深不明显，分型可指导治疗）。","辅助检查":"【必做】伍德灯检查（表皮型/真皮型分型，治疗选择及预后）；【相关】甲状腺功能、妇科/性激素（疑内分泌因素）、肝功能；【皮肤病理】一般不必要（诊断临床为主），黑色素细胞活性增高而非数目增多（区别于雀斑/黑变病，必要时活检鉴别）。","初步诊断":"1. 黄褐斑（混合型）\n（注：治疗（难治易复发，综合长期管理）：①防晒（基石，广谱SPF50+物理防晒，每日使用，即使室内，紫外线是核心诱因）、避免诱因（停避孕药（可能有效）、避免刺激化妆品）；②外用脱色（一线）：氢醌（2%~4%乳膏，qhs，注意刺激及 ochronosis（长期高浓度，褐黄病），间歇使用）、三联霜（氢醌+维A酸+氟轻松，有效但需监测）、壬二酸15~20%（安全，妊娠可用）、曲酸/熊果苷（辅助）；③口服（难治，色深/混合型）：氨甲环酸250mg bid（口服，近年有效，注意血栓风险，有血栓病史者禁用）、维生素C/E（抗氧化辅助）；④化学剥脱（果酸/水杨酸，浅表，辅助）、激光/强脉冲光（针对色素，需慎重，有反跳风险，非一线）；⑤严格保湿修复屏障、避免摩擦；⑥心理（外观困扰）；⑦疗程长（3~6个月起效），防复发，防晒终身；皮肤科随访。）","处理方案":"【药物治疗】\n1. 口服氨甲环酸片0.25g bid，餐后服用，疗程3～6个月（治疗前评估凝血功能及血栓风险，月经期停用）；\n2. 氢醌乳膏2% 每晚睡前1次（qn），仅涂于色素斑处，避光保存，疗程8～12周，用药期间注意观察局部刺激、红斑及色素减退情况；\n3. 维生素C片0.2g tid、维生素E软胶囊0.1g qd，口服，疗程3个月，抗氧化、协同淡斑。\n\n【一般治疗及生活指导】\n1. 严格防晒：全年使用SPF≥50、PA+++及以上的广谱防晒霜，日间每2～3小时补涂1次，外出同时佩戴遮阳帽、口罩及遮阳伞等硬防晒，避免10:00～16:00强光时段户外活动；\n2. 规律作息，保证充足睡眠，避免熬夜、长期精神紧张及焦虑；均衡饮食，多食富含维生素C的新鲜蔬菜水果，少食芹菜、香菜、无花果等光敏性食物；\n3. 停用可能诱发或加重色斑的药物及化妆品：避免长期口服含雌激素的避孕药，停用劣质、刺激性及含激素类祛斑化妆品，日常选用温和保湿、修复皮肤屏障类护肤品，避免过度清洁、去角质、热敷及揉搓面部；\n4. 面部激光、果酸化学剥脱等有创治疗需在专科医师评估后择期进行，不自行滥用祛斑产品。\n\n【随诊要求】\n每4周复诊1次，评估疗效及不良反应；用药期间如出现局部红肿、灼痛、瘙痒、色素加深或脱失，或口服氨甲环酸后出现月经异常、下肢肿痛等，应及时复诊；疗程结束后建议每3～6个月随访1次，评估复发风险并调整维持治疗方案；严格防晒应贯穿治疗全程，自觉色斑加重时随时就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":508,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"1b8de44467de40153aa38d27a8f3c38e822838ee41e5d8e14a20ccd55dfdbd14","pinyin":"huangheban","initials":"hhb","setting":"out","caseName":"门诊病历373","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历373",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-e78f5ff2e3e29842ed08","key":"v1-c9ccc21dfe2a3058|templates-e78f5ff2e3e29842ed08","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"雀斑","category":"门诊病历模板","raw":{"name":"雀斑","category":"门诊病历模板","case":{"case_name":"门诊病历374","templates":{"主诉":"面部褐色斑点10年","现病史":"患者（自幼，儿童期出现，浅肤色人种，日晒部位）于幼年在鼻、颊、眶周出现散在褐色/浅褐色小斑点（针尖至米粒大、圆形/不规则、边界清），日晒后加深增多（夏季明显、冬季变淡），不融合、不高出皮面，无自觉症状，有家族史（常染色体显性遗传，父母常有，支持诊断）、皮肤白皙（光敏肤质）、长期日晒史，与痣/雀斑样痣鉴别（后者孤立、较大、可发生于任何部位包括非日晒区、不因日晒加深，为色素性皮损，黑素细胞数量增多；雀斑为黑素细胞功能活跃）。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P76次/分，R18次/分，BP110/70mmHg。面部（鼻背、双颊、眶周）可见散在针尖至米粒大褐色/浅褐色斑点（圆形或不规则、边界清、不高出皮面、密集但不相融），数目较多，躯干四肢日晒部位可见散在同样斑点（+），口腔黏膜无色素斑（区别于色素沉着息肉综合征等）。","辅助检查":"【必做】一般临床诊断为主（典型病史：幼年起病、日晒加深、家族史）；【其他】皮肤镜（色素网络模式良性，与雀斑样痣/日光性角化/早期恶性鉴别）、皮肤病理（必要时：表皮基底层黑素细胞功能活跃，数目不增多）。","初步诊断":"1. 雀斑\n（注：治疗（美容需求，良性无害，但提示光敏体质及皮肤癌风险，需教育防晒）：①防晒（核心，严格SPF50+，可预防新发及加深，终身）；②脱色及化学剥脱（淡化）：氢醌2%（短期）、维A酸乳膏（0.025%~0.05%，qhs，促进角质剥脱）、果酸换肤（美容）；③物理去除（激光：Q开关激光/强脉冲光，雀斑疗效好，数周消退，可能复发，需防晒）；④液氮冷冻（个别，需慎用，有色素沉着风险）；⑤避免追求快速祛斑（偏方，刺激性，有反黑风险）；⑥随访（光敏人群，皮肤癌筛查，每12个月皮肤检查，关注痣变化（ABCDE：不对称/边缘/颜色/直径/变化），及时就诊；但雀斑本身不恶变）。）","处理方案":"【药物治疗】\n1.氢醌乳膏（2%）适量外用，每晚1次薄涂于雀斑处（仅涂色斑，避免正常皮肤），避光保存，连续使用8～12周，注意观察局部刺激反应。\n2.维A酸乳膏（0.05%～0.1%）每晚1次，与氢醌乳膏间隔30分钟交替外用，可协同抑制色素生成，用药期间严格避光，孕妇禁用。\n3.维生素C片0.2g po tid，联合维生素E胶丸100mg po qd，连续服用4～8周，辅助抗氧化、减少色素沉着。\n4.治疗期间及停药后3个月内严格防晒：外出前30分钟涂抹SPF≥50、PA+++的广谱防晒霜，每2～3小时补涂1次。\n\n【一般治疗及生活指导】\n1.严格防晒为防治关键：外出佩戴宽檐帽、遮阳伞、口罩等物理遮挡，避免10:00～16:00时段长时间日晒，防止皮损加深、增多。\n2.饮食均衡，多食富含维生素C、维生素E的新鲜蔬菜水果（如猕猴桃、番茄、柑橘、草莓）；进食芹菜、香菜、无花果等光敏性食物后避免日晒。\n3.保持规律作息，避免熬夜、精神紧张与焦虑，保证充足睡眠，以维持内分泌稳定、减少色素沉积。\n4.禁用刺激性化妆品及含激素、汞等成分的\"速效祛斑\"产品，避免搔抓、摩擦患处，保持皮肤清洁湿润。\n\n【随诊要求】\n1.外用药物治疗后2周复诊1次，评估疗效及局部反应；出现明显红斑、脱屑、灼痛或色素加深时及时复诊调整用药。\n2.药物治疗8～12周疗效不佳者，可至皮肤科评估行调Q激光、强脉冲光（IPL）等光电治疗，治疗期间严格防晒。\n3.若皮损颜色、形状、边缘发生变化或短期内快速增大、增多，需立即复诊，排除雀斑样痣、恶性黑素瘤等病变。\n4.治疗有效者建议每3～6个月随访1次，长期观察皮损变化，维持期继续严格防晒。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":509,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"33427cd66dbe1d5ce4750dbe198aba7e096681de025a516814bfe644b3085ecd","pinyin":"queban","initials":"qb","setting":"out","caseName":"门诊病历374","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历374",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-c403a1a93beb80882d71","key":"v1-c9ccc21dfe2a3058|templates-c403a1a93beb80882d71","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"黑变病","category":"门诊病历模板","raw":{"name":"黑变病","category":"门诊病历模板","case":{"case_name":"门诊病历375","templates":{"主诉":"面部、颈部网状色素沉着6月","现病史":"患者于6个月前在面部（前额颞部颊部）、颈部出现灰褐色/蓝灰色网状色素沉着，边界不清，渐扩大加深，无光敏物接触史（化妆品（香料/焦油衍生物）、香皂、含光敏物质植物（芹菜/无花果等）），无光敏药物史（四环素类/胺碘酮/氯丙嗪/抗疟药/雌激素），有长期日晒史，无劣质化妆品使用史（含焦油/矿物油），无内分泌疾病（Addison病可致全身色素沉着，黏膜也受累），无营养缺乏（维生素B12/烟酸缺乏所致糙皮病，表现为光暴露部位色素沉着+皮炎+腹泻），无职业接触（焦油沥青石油），无炎症后色素沉着，无自觉症状或轻度瘙痒，日晒加重。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.6℃，P76次/分，R18次/分，BP115/75mmHg。面部（额颞颊颈）可见灰褐色/蓝灰色网状或斑片状色素沉着（边界不清），表面可有细薄鳞屑/毛囊口角化（轻），口腔黏膜及掌跖无色素沉着（排除Addison病，后者黏膜牙龈掌纹皱褶处可见色素沉着点），甲正常，腋下/腹股沟未见皱褶部位色素沉着（黑棘皮病鉴别，后者呈天鹅绒样增厚）。","辅助检查":"检查计划：患者面部、颈部灰褐色网状色素沉着6个月，渐扩大加深，有长期日晒史，本病一般以临床诊断为主，先详细询问并核实光敏物及药物接触史等病因线索；为明确色素沉着的性质并分类，完善皮肤病理检查了解有无表皮基底层色素增加、色素失禁及真皮噬黑素细胞，必要时完善特殊染色以鉴别Riehl黑变病与焦油黑变病；本病需与Addison病所致全身及黏膜色素沉着鉴别，完善血皮质醇及ACTH检查排除肾上腺皮质功能减退；患者皱褶部位色素沉着需警惕黑棘皮病相关胰岛素抵抗，完善血糖及糖化血红蛋白检查了解糖代谢状态；现病史提示需排除营养缺乏所致色素沉着，完善维生素B12、烟酸水平检测排除维生素缺乏；皮损位于面颈部等光暴露部位，完善血常规及肝肾功能检查评估全身状况及药物代谢能力，为后续氢醌、维A酸等药物及果酸换肤、激光治疗提供安全依据；拟予维生素C、氨甲环酸等系统治疗，完善凝血功能检查排除出血倾向；为排除甲状腺及自身免疫性疾病所致色素异常，查甲状腺功能及抗核抗体系列；患者皮损累及颈项部，长期日晒且渐扩大加深，完善颈部皮肤专科检查及皮损拍照记录，动态对比色素沉着范围变化；日晒为明确加重因素，完善伍德灯检查明确色素沉着的深度与分布范围，并定期复诊复查皮肤镜，评估3~6个月治疗反应以指导后续方案。\n\n（检查清单）\n【必做】一般临床诊断为主（病史：光敏物/药物接触是关键）；【内分泌筛查】血皮质醇及ACTH（疑Addison病，皮肤黏膜色素沉着+乏力低血压消瘦者）、血糖（黑棘皮病相关，皱褶天鹅绒样，胰岛素抵抗）；【营养】维生素B12、烟酸水平（疑缺乏，口角炎腹泻者）；【皮肤病理】必要时（表皮基底层色素增加、色素失禁、真皮噬黑素细胞，确诊及分类：Riehl黑变病/焦油黑变病）。","初步诊断":"1. 黑变病（光毒性型）\n（注：①去除病因（核心）：停用可疑化妆品/光敏药物、避免光敏食物及日晒（严格防晒，SPF50+，物理遮挡）、职业防护（焦油沥青，防接触）；②局部治疗（淡化）：氢醌2~4%（短期）、维A酸（促进色素代谢）、维生素C（抗氧化）、果酸换肤（辅助）；③系统：维生素C/E口服（抗氧化辅助）、氨甲环酸（炎症后/血管相关者尝试）；④治疗基础病（Addison病予激素替代后色素减退；营养缺乏者补充B12/烟酸）；⑤激光（慎重，有炎症后反黑风险，稳定期评估）；⑥防晒终身（防复发加深）、避免光敏物（记录并告知患者，避免再接触，永久）；随访（3~6个月评估，色素缓慢减退，需数月）；皮肤科管理。）","处理方案":"【药物治疗】\n1. 口服维生素C片 0.2g tid，联合维生素E软胶囊 0.1g bid，共4周，抗氧化、抑制黑素合成（可加用还原型谷胱甘肽片 0.4g tid 加强疗效）。\n2. 口服烟酰胺片 0.1g tid×4周，修复皮肤屏障、减轻炎症后色素沉着。\n3. 口服氨甲环酸片 0.25g bid×4周（用药前排除血栓栓塞风险及凝血功能异常）。\n4. 外用：2%氢醌乳膏每晚1次涂抹色素沉着处（避光保存），联合0.025%维A酸乳膏隔日晚1次，外用疗程不超过8周，日间配合保湿修复霜及防晒。\n\n【一般治疗及生活指导】\n1. 立即停用可疑致敏化妆品及含香精、焦油类、光敏性成分的护肤品，避免接触光敏性物质及药物，防止接触性皮炎反复诱发加重。\n2. 严格防晒：外出前30分钟涂抹广谱防晒霜（SPF≥30、PA+++），每2-3小时补涂1次，并配合宽檐帽、遮阳伞等物理防晒，减少紫外线及可见光暴露。\n3. 饮食清淡均衡，多食富含维生素C、E的新鲜蔬菜水果（如猕猴桃、番茄、橙子、坚果），忌辛辣刺激食物，戒烟酒；不使用含汞、铅等重金属成分的\"快速祛斑\"产品。\n4. 规律作息，保证充足睡眠，避免熬夜、精神紧张及过度日晒后热水烫洗面部。\n\n【随诊要求】\n1. 每4周复诊1次，评估色素减退程度、疗效及用药不良反应，及时调整治疗方案。\n2. 治疗期间如出现局部红斑、刺痛、瘙痒、脱屑加重或色素明显加深，随时就诊。\n3. 疗程一般3-6个月，治疗结束建议复诊行伍德灯检查评估皮损改善情况并制定维持方案。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":510,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"a12aac5a126191cb4f2d6d9c15df1a446537d52d0a1cff57ec92e811c388375b","pinyin":"heibianbing","initials":"hbb","setting":"out","caseName":"门诊病历375","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历375",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-029ca1313467d691e9bc","key":"v1-c9ccc21dfe2a3058|templates-029ca1313467d691e9bc","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"色素沉着息肉综合征","category":"门诊病历模板","raw":{"name":"色素沉着息肉综合征","category":"门诊病历模板","case":{"case_name":"门诊病历376","templates":{"主诉":"口唇、指趾末端色素斑10年","现病史":"患者（自幼，常染色体显性遗传，Peutz-Jeghers综合征）于婴幼儿期口唇、口腔黏膜（颊黏膜）、鼻孔、指趾末端出现黑褐色色素斑（针尖至黄豆大，蓝黑色/棕褐色），青春期后面部唇周色素可渐消退（但口腔黏膜斑持续存在，为诊断关键），反复发作性腹痛（肠套叠，Peutz-Jeghers综合征胃肠道错构瘤性息肉以小肠最多，可引起肠套叠、肠梗阻，儿童青少年反复腹痛史），无黑便/便血（息肉出血），无贫血，家族史：直系亲属无色素斑/肠息肉/肿瘤史（遗传咨询）。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.8℃，P110次/分，R24次/分，BP100/65mmHg。口唇、口腔颊黏膜、舌可见蓝黑色/棕褐色色素斑（1~5mm、不规则、不高出皮面），鼻孔周围、眼睑、指趾末端可见色素斑（肢端分布），皮肤其他部位未见色素斑，腹部无压痛（肠套叠发作时可有压痛），贫血貌（+/-）。","辅助检查":"【必做】消化道内镜（结肠镜：息肉检出，结肠息肉多见；胃镜：上消化道）；【影像】小肠评估（胶囊内镜/MR小肠造影/钡灌肠，小肠息肉易漏，重要，小肠是息肉主要部位）；【肿瘤筛查】基因检测（STK11基因突变，确诊金标准，遗传咨询）、肿瘤标志物及影像（Peutz-Jeghers综合征全身多器官肿瘤风险显著增高，累及胃肠道（结直肠/胃/小肠/胰腺）及乳腺/卵巢（环管状性索肿瘤）/宫颈/睾丸/肺，需定期筛查，为核心）；【血液】血常规（贫血）、肝肾功能。","初步诊断":"1. Peutz-Jeghers综合征（色素沉着息肉综合征，疑诊，待内镜及基因确认）\n（注：本病需多学科长期管理（核心为肿瘤风险监测）：①色素斑：美容处理（激光，口唇部位，但可复发，良性）；②胃肠道息肉管理：有症状（腹痛/肠套叠/出血）息肉行内镜切除（小肠息肉用双气囊内镜）；无症状者定期内镜随访（结肠镜每2~3年，胃镜、小肠影像每2~3年）；③肿瘤筛查（关键，终身）：结直肠癌行结肠镜每2~3年；胃癌/小肠癌行胃镜及小肠影像；胰腺癌行磁共振胰胆管成像/超声内镜（每1~2年，自30岁起）；乳腺癌行乳腺自检+钼靶（女性，自25岁起）；妇科检查宫颈/卵巢（女性）；睾丸检查（男性）；④遗传咨询及家族筛查（基因检测，一级亲属）；⑤肠套叠急症（剧烈腹痛呕吐血便，儿童）需急诊处理；消化内科+遗传科+肿瘤科多学科长期随访。）","处理方案":"【药物治疗】\n1. 纠正缺铁性贫血（小肠息肉反复慢性渗血所致）：琥珀酸亚铁片（速力菲）0.1g po tid，餐后口服，连用3个月，复查血常规、血清铁蛋白至正常后再维持1-2个月；口服不耐受或中重度贫血者改用静脉铁剂。\n2. 解痉止痛（间歇性腹部绞痛）：匹维溴铵片（得舒特）50mg po tid，餐前整片吞服，症状缓解后逐渐减量至停用，疗程不超过2周。\n3. 抑酸护胃（合并胃、十二指肠息肉伴糜烂或反酸、烧心）：奥美拉唑肠溶胶囊20mg po qd，晨起空腹顿服，疗程4周，症状缓解后可改为按需服用。\n4. 促消化（腹胀、消化不良、脂肪泻）：复方消化酶胶囊1粒 po tid，餐后服用，按症状改善情况调整疗程。\n【一般治疗及生活指导】\n1. 饮食：少渣、易消化、高蛋白、富含维生素的软食，少量多餐；忌粗糙、坚硬、辛辣及过烫食物，减少对息肉的机械刺激和出血风险；慢性失血者注意进食瘦肉、动物肝脏、鸭血、绿叶蔬菜等富含铁及叶酸食物。\n2. 活动：可正常轻中度活动，避免剧烈运动、腹部撞击及长时间屏气用力；保持大便通畅，便秘者予乳果糖口服溶液15-30ml qd，避免用力排便诱发肠套叠、肠梗阻或息肉出血。\n3. 观察：出现黑便、便血、突发剧烈腹痛、腹胀、呕吐（警惕肠套叠、肠梗阻）应立即急诊；口唇及肢端黑色素斑为良性表现，不恶变，无需特殊治疗，勿自行激光、冷冻等去除。\n【随诊要求】\n1. 内镜随访：每1年复查胃镜+结肠镜，镜下所见息肉择期内镜切除；每1-2年行胶囊内镜或MR小肠造影筛查小肠息肉，息肉较大、反复肠套叠者根据患者具体情况制定个体化方案内镜下或外科处理。\n2. 肿瘤筛查（PJS为癌症易感综合征）：自成年起按指南定期筛查，女性每年乳腺MRI/钼靶、宫颈及盆腔检查；男女均定期行胰腺（腹部超声/MRI或EUS）、结直肠及小肠肿瘤筛查，警惕不明原因消瘦、腹痛、黄疸。\n3. 遗传咨询：建议行STK11基因检测；本人及一级亲属行遗传咨询，备孕者行产前咨询与胚胎植入前遗传学检测。\n4. 复诊频率：每3-6个月门诊复诊1次，复查血常规、血清铁蛋白，评估贫血纠正情况及消化道症状；息肉切除后按病理结果个体化调整下次复查间隔。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":511,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"e59f4d80488ad0812e08361d1a11cda38cc3fe1fc2fc2bdf04a72829fc638e86","pinyin":"sesuchenzhuoxirouzonghezheng","initials":"ssczxrzhz","setting":"out","caseName":"门诊病历376","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历376",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-37847ad0be70b1e6f8b6","key":"v1-c9ccc21dfe2a3058|templates-37847ad0be70b1e6f8b6","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"白化病","category":"门诊病历模板","raw":{"name":"白化病","category":"门诊病历模板","case":{"case_name":"门诊病历377","templates":{"主诉":"全身皮肤毛发色素缺失伴畏光10年","现病史":"患儿/患者自幼（出生时即）全身皮肤、毛发（白发/淡黄发）色素显著减少或缺失（眼皮肤白化病：酪氨酸酶基因缺陷，黑色素合成障碍）、虹膜及眼底色素缺失（虹膜呈蓝色/淡灰半透明、畏光、眼球震颤（不自主摆动）、视力低下（黄斑发育不良，屈光不正，斜视），眼皮肤白化病（OCA）：皮肤毛发眼均受累，酪氨酸酶阴性者终身白/阳性者可部分着色；眼白化病（OA）：仅眼受累，X连锁，男性多见；Hermansky-Pudlak综合征：白化+出血倾向（血小板致密颗粒缺乏）+肺纤维化；Chediak-Higashi综合征：白化+免疫缺陷+神经病变，可行亚型基因诊断），皮肤极易晒伤（日晒后红斑水疱，无晒黑保护），有无出血倾向、反复感染及家族史：无出血倾向，无反复感染，家族中无类似疾病史。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.8℃，P78次/分，R18次/分，BP110/70mmHg。皮肤色素缺失（全身皮肤白皙/乳白）、毛发色浅（白色/淡黄）、虹膜色淡（淡蓝/半透明）、眼底色素缺失（眼底检查）、眼球震颤（+）、视力下降（查视力表）、斜视（-），皮肤无日光性角化及雀斑样改变（日晒损伤：日光性角化、雀斑样，中年后皮肤癌风险，需检查）。","辅助检查":"【必做】眼科检查（视力、屈光、眼底、眼震评估；视力矫正重要；弱视治疗：遮眼/眼镜，宜及早）；【基因诊断】TYR/OCA2等基因检测（OCA分型、遗传咨询）、血小板功能（疑Hermansky-Pudlak者行出血筛查）、免疫评估（疑Chediak-Higashi者，有感染史者）；【皮肤】皮肤镜/皮肤检查（日光性角化/皮肤癌：基底细胞癌/鳞癌风险增高，定期检查，防晒为核心）；【其他】听力（部分综合征伴听力障碍）。","初步诊断":"1. 眼皮肤白化病（OCA1型，疑OCA1/OCA2，待基因确诊）\n（注：白化病无根治，管理核心：①严格防晒（终身，基石）：SPF50+广谱防晒霜（每日）、物理遮挡（帽/衣/伞）、避免10~16时外出；白化病皮肤癌风险极高（基底细胞癌/鳞癌），每年皮肤检查；②眼科管理（重要，防弱视）：屈光矫正（眼镜）、弱视治疗（早期，遮眼/遮盖）、低视力辅助（放大镜，教育支持，白化病患者可正常学习，需调适）、畏光者用滤光镜/墨镜；③皮肤癌监测（每年全皮肤检查，发现新生物/溃疡即活检）；④遗传咨询（常染色体隐性，再发风险，家族检测/产前诊断）；⑤心理支持及社会教育（外观，防歧视，视力障碍，教育适应）；⑥相关综合征监测（Hermansky-Pudlak：肺纤维化/出血；Chediak-Higashi：感染/神经）；眼科+皮肤科+遗传科多学科管理。）","处理方案":"【药物治疗】\n1. 防晒药物（核心治疗）：广谱物理性防晒霜（含氧化锌/二氧化钛，SPF50+、PA++++），于外出前15～30分钟均匀涂抹头面部、颈、手背等暴露部位，每2～3小时或出汗、游泳后补涂1次；全年长期规律使用。\n2. 眼部用药：玻璃酸钠滴眼液0.1%，1滴，bid～qid，缓解眼干、畏光及眼部不适；畏光明显者加用人工泪液凝胶（如卡波姆眼用凝胶）睡前1次，并联合佩戴防紫外线遮光镜。\n3. 维生素补充：因严格防晒导致皮肤维生素D合成不足，建议检测血清25-(OH)D，偏低者予维生素D滴剂800～1000IU，qd，长期维持；同时口服维生素C 500mg，qd，辅助抗氧化、减轻紫外线氧化损伤。\n【一般治疗及生活指导】\n1. 严格防晒：避免每日10:00～16:00紫外线最强时段外出；外出穿深色长袖衣裤、戴宽檐帽及防紫外线太阳镜；避免使用含光敏成分的化妆品、护肤品及药物（如维A酸类、四环素类）。\n2. 皮肤护理：每日沐浴后全身涂抹无香精保湿霜以维持皮肤屏障，洗澡水温不宜过高；皮肤轻微破损及时用碘伏清洁消毒，避免搔抓，预防继发感染；定期（每1～2周）自查皮肤，注意新发色素痣、糜烂或久不愈合皮损。\n3. 眼部保健：避免直视强光源及雪地、水面强反射环境；室内采用防眩光灯具；儿童及学生建议教室前排就座，配戴助视器（放大镜、望远镜式助视器）改善视力功能，并加强安全防护防止跌伤。\n4. 饮食与禁忌：均衡饮食，多食富含维生素C、E及β-胡萝卜素的新鲜蔬果（番茄、胡萝卜、柑橘、西兰花等）；戒烟限酒，避免辛辣刺激食物；严格禁止日光浴、紫外线理疗及去角质等刺激皮肤的行为。\n【随诊要求】\n1. 皮肤科随诊：每3～6个月复查1次，重点检查暴露部位有无日光性角化、皮肤新生物及早期皮肤肿瘤（基底细胞癌、鳞状细胞癌、黑色素瘤）征象；每年行全身皮肤检查1次，发现新发色素病变、溃破或出血性皮损随时就诊。\n2. 眼科随诊：每6～12个月复查视力、屈光状态及眼底（儿童每3～6个月），动态调整助视设备及屈光矫正；出现视力进行性下降、眼球震颤加重或斜视时及时就诊。\n3. 一般随诊：每6～12个月检测血清25-(OH)D，监测骨密度；育龄期患者备孕前于皮肤科、眼科及遗传咨询门诊行遗传咨询与风险评估。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":512,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"0178f0837d69d6f1eb7066088d5c5775c5deb012e03c1973fa13bd015127002f","pinyin":"baihuabing","initials":"bhb","setting":"out","caseName":"门诊病历377","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历377",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-8dcf8d3ce603a0d76644","key":"v1-c9ccc21dfe2a3058|templates-8dcf8d3ce603a0d76644","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"斑驳病","category":"门诊病历模板","raw":{"name":"斑驳病","category":"门诊病历模板","case":{"case_name":"门诊病历378","templates":{"主诉":"皮肤局限性白斑伴白发1周","现病史":"患者1周前无明显诱因出现斑驳病相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者1周前无明显诱因出现皮肤局限性白斑伴白发，伴轻度乏力，为明确诊断并与白癜风、无色素痣等色素减退性疾病鉴别，完善皮肤科专科检查：伍德灯检查了解白斑分布范围及色素脱失程度，皮肤镜检查了解白斑区色素网及毛囊周围色素情况；必要时完善皮肤活检行组织病理及黑素细胞免疫组化检查，明确基底层黑素细胞数量以确诊；因患者伴轻度乏力，完善血常规、尿常规、便常规检查排除贫血、感染及消化道慢性失血所致；完善肝肾功能、血糖、血脂、电解质检查了解全身代谢及内环境状态，为后续治疗用药提供安全依据；完善甲状腺功能及维生素B12、叶酸水平检测，排除甲状腺疾病及营养缺乏所致色素改变与乏力；患者白斑累及皮肤并伴白发，完善心电图检查排除心脏传导异常；完善胸部X线片检查排除肺部感染及胸内病变；完善腹部超声检查了解肝脾等腹腔脏器情况，排除内脏疾病相关色素异常；眼周白斑需排除眼部受累，必要时请眼科会诊完善眼底及视力检查；患者自服药物效果欠佳，完善上述检查评估肝肾功能后指导用药，避免药物性肝损伤；本病需长期随访观察白斑变化，定期复查皮肤镜及伍德灯评估病情稳定性。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 斑驳病\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 外用遮盖剂（首选）：氧化铁/二氧化钛类遮瑕霜涂于白斑及额部白发区，每日1次，可长期使用，兼具遮盖与防晒作用；斑驳病为KIT基因缺陷所致黑素细胞先天缺失，无特效复色内服药物，不建议盲目使用光敏剂及糖皮质激素。\n2. 抗氧化辅助治疗：维生素E软胶囊0.1g（100mg）bid口服，连用12周为一疗程，辅助减轻光损伤及氧化应激。\n3. 光疗辅助复色（308nm准分子激光或窄谱中波紫外线NB-UVB）：每周2次，起始剂量NB-UVB 0.3~0.5J/cm²、308nm准分子激光100~200mJ/cm²，据红斑反应每次递增10%~20%，12~24次为一疗程；对稳定期白斑可促进部分色素岛生成，疗效有限，宜与遮盖剂联合患者。\n\n【一般治疗及生活指导】\n1. 严格防晒：白斑区缺乏黑素保护，日间外出使用SPF≥30、PA+++的广谱防晒霜，每2~3小时补涂1次，避免10:00~15:00时段暴晒，减少晒伤及远期光老化、皮肤肿瘤风险。\n2. 毛发遮盖：额部白色发绺可用温和低敏染发剂遮盖，避免频繁烫染及接触刺激性化学物。\n3. 心理疏导与社交支持：本病为常染色体显性遗传病，不影响寿命及全身健康，但影响容貌，应加强心理疏导（尤其儿童及青少年患者），必要时心理科咨询。\n4. 遗传咨询：子女患病概率约50%，有生育计划者建议行遗传咨询及KIT基因检测。\n\n【随诊要求】\n1. 每3~6个月复诊1次，评估白斑范围变化、遮盖效果及有无新发色素。\n2. 白斑区出现新发色素沉着、结节、溃疡、增大或破溃时随时就诊，排除继发皮肤病变。\n3. 行光疗者治疗期间每4周复诊，评估疗效及光疗不良反应；行自体表皮/黑素细胞移植者按移植术后方案于术后1、2周及1、3、6个月随访。\n4. 有整形修复需求者转诊整形外科/皮肤外科评估移植适应证，并持续心理随访。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":513,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"3ea5ba744572edcb5726ea1c389e1cc5155d71be9ec8c63eb0efb864bd2a9712","pinyin":"banbobing","initials":"bbb","setting":"out","caseName":"门诊病历378","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历378",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-5017d95b1931b925ec2a","key":"v1-c9ccc21dfe2a3058|templates-5017d95b1931b925ec2a","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"贫血痣","category":"门诊病历模板","raw":{"name":"贫血痣","category":"门诊病历模板","case":{"case_name":"门诊病历379","templates":{"主诉":"皮肤苍白色斑1周","现病史":"患者1周前无明显诱因出现贫血痣相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者1周前无明显诱因出现皮肤苍白色斑，逐渐加重，伴轻度乏力，为明确色素减退性质并与贫血相关的皮肤改变鉴别，完善血常规加网织红细胞计数检查，了解有无贫血及其程度，评估骨髓造血代偿情况；完善外周血涂片检查了解红细胞形态，排除溶血性贫血及其他血液系统疾病；患者乏力需警惕潜在出血倾向，完善凝血功能检查排除凝血机制障碍；完善肝肾功能、血糖、血脂、电解质检查了解全身状况及代谢水平，为后续治疗提供安全依据；完善腹部超声检查了解肝脾大小及腹腔淋巴结情况，排除肝脾肿大所致血液系统疾病；完善淋巴结超声检查了解浅表淋巴结有无肿大，排除淋巴瘤等恶性疾病；若血常规提示不明原因血细胞减少，需进一步完善骨髓穿刺+活检，明确骨髓造血情况并排除血液系统恶性疾病；必要时完善流式细胞术检查明确细胞免疫表型，排除淋巴增殖性疾病；必要时完善染色体核型分析检查排除骨髓增生异常综合征等克隆性病变；皮肤白斑本身需与白癜风、无色素痣鉴别，完善伍德灯及皮肤镜检查明确色素减退范围与特征；因患者为皮肤表现合并乏力，完善甲状腺功能及维生素B12检查排除内分泌及营养因素；本病为先天性色素减退性疾病，需定期复查并随访观察白斑变化，评估是否需进一步干预。\n\n（检查清单）\n【必做检查】\n血常规+网织红细胞、外周血涂片、凝血功能\n\n【影像学检查】\n腹部超声（肝脾淋巴结）、淋巴结超声\n\n【其他检查】\n骨髓穿刺+活检、流式细胞术、染色体核型分析","初步诊断":"1. 贫血痣\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 首选方案：贫血痣为局部皮肤血管对儿茶酚胺敏感性增高所致的良性血管功能异常，系统及外用药物均无确切疗效，一线处理为不干预＋病情解释，无需处方用药，避免不必要的激光、光疗及色素移植等治疗。\n2. 遮盖美容（暴露部位外观改善需求时）：氧化锌软膏（15%）适量涂于皮损及周边区域，每日1次，按需使用；或选用与肤色匹配的医学遮瑕膏（如Dermablend系列）局部遮盖，仅改善外观，不改变皮损性质，无治疗作用。\n3. 皮损区伴干燥脱屑（因局部血供减少所致）时：尿素维E乳膏（含10%尿素）适量外用，每日2次，连用2-4周，以保湿护肤为主，并非治疗皮损本身。\n【一般治疗及生活指导】\n1. 作息与情绪：规律作息，保证充足睡眠，避免熬夜及过度紧张焦虑；因皮损区血管对儿茶酚胺高度敏感，情绪激动、紧张或剧烈运动时周围正常皮肤充血发红、与皮损反差增大，属正常生理现象，不必恐慌。\n2. 皮肤护理：皮损区血供减少、皮肤较干燥，日常温和清洁并配合润肤霜保湿（每日1-2次）；避免搔抓、摩擦及冷热过度刺激，忌热水烫洗或用力搓揉皮损。\n3. 防晒与禁忌：皮损区注意防晒（物理遮挡或SPF30以上防晒霜），防止晒伤；严禁在美容院或非专科机构行激光、磨削、植皮、化学剥脱等\"祛白\"治疗，此类治疗对贫血痣无效且可造成瘢痕、色素异常等继发损伤。\n4. 饮食与活动：正常均衡饮食，无需忌口、无需特殊进补（维生素C、酪氨酸、黑芝麻等\"色素食物\"不能使皮损着色）；可正常活动和运动，无活动限制。\n【随诊要求】\n本病为先天性良性病变，皮损终身稳定，无恶变及系统损害风险，一般无需复诊。出现以下情况建议皮肤科门诊复诊：（1）皮损短期内（数周至数月）明显扩大、增多或颜色改变；（2）出现新发白斑，伴瘙痒、脱屑、破溃等异常表现；（3）皮损性质不明确、需与白癜风、无色素痣、花斑糠疹等鉴别时，建议6-12个月内复诊1次，行Wood灯及皮肤镜检查以确诊。患者或家属因外观问题存在明显焦虑时，可随时复诊行心理疏导与健康宣教。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":514,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"29e9e1b437c4c23f95891ce34b11b396d7ede5d7ab963d099ea291e6c9e8b953","pinyin":"pinxuezhi","initials":"pxz","setting":"out","caseName":"门诊病历379","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历379",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-54b4648721dce99c497b","key":"v1-c9ccc21dfe2a3058|templates-54b4648721dce99c497b","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"无色素痣","category":"门诊病历模板","raw":{"name":"无色素痣","category":"门诊病历模板","case":{"case_name":"门诊病历380","templates":{"主诉":"皮肤色素减退斑1周","现病史":"患者1周前无明显诱因出现无色素痣相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者1周前无明显诱因出现皮肤色素减退斑，逐渐加重，伴轻度乏力，为明确色素减退斑的性质并与白癜风、斑驳病等鉴别，完善伍德灯检查了解色素脱失范围及分布；完善皮肤镜检查了解白斑区色素网及毛囊周围色素残留情况，必要时完善皮肤活检行组织病理及黑素细胞免疫组化检查，明确基底层黑素细胞数量以确诊并排除其他色素减退性疾病；患者伴轻度乏力，完善血常规、尿常规、便常规检查排除贫血、感染及消化道慢性失血；完善肝肾功能、血糖、血脂、电解质检查了解全身代谢及内环境状态，为用药提供安全依据；完善甲状腺功能及维生素B12、叶酸检测排除内分泌及营养缺乏所致色素异常；完善心电图检查排除心脏传导异常及心律失常；完善胸部X线片检查排除肺部感染及胸内病变；完善腹部超声检查了解肝脾等腹腔脏器情况，排除内脏疾病；患者自服药物效果欠佳，完善上述检查评估肝肾功能后指导规范用药；本病为先天性色素减退性疾病，需长期随访观察，定期复查皮肤镜及伍德灯评估白斑范围有无变化。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 无色素痣\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 钙调神经磷酸酶抑制剂类：0.1%他克莫司软膏，皮损处薄涂，每日2次，连续外用3～6个月；部分患者可诱导色素部分再生，疗效存在个体差异，用药初期局部出现灼热、红斑属常见反应，多于1～2周内耐受，若持续加重或出现水疱、破溃则暂停用药并复诊。\n2. 大环内酯类免疫抑制剂（他克莫司不耐受或刺激明显时替换）：1%吡美莫司乳膏，外用每日2次，疗程3～6个月，用法与注意事项同前。\n3. 维生素D3衍生物（联合辅助）：卡泊三醇软膏0.005%（50μg/g），外用每日2次，与他克莫司/吡美莫司间隔至少30分钟涂用，两药联合使用3～6个月，可轻度提高色素再生反应；面部、皱褶部位慎用，注意局部刺激。\n4. 若患者要求积极复色且药物治疗3～6个月无效，可联合308 nm准分子激光治疗（每周1～2次，6～12次为一疗程），药物与光疗间隔使用，避免同日同部位叠加刺激。\n\n【一般治疗及生活指导】\n1. 防晒：日常外用SPF≥30、PA+++及以上广谱防晒霜，外出配合遮阳伞、遮阳帽等物理遮挡，避免过度日晒加深正常皮肤与白斑的色差；本病与日晒无因果关系，防晒目的仅为改善外观对比度，无需刻意\"忌晒\"或长期避光。\n2. 美容遮盖：可用专用遮盖霜、防水粉底等化妆品遮盖皮损，满足美观需求；儿童青少年在学校、社交场合中可根据患者具体情况制定个体化方案使用，不影响皮损本身。\n3. 避免过度治疗：本病为良性先天性色素减退斑，无恶变倾向、不自行扩散，不建议手术切除或追求\"根治\"；对药物、光疗反应不佳者应避免反复、过量的物理治疗，防止继发色素沉着或瘢痕。\n4. 心理疏导：对因外观产生自卑、焦虑的儿童及青少年患者，需给予解释和心理支持，必要时转诊心理专科。\n\n【随诊要求】\n1. 药物治疗及光疗期间每1～2个月复诊1次，评估色素恢复程度、局部刺激反应及疗程耐受性，据疗效调整或终止治疗。\n2. 若出现皮损短期内明显扩大、数目增多或新发白斑，或伴抽搐、智力发育迟缓、面部血管纤维瘤等系统表现时，需及时复诊，排查结节性硬化症等系统性疾病（本病需与叶状白斑相鉴别）。\n3. 疗效稳定或停止治疗后，可延长至每3～6个月复诊一次，随访至色素达满意程度或确认无变化后终止随访。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":515,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"9399b7b8564d8ca089a8b79e402b56b3d5197c4639e168a20a18c7fc55b45347","pinyin":"wusesuzhi","initials":"wssz","setting":"out","caseName":"门诊病历380","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历380",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-aead500d55ff32072953","key":"v1-c9ccc21dfe2a3058|templates-aead500d55ff32072953","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"伊藤色素减少症","category":"门诊病历模板","raw":{"name":"伊藤色素减少症","category":"门诊病历模板","case":{"case_name":"门诊病历381","templates":{"主诉":"皮肤色素减退斑1周","现病史":"患者1周前无明显诱因出现伊藤色素减少症相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者1周前无明显诱因出现皮肤色素减退斑，逐渐加重，伴轻度乏力，伊藤色素减少症常沿Blaschko线呈漩涡状、条纹状分布并常伴神经系统异常，故完善皮肤科专科检查：伍德灯检查了解色素减退区分布及形态，皮肤镜检查了解色素网及毛囊周围色素情况，必要时完善皮肤活检行组织病理及黑素细胞免疫组化检查，明确黑素细胞数量以确诊并与其他色素减退性疾病鉴别；因本病可伴中枢神经系统受累，完善头颅MRI检查明确有无脑白质病变、皮质发育异常等结构异常；完善脑电图检查了解有无异常放电，评估癫痫风险；患者伴轻度乏力，完善血常规、尿常规、便常规检查排除贫血、感染及消化道慢性失血；完善肝肾功能、血糖、血脂、电解质检查了解全身代谢及内环境状态，为用药提供安全依据；完善甲状腺功能及维生素B12、叶酸检测排除内分泌及营养缺乏所致色素异常；完善心电图检查排除心脏传导异常；完善胸部X线片检查排除肺部感染；完善腹部超声检查了解肝脾等腹腔脏器情况，排除内脏畸形及占位；必要时请神经内科、眼科会诊，完善视力及眼底检查排除眼受累；本病需长期随访，定期复查皮肤镜、脑电图及发育评估，动态观察病情变化。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 伊藤色素减少症\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 左乙拉西坦片0.5g po bid（伴癫痫发作者首选抗癫痫药，自0.25g po bid起始、1周内渐加至维持量；长期规律服药，不可骤停，定期复查血常规、肝肾功能及脑电图）\n2. 碳酸钙D3片（含元素钙300mg）0.6g po qd，联合维生素D3滴剂800IU po qd（色素减退范围广泛、需严格避晒致日照不足者补充，疗程3～6个月，复查血钙、血磷、尿钙及25-(OH)D3）\n3. 舍曲林片50mg po qd晨服（伴明显焦虑、抑郁等情绪障碍者，疗程3～6个月，定期行心理评估并监测不良反应）\n\n【一般治疗及生活指导】\n1. 严格防晒：日间外出（尤其10:00～16:00时段）于色素减退区涂抹SPF50+、PA+++广谱防晒霜，每2～3小时补涂1次，同时穿长袖衣裤、戴宽檐帽、使用遮阳伞，防止白斑区晒伤及光损伤\n2. 皮肤护理：白斑区每日外用温和保湿剂1～2次维持皮肤屏障；影响外观者可用遮瑕化妆品遮盖，避免使用刺激性美白或脱色制剂\n3. 生活方式：均衡饮食，适量摄入奶制品、蛋黄、深海鱼等富含钙及维生素D的食物；保证充足睡眠、适度体育锻炼，避免精神紧张和过度劳累\n4. 伴发表现监测：自我观察有无抽搐发作、智力及运动发育迟缓、行为异常、视力听力改变，出现异常及时就诊\n5. 心理及遗传宣教：本病为非传染性遗传性皮肤病，无需隔离；避免不必要心理负担，备孕及家族史咨询可至遗传咨询门诊\n\n【随诊要求】\n每3～6个月皮肤科复诊评估皮损变化及伴发症状；伴癫痫者遵神经内科医嘱规律复诊，监测发作控制情况及脑电图；每年行眼科、口腔科、骨科检查及头颅MRI，筛查虹膜异色、屈光不正、龋齿、脊柱侧弯等合并症；出现新发抽搐、发育倒退或行为异常者随时就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":516,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"cedd0601c1c68701e44bb19af94f3a231e16215cb5f6c99422f811b319847837","pinyin":"yitengsesujianshaozheng","initials":"ytssjsz","setting":"out","caseName":"门诊病历381","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历381",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-9eecf7376611f0c0b547","key":"v1-c9ccc21dfe2a3058|templates-9eecf7376611f0c0b547","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"脱发","category":"门诊病历模板","raw":{"name":"脱发","category":"门诊病历模板","case":{"case_name":"门诊病历382","templates":{"主诉":"头发脱落增多6月","现病史":"患者于6个月前出现头发脱落增多（每日梳洗脱落约150根，>100根/日属异常）、发量减少（头顶及发际弥漫性），有近期诱因：精神压力大，无发热/手术/大出血/分娩（休止期脱发常在2~3月后脱落），无节食减肥（营养不良），未用化疗、抗凝、维A酸、丙戊酸等药物，无甲状腺病/贫血/系统性红斑狼疮（弥漫性，内分泌/自身免疫相关），无头皮疾病（脂溢性皮炎，头皮屑多伴痒），无拔毛癖（儿童不规则斑秃、毛发折断，心理因素），家族秃发史（雄激素性脱发，遗传）：父亲有秃发史。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.8℃，P78次/分，R18次/分，BP118/76mmHg。头皮弥漫稀疏（顶部及额部为主，符合雄激素性脱发，发际M形后退+顶部稀疏；女性则顶部弥漫稀疏、保留发际线）、无斑片状脱发区（斑秃，境界清）、无炎症（红斑鳞屑见于脂溢性皮炎/红斑狼疮，可伴萎缩），毛囊口正常（无萎缩），拉发试验阳性（轻拉一束头发脱落>2~3根，提示活动性脱发），眉毛/睫毛/体毛无受累（未见全秃/普秃）。","辅助检查":"检查计划：患者6个月来头发脱落增多，每日梳洗脱落约150根，头顶及发际弥漫性发量减少，近期精神压力大，父亲有秃发史，为判断脱发类型与活动性，完善拉发试验了解毛发松动情况；完善毛发镜检查了解毛干异常、毛囊开口、黄点征、毳毛增多及头皮炎症表现，以鉴别雄激素性脱发、斑秃与休止期脱发；完善血常规检查排除贫血所致脱发；完善铁蛋白检查排除缺铁，缺铁者补铁可改善脱发；完善甲状腺功能检查排除甲状腺疾病所致弥漫性脱发；因患者为弥漫性脱发且需除外内分泌因素，完善性激素检查排除雄激素性脱发及多囊卵巢综合征，月经不调者尤为必要；拟长期口服非那雄胺或螺内酯等药物，完善肝肾功能检查排除肝肾功能不全，指导用药安全；完善维生素B12、维生素D及叶酸检测排除营养缺乏所致脱发；完善抗核抗体及补体检查排除系统性红斑狼疮等自身免疫性疾病；若头皮出现瘢痕、毛发不可再生或诊断不明，完善头皮活检明确有无瘢痕性脱发及其原发病，如红斑狼疮或扁平苔藓所致瘢痕性脱发需早期诊断以防永久性秃发；儿童出现脱发斑者完善真菌镜检排除头癣；完善皮肤镜检查并定期复查毛发镜及拉发试验，动态评估治疗4~6个月的反应以调整方案。\n\n（检查清单）\n【必做】拉发试验、毛发镜检查（毛干异常（断发，见于拔毛癖）、毛囊开口、黄点征（斑秃）、毳毛增多（AGA）、头皮炎症）、血常规、铁蛋白（缺铁，女性常见，补铁可改善）、甲状腺功能、性激素（女性雄激素性脱发/多囊卵巢，月经不调者）、肝肾功能；【其他】头皮活检（瘢痕性脱发/诊断不明，如红斑狼疮或扁平苔藓所致瘢痕性脱发，永久性，需早期诊断）、真菌镜检（头癣，儿童脱发斑）。","初步诊断":"1. 脱发（雄激素性型，需与休止期/斑片状/瘢痕性脱发鉴别）\n（注：①明确并去除诱因（休止期脱发多数去除诱因后3~6个月自行恢复，安慰+随访）；②雄激素性脱发：男性用非那雄胺1mg qd（抑制5α还原酶，需用6~12个月，注意性功能不良反应，育龄女性禁用）+外用米诺地尔2%~5%（bid，男女均可，初用期一过性脱发增多，坚持4~6个月起效）；女性用外用米诺地尔+螺内酯（抗雄激素，多囊者）；③斑秃：外用强效激素或米诺地尔、皮损内激素注射（曲安奈德，局限斑秃）、局部免疫治疗（二苯环丙烯酮，顽固者）、口服激素（进展快/全秃普秃，短程）、JAK抑制剂（巴瑞替尼，中重度斑秃，近年获批）；④补充缺乏（铁蛋白<30ng/ml补铁、B12/维生素D）；⑤治疗头皮病（脂溢性皮炎用酮康唑洗剂）、甲状腺病、停用致脱药物（化疗后可再生）；⑥瘢痕性脱发：早期诊断并治疗原发病（红斑狼疮/扁平苔藓，免疫抑制），防永久性，稳定后可行毛发移植；⑦心理支持（外观，脱发对心理影响大）、避免过度烫染拉扯（牵拉性脱发，需调整发型）；皮肤科专科评估（毛发门诊），毛发镜随访，疗程长需耐心。）","处理方案":"【药物治疗】\n1. 米诺地尔搽剂（5%）1ml bid，均匀涂于脱发区头皮并轻柔按摩3~5分钟，早晚各1次，连续使用至少3~6个月，适用于雄激素性脱发及斑秃等非瘢痕性脱发。\n2. 非那雄胺片 1mg qd 口服，疗程至少6~12个月，用于男性雄激素性脱发（仅限男性）；女性患者禁用，生育期女性可选用螺内酯片 20mg bid 口服，每月复查血钾并注意月经紊乱等不良反应。\n3. 斑秃急性进展期：卤米松乳膏外用 bid，或复方倍他米松注射液皮损内注射，每月1次，连用3次；病情严重者可短期口服泼尼松片 30mg qd，有效后逐渐减量。\n4. 辅助治疗：复合维生素B片 2片 tid，葡萄糖酸锌口服液 10ml bid，连用1~3个月。\n【一般治疗及生活指导】\n1. 规律作息，保证每日睡眠7~8小时，避免熬夜及精神紧张、焦虑，必要时行心理疏导。\n2. 均衡饮食，适当增加富含蛋白质、铁、锌及B族维生素的食物（如瘦肉、蛋类、豆制品、坚果、绿叶蔬菜），避免过度节食减肥。\n3. 减少烫发、染发、拉直等刺激性美发操作，洗发水温不宜过高，选用温和洗发产品，避免用力搔抓头皮。\n4. 避免扎发过紧或长期佩戴过紧发饰、帽子压迫头皮；戒烟限酒，减少咖啡因过量摄入。\n【随诊要求】\n1. 用药后每1~3个月复诊1次，评估疗效及不良反应（非那雄胺注意性欲减退、勃起功能障碍，螺内酯注意血钾升高及月经紊乱）。\n2. 连续治疗6个月无效或脱发进行性加重者，建议完善毛发镜检查、甲状腺功能、性激素六项及血清铁蛋白等检查，必要时转皮肤科专科进一步诊治。\n3. 用药期间出现头皮红肿、瘙痒、过敏或局部刺激等不适，及时复诊调整用药。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":517,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"fd45f4fdcc9877f2a6dfbb84bacf4bdd7ec22cd58de75876182ab1dade2381cf","pinyin":"tuofa","initials":"tf","setting":"out","caseName":"门诊病历382","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历382",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-217799f998602428bc03","key":"v1-c9ccc21dfe2a3058|templates-217799f998602428bc03","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"斑秃","category":"门诊病历模板","raw":{"name":"斑秃","category":"门诊病历模板","case":{"case_name":"门诊病历383","templates":{"主诉":"头皮圆形脱发斑1月","现病史":"患者于3周前无意中发现头皮（枕部为主，可位于顶部/颞部等任何部位）圆形或椭圆形脱发斑（一个或多个，境界清楚、皮肤光滑无瘢痕无炎症），渐扩大或出现新发斑，拉发试验在斑缘阳性（活动期），无全秃（全部头发脱落）、无普秃（全身毛发，眉毛睫毛体毛）、无指甲改变（点状凹陷/粗糙，约10~20%）、无甲状腺病/白癜风等自身免疫病（斑秃为器官特异性自身免疫病，常相关，家族史常见）、有精神应激/劳累诱因（常见，但非必需）、非Down综合征/特应性体质（儿童，预后差因素），多数无明显自觉症状。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.6℃，P76次/分，R18次/分，BP116/74mmHg。头皮可见境界清楚的圆形/椭圆形脱发斑（直径约2cm，一个或多个）、斑内皮肤正常光滑（无红斑鳞屑萎缩）、毛囊口存在（非瘢痕性，预后好）、斑缘可见感叹号样发（活动期，断发）、拉发试验（斑缘阳性），眉毛/睫毛/体毛未受累（已评估，无全秃/普秃），甲无点状凹陷及甲粗糙。","辅助检查":"【必做】一般临床诊断为主（典型皮损）；毛发镜（黄点征、黑点征、感叹号发，为活动期特征，需随访）；【相关筛查】甲状腺功能及抗体（自身免疫甲状腺病与斑秃相关，需筛查，治疗不影响斑秃但改善整体）、血常规铁蛋白（评估营养因素，合并评估）；【其他】头皮活检（诊断不明或需与瘢痕性脱发鉴别，如狼疮/扁平苔藓所致瘢痕性脱发，斑秃不形成瘢痕）；梅毒血清学（梅毒性脱发，呈虫蚀状脱发，需鉴别，流行病学相关时）。","初步诊断":"1. 斑秃（单斑，活动期）\n（注：治疗（多数斑秃（<50%面积）可自愈（6~12个月），但复发常见，约50%，需告知；治疗可加速恢复）：①局限（<50%）：外用强效糖皮质激素（氯倍他索，可封包）、皮损内糖皮质激素注射（曲安奈德2.5~10mg/ml，每4~6周，有效，限斑秃，每周总量有限制）、米诺地尔2~5%外用（辅助，每日2次，4~6个月）；②广泛（>50%）/进展快/全秃普秃：局部免疫治疗（二苯环丙烯酮，每周1次，接触致敏，需专科，有效但反应大）、光疗（PUVA/308nm准分子）、口服糖皮质激素（泼尼松30~40mg/d短程渐减，用于进展迅速者，注意副作用，不长期用）、JAK抑制剂（巴瑞替尼2~4mg qd，中重度斑秃（全秃普秃），近年获批，疗效好，需监测感染/血常规，专科处方）、环孢素（顽固者）；③辅助：低剂量口服米诺地尔（部分患者）；④处理相关自身免疫病（甲状腺，需治疗）、心理支持（重要，斑秃对外观影响大，易焦虑抑郁，儿童注意校园压力）；⑤随访（毛发镜，3~6个月，评估再生及复发）；皮肤科专科（毛发门诊）管理，病程不可预测，安慰支持重要。）","处理方案":"【药物治疗】\n1. 外用糖皮质激素（轻中度局限性斑秃首选）：糠酸莫米松乳膏，涂于脱发区，每日1次，轻揉片刻，疗程3-6个月；脱发区较大时可选用0.1%倍他米松乳膏，每日1次。\n2. 米诺地尔搽剂（2%或5%）：每次1ml，涂于脱发区并轻轻按摩，每日2次，需连续使用至少3-6个月，以促进毛发生长。\n3. 复方甘草酸苷片：每次3片，每日3次，口服，疗程1-3个月，联合外用药起抗炎免疫调节作用。\n4. 病情进展迅速（近3个月内脱发面积明显扩大）者：泼尼松片20-30mg/d，晨起顿服，连用2-4周后每1-2周减量5mg，总疗程不超过6-8周，用药期间监测血压、血糖。\n\n【一般治疗及生活指导】\n1. 生活规律，保证充足睡眠（每日7-8小时），避免熬夜、精神紧张及过度劳累，注意劳逸结合。\n2. 保持头皮清洁，洗发水温适宜、动作轻柔，避免用力搔抓头皮、烫染头发、紧扎发辫或佩戴过紧帽子等机械刺激。\n3. 均衡饮食，适当增加富含B族维生素、锌、铁及优质蛋白的食物（如瘦肉、蛋奶、豆类、坚果），避免过度节食减肥；忌辛辣刺激性食物及烟酒。\n4. 正确认识本病（部分斑秃可自行恢复），保持心态平和，避免过度焦虑；急性期避免剧烈运动导致头皮多汗刺激。\n\n【随诊要求】\n1. 每2-4周复诊1次，评估脱发进展及新生毳毛情况，据病情调整用药。\n2. 用药期间如出现局部红肿、瘙痒、灼痛等刺激反应，或口服激素后出现血压/血糖异常、胃部不适等，及时就诊。\n3. 治疗3-6个月无改善或脱发范围持续扩大者，建议完善甲状腺功能、抗核抗体、血常规等检查，排除甲状腺疾病、红斑狼疮等相关疾病。\n4. 若进展为全秃或普秃，或反复复发者，需转皮肤科专科评估系统性治疗（如JAK抑制剂等）指征。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":518,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"640c87da0711ab108f765e7885ddb00324c5e6ba50e1572acec3cc7acacf1c68","pinyin":"bantu","initials":"bt","setting":"out","caseName":"门诊病历383","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历383",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-19896f14539036e10146","key":"v1-c9ccc21dfe2a3058|templates-19896f14539036e10146","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"全秃","category":"门诊病历模板","raw":{"name":"全秃","category":"门诊病历模板","case":{"case_name":"门诊病历384","templates":{"主诉":"反复全秃相关不适1周，加重1天。","现病史":"患者1周前无明显诱因出现全秃相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者1周前无明显诱因出现全秃相关症状，逐渐加重，伴轻度乏力，全秃属斑秃重症类型，为评估病情活动性及范围，完善拉发试验及毛发镜检查，了解毛囊开口、黄点征、断发及毳毛情况，必要时完善皮肤活检排除瘢痕性脱发及其他毛发疾病；患者伴轻度乏力，完善血常规、尿常规、便常规检查排除贫血、感染及消化道慢性失血；完善肝肾功能、血糖、血脂、电解质检查了解全身代谢及内环境状态，为口服激素或JAK抑制剂治疗提供安全依据；斑秃常合并自身免疫性甲状腺病，完善甲状腺功能及甲状腺自身抗体检查排除甲状腺疾病；完善抗核抗体及免疫球蛋白检查排除系统性红斑狼疮等自身免疫性疾病；完善维生素B12、叶酸、铁蛋白及维生素D检测排除营养缺乏所致脱发；因拟予系统免疫治疗，完善结核感染T细胞检测、乙肝两对半及丙肝抗体检查排除结核及病毒性肝炎等潜伏感染；完善心电图检查排除心脏传导异常，为用药做准备；完善胸部X线片检查排除肺部感染及结核；完善腹部超声检查了解肝脾等腹腔脏器情况，排除内脏疾病；治疗期间定期复查血常规、肝肾功能及血脂，监测药物不良反应并指导剂量调整。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 全秃\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 外用米诺地尔：5%米诺地尔搽剂1ml，bid，涂于脱发区头皮并按摩3-5分钟，疗程至少3-6个月。\n2. 外用强效糖皮质激素：卤米松乳膏（或0.05%丙酸氯倍他索乳膏）薄涂患处，bid，连续使用4-8周后评估，注意局部皮肤萎缩及毛囊炎风险。\n3. 皮损内糖皮质激素注射：曲安奈德注射液2.5-10mg/ml，于脱发区多点皮内注射，每点0.1ml，点距1cm，每4周1次，总剂量不超过40mg/次；适用于局限性斑片或范围较小者。\n4. 系统治疗（快速进展或全秃广泛者）：口服糖皮质激素（如泼尼松0.5mg/kg/d，晨起顿服，连用4-6周后每2周减量5mg，总疗程3-4个月），或口服JAK抑制剂（如利特昔替尼50mg qd），用药前完善血常规、肝肾功能及感染筛查，疗程中定期监测。\n\n【一般治疗及生活指导】\n1. 保持情绪稳定，避免焦虑、紧张及精神压力，规律作息，保证充足睡眠，避免熬夜。\n2. 均衡饮食，适当增加优质蛋白、B族维生素、铁、锌及维生素D的摄入（如瘦肉、蛋、奶、豆制品、坚果），忌辛辣刺激及过量饮酒。\n3. 选择温和、刺激性小的洗发护发产品，避免过度烫染、扎紧头发及反复搔抓头皮；外出佩戴帽子或假发，注意头皮防晒。\n4. 配合心理疏导，正确认识病程，树立长期治疗信心，避免因外观焦虑自行中断治疗。\n\n【随诊要求】\n1. 每2-4周复诊1次，评估脱发区毳毛/终毛再生情况及皮损变化，必要时拍照对比。\n2. 外用及系统用药期间监测不良反应：局部刺激、毛囊炎、皮肤萎缩、血压、血糖及肝肾功能等；口服糖皮质激素者监测血压、血糖、骨密度。\n3. 治疗3个月无效或病情继续扩大者，复诊评估调整治疗方案（如加用接触性免疫治疗DPCP或更换系统药物）。\n4. 病情缓解后仍需定期随访半年至1年，警惕复发；出现甲损害、其他部位毛发脱落或新发斑秃时及时复诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":519,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"c452335e8f38841e8646c3f02979c087bfadbc279fc77620f1a88588e97adbc7","pinyin":"quantu","initials":"qt","setting":"out","caseName":"门诊病历384","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历384",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-376cbd94fe51158694e6","key":"v1-c9ccc21dfe2a3058|templates-376cbd94fe51158694e6","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"普秃","category":"门诊病历模板","raw":{"name":"普秃","category":"门诊病历模板","case":{"case_name":"门诊病历385","templates":{"主诉":"反复普秃相关不适1周，加重1天。","现病史":"患者1周前无明显诱因出现普秃相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以反复普秃相关不适1周、加重1天就诊，近1周症状逐渐加重并伴轻度乏力，但无明显发热及恶心呕吐，为排除感染、贫血及营养素缺乏等可致毛发脱落的全身因素，入院当日完善血常规检查；完善尿常规检查了解泌尿系统有无感染及蛋白尿等情况，排查系统性疾病；完善大便常规检查排除消化道慢性失血、寄生虫感染等导致营养吸收障碍与脱发的原因，必要时加做便潜血；患者既往体健，但普秃需长期外用及系统用药，药物多经肝肾代谢，完善肝肾功能检查排除肝肾功能不全，为用药安全提供依据；完善血糖检查排除糖尿病等代谢异常所致脱发，并行血脂检查了解血脂水平；完善电解质检查排除低钙、低锌等电解质与微量元素紊乱对毛发生长的影响；为评估心肺基础状况、排除系统性疾病及用药禁忌，完善心电图检查了解有无心肌缺血及心律失常；完善胸部X线片检查排除肺部感染、结核及纵隔占位等慢性消耗性疾病；完善腹部超声检查了解肝胆胰脾及腹腔脏器情况，明确有无腹部病变影响营养代谢；患者头皮脱发范围广泛、进展较快，必要时完善毛发镜检查了解毛囊开口、毛干形态及毛发密度，必要时行真菌镜检排除头癣所致脱发，必要时完善甲状腺功能及自身抗体检测排除甲状腺疾病、红斑狼疮等免疫性疾病所致脱发，以进一步明确普秃的病因与病情活动度。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 普秃\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 5%米诺地尔搽剂1ml，涂搽全头皮及受累部位并轻揉，每日2次，连续使用至少6个月，一般用药3～6个月可见新生毳毛，勿用于破损皮肤。\n2. 0.05%丙酸氯倍他索乳膏，涂搽皮损处，每日1次，连用5日后停用2日，4～8周为一疗程，可间歇重复，避免面部及皮肤皱褶处长期使用以防皮肤萎缩。\n3. 巴瑞替尼片4mg，口服，每日1次，适用于病程≥6个月的重度斑秃（普秃）患者，连用12周评估疗效，有效者维持治疗至少6个月；用药期间监测血常规、肝肾功能、血脂及感染征象。（如当地可及，亦可选用利特昔替尼胶囊50mg，每日1次。）\n4. 复方甘草酸苷片2片，口服，每日3次，辅助免疫调节治疗，疗程2～3个月。\n\n【一般治疗及生活指导】\n1. 规律作息，保证充足睡眠，避免熬夜、精神紧张及焦虑，保持情绪平稳，避免诱发因素。\n2. 均衡饮食，适量摄入优质蛋白及富含B族维生素、铁、锌的食物（瘦肉、蛋类、豆制品、坚果、深色蔬菜），避免盲目节食减肥。\n3. 洗护头发动作轻柔，水温适中，避免烫染、紧扎发型及用力搔抓头皮；外出注意防晒，避免头皮暴晒。\n4. 避免使用成分不明的生发偏方及刺激性外用制剂，坚持规范治疗并定期评估疗效。\n\n【随诊要求】\n1. 每4～12周门诊复诊1次，评估毛发再生情况及药物不良反应。\n2. 口服巴瑞替尼者，用药前及用药期间定期复查血常规、肝肾功能、血脂；出现发热、感染、出血倾向或下肢肿痛等血栓相关症状时及时就医。\n3. 外用糖皮质激素单个疗程不超过8周，疗程间须复诊评估后再决定是否继续，以防皮肤萎缩等不良反应。\n4. 规范治疗6～12个月仍无明显毛发再生或病情进展者，建议转皮肤专科评估行接触性免疫治疗（DPCP）等进一步方案。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":520,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"dca34a6af1f931f2853abc19530f8a73bfd63b348e655d0b41d530e7c9bde2bb","pinyin":"putu","initials":"pt","setting":"out","caseName":"门诊病历385","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历385",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-84b7c1596ba4df903394","key":"v1-c9ccc21dfe2a3058|templates-84b7c1596ba4df903394","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"雄激素性脱发","category":"门诊病历模板","raw":{"name":"雄激素性脱发","category":"门诊病历模板","case":{"case_name":"门诊病历386","templates":{"主诉":"发际后退、头顶头发稀疏3年","现病史":"患者男性，青春期后起病：前额发际线后退（M形）+顶部（头顶）头发稀疏，呈进行性，可进展至全顶及枕上（保留枕部供区）；女性则表现为顶部中央发缝增宽（圣诞树型，保留前额发际线，不秃顶），并注意月经及多毛情况（排除多囊卵巢，女性雄激素过多）。患者于3年前开始脱发并渐加重，每日脱落量不多（毛囊微小化，终毛变毳毛，呈缓慢进行性），头皮皮脂多（部分伴脂溢性皮炎），家族秃发史（父系母系）：父亲有秃发史（遗传易感，多基因）。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.7℃，P78次/分，R18次/分，BP120/78mmHg。男性：前额发际M形后退（Norwood-Hamilton分级Ⅲ级）、顶部稀疏（分级Ⅲ级）、枕部头发保留；女性：顶部弥漫稀疏（发缝增宽，Ludwig分级，前额发际保留）；毛发镜（毛发粗细不均（毛干直径变异>20%，为特征性表现，支持雄激素性脱发）、毳毛增多、黄点征少，与斑秃鉴别），拉发试验阴性（慢性期通常阴性），头皮皮脂分泌较多、无明显炎症。","辅助检查":"【必做】一般临床诊断为主（典型模式）；毛发镜（毛干直径变异，支持诊断）；【内分泌】性激素（女性，伴月经不调/多毛/痤疮者查睾酮、硫酸脱氢表雄酮，评估多囊卵巢，必要时超声）、甲状腺功能（弥漫性脱发鉴别）、铁蛋白（女性，缺铁常见，补铁有助疗效）；【其他】头皮活检（少见需要，用于与其他脱发鉴别）。","初步诊断":"1. 雄激素性脱发（男性型，Norwood-Hamilton分级Ⅲ级）\n（注：治疗（需长期坚持，停药后复脱，早期干预效果好，目标为延缓而非治愈）：①男性：非那雄胺1mg qd（抑制Ⅱ型5α-还原酶，双氢睾酮↓，需6~12个月评估疗效，维持治疗，注意性欲减退/勃起功能障碍/情绪改变（约1~2%，停药可恢复）、50岁以上监测前列腺特异抗原）、外用米诺地尔5%bid（联合非那雄胺疗效协同，初用2~6周可有暂时性脱发增多（毛发周期同步化，属正常，应坚持），对丙二醇过敏者换泡沫剂）；②女性：外用米诺地尔2~5%（首选，女性专用5%每日1次）、螺内酯50~200mg qd（抗雄激素，需避孕，监测血钾），口服避孕药（多囊卵巢/雄激素高者，含环丙孕酮/屈螺酮）；③辅助：低能量激光（激光帽，有循证支持，辅助治疗）、毛发移植（毛囊单位提取，供区为枕部，稳定期进行，属美容外科）；④头皮护理（温和洗发、避免紧扎/烫染，牵拉可加重）、治疗伴发脂溢性皮炎；⑤评估（毛发镜+照相，每6~12个月，判断疗效，无效则调整剂量或依从性）；皮肤科（毛发门诊）随访管理。）","处理方案":"【药物治疗】\n1. 非那雄胺片 1mg 口服 qd，连续服用6-12个月以上（仅限男性患者，育龄期女性禁用）。\n2. 米诺地尔搽剂 5% 1ml 外用 bid（头皮局部喷涂，每次约喷6次，涂于脱发区并轻柔按摩2-3分钟），连续使用至少6个月。\n3. 螺内酯片 40mg 口服 bid（女性患者适用，男性禁用），疗程至少6个月，用药期间注意监测血压及月经情况。\n4. 复合维生素B片 2片 口服 tid，辅助营养支持。\n\n【一般治疗及生活指导】\n1. 保证充足睡眠，避免熬夜及精神紧张、焦虑，保持规律作息。\n2. 均衡饮食，适当增加优质蛋白（瘦肉、鱼、蛋、豆制品）及富含锌、铁、B族维生素食物摄入，减少高脂、高糖及辛辣刺激饮食。\n3. 头皮温和护理：选用温和洗发产品，洗护时避免用力搔抓头皮，避免频繁烫发、染发及扎过紧发型。\n4. 适度有氧运动，戒烟限酒，保持心情舒畅。\n\n【随诊要求】\n1. 用药后每3-6个月复诊一次，评估脱发量、发际线及毛发密度改善情况和药物不良反应。\n2. 米诺地尔、非那雄胺起效一般需3-6个月，治疗初期（1-2个月）出现暂时性脱发增多属正常现象，需坚持用药，勿擅自停药。\n3. 关注药物不良反应：男性服用非那雄胺注意性欲减退、勃起功能障碍等；女性服用螺内酯注意月经紊乱、低血压等，出现异常及时复诊。\n4. 停药后脱发可能复发，建议在医师指导下缓慢减量或长期维持治疗，定期随访。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":521,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"8666d0ad41caa4ca4508ccdd0c5c049a7a14ebb339cc35fef943d49e2c60248a","pinyin":"xiongjisuxingtuofa","initials":"xjsxtf","setting":"out","caseName":"门诊病历386","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历386",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-1525c980835f608cc5f7","key":"v1-c9ccc21dfe2a3058|templates-1525c980835f608cc5f7","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"休止期脱发","category":"门诊病历模板","raw":{"name":"休止期脱发","category":"门诊病历模板","case":{"case_name":"门诊病历387","templates":{"主诉":"弥漫性头发脱落增多3个月","现病史":"患者于应激事件（发热性疾病（高热/感染）、大手术/外伤/大出血、分娩（产后脱发，产后2~4个月出现，常见）、精神应激、快速减重/节食（营养不良）、重大疾病、停用避孕药）后约2~3个月开始出现弥漫性头发脱落增多（每日脱落百余根，洗头梳头时成把脱落，患者常惊恐），全头均匀稀疏（不秃顶，发际保留），无铁缺乏（无献血/月经过多史，女性）、无甲状腺功能异常、继续应激因素已去除，脱发持续2个月（急性休止期脱发通常3~6个月自行恢复；慢性休止期脱发>6个月，多有持续诱因，如营养/铁/甲功问题），无头皮炎症无瘢痕。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P76次/分，R18次/分，BP115/72mmHg。全头头发弥漫性稀疏（均匀，顶部及颞部均受累）、无明显秃发斑，拉发试验阳性（活动期，脱落>2~3根/束），头皮正常无炎症无瘢痕，眉毛体毛正常，甲正常。","辅助检查":"【必做】拉发试验、毛发镜（毳毛比例、毛囊开口正常，排除其他脱发，休止期可见生长期/休止期比例变化）；【营养/内分泌】血常规、铁蛋白（缺铁常见，与月经过多/素食相关，重要）、甲状腺功能、维生素D/B12（必要时）；【其他】头皮活检（少见，用于慢性或诊断不明者，可见休止期毛囊比例增高）。","初步诊断":"1. 休止期脱发（急性型，病程<6个月，应激事件后起病）\n（注：①核心为去除诱因及安慰：多数急性休止期脱发为自限性，3~6个月内毛囊恢复，新发长出，完全恢复约需6~12个月，向患者解释，减轻焦虑（焦虑本身可加重脱发）；②补充缺乏：铁蛋白<30~40ng/ml者补铁（硫酸亚铁，需复查）、维生素D/B12/蛋白质（均衡营养，避免快速节食）；③治疗基础病（甲状腺病用左甲状腺素、控制糖尿病等）；④米诺地尔外用（2%，用于慢性/促进恢复，可选，疗程6个月，帮助加速生长）；⑤毛发护理（温和，避免染烫拉直，减少物理损伤）；⑥随访（3~6个月，观察拉发试验转阴、新生发，评估恢复）；⑦慢性者（>6个月）需排查慢性诱因（持续应激/营养/内分泌）并处理；皮肤科随访，多数预后好，可完全再生。）","处理方案":"【药物治疗】\n1. 米诺地尔搽剂：2%浓度（女性）或5%浓度（男性）1ml涂擦于脱发区头皮，bid，疗程至少3～6个月\n2. 复合维生素B片1片 tid 或 多维元素片1片 qd，疗程1～3个月，补充毛发生长所需微量元素\n3. 琥珀酸亚铁片0.1g tid（饭后服，适用于血清铁蛋白＜30μg/L者），疗程2～3个月或至铁蛋白恢复正常\n\n【一般治疗及生活指导】\n1. 寻找并去除诱因（近期分娩、手术、高热、重大应激、快速节食减肥或停用激素等），保证规律作息、每晚7～8小时睡眠，避免熬夜及精神紧张焦虑\n2. 均衡饮食，保证优质蛋白摄入（瘦肉、鱼、蛋、奶、豆制品）及足量新鲜蔬果，避免节食和体重骤降；洗护时水温适中，动作轻柔，避免频繁烫染及过度牵拉（紧扎马尾、编发等）\n\n【随诊要求】\n去除诱因后脱发多于3～6个月内自行缓解，建议2～3个月后复诊评估脱发量变化；若脱发持续超过6个月、进行性加重或出现斑片状脱发，应提前复诊；必要时复查血常规、血清铁蛋白及甲状腺功能以排查继发原因。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":522,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"0f2c6bb8e57e870d64536ca5c0ef211016dd8d61f8e4d2bceacf5540c766b81c","pinyin":"xiuzhiqituofa","initials":"xzqtf","setting":"out","caseName":"门诊病历387","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历387",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-f78dee564521e82af254","key":"v1-c9ccc21dfe2a3058|templates-f78dee564521e82af254","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"生长期脱发","category":"门诊病历模板","raw":{"name":"生长期脱发","category":"门诊病历模板","case":{"case_name":"门诊病历388","templates":{"主诉":"头发大量脱落1周","现病史":"患者1周前无明显诱因出现生长期脱发相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以头发大量脱落1周就诊，病前无明显诱因，症状逐渐加重并伴轻度乏力，无明显发热及恶心呕吐，生长期脱发多与药物、毒物、发热、精神应激及营养障碍有关，入院当日完善血常规检查排除感染、贫血及营养素缺乏所致脱发；完善尿常规检查了解泌尿系统情况，排除系统性疾病及药物相关肾损害；完善大便常规检查排除消化道慢性失血与寄生虫感染所致营养吸收障碍，必要时加做便潜血；患者起病与近期用药、接触化学物质或应激因素相关，药物多经肝肾代谢，完善肝肾功能检查排除肝肾功能不全，并为后续用药安全提供依据；完善血糖检查排除糖尿病等代谢性疾病所致脱发；完善血脂检查了解血脂水平；完善电解质检查排除电解质紊乱与微量元素缺乏对毛发生长的影响；为评估机体基础状况并排除系统性疾病，完善心电图检查了解有无心肌缺血及心律失常；完善胸部X线片检查排除肺部感染、结核等慢性消耗性疾病；完善腹部超声检查了解肝胆胰脾及腹腔脏器情况；考虑甲状腺功能异常常表现为弥漫性脱发，必要时完善甲状腺功能及性激素检查排除内分泌紊乱所致脱发，必要时完善毛发镜检查观察毛干形态、毛囊开口及毛发密度以明确脱发类型，必要时行拉发试验计数脱落毛发评估脱发活动性，必要时完善铁代谢及维生素D、锌等营养素检测，进一步明确生长期脱发的诱因。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 生长期脱发\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1.米诺地尔搽剂（5%）1ml 外用，涂于脱发区头皮并轻揉按摩3～5分钟，每日2次，疗程3～6个月（女性患者可选用2%浓度，减少局部刺激及多毛等不良反应）。\n2.复合维生素B片2片 tid，口服，或 多维元素片（29）1片 qd，口服，疗程1～3个月，补充毛发生长所需B族维生素及微量元素。\n3.胱氨酸片50mg tid，口服，疗程1～3个月，与复合维生素B联用协同促进毛发再生。\n\n【一般治疗及生活指导】\n1.去除病因：如系化疗、放疗所致，应与肿瘤科协作调整方案或于化疗期间佩戴头皮冷却帽以减少毛囊损伤；避免接触铊、砷、汞等重金属及毒性化学物质，脱离致病因后毛发方可再生。\n2.毛发护理：温水轻柔洗护，选用温和无刺激洗发产品，避免烫染、高温吹风、紧扎发辫及过度梳理牵拉，减少对生长期毛囊的机械性损伤。\n3.饮食作息：均衡高蛋白饮食（瘦肉、鱼、蛋、奶、豆制品），适量补充富含铁、锌、维生素的深色蔬菜及水果；规律作息，保证充足睡眠，避免熬夜及精神紧张。\n4.心理疏导：向患者说明脱发为暂时性，去除病因后多可完全再生，缓解焦虑情绪，避免因过度担忧加重应激性脱发。\n\n【随诊要求】\n每2～4周复诊1次，评估脱发范围及新生毛发情况，监测外用药物局部刺激反应。去除病因后毛发多于1～3个月开始再生，6～12个月基本恢复正常；若6个月以上仍无明显再生，或脱发区出现红斑、萎缩、瘢痕等，应及时复诊，行皮肤镜、毛发病理等检查，排除瘢痕性脱发及其他系统性疾病。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":523,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"ee0e34f48ea98fd9bcbdc7b3d07225750a1fb027ec9c1cb4501166a7eafbb114","pinyin":"shengzhangqituofa","initials":"szqtf","setting":"out","caseName":"门诊病历388","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历388",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-c45f2985b81139d8f3ad","key":"v1-c9ccc21dfe2a3058|templates-c45f2985b81139d8f3ad","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"牵拉性脱发","category":"门诊病历模板","raw":{"name":"牵拉性脱发","category":"门诊病历模板","case":{"case_name":"门诊病历389","templates":{"主诉":"牵拉部位头发脱落1周","现病史":"患者1周前无明显诱因出现牵拉性脱发相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以牵拉部位头发脱落1周就诊，病变局限于长期受牵拉的头皮区域，症状逐渐加重并伴轻度乏力，为排除感染、贫血及营养障碍等全身因素对毛发生长的影响，入院当日完善血常规检查；完善尿常规检查了解泌尿系统情况，排除系统性疾病；完善大便常规检查排除消化道慢性失血及寄生虫感染所致营养吸收障碍，必要时加做便潜血；患者需长期用药及局部治疗，药物经肝肾代谢，完善肝肾功能检查排除肝肾功能不全，为用药安全提供依据；完善血糖检查排除糖尿病等代谢异常所致脱发；完善血脂检查了解血脂水平；完善电解质检查排除电解质紊乱及微量元素缺乏；为评估心肺基础状况，完善心电图检查了解有无心肌缺血及心律失常；完善胸部X线片检查排除肺部感染、结核等慢性消耗性疾病；完善腹部超声检查了解肝胆胰脾及腹腔脏器情况；本例为长期牵拉所致脱发，需重点排除瘢痕性脱发与其他秃发疾病，必要时完善毛发镜检查观察牵拉区毛囊开口、毛干形态及有无断发，明确毛囊是否受累；必要时行拉发试验计数脱落毛发并评估头皮张力及炎症情况，以判断脱发活动性；必要时完善甲状腺功能、铁代谢及自身抗体检测，排除甲状腺疾病、缺铁及免疫性疾病所致脱发，进一步明确牵拉性脱发的诊断并指导发型及治疗调整。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 牵拉性脱发\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 5%米诺地尔搽剂1mL，涂搽脱发区并轻柔按摩2-3分钟，每日2次，疗程至少6个月（一线促毛发生长药物，停药需逐渐减量）。\n2. 0.05%丙酸氯倍他索溶液（或0.1%糠酸莫米松乳膏）外用脱发区，每日1次，连用2-4周，适用于伴局部红肿、瘙痒或早期纤维化者；症状消退即停用，避免长期外用强效糖皮质激素。\n3. 硫酸亚铁片0.3g口服，每日3次，餐后服用（或按血清铁蛋白结果补充铁剂），适用于伴缺铁者；复合维生素B片2片口服，每日3次，疗程4-8周。\n\n【一般治疗及生活指导】\n1. 立即去除致病诱因：停止扎紧马尾、高髻、编发、接发及紧贴头皮的辫发等牵拉发型，改梳宽松发型，避免佩戴过紧发夹、发箍、发绳及头套等压迫毛囊的饰物。\n2. 梳理头发动作轻柔，避免暴力梳理、频繁烫染及高温电吹风，洗发水温适中，减少机械性损伤。\n3. 均衡饮食，保证优质蛋白（鱼、蛋、瘦肉、豆制品）及富含铁、锌、B族维生素的食物（红肉、动物肝脏、绿叶蔬菜、坚果）摄入；规律作息，保证充足睡眠，避免熬夜，缓解精神压力。\n4. 每日轻柔按摩头皮1-2次，促进局部血液循环，有助于毛囊恢复。\n\n【随诊要求】\n1. 治疗后每4周复诊1次，评估脱发区新生绒毛生长及局部炎症消退情况；用药期间如出现局部刺激、过敏或脱发加重，及时复诊。\n2. 持续随访6-12个月；若去除牵拉因素并规范治疗6个月后仍无绒毛生长，建议行皮肤镜检查评估毛囊瘢痕化程度，必要时转诊评估毛发移植手术适应证。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":524,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"c0bb7d10832ef5e99dd80999bf496ba3cecebf4b721561615492818c08601f3d","pinyin":"qianlaxingtuofa","initials":"qlxtf","setting":"out","caseName":"门诊病历389","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历389",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-4db79b912203b3c225f5","key":"v1-c9ccc21dfe2a3058|templates-4db79b912203b3c225f5","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"头癣性脱发","category":"门诊病历模板","raw":{"name":"头癣性脱发","category":"门诊病历模板","case":{"case_name":"门诊病历390","templates":{"主诉":"头皮鳞屑、断发伴脱发1周","现病史":"患者1周前无明显诱因出现头癣性脱发相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以头皮鳞屑、断发伴脱发1周就诊，症状逐渐加重并伴轻度乏力，为排除细菌感染及贫血等全身因素，入院当日完善血常规检查；头癣为皮肤癣菌感染所致，真菌镜检加培养为确诊依据，取断发与鳞屑行真菌镜检可直接查找菌丝与孢子，完善真菌镜检加培养明确致病菌种并指导抗真菌药物选择；患者头皮有鳞屑及脱发，完善皮肤镜检查观察有无逗号发、螺旋发、断发及毛囊开口情况，协助鉴别头癣与脂溢性皮炎、斑秃等疾病；患者既往体健而本次出现头皮炎症表现，完善过敏原检测了解有无过敏体质及接触性致敏因素，协助判断是否合并变应性皮炎；患者头皮损害需与红斑狼疮、扁平苔藓等免疫性疾病鉴别，必要时完善免疫荧光检查；考虑接触性皮炎可加重头皮炎症与脱发，必要时完善斑贴试验明确接触性致敏原；若皮损不典型、治疗反应差或怀疑瘢痕性脱发，必要时完善皮肤活检行组织病理及真菌染色检查以进一步明确诊断；患者为育龄期成人，若病史或查体提示性传播疾病风险，必要时完善性病相关检测排除梅毒等感染所致脱发，做到既不遗漏也不过度检查。\n\n（检查清单）\n【必做检查】\n血常规、过敏原检测、真菌镜检+培养\n\n【影像学检查】\n皮肤镜、皮肤活检（必要时）\n\n【其他检查】\n免疫荧光、斑贴试验、性病相关检测（必要时）","初步诊断":"1. 头癣性脱发\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 抗真菌口服药（首选）：盐酸特比萘芬片250mg 每日1次口服，连用4周；或灰黄霉素片0.5g 每日2次口服（饭后服），连用4-6周，脓癣及深在型感染可延长至8周。\n2. 外用药（辅助治疗，不能单独治愈）：2%酮康唑洗剂或2.5%二硫化硒洗剂洗头，每日1次，停留5分钟后冲洗干净；患处外涂1%盐酸特比萘芬乳膏或1%联苯苄唑乳膏，每日2次。\n3. 继发细菌感染（脓癣化脓）时加用：头孢呋辛酯片0.25g 每日2次口服，连用7-10天。\n4. 炎症反应明显（脓癣、严重角化）者短期加用泼尼松片10mg 每日3次口服，连用1-2周，以减少瘢痕性脱发。\n\n【一般治疗及生活指导】\n1. 注意个人卫生：毛巾、枕巾、梳子、帽子、理发器具专人专用，定期煮沸消毒（100℃煮沸5-10分钟），衣物、被褥勤洗烫晒。\n2. 每周剃发或剪短病发，以利于涂药及去除带菌毛发，剃下的头发用纸包好后焚烧处理；理发器具每次使用前严格消毒。\n3. 饮食清淡均衡，适当增加优质蛋白及B族维生素摄入，忌辛辣刺激、油腻及高糖饮食；规律作息，避免熬夜、过度劳累。\n4. 排查并同时治疗家庭成员及密切接触宠物（猫、犬）的皮肤癣菌感染，避免交叉感染；避免搔抓头皮，防止继发感染和瘢痕形成。\n\n【随诊要求】\n1. 用药2-4周后复诊，评估皮损消退及炎症控制情况，必要时调整方案；疗程结束时行真菌镜检（或真菌培养），连续2次（间隔1周）阴性方可停药。\n2. 停药后随访3-6个月，观察毛发生长情况，评估有无遗留瘢痕性脱发；若出现皮损扩大、新发脓疱、疼痛或发热，应随时提前复诊。\n3. 治愈后注意复查家庭成员及宠物有无癣病，发现后同步治疗，防止复发。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":525,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"88ad0e79f3913849d86fbd416647b02433154fe623c4df85e6b38a38879313f1","pinyin":"touxuanxingtuofa","initials":"txxtf","setting":"out","caseName":"门诊病历390","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历390",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-45638764040b0d69b6fa","key":"v1-c9ccc21dfe2a3058|templates-45638764040b0d69b6fa","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"梅毒性脱发","category":"门诊病历模板","raw":{"name":"梅毒性脱发","category":"门诊病历模板","case":{"case_name":"门诊病历391","templates":{"主诉":"头皮虫蚀状脱发1周","现病史":"患者1周前无明显诱因出现梅毒性脱发相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以头皮虫蚀状脱发1周就诊，症状逐渐加重并伴轻度乏力，虽无明显发热，为排除合并感染及评估贫血、营养状况，入院当日完善血常规检查；完善CRP及降钙素原检查评估体内炎症反应程度，排除合并细菌感染；完善血沉检查了解炎症活动度并作为病情随访指标；梅毒血清学检查为确诊梅毒性脱发的关键，完善非梅毒螺旋体抗原试验及梅毒螺旋体特异性抗体检测以明确诊断与判断活动性；患者需接受青霉素规范抗梅治疗，药物经肝肾代谢，完善肝肾功能检查排除肝肾功能不全，为用药安全提供依据；为评估有无系统性损害，完善胸部CT检查排除肺部感染、结核及纵隔淋巴结肿大；完善腹部超声检查了解肝胆胰脾等腹腔脏器情况；患者可有全身淋巴结肿大，完善淋巴结超声检查明确有无淋巴结肿大及其性质；患者存在感染性疾病可能，完善血培养、痰培养及尿培养检查明确有无血流感染及合并细菌感染，并据药敏指导抗感染治疗；为鉴别发热及免疫抑制相关因素，完善病毒学检测排除HIV、EB病毒、巨细胞病毒等感染；必要时完善G试验及GM试验排除侵袭性真菌感染；若出现神经系统症状，必要时完善脑脊液检查排除神经梅毒，进一步明确诊断并指导分期治疗。\n\n（检查清单）\n【必做检查】\n血常规、CRP、降钙素原、血沉、肝肾功能\n\n【影像学检查】\n胸部CT、腹部超声、淋巴结超声\n\n【其他检查】\n血培养、痰培养、尿培养、病毒学检测、G试验/GM试验","初步诊断":"1. 梅毒性脱发\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 青霉素类（首选）：苄星青霉素注射液240万U，分两侧臀部肌内注射，每周1次，共3周（第0、1、2周各1次），为早期/二期梅毒标准治疗方案；肌注前先行青霉素皮试。\n2. 四环素类（青霉素过敏替代）：多西环素胶囊0.1g，口服，每日2次，连用14天。\n3. 随诊用药：治疗期间不需外用生发药物，毛发多在驱梅治疗后自行再生；如伴明显瘙痒或脂溢性皮炎表现，可短期外用二硫化硒洗剂（2.5%，每周2次，洗头停留3~5分钟后冲净）。\n【一般治疗及生活指导】\n1. 隔离与性卫生：治疗期间禁止性生活，性伴侣应同步进行梅毒血清学检查及治疗（同防同治），治愈前避免密切接触传播。\n2. 饮食与作息：规律作息，避免熬夜与过度劳累，保持情绪平稳；饮食均衡、富含优质蛋白及B族维生素（瘦肉、蛋、豆制品、粗粮），忌辛辣刺激及烟酒。\n3. 个人卫生：勤换洗枕巾、毛巾及梳子并单独使用，避免与家人共用，防止间接接触传染。\n4. 禁忌：禁用糖皮质激素及免疫抑制剂，以免掩盖病情、延误诊断；如用药后出现皮疹、发热、肌注部位硬结等吉海反应表现，及时复诊处理。\n【随诊要求】\n1. 治疗后第3、6、9、12个月各复查1次非梅毒螺旋体血清学试验（RPR/TRUST），观察滴度下降情况，早期梅毒应随访2年，滴度下降4倍或转阴为有效；滴度不降或升高需复查评估并排除神经梅毒。\n2. 治疗结束后1个月复查梅毒螺旋体特异性抗体试验（TPPA）定性，随访期间动态观察毛发再生情况，一般驱梅治疗后数周至数月脱发区毛发可逐渐再生。\n3. 如治疗后3个月毛发仍无明显再生，或出现新发脱发斑、神经症状（头痛、视力听力异常等），应及时至皮肤科、神经内科复诊，完善脑脊液检查排除神经梅毒。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":526,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"12233d43edcb2ae01d7fb5766b4f7967259a56cd483532b15986c69281a463c8","pinyin":"meiduxingtuofa","initials":"mdxtf","setting":"out","caseName":"门诊病历391","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历391",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-4ac669992cd260facc07","key":"v1-c9ccc21dfe2a3058|templates-4ac669992cd260facc07","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"多汗症","category":"门诊病历模板","raw":{"name":"多汗症","category":"门诊病历模板","case":{"case_name":"门诊病历392","templates":{"主诉":"手足、腋窝过度出汗5年","现病史":"患者于5年前开始（多起于儿童青少年）在手掌、腋窝（原发局灶性多汗，可多部位并存）出现过度出汗（静止及凉爽环境亦明显，呈持续性、不受温度调节，属原发性，系交感神经过度活跃；睡眠时不出汗，可与继发性鉴别，夜间出汗需排查），无继发因素：无甲状腺功能亢进（怕热多汗+心悸消瘦）、非更年期（潮热出汗）、无嗜铬细胞瘤（阵发大汗+头痛心悸高血压）、无结核/淋巴瘤（盗汗，夜间）、无低血糖（心慌冷汗）、无焦虑（情绪相关）、无肥胖、未用特殊药物，家族史（原发多汗常有家族聚集）无类似病史，对生活影响明显（握手/书写/工作/社交回避，有心理困扰）。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.6℃，P82次/分（甲亢可增快），R18次/分，BP118/76mmHg。手掌/腋窝/足底明显潮湿（可见汗珠，视诊皮肤浸渍发白、足部有气味，易继发浸渍/真菌感染）、头面部出汗，甲状腺无肿大、无震颤（甲亢查体），双手细颤（-），皮肤无腋窝浸渍红斑（间擦疹可继发念珠菌/棒状杆菌感染即红癣）。","辅助检查":"【必做】一般临床诊断为主（原发多汗标准：局灶性可见出汗≥6个月，且符合以下≥2条：双侧对称、每周≥1次、起病<25岁、家族史、睡眠时停止、影响日常）；【继发筛查】甲状腺功能（怕热心悸者筛查）、血糖（有低血糖症状者）、性激素（围绝经期，潮热）、胸片（盗汗明显，排查结核/淋巴瘤）、尿儿茶酚胺代谢物（疑嗜铬细胞瘤，阵发大汗伴高血压）；【客观评估】碘-淀粉试验（Minor试验，出汗范围定位，治疗前）、称重法（评估汗量）。","初步诊断":"1. 多汗症（原发局灶性型，累及掌/腋/足/头面；继发性病因待查）\n（注：①外用收敛剂（一线，用于轻中度）：20%氯化铝溶液（睡前涂于干燥皮肤，封包过夜，晨起清洗，每周2~3次渐调整，注意刺激）；②离子电渗疗法（掌跖，水中通电，每周数次，有效维持）；③肉毒毒素注射（A型肉毒毒素，腋窝（疗效维持5~10个月，一线强效）及掌跖，皮内注射，效果显著，为目前最有效的非手术手段之一，费用较高）；④口服抗胆碱能药（全身/顽固者，奥昔布宁/格隆溴铵，有口干、视物模糊副作用，老年慎用）；⑤微波热解/激光（破坏腋窝汗腺，疗效持久）；⑥内镜胸交感神经切断术（ETS，用于掌汗，为最后一招，有代偿性多汗（躯干）风险，需严格选择）；⑦心理支持（社交焦虑，影响大，可合并治疗）；⑧治疗继发因素（甲亢、更年期可予激素替代、焦虑予抗焦虑治疗）；⑨皮肤护理（防浸渍感染，保持干燥、抗真菌，注意腋窝念珠菌）；皮肤科专科评估，阶梯治疗（先无创后微创）。）","处理方案":"【药物治疗】\n1. 外用止汗剂：20%六水合氯化铝无水乙醇溶液，睡前涂于清洁干燥的出汗部位（手掌、足底、腋窝），每次适量（每部位2~4喷或薄涂一层），每周2~3次，症状控制后改为每周1次维持；用药期间保持局部干燥，次日晨起洗去。若出现明显皮肤刺激可间隔2~3天使用并外用保湿霜。\n2. 口服抗胆碱能药物：奥昔布宁片2.5mg bid口服，饭后服用，2周后疗效不理想且无明显不良反应可增至5mg bid，疗程4~8周（用于外用治疗无效或全身多部位受累者，老年人慎用）。\n3. 局部注射治疗：A型肉毒毒素局部皮内注射（掌跖部每只手掌约100U，腋窝每侧约50U，分点注射），疗效可维持4~12个月，疗效减退后可重复注射；适用于外用治疗无效的中重度腋窝及掌跖多汗。\n4. 顽固性重症患者可转诊评估交感神经链切断术（胸交感神经切除术）等外科治疗；继发于甲亢、糖尿病、感染、肿瘤者应针对原发病治疗。\n\n【一般治疗及生活指导】\n1. 保持皮肤清洁干燥，勤洗澡、勤换衣物，选择棉质、宽松、透气的衣物鞋袜，避免化纤紧身衣物；出汗后及时擦干并更换干爽衣物。\n2. 避免辛辣刺激性食物、咖啡、浓茶、酒精及过热饮品等可诱发或加重出汗的饮食因素；规律作息，保证充足睡眠，避免过度劳累。\n3. 保持情绪平稳，避免紧张、焦虑、激动等精神应激因素；必要时进行放松训练，以减轻精神性出汗。\n4. 避免剧烈运动及高温环境；使用止汗剂前确保皮肤干燥，勿在刚脱毛或破损皮肤上使用，注意局部皮肤刺激反应。\n\n【随诊要求】\n1. 用药2周后复诊，评估止汗疗效、皮肤刺激及口服药不良反应（口干、便秘、视物模糊、尿潴留等），据此调整药物剂量或方案。\n2. 口服抗胆碱能药物疗程结束或症状反复时复诊，评估是否需升级治疗（如肉毒毒素注射或转外科评估）。\n3. 肉毒毒素注射后3~6个月疗效减退时复诊，评估重复注射时机；出现心悸、发热、消瘦、夜汗等全身症状或疑有继发性病因者应及时复诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":527,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"9ea40d0dc81dec69b9ace73f4e80497e7c20f71705f774a779c91da50c3a923f","pinyin":"duohanzheng","initials":"dhz","setting":"out","caseName":"门诊病历392","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历392",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-8790b505f2dc75a789e0","key":"v1-c9ccc21dfe2a3058|templates-8790b505f2dc75a789e0","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"臭汗症","category":"门诊病历模板","raw":{"name":"臭汗症","category":"门诊病历模板","case":{"case_name":"门诊病历393","templates":{"主诉":"腋窝汗液异味1周","现病史":"患者1周前无明显诱因出现臭汗症相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以腋窝汗液异味1周就诊，症状逐渐加重并伴轻度乏力，为排除感染、贫血及代谢性疾病等全身因素，入院当日完善血常规检查；完善尿常规检查了解泌尿系统情况，排除系统性疾病所致汗液成分异常；完善大便常规检查排除消化道慢性失血及寄生虫感染等消耗性疾病，必要时加做便潜血；患者汗腺分泌受内分泌与代谢状态影响，且后续用药及必要的手术治疗需经肝肾代谢，完善肝肾功能检查排除肝肾功能不全，为用药与手术安全提供依据；完善血糖检查排除糖尿病所致多汗与皮肤感染；完善血脂检查了解血脂水平；完善电解质检查排除电解质紊乱及微量元素缺乏；为评估心肺基础状况，完善心电图检查了解有无心肌缺血及心律失常；完善胸部X线片检查排除肺部感染、结核等慢性消耗性疾病；完善腹部超声检查了解肝胆胰脾及腹腔脏器情况；患者腋窝异味需排除局部细菌分解汗液及化脓性汗腺炎等病变，必要时完善腋窝分泌物细菌培养及药敏试验明确致病菌并指导抗菌治疗，必要时完善皮肤镜检查观察腋窝大汗腺、毛囊及皮肤附属器情况，为是否行手术治疗提供依据，进一步明确臭汗症的病因与病情程度。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 臭汗症\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 止汗抑臭：20%氯化铝无水乙醇溶液（如安多喜），睡前涂于腋窝等多汗部位，每周1-2次，连用2-4周，收敛止汗、减少异味。\n2. 抗菌外用：2%甲醛溶液或0.1%苯扎溴铵溶液涂搽患处，每日2次，疗程2-4周，抑制产臭菌繁殖。\n3. 严重顽固性腋臭：A型肉毒毒素（保妥适）局部皮内注射，每侧腋窝50-100U分点注射，每4-6个月重复1次。\n【一般治疗及生活指导】\n1. 保持局部清洁干燥：每日清洗腋窝、腹股沟等易出汗部位，勤洗澡、勤换内衣，可配合抗菌皂清洁。\n2. 穿着宽松、透气、吸汗的棉质衣物，避免紧身不透气化纤衣裤。\n3. 忌食辛辣、刺激性食物及葱蒜等气味浓烈食物，少饮咖啡、浓茶，戒烟限酒。\n4. 保持情绪平稳，避免紧张焦虑和剧烈运动，减少出汗。\n【随诊要求】\n用药2-4周后复诊评估疗效；如药物治疗效果不佳或异味严重影响社交生活，建议转皮肤科评估，必要时行微创大汗腺清除术或肉毒毒素注射治疗，并按医嘱定期随访。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":528,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"8f4dab477c9d7b2599a04915174e19b79d7a13eabe9cda30c97c58f302c14a41","pinyin":"chouhanzheng","initials":"chz","setting":"out","caseName":"门诊病历393","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历393",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-af5ab0a27bb03b93a9b2","key":"v1-c9ccc21dfe2a3058|templates-af5ab0a27bb03b93a9b2","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"色汗症","category":"门诊病历模板","raw":{"name":"色汗症","category":"门诊病历模板","case":{"case_name":"门诊病历394","templates":{"主诉":"汗液着色1周","现病史":"患者1周前无明显诱因出现色汗症相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以汗液着色1周就诊，症状逐渐加重并伴轻度乏力，色汗症可为外源性染料、药物所致，也可继发于体内代谢异常或细菌感染，为排除感染、贫血及血液系统疾病，入院当日完善血常规检查；完善尿常规检查了解有无血尿、胆红素尿及泌尿系统感染，协助鉴别色汗与尿色异常；完善大便常规检查排除消化道出血与寄生虫感染，必要时加做便潜血；患者汗液着色可能与肝胆代谢异常、药物蓄积相关，完善肝肾功能检查排除肝肾功能不全所致胆红素及代谢产物经汗液排泄异常，同时为用药安全提供依据；完善血糖检查排除糖尿病所致皮肤感染与汗液成分改变；完善血脂检查了解血脂水平；完善电解质检查排除电解质紊乱；为评估心肺基础状况，完善心电图检查了解有无心肌缺血及心律失常；完善胸部X线片检查排除肺部感染、结核等慢性消耗性疾病；完善腹部超声检查了解肝胆胰脾及腹腔脏器情况；患者汗液着色需明确是外源性染色还是内源性色素，必要时完善汗液常规及细菌培养检查排除色汗症相关的假单胞菌等细菌感染，必要时完善皮肤镜检查观察腋窝、面部等出汗部位皮肤及毛囊情况，并详细询问近期药物、染料接触史，进一步明确色汗症的病因。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 色汗症\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 外用辣椒素类（辣椒素乳膏0.025%）：取少量均匀外涂于色汗区域，每日2-3次，疗程4-8周，适用于大汗腺（脂质）性色汗症，通过耗竭P物质减少大汗腺分泌；用药初期可有局部烧灼感，多可自行耐受。\n2. 收敛止汗类（20%氯化铝无水乙醇溶液）：睡前外涂于干燥的色汗部位皮肤，次晨洗去，每周2-3次，持续2-4周评估疗效，通过收敛汗腺导管开口减少出汗量。\n3. 抗菌类（2%克林霉素凝胶）：外涂患处，每日2次，疗程1-2周，适用于假性色汗症（皮肤表面产色细菌如棒状杆菌感染所致）；可配合含抗菌成分的沐浴液清洁皮肤。\n4. A型肉毒毒素注射（保妥适/衡力100U）：以生理盐水2.5ml稀释后于腋窝等大汗腺密集区域皮内多点注射，每点约0.1U，一次注射疗效可维持3-6个月，适用于外用药物疗效不佳的顽固性大汗腺性色汗症。\n\n【一般治疗及生活指导】\n1. 皮肤护理：保持患处皮肤清洁干燥，每日温水清洗后彻底擦干，勤换内衣，避免潮湿环境，不与他人共用毛巾；假性色汗症患者尤应注意个人卫生，防止产色细菌定植。\n2. 饮食：忌辛辣刺激性食物，避免浓茶、咖啡、酒精及含人工色素食品，此类食物可诱发或加重出汗及色汗发作，宜清淡饮食、适量饮水。\n3. 活动：避免剧烈运动和情绪激动，减少交感兴奋所致的汗液分泌增多；出汗后及时擦干并更换衣物。\n4. 着装：穿着宽松、透气、吸汗的纯棉衣物，避免化纤紧身衣物包裹患处；腋下色汗者可根据患者具体情况制定个体化方案剔除腋毛以利清洁干燥。\n\n【随诊要求】\n1. 治疗后2周复诊，评估疗效及局部皮肤耐受情况（有无红肿、刺激、过敏反应）。\n2. 外用药物治疗无效或停药后复发者，复诊后考虑升级为肉毒毒素注射治疗，并预约复诊安排再次注射时间。\n3. 若出现全身性色汗、尿液色深、皮肤色素沉着或关节疼痛等表现，应及时复诊并行尿黑酸检测等检查，排除褐黄病（尿黑酸尿症）、重金属中毒等系统性疾病。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":529,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"1c6007a8628dca4ea19a0a82a5308d9da600e35082dbaf1308e78b273492dfcf","pinyin":"sehanzheng","initials":"shz","setting":"out","caseName":"门诊病历394","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历394",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-19b74139b8d112e1a56b","key":"v1-c9ccc21dfe2a3058|templates-19b74139b8d112e1a56b","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"血汗症","category":"门诊病历模板","raw":{"name":"血汗症","category":"门诊病历模板","case":{"case_name":"门诊病历395","templates":{"主诉":"汗液带血1周","现病史":"患者1周前无明显诱因出现血汗症相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以汗液带血1周就诊，症状逐渐加重并伴轻度乏力，血汗症需首先排除凝血功能障碍、血小板异常及血管性病变，入院当日完善血常规检查了解血小板计数、有无贫血及感染；完善尿常规检查排除血尿及泌尿系统疾病所致类似表现，明确出血来源；完善大便常规检查排除消化道出血与寄生虫感染，必要时加做便潜血；患者汗液带血提示凝血与血管因素可能，完善肝肾功能检查排除肝功能不全所致凝血因子合成障碍，并为用药安全提供依据；完善血糖检查排除糖尿病所致微血管病变；完善血脂检查了解血脂水平及动脉粥样硬化危险因素；完善电解质检查排除电解质紊乱影响；为评估心肺基础状况并排除感染性心内膜炎、肺部病变，完善心电图检查了解有无心肌缺血及心律失常；完善胸部X线片检查排除肺结核、肺部肿瘤及感染性病变；完善腹部超声检查了解肝胆胰脾及腹腔脏器情况；为明确出血性质，必要时完善凝血功能及D-二聚体检查排除凝血机制异常，必要时完善汗液隐血试验及涂片检查证实汗液含血并排除外源性血液污染，必要时完善皮肤镜检查观察出血部位皮肤及毛细血管情况，必要时行皮肤活检排除血管炎、血管瘤及出血性皮肤病，进一步明确血汗症的病因。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 血汗症\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 卡巴克络片（安络血）5mg，po，tid×7天：降低毛细血管脆性与通透性，促进毛细血管断端回缩，减少血液外渗。\n2. 酚磺乙胺片 0.5g，po，tid×7天：增强血小板黏附聚集功能及毛细血管抵抗力，辅助止血。\n3. 地西泮片 2.5mg，po，qn×7天：抗焦虑、镇静，消除紧张情绪这一最常见诱因，同时改善睡眠。\n4. 谷维素片 20mg，po，tid×14天：调节自主神经功能，减轻交感神经过度兴奋诱发的发作性出血与出汗。\n\n【一般治疗及生活指导】\n1. 休息：保证充足睡眠，避免熬夜、劳累；保持情绪平稳，避免紧张、焦虑、激动等情绪应激，情绪波动是本病最常见诱因。\n2. 饮食：清淡饮食，多食富含维生素C、维生素K的新鲜蔬果（柑橘、猕猴桃、番茄、菠菜等），忌辛辣刺激食物，少饮咖啡、浓茶，戒酒。\n3. 活动：适度进行散步、太极拳等舒缓运动以调节情绪；避免剧烈运动及桑拿、高温作业等高温环境，减少出汗、防止诱发发作。\n4. 禁忌：保持出血部位皮肤清洁干燥，勿搔抓、挤压、摩擦，防止继发感染；如正在服用阿司匹林、华法林等抗血小板或抗凝药物，应告知医生评估，勿自行增减。\n\n【随诊要求】\n1. 用药7天后复诊，评估发作频率、出血量变化及药物疗效与不良反应，决定巩固或调整方案。\n2. 若出血量增多、发作频繁，或伴牙龈出血、皮肤瘀斑、鼻出血、黑便等全身出血倾向，应随时就诊，必要时行血常规、凝血功能、血小板功能及肝功能等检查，排查凝血功能障碍等基础疾病。\n3. 症状缓解后建议每月门诊随访1次，连访3个月，观察有无复发；反复发作或病因不明者转血液科进一步诊治。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":530,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"363bc4fd4f948243f51aff6ca4579869a13d4d0754d4c2db46c411099ee6abde","pinyin":"xuehanzheng","initials":"xhz","setting":"out","caseName":"门诊病历395","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历395",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-a0931fccd353cc3e2798","key":"v1-c9ccc21dfe2a3058|templates-a0931fccd353cc3e2798","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"无汗症","category":"门诊病历模板","raw":{"name":"无汗症","category":"门诊病历模板","case":{"case_name":"门诊病历396","templates":{"主诉":"皮肤无汗伴不耐热1周","现病史":"患者1周前无明显诱因出现无汗症相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者皮肤无汗伴不耐热1周、症状逐渐加重并伴轻度乏力，无汗症须先除外全身性疾病及药物性因素所致，完善血常规检查排除感染、贫血及血液系统疾病；查尿常规、便常规了解有无泌尿系及消化道慢性失血、感染等消耗性因素；患者既往虽体健，但无汗可继发于内分泌及代谢异常，查血糖了解有无糖尿病所致自主神经病变，完善肝肾功能检查排除肝肾功能不全，同时为后续用药安全性提供依据；查电解质检查排除电解质紊乱影响汗腺分泌功能；查血脂了解血脂水平，评估有无代谢综合征基础；行心电图检查排除心脏疾患所致代偿性出汗异常及心律失常；本次以不耐热为主要表现，查胸部X线片排除肺部感染、肺结核等慢性感染性疾病；行腹部超声了解肝胆胰脾及腹腔情况，排除腹腔脏器病变所致全身性因素；必要时完善甲状腺功能检查排除甲状腺功能异常所致汗腺分泌障碍，如疑汗腺本身病变可行皮肤活检明确诊断；对局限性无汗者必要时行发汗试验（如碘淀粉试验）了解汗腺功能及分布范围，以明确无汗系全身性抑或节段性病变，指导后续治疗；上述检查根据病情需要选择相应项目，病情稳定后定期复查，必要时请神经内科、内分泌科会诊。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 无汗症\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 营养神经、改善汗腺神经支配：甲钴胺胶囊0.5mg tid×4周；维生素B1片20mg tid×4周。\n2. 调节自主神经功能：谷维素片20mg tid×4周。\n3. 促汗治疗：可试用毛果芸香碱（匹罗卡品）5mg po tid，自小剂量开始，用药期间监测心率、血压及出汗反应；青光眼、哮喘、消化性溃疡及心血管疾病患者禁用。\n4. 继发性无汗症积极治疗原发病（如干燥综合征、糖尿病、甲状腺疾病等，遵相应专科方案），并停用可疑导致无汗的药物（如抗胆碱能药、三环类抗抑郁药、抗组胺药等）。\n【一般治疗及生活指导】\n1. 避免高温环境、剧烈运动及暴晒，夏季室内使用空调等降温措施，谨防中暑及高热危象；出汗功能恢复前避免高温作业。\n2. 每日温水淋浴保持皮肤清洁湿润，浴后及时涂抹润肤乳，防止皮肤干燥、皲裂及毛囊炎；穿宽松透气的棉质衣物。\n3. 适当增加饮水，每日保证1500～2000ml水分摄入；均衡饮食，忌辛辣刺激食物及大量饮酒。\n4. 禁忌：禁用热水浴、桑拿、汗蒸等强行发汗措施，避免使用电热毯；勿自行超量服用解热镇痛药强行退热。\n【随诊要求】\n建议每4周复诊1次，评估出汗功能恢复情况及药物耐受性；用药期间每4～8周复查血常规、肝肾功能。若出现发热、皮肤潮红、心悸、头晕、恶心等热相关症状应立即就诊。继发性无汗症患者需随原发病专科（风湿免疫科、内分泌科等）定期随访，动态调整治疗方案。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":531,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"a98f8104391dc5d26fcbdfd64e410e152a2dd09f0c701559fd549e5414df9baa","pinyin":"wuhanzheng","initials":"whz","setting":"out","caseName":"门诊病历396","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历396",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-fa22b0898a6571714eed","key":"v1-c9ccc21dfe2a3058|templates-fa22b0898a6571714eed","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"甲病","category":"门诊病历模板","raw":{"name":"甲病","category":"门诊病历模板","case":{"case_name":"门诊病历397","templates":{"主诉":"反复甲病相关不适1周，加重1天。","现病史":"患者1周前无明显诱因出现甲病相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者反复甲病相关不适1周、加重1天，并伴轻度乏力，甲病可为局部因素所致，亦可为全身性疾病在甲的表现，完善血常规检查排除贫血、感染所致甲床营养障碍；查尿常规、便常规了解有无泌尿系及消化道感染、慢性失血等全身消耗因素；甲板生长依赖正常营养与代谢状态，完善肝肾功能检查排除肝肾功能不全，并为后续药物治疗的安全性提供依据；查血糖了解有无糖尿病，糖尿病患者易并发甲周感染且甲生长缓慢；查血脂了解血脂水平，评估代谢状况；查电解质检查排除电解质紊乱所致甲营养不良；甲病可由周围循环及心脏疾病引起，行心电图检查排除心脏疾患；查胸部X线片排除肺部感染、肺结核等慢性感染；行腹部超声了解肝胆胰脾情况，排除腹腔脏器疾病所致全身性因素；疑甲真菌病者完善真菌镜检加培养明确有无真菌感染，必要时行甲单位活检或甲母质检查明确甲损害性质，指导后续用药及手术方案；上述检查根据病情需要选择相应项目，病情稳定后定期复查复诊。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 甲病\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 外用抗真菌药（甲真菌病首选，适用于病甲数少、感染表浅者）：5%阿莫罗芬甲搽剂，每周涂药1次，涂药前先用锉刀尽量锉薄病甲并清除甲屑，药液涂满整个甲板后待干形成药膜，指甲连用6个月、趾甲连用9~12个月；或8%环吡酮胺甲搽剂，每日涂药1次，疗程同上。\n2. 口服抗真菌药（病甲≥3个、甲根受累或外用无效者）：盐酸特比萘芬片250mg qd，餐后口服，指甲连用6~8周、趾甲连用12周；或伊曲康唑胶囊200mg bid，每月连服7天、停药21天为1个脉冲，指甲连用2个脉冲、趾甲连用3~4个脉冲。口服前及疗程中定期复查肝功能。\n3. 对症辅助治疗（甲营养不良、脆甲、甲板增厚粗糙）：10%尿素软膏每日1次涂于病甲，可封包过夜以软化增厚甲板，配合口服多维元素片（含生物素、锌）1片qd，疗程2~3个月。\n【一般治疗及生活指导】\n1. 保持手足清洁干燥，洗浴后彻底擦干指（趾）缝及甲周，避免长期浸水；每日更换棉质透气鞋袜，鞋袜洗净后阳光下晾晒或定期消毒。\n2. 正确修剪指甲：指甲剪平、勿剪得过短过深，避免剪伤甲沟及甲周皮肤；不与他人共用指甲剪、毛巾、浴巾、拖鞋等个人用品，修甲工具用后以75%酒精消毒。\n3. 避免指甲外伤及咬甲、撕扯甲周倒刺等不良习惯；女性避免长期涂抹指甲油及粘贴人造甲，以免影响甲板透气及药物渗透。\n4. 合并足癣（脚气）、体癣者应同时规范治疗，防止交叉感染及甲癣复发；规律作息、均衡饮食，适当补充优质蛋白与B族维生素，增强甲板抵抗力。\n【随诊要求】\n1. 外用及口服抗真菌药治疗期间每4~8周复诊1次，观察病甲生长及消退情况、评估局部不良反应（刺激、红肿等），必要时调整方案。\n2. 口服特比萘芬或伊曲康唑者，用药前及用药第4周复查肝功能；治疗期间出现乏力、食欲减退、恶心、皮肤巩膜黄染等应及时复诊，必要时停药。\n3. 疗程结束后复诊行真菌镜检及培养，确认病原菌转阴、新甲长出后再考虑停药；停药后继续随访3~6个月，出现病甲复发或新发甲损害时及时复诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":532,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"963ead7b2f122435663b8beb391cb725abda424f3c0625e0bf0a6cf8a6606c6f","pinyin":"jiabing","initials":"jb","setting":"out","caseName":"门诊病历397","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历397",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-62d17f916a1914fd5d5a","key":"v1-c9ccc21dfe2a3058|templates-62d17f916a1914fd5d5a","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"甲营养不良","category":"门诊病历模板","raw":{"name":"甲营养不良","category":"门诊病历模板","case":{"case_name":"门诊病历398","templates":{"主诉":"指趾甲变薄、易碎1周","现病史":"患者1周前无明显诱因出现甲营养不良相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者指趾甲变薄、易碎1周并伴轻度乏力，甲营养不良常继发于全身性疾病、营养障碍或局部血供异常，完善血常规检查排除贫血、感染及血液系统疾病所致甲床营养障碍；查尿常规、便常规了解有无泌尿系及消化道慢性失血、吸收不良等因素；甲板生长依赖正常蛋白合成与代谢，完善肝肾功能检查排除肝肾功能不全，并为后续用药安全性提供依据；查血糖了解有无糖尿病及糖代谢异常，糖尿病可致甲生长缓慢、易并发甲周感染；查血脂了解血脂水平，评估有无代谢紊乱；查电解质检查排除电解质紊乱所致甲生长异常；甲营养不良可与末梢循环障碍并存，行心电图检查排除心脏疾患及心律失常；查胸部X线片排除肺部感染、肺结核等慢性消耗性疾病；行腹部超声了解肝胆胰脾情况，排除腹腔脏器病变所致吸收障碍；疑甲真菌病者完善真菌镜检加培养排除浅表真菌感染，必要时查甲状腺功能、血清铁及铁蛋白排除甲状腺疾病、缺铁所致甲脆裂，如诊断仍不明确可行甲单位活检明确甲损害性质，指导治疗及随访；上述检查按病情需要选择，病情稳定后定期复查。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 甲营养不良\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 维生素及微量元素类（首选基础治疗）：复合维生素B片，口服，一次2片，一日3次；多维元素片（含锌、铁、钙等），口服，一次1片，一日1次；疗程3～6个月，随甲板再生周期调整。\n2. 氨基酸类（促进角蛋白合成）：胱氨酸片50mg，口服，一次2片（100mg），一日3次，疗程3～6个月。\n3. 外用角质软化及保湿剂：5%尿素软膏，温水浸泡患甲5～10分钟后涂于病甲及甲周皮肤，一日2次，长期使用，软化甲板、减少脆裂分层。\n4. 若真菌镜检阳性或伴甲患者肿，加用抗真菌外用制剂：联苯苄唑乳膏，涂患甲甲板及甲沟，一日1次，连用4周后复诊评估疗效。\n\n【一般治疗及生活指导】\n1. 避免咬甲、抠甲、过度修剪及甲周外伤，修剪指甲时勿剪得过短或损伤甲周皮肤，防止继发感染。\n2. 减少双手直接接触肥皂、洗涤剂、化学溶剂、染发剂等刺激性物质，做家务及接触化学品时佩戴橡胶手套。\n3. 均衡饮食，多食富含优质蛋白（蛋、奶、瘦肉、鱼虾）及维生素、锌等微量元素的食物（坚果、新鲜蔬果），纠正偏食；保持甲周滋润，每日外用保湿霜或凡士林。\n4. 积极排查并治疗原发病（如银屑病、扁平苔藓、斑秃、甲状腺疾病等），去除长期压迫、摩擦等诱因。\n\n【随诊要求】\n1. 每2～4周门诊复诊1次，评估甲板色泽、厚度、光泽及生长情况；指甲每月约生长3mm、趾甲约1mm，疗程一般需3～6个月，应坚持足疗程治疗，勿中途自行停药。\n2. 复诊时建议留存治疗前后患甲照片对比，便于客观评价疗效。\n3. 若治疗中出现甲患者肿、疼痛、脓性分泌物，或足疗程3个月后仍无任何改善，应及时复诊，进一步完善真菌镜检、甲组织病理等检查，排除甲真菌病、甲银屑病等继发性甲病。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":533,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"626d95bf91dbdf56b0a87da792b09e650ed4b9dc23a6782a1db80ad4c5082da7","pinyin":"jiayingyangbuliang","initials":"jyybl","setting":"out","caseName":"门诊病历398","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历398",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-c2856109250f9cec598e","key":"v1-c9ccc21dfe2a3058|templates-c2856109250f9cec598e","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"甲真菌病","category":"门诊病历模板","raw":{"name":"甲真菌病","category":"门诊病历模板","case":{"case_name":"门诊病历399","templates":{"主诉":"趾甲增厚、变色1年","现病史":"患者于1年前出现拇趾甲甲板增厚、变色（黄色/灰白色/褐色，浑浊）、失去光泽、甲下碎屑堆积（甲下角化，甲与甲床分离，即甲剥离）、甲板翘起不平；拇趾甲最常见，单甲起病渐累及多甲。分型为远端侧位甲下型（最常见，自甲缘向近端发展）、近端甲下型（甲半月处，免疫低下者如HIV）、浅表白甲型（甲板表面白斑，儿童）及全甲毁损型（晚期）。足癣/手癣（常并存，足癣为传染源）、糖尿病、外周血管病、免疫低下、穿不透气鞋、外伤史：均无。行走时疼痛/影响（嵌甲、压迫痛）。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P76次/分，R18次/分，BP120/80mmHg。双足拇趾甲板增厚、浑浊、呈黄褐色，甲下碎屑堆积，甲板与甲床分离（甲剥离）；受累范围以远端为主，共4个甲。足趾间及足底未见异常（无脱屑，未并存足癣）。甲周皮肤无红肿（排除甲沟炎）。","辅助检查":"【必做】甲屑真菌镜检（KOH涂片，甲下近端碎屑阳性率高，见菌丝/孢子即可确诊）、真菌培养（菌种鉴定（以毛癣菌为主）及药敏，作为治疗依据）；【鉴别】甲病鉴别（银屑病甲（点状凹陷/油滴）、扁平苔藓甲、甲外伤、甲营养不良，通过临床及镜检排除）；【影像】一般不必要；【其他】糖尿病/免疫状态评估（适用于反复/顽固感染者）。","初步诊断":"1. 甲真菌病（甲癣，远端侧位甲下型）\n（注：治疗原则为顽固病例需耐心及足疗程：①外用药（轻中度，甲板未累及甲根/近端<50%且≤3个甲）：阿莫罗芬搽剂（每周1次，涂后晾干，疗程：指甲6个月/趾甲9~12个月）或环吡酮搽剂（每日1次，疗程长）；可先锉薄病甲（去甲，提高渗透）；②口服抗真菌药（累及甲根/近端/多甲或外用药失败者）：特比萘芬250mg qd（指甲6周/趾甲12周，首选，需肝功能监测，对皮肤癣菌疗效好）或伊曲康唑（冲击疗法：0.2g bid，1周/月，趾甲3~4个冲击）；③联合治疗（外用药+口服，用于顽固病例）；④激光/拔甲（辅助治疗，激光疗效证据有限，严重变形/压迫痛者可考虑，手术拔甲少用）；⑤治疗并存足癣（防再感染，重要）、鞋袜消毒（抗真菌粉，鞋内）、穿透气鞋；⑥疗效评估（新甲长出，趾甲需9~12个月，真菌镜检转阴+外观恢复为治愈标准）；肝功能监测（口服抗真菌药者，用药前及疗程中）；老年/糖尿病患者评估风险收益（药物相互作用，伊曲康唑）；皮肤科随访。）","处理方案":"【药物治疗】\n1. 盐酸特比萘芬片 250mg qd 口服，指甲受累疗程6周，趾甲受累疗程12周（特比萘芬对皮肤癣菌杀菌作用强，为首选口服药）；\n2. 伊曲康唑胶囊 200mg bid 口服冲击疗法（每月服药1周、停药3周），指甲受累2个冲击，趾甲受累3-4个冲击，服药期间随餐或餐后即服以提高吸收；\n3. 外用抗真菌药（适用于浅表型、仅累及少数甲或不能耐受口服药者）：5%阿莫罗芬搽剂每周1次涂搽病甲，或8%环吡酮胺搽剂每日1次，疗程6-12个月，用药前先用锉刀锉薄病甲表面并清除甲屑；\n4. 合并手足癣者同时外涂硝酸咪康唑乳膏或联苯苄唑乳膏治疗足癣，防止再感染。\n\n【一般治疗及生活指导】\n1. 保持手足及甲周清洁干燥，洗浴后彻底擦干趾（指）缝及甲缘，避免长时间穿不透气鞋袜；\n2. 勤换鞋袜，袜子每日更换，鞋内定期喷洒抗真菌散剂，鞋袜在阳光下晾晒或定期煮沸、消毒液浸泡消毒；\n3. 不与他人共用拖鞋、浴巾、脚盆、指甲刀，浴室、泳池等公共场所注意足部防护；修剪病甲前先剪健康甲，病甲专用指甲刀单独存放并消毒，避免搔抓患甲引起自身接种扩散；\n4. 积极控制糖尿病、外周循环障碍等基础疾病，治疗期间戒烟，避免使用他人可能污染的修甲工具。\n\n【随诊要求】\n1. 口服抗真菌药（特比萘芬、伊曲康唑）治疗前及治疗期间每4周复查肝功能（ALT、AST、胆红素），肝功能异常者慎用并加强监测，出现黄疸、乏力等不适及时就诊；\n2. 治疗期间每1-2个月门诊复诊，观察新甲长出情况及病甲改善程度，评估依从性与疗效；\n3. 疗程结束后4周复查真菌镜检及培养，确认真菌学治愈；此后半年内如见甲板再次增厚、变色、浑浊，需及时复诊评估复发可能并调整方案。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":534,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"bcce0ba7f484d47c1bf30ef4ef53c5dd1ce7ae046b4d44fcc1c0cd03435716db","pinyin":"jiazhenjunbing","initials":"jzjb","setting":"out","caseName":"门诊病历399","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历399",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-09ea85533347eec6c6cc","key":"v1-c9ccc21dfe2a3058|templates-09ea85533347eec6c6cc","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"甲沟炎","category":"门诊病历模板","raw":{"name":"甲沟炎","category":"门诊病历模板","case":{"case_name":"门诊病历400","templates":{"主诉":"甲沟红肿、疼痛伴化脓5天","现病史":"患者于3天前在拇趾（趾甲内嵌刺入甲沟，为最常见原因）出现甲沟红肿、疼痛（搏动性跳痛，进行性加重），渐化脓（甲沟/甲下溢脓，黄色脓液），行走/触摸痛明显。急性甲沟炎多为细菌感染（金黄色葡萄球菌为主），一般无发热（部分患者可有低热）；慢性者表现为反复红肿溢脓、肉芽组织增生（常与念珠菌、潮湿职业（厨师/洗衣/糖厂工人）、免疫低下、嵌甲相关，多指受累）。既往无糖尿病（感染加重因素，反复发作者需筛查）。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.8℃，P88次/分，R20次/分，BP118/76mmHg。拇趾甲外侧甲沟红肿、压痛明显、可及波动感并见溢脓（脓液自甲沟挤出；甲下积脓时甲板下透见黄绿色脓液），甲周无肉芽组织增生（慢性者可见），趾甲呈嵌甲改变（甲缘刺入甲沟软组织），甲板无增厚、无变形（慢性者可见），区域淋巴结未及肿大（严重感染时可肿大），足背/趾端血运感觉正常。","辅助检查":"检查计划：患者5天前因趾甲内嵌刺入甲沟出现甲沟红肿、搏动性跳痛并进行性加重，渐至甲沟溢脓，行走及触摸痛明显，急性甲沟炎多为金黄色葡萄球菌感染，本病一般以临床诊断为主，无需常规辅助检查；本次已化脓并行切开引流，为明确致病菌及指导抗生素选择，完善脓液细菌培养加药敏试验，尤适用于反复发作、治疗无效或疑特殊感染（如假单胞菌所致绿甲，常见于热水浴、泳池接触者）者；患者反复感染或存在感染加重因素，查血糖检查排除糖尿病（反复感染者需常规筛查，糖尿病为感染加重及慢性化的重要因素，血糖控制对治疗至关重要）；病程迁延、反复红肿溢脓疑慢性甲沟炎者，完善真菌检查（甲周取材）排除念珠菌感染所致，慢性甲沟炎多与潮湿职业、免疫低下及嵌甲相关，常多指受累；必要时查血常规及CRP评估感染程度及有无全身炎症反应，发热、蜂窝织炎蔓延或免疫低下者及时评估；上述检查按病情需要选择，治疗后定期复查，并同时处理嵌甲、控制基础病，做好患指（趾）护理及健康教育。\n\n（检查清单）\n【必做】一般以临床诊断为主；【其他】脓液细菌培养+药敏（反复发作/治疗无效/疑特殊感染（假单胞菌，可致绿甲，常见于热水浴/泳池接触者））、血糖（反复感染/糖尿病筛查，重要）、真菌检查（慢性甲沟炎，念珠菌，甲周取材）。","初步诊断":"1. 甲沟炎（急性细菌性，拇趾，伴嵌甲）\n（注：①急性早期（未化脓）：温水浸泡（每日3~4次，可软化）、局部抗生素（莫匹罗星/夫西地酸软膏，bid）、抬高患肢；②化脓（波动感/甲下积脓）：切开引流（甲沟纵行切开排脓；甲下积脓者拔甲或部分拔甲（甲根受累时），需局部麻醉，由医生操作）；③全身抗生素（发热/蜂窝织炎蔓延/免疫低下/糖尿病者：头孢氨苄或阿莫西林克拉维酸5~7天）；④慢性甲沟炎：保持干燥（核心措施，慢性与潮湿相关）、避免接触水/化学刺激（戴手套）、抗真菌（念珠菌感染用咪康唑/克霉唑软膏）+弱效激素（炎症明显者用他克莫司，为非激素优选）、避免修甲过深；⑤嵌甲处理：正确修甲（平剪，不剪圆角）、棉垫/甲矫正器（轻中度）、严重/反复者行甲沟成形术或部分拔甲（含甲母质处理，防复发）；⑥治疗基础病（控制糖尿病）；⑦健康教育（穿宽松鞋、防倒刺咬甲，手部尤需注意）；甲沟炎处理不当可致慢性化/甲变形，早期正确处理并随访。）","处理方案":"【药物治疗】\n1. 口服抗菌药物：阿莫西林克拉维酸钾片0.625g bid×5天（青霉素过敏者改头孢呋辛酯片0.25g bid×5天，均需皮试或明确无过敏史后使用）。\n2. 局部抗感染：莫匹罗星软膏（百多邦）涂患甲患者肿处，bid，连用5～7天；或夫西地酸乳膏外用，tid。\n3. 局部消肿促脓：碘伏消毒后予鱼石脂软膏厚涂患处，qd，外覆纱布包扎，用至红肿消退或脓液引出。\n4. 疼痛明显者：布洛芬缓释胶囊0.3g bid×3天，餐后服用。\n\n【一般治疗及生活指导】\n1. 休息与体位：患肢抬高，减少站立行走，避免穿紧窄鞋袜挤压患趾，可穿前端宽松的拖鞋或凉鞋。\n2. 甲部护理：修剪指甲勿过短过深，两侧甲角保留根据患者具体情况制定个体化方案超出甲缘，不用锐器剔挖甲沟，勿撕扯甲周倒刺。\n3. 局部保护：保持患处干燥清洁，避免接触污水、洗涤剂等刺激物；有糖尿病者严格监测并控制血糖，如血糖控制不佳需内分泌科协同治疗。\n4. 禁忌：患处未愈期间禁止浸水、游泳、足浴，禁止自行挤压排脓，禁止剧烈运动或长时间负重行走。\n\n【随诊要求】\n1. 口服抗菌药物及局部用药3天后症状无缓解或红肿范围扩大、疼痛加重，应及时复诊。\n2. 出现甲下积脓或甲周脓肿形成（波动感阳性）者，需复诊行切开引流、甲下引流或部分拔甲术，术后每日换药至创面愈合。\n3. 反复发作或单次病程超过2周者，建议皮肤科或手足外科专科复诊，排查慢性甲沟炎及继发真菌感染（必要时真菌镜检），并评估是否需要外科治疗。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":535,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"c5bc14d3b4dce72881cf75b737ea770dc9d4bdaf02a29a1babf6d683375de91d","pinyin":"jiagouyan","initials":"jgy","setting":"out","caseName":"门诊病历400","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历400",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-6562ef036fdf3e1a9399","key":"v1-c9ccc21dfe2a3058|templates-6562ef036fdf3e1a9399","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"甲下出血","category":"门诊病历模板","raw":{"name":"甲下出血","category":"门诊病历模板","case":{"case_name":"门诊病历401","templates":{"主诉":"甲板暗褐色斑片1周","现病史":"患者于7天前在拇趾甲出现甲下暗红至黑褐色斑片（甲下出血，即甲板下瘀血），可伴轻度胀痛（甲下张力增高），渐随甲生长向远端移动。有明确外伤史（挤压/砸伤、运动鞋过紧（跑步者趾甲，即长跑黑甲）、穿高跟鞋，多见于趾甲）。无自发性出血倾向：无出血性疾病及抗凝药（华法林/阿司匹林/氯吡格雷）使用史，无血小板减少；自发性者无明确外伤，需与甲下黑素瘤鉴别（纵向黑色条纹/甲黑线为恶变征象，需警惕）。无甲患者肿（鉴别甲沟炎）。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.7℃，P80次/分，R18次/分，BP116/74mmHg。拇趾甲板下可见暗红色斑片（甲下出血，边界清，距甲根/甲半月有一定距离，近端边缘随甲生长移动），压之不变色（区别于甲下血管球瘤的点状压痛），甲板无增厚、无变形（排除甲真菌病/黑素瘤；甲黑线表现为纵行色素带、宽度不规则或累及甲周皮肤（Hutchinson征），为恶变征象）。","辅助检查":"【必做】一般以临床诊断为主（外伤史+典型外观）；皮肤镜检查（甲下出血表现为红色/黑色均质区域、近端边缘清晰并随甲移动，为良性特征；与甲下黑素瘤鉴别：黑素瘤可见纵向不规则色素条纹、假性Hutchinson征及线条状/网格状色素等微观结构，为皮肤镜关键鉴别点）；【其他】出血倾向评估（自发性/多甲出血/易瘀斑者查血常规血小板、凝血功能）、抗凝药评估、随访观察（出血斑随甲生长移动消退，需2~6个月；若黑斑不随甲移动、扩大或出现色素条纹，应排查甲下黑素瘤并行活检）。","初步诊断":"1. 甲下出血（拇趾甲，外伤性）\n（注：①外伤性甲下出血多可自行吸收（随甲生长移出，趾甲需6~9个月，指甲3~4个月），无需特殊治疗，告知自然病程（避免反复就诊，随访观察即可）；②疼痛明显（甲下张力大，急性大出血时甲下积血胀痛剧烈）者行甲下钻孔引流（无菌针头灼孔/钻孔，减压止痛，由医生操作，宜在48小时内）；③排除甲下黑素瘤（关键，尤其无外伤史、单甲纵向黑条纹、色素不规则、累及甲周皮肤（Hutchinson征）、发生于指甲（非趾甲，趾甲外伤更常见）、黑斑不随甲移动者：行皮肤镜检查，可疑者行甲活检（甲单位活检，组织病理确诊））；④评估出血倾向（自发性/多处出血者查血小板、凝血功能，评估是否停用抗凝药，必要时血液科会诊，较少见）；⑤预防（运动鞋合脚（防跑步黑甲）、防挤压外伤）；皮肤科随访，必要时皮肤镜动态观察（3个月复查，观察出血斑移动情况）。）","处理方案":"【药物治疗】\n1. 镇痛：布洛芬缓释胶囊（如芬必得）0.3g bid po，疼痛明显时服用，一般连用3-5天；疼痛轻微者可不服用。\n2. 破伤风预防：外伤所致且皮肤破损或伤口污染者，予破伤风抗毒素（TAT）1500IU im（皮试阴性后）或破伤风人免疫球蛋白250IU im，一次性注射。\n3. 预防感染：甲板破损或已行甲板钻孔引流者，局部外用莫匹罗星软膏涂于患甲及甲周，bid，连用3-5天；若出现甲患者肿、脓性分泌物等感染征象，加用头孢呋辛酯片0.25g bid po×5天（头孢菌素过敏者改用阿奇霉素片0.5g qd po×3天）。\n\n【一般治疗及生活指导】\n1. 伤后24-48小时内局部冷敷（每次15-20分钟，每日3-4次），以减少继续出血及肿胀；48小时后改为热敷，促进淤血吸收。\n2. 抬高患肢，适当制动休息，避免患指（趾）用力负重及剧烈运动；穿宽松鞋袜，避免挤压患甲，防止血肿扩大。\n3. 血肿面积超过甲面1/3或疼痛呈\"跳痛\"剧烈者，建议行甲板钻孔引流减压，减压后疼痛多明显缓解。\n4. 保持患部清洁干燥，避免沾水、涂指甲油遮盖，防止继发感染；戒烟（尼古丁收缩血管，影响愈合）。\n\n【随诊要求】\n1. 治疗后1周复诊，评估血肿吸收及愈合情况。\n2. 若出现甲患者肿加重、持续跳痛、发热或脓性分泌物等感染征象，或出血不止，应随时就诊。\n3. 血肿较大或已行引流减压者，注意观察甲板有无变色、松动或脱落；新生指甲完全替换约需3-6个月，若出现甲板变形、纵嵴或反复甲沟炎，应于1-3个月后复诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":536,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"140f54d261da5c0ba7611407f8522bfd86f482b57dc4bf080e014e0f6e4abf41","pinyin":"jiaxiachuxie","initials":"jxcx","setting":"out","caseName":"门诊病历401","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历401",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-6a38322d11bfe12eb949","key":"v1-c9ccc21dfe2a3058|templates-6a38322d11bfe12eb949","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"黏膜白斑","category":"门诊病历模板","raw":{"name":"黏膜白斑","category":"门诊病历模板","case":{"case_name":"门诊病历402","templates":{"主诉":"口腔黏膜白色斑块6月","现病史":"患者有吸烟史（吸烟为口腔白斑最重要危险因素）于3月前在颊黏膜（咬合线处，为口腔白斑最常见部位）发现白色斑块，不能刮除（区别于可刮除的鹅口疮），无症状或仅有粗涩感，渐增大或多发。危险因素：吸烟（最重要，戒烟后部分白斑可消退）；无饮酒、槟榔（可致口腔黏膜下纤维化伴白斑）、假牙摩擦/锐利牙尖刺激（摩擦性角化，属良性）、口腔念珠菌（白斑可合并）、人乳头瘤病毒感染及糖尿病/免疫低下。外阴白斑多见于女性，可伴硬化性苔藓（萎缩性、瘙痒，恶变风险低），本例未见外阴受累。无破溃、出血、疼痛（溃疡/硬结/迅速增大为恶变警示，需活检）。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.6℃，P76次/分，R18次/分，BP120/78mmHg。口腔颊黏膜（咬合线处；舌腹、口底为高危部位）可见白色斑块，边界清，表面光滑，不能刮除，大小约1.0cm×0.8cm；无红白相间改变（红斑型/增殖型恶变风险更高）；触诊质地柔软（硬结提示浸润，为恶变征象）。无糜烂、溃疡（糜烂溃疡为恶变征象）。外阴未见白色斑块（外阴白斑可呈萎缩或增厚）。","辅助检查":"【必做】口腔黏膜病专科检查及活检（关键：任何白斑，尤其高危部位（舌腹/口底/软腭）、非均质型（疣状/颗粒状/红斑型）、硬结/溃疡/迅速增大者，活检排除癌变及异型增生，病理确诊）；【筛查】念珠菌镜检培养（白斑伴念珠菌，抗真菌后部分消退）、HPV检测（口腔，低相关，外阴相关）；【随访】定期口腔黏膜复查（白斑随访：均质型无异型增生，每6~12个月复检，出现变化即再活检）；【相关】戒烟戒酒评估、糖尿病筛查。","初步诊断":"1. 黏膜白斑（口腔黏膜白斑/外阴白斑，伴/不伴异型增生，待病理）\n（注：①去除刺激（核心）：戒烟（最重要，可致部分消退）、限酒、停槟榔、修复假牙/锐利牙尖（去除摩擦因素，观察4周，部分为摩擦性角化，可消退）；②活检评估（所有非均质型/高危部位/可疑者，病理，异型增生分级）；③轻度异型增生：去除刺激后观察（3~6个月复查，仍存，再评估/激光冷冻切除）；中重度异型增生/原位癌：完全切除（激光/手术切除，密切随访，恶变风险高）；浸润癌：按口腔癌治疗（手术±放化疗，转口腔颌面外科/肿瘤科）；④均质型无症状：观察随访（每6~12个月，口腔黏膜专科）；健康教育（自我观察：溃疡/硬结/增大，及时就诊）；⑤外阴白斑：硬化性苔藓（强效激素外用：氯倍他索），萎缩者定期随访（外阴癌风险，低但需监测）；⑥念珠菌相关：抗真菌治疗；随访（恶变率：口腔白斑约5~17%，长期随访重要，专科管理。）","处理方案":"【药物治疗】\n1. 维A酸类（首选）：0.05%维A酸乳膏，取适量涂布白斑患处，每日1次（睡前涂抹），疗程4~8周；对角化明显或范围较大者，可口服异维A酸胶囊10mg，每日2次，疗程8~12周，用药期间监测肝肾功能及血脂，育龄期女性用药期间及停药后1个月内避孕。\n2. 维生素A：维生素A胶丸2.5万U，每日1次口服，疗程4~8周，可配合维生素E同服以减轻毒性、增强疗效。\n3. 维生素E：维生素E胶丸0.1g，每日2次口服，疗程8~12周，抗氧化辅助治疗，防止病变进展。\n4. 复合维生素B：复合维生素B片2片，每日3次口服，疗程4周，促进口腔黏膜代谢与修复。\n\n【一般治疗及生活指导】\n1. 戒烟、戒酒，忌嚼槟榔，消除口腔不良刺激：调磨锐利牙尖、拔除残根残冠、修整不良修复体，避免机械性摩擦诱发或加重白斑。\n2. 饮食宜清淡温软，多食富含维生素A、β-胡萝卜素及维生素E的食物（胡萝卜、番茄、蛋黄、动物肝脏、深绿色蔬菜），忌过烫、辛辣及粗糙坚硬食物刺激患处。\n3. 保持口腔清洁，饭后漱口，早晚正确刷牙，避免使用刺激性强的含醇漱口水；发现白斑处糜烂、破溃时避免用力刷洗。\n\n【随诊要求】\n1. 每3~6个月复诊1次，重点观察白斑范围、厚度及形态变化；疣状、颗粒状及糜烂溃疡型白斑建议手术切除并送病理检查。\n2. 随访中出现以下情况须立即复诊并行病理活检：白斑面积增大、增厚、出现糜烂、溃疡、出血、疼痛或疣状结节突起。\n3. 口服维A酸者每4~8周复查肝功能、血脂；局部用药刺激明显者调整涂药频次并复诊评估。\n4. 局部药物治疗3个月无好转或反复复发者，转口腔颌面外科评估手术切除，术后继续定期随访观察。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":537,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"eb5f4f7bd29a4ae77e0aac75717dfee4ab770151ac686a4c8e992f88e568df86","pinyin":"nianmobaiban","initials":"nmbb","setting":"out","caseName":"门诊病历402","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历402",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-9cbfb01ba67bbc2bec9d","key":"v1-c9ccc21dfe2a3058|templates-9cbfb01ba67bbc2bec9d","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"口腔扁平苔藓","category":"门诊病历模板","raw":{"name":"口腔扁平苔藓","category":"门诊病历模板","case":{"case_name":"门诊病历403","templates":{"主诉":"颊黏膜白色网状条纹6月","现病史":"患者于6月前在口腔双颊黏膜（白色网状条纹（Wickham纹）对称分布，为最常见表现，亦可累及舌/牙龈/唇）出现白色网状或树枝状条纹，伴糜烂（红斑糜烂型，疼痛明显，进食辛辣热刺激加重），伴粗糙感及灼痛。无萎缩、水疱。无明显精神紧张/压力（常见诱因）、口腔金属修复体（汞合金可致苔藓样接触反应）、可疑药物（NSAIDs/ACEI等可致苔藓样药疹）、丙型肝炎感染（口腔扁平苔藓与丙肝相关）、糖尿病及吸烟饮酒史。皮肤无紫红色丘疹（约1/4患者并存皮肤扁平苔藓，多见于四肢屈侧）。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.7℃，P78次/分，R18次/分，BP118/76mmHg。口腔双颊黏膜可见白色网状条纹（Wickham纹）对称分布，并见红斑基础上的糜烂面，周围有白色条纹（糜烂型）；舌、牙龈未见受累。口腔卫生尚可。牙科修复体：无金属冠（金属冠可与皮损对应）。皮肤未见紫红色扁平丘疹（四肢屈侧为并存皮肤扁平苔藓的常见部位，需评估）。","辅助检查":"【必做】临床诊断为主（典型白色网状条纹）；【确诊】口腔黏膜活检（病理：表皮角化过度、基底细胞液化变性、真皮带状淋巴细胞浸润，诊断及排除恶变，尤其糜烂型，长期糜烂型有恶变风险（约1%））；【筛查】丙肝抗体（口腔扁平苔藓，丙肝相关，我国应查）、血糖（糖尿病相关）；【其他】斑贴试验（疑牙科金属过敏，苔藓样接触反应）。","初步诊断":"1. 口腔扁平苔藓（糜烂型，不伴皮肤受累）\n（注：①无症状网状型可观察随访（无需治疗，6~12个月口腔科复查）；②糜烂型/症状明显者：局部糖皮质激素（曲安奈德口腔软膏涂患处 bid~tid，或0.1%地塞米松含漱液，控制糜烂）、他克莫司0.1%软膏（激素疗效不佳或需长期使用时，无萎缩副作用）、糜烂严重者短期系统激素（泼尼松20~30mg/d×1~2周）；③避免刺激（辛辣热食、烟酒、精神紧张，注意减压）；④处理相关因素（治疗丙肝、控制血糖、更换可疑金属修复体，适用于接触反应者）；⑤长期随访（糜烂/萎缩型有口腔癌风险（约1%），每6~12个月口腔黏膜专科复查，出现溃疡不愈/硬结/增生时及时活检）；⑥维护口腔卫生、避免过度刷牙损伤；由口腔科（黏膜专科）管理。）","处理方案":"【药物治疗】\n1. 醋酸地塞米松粘贴片（0.3mg/片）：每次1片贴于糜烂或充血病损处，tid，饭前贴敷，疗程2～4周；或以0.1%曲安奈德口腔软膏涂布患处，bid～tid，疗程2～4周，症状缓解后逐渐减量至停药。\n2. 0.1%他克莫司软膏：涂布病损处，bid，适用于糜烂型、激素疗效不佳或需长期控制者，疗程4～8周，注意局部烧灼感及停药后反弹，用药后勿立即进食饮水。\n3. 复方氯己定含漱液（0.05%）：每次10ml含漱1分钟，bid，餐后使用，用于控制继发感染、保持口腔清洁，伴糜烂或继发感染者尤为适用，疗程1～2周，长期使用需防牙面着色。\n4. 辅助治疗：甲钴胺片0.5mg tid口服，配合维生素E胶丸100mg bid口服，疗程4～8周，辅助促进黏膜修复、缓解神经性不适；糜烂面积大、症状重者可短期口服泼尼松（30～40mg/d，晨顿服，渐减量），患者医生指导下进行，门诊不常规首选。\n\n【一般治疗及生活指导】\n1. 饮食：清淡软食，避免辛辣、过烫、过硬及粗糙刺激性食物（辣椒、酒精、浓茶、咖啡、坚果、油炸食品等），减少对病损黏膜的物理和化学刺激。\n2. 口腔卫生：使用软毛牙刷轻柔清洁，保持口腔卫生；定期洁牙，去除牙结石、锐利牙尖、不良修复体及金属冠等局部刺激因素，消除诱发诱因。\n3. 生活方式：戒烟限酒，规律作息、避免熬夜，保持情绪稳定、减轻精神压力和焦虑（精神紧张为常见诱发及加重因素）；糜烂明显时避免牙刷直接摩擦病损区。\n4. 避免长期自行使用市售含激素漱口液或含片刺激黏膜，禁用热水烫洗或强刺激药物局部涂抹。\n\n【随诊要求】\n1. 糜烂型或症状明显者：治疗后2～4周复诊，评估疗效并调整方案；症状缓解后每1～3个月复诊1次。\n2. 病损长期不愈、局部增厚、糜烂加重或出现新发溃疡者：应尽快复诊，必要时行活检病理检查以排除恶变。\n3. 本病有低度恶变倾向，建议每3～6个月定期复查1次并长期随访监测；停药后症状反复或复发者及时就诊，勿自行长期滥用激素类药物。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":538,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"dc38689af3d46a2636bffe5c834c05d0f36a261e97aface860458982468075ac","pinyin":"kouqiangbianpingtaixian","initials":"kqbptx","setting":"out","caseName":"门诊病历403","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历403",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-17342a8073c4c2db81ba","key":"v1-c9ccc21dfe2a3058|templates-17342a8073c4c2db81ba","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"复发性阿弗他溃疡","category":"门诊病历模板","raw":{"name":"复发性阿弗他溃疡","category":"门诊病历模板","case":{"case_name":"门诊病历404","templates":{"主诉":"口腔溃疡反复发作3年","现病史":"患者于2年前开始口腔黏膜反复出现溃疡（复发性阿弗他溃疡，为最常见口腔溃疡类型），每次1~2个，好发于唇内侧及颊黏膜（非角化黏膜），呈圆形/椭圆形、中央凹陷、覆黄白色假膜、周围红晕、疼痛明显（进食说话加重），持续约10天（轻型7~14天愈合），反复发作，每月约1次。分型属轻型（最常见，直径<10mm，不留瘢痕；重型大而深、>10mm，愈合慢且留瘢痕；疱疹样型小而多，可达数十个）。诱因：精神紧张/睡眠不足、进食辛辣等；无口腔外伤、维生素缺乏、食物过敏及免疫因素（女性需注意月经期因素）。无生殖器溃疡、眼炎、关节痛（反复口腔溃疡伴其他系统表现者需筛查白塞病），无发热。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.6℃，P78次/分，R18次/分，BP118/76mmHg。口腔唇内侧及颊黏膜可见2个圆形/椭圆形溃疡（直径约5mm，中央凹陷、覆黄白色假膜、周围红晕、触痛明显），无深大溃疡（重型者可见），口腔卫生及牙体未见锐利牙尖及不良修复体（刺激因素评估），外阴未见溃疡（白塞病筛查，必要时检查）。","辅助检查":"【必做】以临床诊断为主；【鉴别检查】血常规（排除贫血/粒细胞缺乏，适用于反复重症者）、维生素B12/叶酸/铁蛋白（营养缺乏，适用于反复发作者）、自身抗体（疑白塞病/系统性红斑狼疮，适用于反复口腔溃疡+眼/生殖器/皮肤/关节症状者）、HIV（不典型/顽固性溃疡，适用于免疫低下者）；【确诊】活检（溃疡>3周不愈/形态不典型/疑恶变，排除癌性溃疡，老年单发溃疡尤为重要）。","初步诊断":"1. 复发性阿弗他溃疡（轻型）\n（注：①局部治疗（缓解疼痛、促进愈合）：含漱（康复新液/氯己定漱口液，短期）、局部麻醉止痛（利多卡因凝胶，进食前）、糖皮质激素局部（曲安奈德口腔软膏，涂溃疡面，促进愈合）、重组人表皮生长因子凝胶、西瓜霜/冰硼散（中药）；②全身治疗（反复/重症者，减少复发）：秋水仙碱0.5mg bid（有效，可有腹泻副作用）、沙利度胺（重型难治者，强效，须严格避孕及神经监测，专科使用）、羟氯喹、维生素B族/叶酸/补铁（缺乏者补充可减少复发）；③去除诱因（保证睡眠、减压、避免辛辣烫食及口腔外伤、纠正不良修复体）；④鉴别并处理系统病（白塞病转免疫抑制专科；营养缺乏者予补充）；⑤随访（反复发作者行病程管理，多数轻型自限，予安慰及健康指导；老年新发单发溃疡>3周不愈者活检排除癌变）。）","处理方案":"【药物治疗】\n1. 局部糖皮质激素（首选，抗炎促愈）：曲安奈德口腔软膏0.1%适量涂于溃疡面，bid×5～7天，涂后暂不饮水进食；或醋酸地塞米松粘贴片1片贴敷于溃疡处，qd～bid×3～5天。\n2. 局部止痛（疼痛明显影响进食时）：利多卡因凝胶2%于餐前涂布溃疡处，每次少量（≤2cm），tid，用后1小时内勿进食过热食物。\n3. 消毒防腐含漱：0.05%氯己定含漱液10ml含漱1～2分钟，bid×7天，于饭后及睡前使用。\n4. 促进愈合：重组人表皮生长因子凝胶（贝复新）涂布溃疡面，tid×5～7天，可与糖皮质激素软膏交替使用。\n【一般治疗及生活指导】\n1. 休息：保证充足睡眠，规律作息，避免熬夜、精神紧张及过度劳累，学会压力管理。\n2. 饮食：均衡营养，适当补充维生素B族、维生素C及锌、铁等微量元素；忌辛辣、过烫、过硬及酸性刺激性食物，戒烟限酒，少食坚果、巧克力、咖啡等可能诱发溃疡的食物。\n3. 口腔护理：保持口腔清洁，每日刷牙2次，使用软毛牙刷；及时处理龋齿锐缘、不良修复体等创伤因素，避免损伤口腔黏膜。\n4. 活动：正常生活活动，避免剧烈摩擦口腔黏膜的运动；若明确与特定食物或药物相关，注意规避。\n【随诊要求】\n1. 溃疡多在7～14天内愈合；若单个溃疡超过3周不愈、面积增大或数目明显增多，应尽快复诊，必要时行活检排除癌变。\n2. 发作频繁（如每月≥2次）或溃疡重型/疱疹样型者，建议1～2周内复诊评估并调整维持治疗方案。\n3. 若伴生殖器溃疡、眼部及关节症状，或伴长期腹泻、发热等全身表现，建议转口腔黏膜病专科及风湿免疫科进一步排查白塞病、炎症性肠病等系统性疾病。\n4. 局部糖皮质激素使用5～7天后症状无缓解或出现继发感染（疼痛加重、红肿溢脓）者，及时复诊调整用药。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":539,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"7709caa3f4e6e0d9abd17dafa8091f336ce840345be5c4edbc4cdb455e9580a9","pinyin":"fufaxingafutakuiyang","initials":"ffxaftky","setting":"out","caseName":"门诊病历404","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历404",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-1cf39efca5d4ed4cb784","key":"v1-c9ccc21dfe2a3058|templates-1cf39efca5d4ed4cb784","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"白塞病","category":"门诊病历模板","raw":{"name":"白塞病","category":"门诊病历模板","case":{"case_name":"门诊病历405","templates":{"主诉":"反复口腔溃疡、外阴溃疡3年","现病史":"患者于3年前开始反复口腔溃疡（复发性，每年≥3次，为最常见首发症状）、外阴溃疡（疼痛性，见于阴囊/阴唇，愈合后留瘢痕）、眼部炎症（葡萄膜炎，表现为红眼、痛、畏光、视力下降，复发性，可致盲，属严重表现）、皮肤损害（结节性红斑（小腿）、假性毛囊炎、痤疮样疹）、针刺反应（皮肤针刺/注射后出现红肿脓疱，为白塞病特征及诊断标准之一）。无关节痛（膝踝关节，非侵蚀性）、无血管受累（深/浅静脉血栓、动脉瘤，属严重情况）、无神经系统受累（头痛、偏瘫、脑干症状，即神经白塞，预后差，属严重情况）、无消化道受累（溃疡、腹痛便血，即肠白塞）、无附睾炎。HLA-B51阴性，无家族史。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T37.2℃，P86次/分，R18次/分，BP120/78mmHg。口腔黏膜可见2个溃疡（位于颊黏膜及舌缘）；外阴可见溃疡及愈合后瘢痕；眼部见结膜充血及前房积脓（虹膜睫状体炎），眼底检查见葡萄膜炎/视网膜血管炎改变，视力下降；皮肤见小腿结节性红斑及假性毛囊炎；针刺反应试验（前臂针刺后24~48小时）阳性（+），可见红肿脓疱；关节无肿痛；神经系统及腹部查体未见异常（受累时可出现偏瘫/腹压痛）。","辅助检查":"【必做】针刺反应试验（皮肤针刺反应，特异性较高，诊断支持）；【实验室】血常规、血沉、CRP（活动指标）、HLA-B51（支持诊断，非必需）、抗核抗体（阴性，排除SLE）、肝肾功能、尿常规；【受累评估】眼科（裂隙灯+眼底+荧光血管造影：葡萄膜炎、视网膜血管炎，核心，防盲）、头颅MRI（神经系统症状：神经白塞）、血管超声/CTA（血管受累）、胃肠镜（消化道症状：肠白塞，溃疡）；【病理】皮肤/黏膜活检（血管炎，不典型时）。","初步诊断":"1. 白塞病（眼型；伴口腔、外阴及皮肤损害，活动期）\n（注：治疗依受累系统分层（多学科协作，由风湿免疫科牵头）：①黏膜皮肤/关节（轻症）：秋水仙碱0.5mg bid（口腔溃疡/结节性红斑，一线）、局部激素（口腔用曲安奈德软膏）、糖皮质激素短程（皮肤损害重者）；②眼受累（葡萄膜炎，严重，需防盲）：糖皮质激素（泼尼松1mg/kg/d）+免疫抑制剂（硫唑嘌呤/环孢素，一线联合）、生物制剂（肿瘤坏死因子抑制剂，如英夫利昔单抗，用于难治性眼/神经/血管受累，重要）、干扰素α（眼）；③血管型（血栓者抗凝+免疫抑制；动脉瘤者免疫抑制+介入/手术，属严重情况）；④神经型：大剂量激素冲击+免疫抑制（环磷酰胺），预后差，需积极治疗；⑤肠白塞：美沙拉嗪/激素/免疫抑制/英夫利昔单抗（与炎症性肠病治疗相似）；⑥随访（多系统受累者定期眼科/神经/血管评估，控制炎症以防器官损害；复发常见，需长期管理）；由皮肤科/眼科/神经科/消化科协作。）","处理方案":"【药物治疗】\n1. 秋水仙碱片 0.5mg bid po（餐后服用）：为口腔溃疡、生殖器溃疡及结节性红斑的一线首选药物，疗程3~6个月，症状缓解后根据患者具体情况制定个体化方案减量维持，注意腹泻、恶心等胃肠道反应及血细胞减少，肾功能不全者减量。\n2. 泼尼松片 0.5~1mg/kg/d（如30~40mg qd，晨起顿服）：用于急性活动期、严重眼炎、血管受累及神经系统受累者，症状控制后每1~2周递减5mg，逐渐减至最小维持量或停用，长期使用注意补钙、护胃及血糖血压监测。\n3. 硫唑嘌呤片 50mg bid po（1~2.5mg/kg/d）：用于中重度、复发频繁或激素依赖者，与激素联合可减少激素用量，用药前及用药期间每2~4周复查血常规、肝肾功能，警惕骨髓抑制及肝损伤。\n4. 沙利度胺片 50mg qn po（睡前顿服）：用于顽固性复发性口腔溃疡及结节性红斑，育龄期女性禁用（强致畸），注意监测周围神经病变，出现肢体麻木刺痛立即停药。\n【一般治疗及生活指导】\n1. 口腔护理：使用软毛牙刷，餐后以生理盐水或复方氯己定含漱液漱口，避免进食辛辣、过热、过硬及带壳坚果等易损伤口腔黏膜的食物，减少溃疡复发。\n2. 规律作息、避免劳累与熬夜，注意保暖、预防上呼吸道感染，感染及精神紧张均可诱发或加重病情。\n3. 戒烟限酒，吸烟与血管受累及血栓事件相关；保持皮肤清洁干燥，避免挤压毛囊炎样皮损及注射部位反复穿刺。\n4. 眼部受累者注意用眼卫生、避免长时间用眼及强光刺激，外出佩戴太阳镜；日常适度活动，避免剧烈运动及外伤。\n【随诊要求】\n1. 活动期每2~4周复诊1次，稳定期每1~3个月复诊1次，评估口腔溃疡、皮损及全身症状控制情况。\n2. 每1~3个月复查血常规、肝肾功能、ESR、CRP；患者硫唑嘌呤等免疫抑制剂者每2~4周复查血常规及肝肾功能。\n3. 眼部受累者转诊眼科，每1~3个月行裂隙灯及眼底检查；疑血管受累者定期行血管超声或CTA/DSA评估。\n4. 若出现新发或增多溃疡、皮肤结节、发热、视力下降、眼红眼痛、头痛、胸痛、腹痛、下肢肿痛或血栓表现，立即就诊，不可自行停药或调整激素剂量。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":540,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"314160c5b86396d4373907334d6aa653ae38524e5adbaee4eaa6687f5f5bf1d6","pinyin":"baisaibing","initials":"bsb","setting":"out","caseName":"门诊病历405","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历405",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-af9a6a80cd29a00147ac","key":"v1-c9ccc21dfe2a3058|templates-af9a6a80cd29a00147ac","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"皮肤肿瘤","category":"门诊病历模板","raw":{"name":"皮肤肿瘤","category":"门诊病历模板","case":{"case_name":"门诊病历406","templates":{"主诉":"皮肤肿物1周","现病史":"患者1周前无明显诱因出现皮肤肿瘤相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者皮肤肿物1周并伴轻度乏力，皮肤肿物需先鉴别感染性、过敏性及肿瘤性病变，完善血常规检查排除感染、贫血及血液系统疾病；查过敏原检测排除湿疹、接触性皮炎等变态反应性皮肤病所致皮损；查真菌镜检加真菌培养排除体癣、孢子丝菌病等浅表真菌感染所致类似皮损；行皮肤镜检查观察皮损色素结构、血管形态及有无溃疡，协助判断病变良恶性并指导是否需活检；对性质不明、短期增大或伴溃疡出血的皮损，完善皮肤活检（必要时）送组织病理检查以明确诊断，为皮肤肿瘤诊断的金标准；疑自身免疫性大疱性皮肤病者行免疫荧光检查排除天疱疮、大疱性类天疱疮；疑变应性接触性皮炎者行斑贴试验明确致敏原；皮损表现不典型、疑二期梅毒疹等性传播疾病者，行性病相关检测（必要时）明确病因；如病理证实为恶性肿瘤，进一步行血常规、肝肾功能及胸部X线片或CT等检查评估有无远处转移及手术耐受性；上述检查按病情需要选择，确诊后定期复诊随访。\n\n（检查清单）\n【必做检查】\n血常规、过敏原检测、真菌镜检+培养\n\n【影像学检查】\n皮肤镜、皮肤活检（必要时）\n\n【其他检查】\n免疫荧光、斑贴试验、性病相关检测（必要时）","初步诊断":"1. 皮肤肿瘤\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 疑诊或确诊皮肤恶性肿瘤（基底细胞癌、鳞状细胞癌、黑色素瘤等）者，首选外科扩大切除术，术后依据病理结果决定是否行放疗、靶向或免疫等进一步治疗；门诊术前无需常规预防性抗感染治疗。\n2. 表浅型基底细胞癌、鲍温病等不宜或不愿手术者，可选用5%咪喹莫特乳膏，隔日1次（每周3次），睡前薄涂于皮损处并保留6～10小时后清洗，连续16周。\n3. 日光性角化、皮角等癌前病变：5%氟尿嘧啶乳膏，每日1～2次外用，薄涂于皮损，连用4周，注意局部红肿、糜烂等反应。\n4. 手术切除术后创面较大或污染较重者：头孢呋辛酯片0.25g bid口服，共3～5天预防感染；术后疼痛明显者予布洛芬缓释胶囊0.3g bid饭后口服，必要时连用3～5天。\n【一般治疗及生活指导】\n1. 严格防晒：避免10:00～16:00时段外出，外出戴宽檐帽、穿长袖衣并涂抹SPF≥50、PA+++的广谱防晒霜，每2～3小时补涂1次，减少紫外线损伤、预防新发与复发。\n2. 避免反复摩擦、搔抓、挤压或烧灼皮损（色素痣、赘生物等），禁止使用药水点痣、偏方腐蚀等刺激处理，防止恶变或继发感染。\n3. 饮食清淡均衡，多食新鲜蔬菜水果，忌辛辣刺激食物及饮酒；保证充足睡眠，适当运动，戒烟，增强机体免疫力。\n4. 术后创面保持干燥清洁，按时换药，愈合前避免沾水及剧烈活动牵拉，直至拆线后创面完全愈合。\n【随诊要求】\n1. 术后患者按病理结果定期复诊：良性肿瘤术后1个月复诊1次评估创面愈合；恶性肿瘤术后第1年内每3个月复诊1次，第2年每6个月复诊1次，此后每年1次，重点检查局部有无复发及区域淋巴结情况。\n2. 局部药物治疗期间每4周复诊1次，评估疗效及局部红肿、糜烂等不良反应，必要时调整方案。\n3. 有多发色素痣、既往皮肤癌病史或黑色素瘤家族史者，建议每6～12个月行全身皮肤专科检查，新发或变化的皮损及时就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":541,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"b3f77b882800ff1b52b51dc92ccc1b54a4702d8a0673eae08c03dd256ae4ad35","pinyin":"pifuzhongliu","initials":"pfzl","setting":"out","caseName":"门诊病历406","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历406",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-f84094ea7a8ddc2a3aea","key":"v1-c9ccc21dfe2a3058|templates-f84094ea7a8ddc2a3aea","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"色素痣","category":"门诊病历模板","raw":{"name":"色素痣","category":"门诊病历模板","case":{"case_name":"门诊病历407","templates":{"主诉":"皮肤黑色素斑10年","现病史":"患者（色素痣（痣细胞痣，良性黑色素细胞增生；获得性痣多于儿童期出现，青少年期增多，20岁前多数已出现）、先天性痣（出生即有；大先天性色素痣>20cm为巨痣，有恶变风险（终身5~10%），需随访及评估预防性切除，重要）、发育不良（非典型）痣（不典型痣综合征者黑色素瘤风险显著升高；家族性非典型多发痣即黑色素瘤综合征）、多痣（>100个者黑色素瘤风险升高）、家族黑色素瘤/痣史）于10余年前发现色素痣（多年存在）就诊。色素痣外观：大小数毫米至1cm，颜色均匀（棕/黑），边界清晰规则，圆形/椭圆形，对称，略高出皮面，无症状。警示征象（恶变评估，ABCDE）：A不对称、B边缘不规则呈锯齿状、C颜色不均（黑褐/红/白/蓝混杂）、D直径>6mm、E变化（增大、隆起、颜色改变、出血、溃疡、痒、发炎、卫星灶，提示黑色素瘤可能，重要）；任何痣近期变化均需皮肤科评估。部位：掌跖/甲下/黏膜（黄种人肢端黑色素瘤（肢端雀斑样型）常见，重要；掌跖痣也需评估，但多数良性）、摩擦部位；无创伤后变化。鉴别：雀斑/脂溢性角化/蓝痣/晕痣。先天性痣（大小、巨痣）。家族史。多痣（数目、全身分布）。今日来我院皮肤科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.6℃，P76次/分，R18次/分，BP118/76mmHg。皮肤全面检查（全身痣计数、部位、大小、颜色、形态、边界、对称性、是否高出皮面）；警示征象（ABCDE特征）评估未见异常；无先天性痣/巨痣（>20cm）；无发育不良（非典型）痣（>5~6mm、颜色不均、边缘模糊不规则、中央高出皮面）；无卫星灶；掌跖/甲下痣未见异常；区域淋巴结未及肿大；已行全身皮肤照相（便于多痣随访对比）。","辅助检查":"【必做】皮肤镜（核心：痣放大观察（：色素网络规则：良性、黑色素瘤特征：结构不对称、色素网络破坏、蓝白幕、假性网络（面部）、退行结构、不规则点/球，评估良恶性，重要，初筛，随访）；【其他】皮肤照相（多痣，定期随访，对比，变化）、活检（切除活检（指征：ABCDE警示/不典型/增大/变化/诊断不明、手术完整切除送病理（痣细胞痣或黑色素瘤确诊金标准，重要）、不做切取/刮除部分活检（疑似黑色素瘤，防误诊及播散，重要）、巨痣/先天性痣（评估预防性切除或随访、照相、病理，依大小部位））；【随访】（多痣/非典型痣/家族史（定期皮肤科随访，每3~12个月全身皮肤检查、照相、黑色素瘤筛查、教育、自我检查ABCDE、新变化就医重要）。","初步诊断":"1. 色素痣（痣细胞痣，良性，获得性；全身数目及部位见上，已行ABCDE警示征评估以与黑色素瘤鉴别，暂无皮肤镜/活检指征）\n（注：治疗（多数良性，无需治疗）：①观察（典型良性痣、无症状且稳定者，告知良性、无需处理，定期自我观察，重要；随访，出现变化再评估）；②切除（指征：ABCDE警示征、近期变化、诊断不明、美容需求、摩擦部位反复刺激、巨痣评估后预防性切除）：手术完整切除（梭形切口，全层包括痣全部，切缘达正常皮肤，送病理，以病理确认良性痣或黑色素瘤，重要；勿用激光/冷冻去痣，以免不留病理且反复刺激带来潜在风险，重要，应到正规医院手术切除）；先天性巨痣应评估恶变风险，行手术分期切除/扩张器修复或随访（皮肤科/整形专科）；③黑色素瘤监测（不典型痣、多痣、有家族史者定期皮肤科随访，行皮肤镜/照相记录变化，以早期发现黑色素瘤，重要；进行自我检查教育（ABCDE，出现新痣或痣变化时及时就医，不要拖延）、注意防晒（减少日晒，预防新痣及恶变风险））；皮肤科对良性者观察，对具警示征者活检并切除送病理，以防漏诊黑色素瘤，重要。）","处理方案":"【药物治疗】色素痣首选治疗为手术完整切除+病理检查，药物用于术后创面处理与辅助治疗：1. 莫匹罗星软膏（百多邦）：术后创面薄涂，bid×5~7天，预防切口感染；2. 重组人表皮生长因子凝胶（易孚）：创面清洁后涂敷，qd~bid×7天，促进创面愈合；3. 拆线后创口愈合良好者，予硅酮凝胶（如疤克）：bid×3个月，预防瘢痕增生；4. 若创面出现红肿、渗液等感染征象，予夫西地酸乳膏（立思丁）bid×7天。\n【一般治疗及生活指导】1. 避免反复摩擦、搔抓、刺激痣体，严禁自行使用\"点痣水\"、激光、冷冻等不正规手段处理，以防刺激恶变或留疤；2. 严格防晒：外出涂SPF30+/PA+++以上防晒霜，避免暴晒，减少紫外线诱发色素改变；3. 术后创面保持干燥清洁，拆线前避免沾水及剧烈运动出汗，勿自行揭除敷料；4. 饮食清淡，忌辛辣刺激食物及饮酒，戒烟，保证充足睡眠。\n【随诊要求】1. 术后按期拆线：面部5~7天，躯干四肢7~10天；2. 术后组织病理报告回报后携报告复诊，明确痣体性质；3. 未切除的痣体建议每3~6个月自查一次，观察大小、颜色、形态变化，若短期内增大、颜色不均、边界不清、破溃出血、瘙痒或疼痛，及时就诊；4. 高危人群（多发性非典型痣、反复摩擦部位痣、家族性黑色素瘤病史）建议每年皮肤科专科检查。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":542,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"8e3b85652d1f91a9ff0ed69474755260a23440f40826eea2e119512c74479f0f","pinyin":"sesuzhi","initials":"ssz","setting":"out","caseName":"门诊病历407","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历407",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-16b83659a8df2f8bf899","key":"v1-c9ccc21dfe2a3058|templates-16b83659a8df2f8bf899","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"脂溢性角化","category":"门诊病历模板","raw":{"name":"脂溢性角化","category":"门诊病历模板","case":{"case_name":"门诊病历408","templates":{"主诉":"面部、躯干褐色疣状斑片5年","现病史":"患者为中老年人，于3年前开始面（颞部）、躯干、手背出现褐色/深褐色/黑色疣状斑片（脂溢性角化，即基底细胞乳头瘤，为良性肿瘤，非癌前病变），表面覆油腻性鳞屑、似贴附状（贴邮票样外观，为其特征），边界清，渐增大增多（数目随年龄增多），无自觉症状或有轻微痒（摩擦/刺激后）。无快速出现多发卫星样皮损（Leser-Trélat征：短期内爆发性增多，可伴内脏肿瘤，少见，需注意）；无表面破溃出血（瘙痒搔抓/摩擦后可致炎症，可自行消退或持续）。皮肤癌/日光性角化史：无。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P74次/分，R18次/分，BP126/78mmHg。面部（颞部）、躯干、手背可见10余个（多数）疣状/乳头瘤样斑片，大小0.2~3cm，褐色/深褐色/黑色，表面覆油腻性角化鳞屑，边界清，呈贴附状外观，皮纹存在，无浸润；无发炎、出血、破溃（刺激后可出现）；与周围皮肤分界清；皮肤镜见脑回状/沟脊样结构、粟粒样囊肿、粉刺样开口、边界锐利（特征性，可与黑色素瘤鉴别）。","辅助检查":"【必做】以临床及皮肤镜诊断为主（典型贴附状外观+皮肤镜特征，提示良性，不需常规活检）；【皮肤镜】为鉴别诊断关键（与日光性角化（红斑基底角化）、基底细胞癌（珍珠样边缘）、黑色素瘤（色素网络破坏）鉴别；诊断不确定或色素沉着型者（黑素细胞增生、色素型脂溢性角化，外观似黑色素瘤）行皮肤镜/活检，排除恶性，重要）；【其他】Leser-Trélat征（爆发性增多者需行内脏肿瘤筛查，与年龄相关）。","初步诊断":"1. 脂溢性角化（老年疣，即基底细胞乳头瘤）\n（注：①良性病变，无需治疗（告知良性性质，安抚患者，避免不必要的切除，除非出于美容需求或诊断不明）；②治疗（美容需求/反复刺激发炎/诊断不清者）：液氮冷冻（常用，1~2次，可能出现色素沉着或色素减退）、激光/电灼、刮除（浅表病变）、手术切除（大/厚/疑恶变者送病理）；③鉴别及随访（色素沉着型/不典型者行皮肤镜，必要时活检排除黑色素瘤及基底细胞癌，尤其快速增大/颜色改变/破溃者，需谨慎，勿因本病良性常见而漏诊恶性（日光性角化/基底细胞癌/黑色素瘤可模拟，不对称者应活检））；④一般无需特殊随访（良性）；由皮肤科门诊处理，并教育患者（新发变化皮损及时就诊，但多数为良性）。）","处理方案":"【药物治疗】\n1. 0.025%维A酸软膏：外用，每晚1次，涂于皮损处（避光保存，避免涂及正常皮肤及眼周），连续4~8周，适用于较扁平皮损，可促进角化性皮损软化脱落。\n2. 10%~25%水杨酸软膏：外用，每日1~2次，薄涂皮损表面，连用2~4周，起角质剥脱作用；若局部出现红肿、灼痛应减量或停用。\n3. 5%氟尿嘧啶软膏：外用，每日1~2次，仅限小面积、扁平型皮损，连用2~4周，注意局部刺激反应（红斑、水疱），炎症明显者暂停；大面积、厚角化型皮损不适用。\n4. 合并瘙痒或炎症者，可短期外用丁酸氢化可的松乳膏（0.1%）每日2次，连用不超过1周；症状缓解后停用。\n（说明：脂溢性角化为良性表皮肿瘤，药物治疗仅对部分扁平皮损有效，明显隆起、肥厚型皮损首选液氮冷冻、CO2激光、电灼或刮除术等物理治疗。）\n\n【一般治疗及生活指导】\n1. 避免搔抓、抠除、摩擦皮损及热水烫洗，防止破损后继发感染；如皮损破溃，外用莫匹罗星软膏每日2~3次预防感染。\n2. 注意防晒：外出使用防晒霜（SPF30+，PA+++以上）、撑遮阳伞、穿防晒衣，减少紫外线对皮肤的慢性刺激。\n3. 饮食无特殊禁忌，均衡饮食即可；皮损伴红肿炎症期间避免辛辣刺激、油腻及饮酒，以免加重局部反应。\n4. 保持皮肤清洁干燥，穿宽松棉质衣物，减少局部摩擦刺激；老年患者注意皮肤保湿，可每日涂抹润肤乳。\n\n【随诊要求】\n1. 药物治疗者4~8周后复诊，评估皮损消退情况及局部刺激反应，必要时调整方案或改行物理治疗。\n2. 物理治疗（冷冻、激光、电灼）后2~4周复诊，检查创面愈合情况及有无瘢痕、色素沉着，必要时再次治疗。\n3. 脂溢性角化为良性病变，但需长期观察：若皮损出现迅速增大、破溃、出血、瘙痒、颜色加深或边缘不规则等变化，应及时到皮肤科就诊，必要时行皮肤镜检查或活检以排除恶变；建议每年皮肤科随访一次。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":543,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"e2097314e1fdb1cb09dec34d36c4a15a42937d265fa9f87d0ed14fc4da7b7bdf","pinyin":"zhiyixingjiaohua","initials":"zyxjh","setting":"out","caseName":"门诊病历408","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历408",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-46700887cbac2a16b3f5","key":"v1-c9ccc21dfe2a3058|templates-46700887cbac2a16b3f5","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"日光性角化","category":"门诊病历模板","raw":{"name":"日光性角化","category":"门诊病历模板","case":{"case_name":"门诊病历409","templates":{"主诉":"面部日晒部位角化性皮损3年","现病史":"患者长期日晒（紫外线累积暴露，户外工作或休闲为主要病因），为浅肤色、中老年（50岁以上常见），并有免疫抑制（器官移植后多发日光性角化，鳞癌风险显著增高）、年龄相关皮肤老化、既往皮肤癌或日光性角化史等高危因素。于10余年前在长期日晒部位出现皮损：日晒部位（面、颊、鼻、前额、头顶秃发区、头皮、耳、手背、前臂伸侧、下唇）可见多发红斑角化性皮损，呈淡红至棕红色，表面粗糙、角化，覆鳞屑及痂，直径数毫米至1~2cm，平或微隆起；触诊粗糙，呈砂纸样感觉，触诊为重要体征；皮损常为多个、散在分布，可相互融合；多无症状，或仅有轻度瘙痒；部分皮损可自行消退后又新发。分型包括色素型（褐色，似脂溢性角化）、萎缩型及增生型（角化明显，可形成皮角，即角化性柱状突起，基底可发生鳞癌）。本病约10%可在数年内进展为鳞状细胞癌，尤其见于免疫抑制、多发及厚角化皮损者。需与脂溢性角化、基底细胞癌、鳞状细胞癌鉴别，不典型者需行活检。口腔及唇部可表现为日光性唇炎，下唇干燥、脱屑、皲裂，存在鳞癌风险。今日来我院皮肤科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.8℃，P78次/分，R18次/分，BP120/80mmHg。皮肤日晒部位（面部、头皮、耳、手背、前臂）可见红斑角化性丘疹，大小不等、数目多发，表面粗糙，触诊呈砂纸样，覆鳞屑及痂；皮损分布与日光暴露部位一致；可见色素型（褐色）皮损及皮角（角化性突起）；周围皮肤呈日光性弹性组织变性，皮肤粗糙、有皱纹、呈黄褐色；下唇可见日光性唇炎；手背、前臂皮损明显；淋巴结未触及肿大，恶变及转移少见；全身皮肤可见其他日晒性损害，如脂溢性角化、雀斑。","辅助检查":"【必做】临床诊断（典型日光暴露部位粗糙角化皮损，结合病史）；【确诊】皮肤活检（指征（厚角化皮损、增大/溃疡/出血、皮角、基底、色素不典型，疑鳞癌/基底细胞癌、免疫抑制者低阈值活检重要）；病理（表皮角化过度、不典型角质形成细胞（异型性基底层下部不典型增生，日光性角化表皮内原位癌变分级）、与鳞癌鉴别（侵袭深度））；【随访】（全身皮肤检查（多发日光性角化，定期随访，新发皮损鳞癌监测重要）、皮肤镜（辅助鉴别）。","初步诊断":"1. 日光性角化（光化性角化，癌前病变），位于日晒部位（面、手背等），需评估皮损数目、角化程度、鳞状细胞癌进展风险（免疫抑制者高）及活检指征。\n（注：治疗原则为治疗所有日光性角化，防止进展为鳞癌并预防新发。①局部破坏性治疗：液氮冷冻（适用于单发或少数皮损，常用且有效，可出现疼痛、水疱及色素改变）、刮除电灼（适用于角化较厚的皮损）、激光（二氧化碳激光或点阵激光，可选择）；外用药物治疗：5-氟尿嘧啶软膏（5%，每日1~2次，连用4~6周，出现红斑、糜烂属正常反应，对多发皮损有效且重要）、咪喹莫特乳膏（免疫调节，每周3~5次，连用4~8周，可见炎症反应）、双氯芬酸凝胶（3%，每日2次，连用60~90天，适用于轻症）、光动力治疗（5-氨基酮戊酸光敏剂加光照，适用于多发皮损，美容效果好）；治疗选择应依据皮损数目、部位、角化程度及美容要求。②多发、融合或光化性损伤区：予光动力治疗或5-氟尿嘧啶（大面积治疗日光性损伤区、预防新发癌，重要），并皮肤科定期随访。③恶变监测：治疗后随访，对新发或进展皮损行活检（鳞癌早期诊断及治疗重要）；免疫抑制者（移植后皮损多发、复发率高）应皮肤科密切随访，降低活检阈值。④防晒：为核心预防新发措施（SPF50+宽谱防晒霜，每日使用，戴帽子、穿长袖衣，避免日晒高峰，重要；儿童防晒及终身防皮肤癌教育），并定期行全身皮肤自查，出现新变化及时就医。皮肤科治疗现有皮损、预防新发、防晒、随访及癌变监测均重要。）","处理方案":"【药物治疗】\n1. 首选局部外用5%氟尿嘧啶乳膏：取适量涂于皮损及周围0.5cm区域，每日1-2次，连续2-4周（皮损区出现红斑、糜烂为有效反应，可继续至4周）。\n2. 亦可选用5%咪喹莫特乳膏：睡前涂于皮损处，每周3次（隔晚1次），连续16周，涂后6-10小时以清水洗净；局部红肿明显者可暂停1周后继续。\n3. 对多发性或大面积皮损可选用3%双氯芬酸钠凝胶：每日2次涂抹皮损处，连续60-90天。\n4. 炎症反应明显伴疼痛者可短期外用糖皮质激素（如糠酸莫米松乳膏，每日1次，连用不超过2周）以缓解不适。\n【一般治疗及生活指导】\n1. 严格防晒：外出使用广谱防晒霜（SPF≥50、PA+++以上），每2-3小时补涂1次；避免10:00-16:00时段外出，配合遮阳帽、口罩、长袖衣物等物理遮挡。\n2. 避免日光累积损伤：减少日光浴、露天作业及紫外线理疗，已出现皮损的暴露部位（面、手背、头皮）重点防护。\n3. 皮肤护理：保持皮损处清洁干燥，避免搔抓、搓洗、热水烫洗及自行撕剥痂皮，以防破溃感染及恶变。\n4. 戒烟限酒，均衡饮食，适量补充富含维生素C、维生素E的食物，增强皮肤抗氧化能力。\n【随诊要求】\n1. 药物治疗期间每2-4周复诊1次，评估疗效及局部炎症反应，调整用药方案。\n2. 治疗结束后3个月复查1次，确认皮损是否完全消退；此后每6-12个月皮肤科长期随访。\n3. 如皮损增厚、破溃、出血、扩大或出现新的皮损，需随时就诊并行皮肤镜检查或活检，排除进展为鳞状细胞癌的可能。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":544,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"586801a4cad23a4b65d110b6860dc28e5fb628f9a31f33f472f7c0d8992057f6","pinyin":"riguangxingjiaohua","initials":"rgxjh","setting":"out","caseName":"门诊病历409","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历409",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-7c265cde089f91021a4a","key":"v1-c9ccc21dfe2a3058|templates-7c265cde089f91021a4a","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"基底细胞癌","category":"门诊病历模板","raw":{"name":"基底细胞癌","category":"门诊病历模板","case":{"case_name":"门诊病历410","templates":{"主诉":"面部结节伴溃疡1年","现病史":"患者为中老年、浅肤色、长期日晒者，于6个月前在面部（鼻、眼周、颊、耳等曝光部位为主）出现皮损，表现为珍珠样、半透明小结节，可见毛细血管扩张（结节型，最常见）；本病其他表现还包括缓慢扩大的溃疡（侵蚀性溃疡，边缘隆起呈珍珠样卷边，中央溃疡结痂、反复出血、不愈合）及扁平萎缩斑（表浅型，多见于躯干，呈粉红色鳞屑斑，似湿疹或银屑病，扩大缓慢）。皮损无痛或仅有轻微疼痛，出血结痂反复，缓慢增大。本病病程数月至数年，属低度恶性，极少转移，但可造成局部破坏，可侵犯深部组织及眼、鼻软骨。既往皮肤癌史、长期日晒或晒伤史、放射线接触、砷暴露及免疫抑制（移植）史：均否认。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.8℃，P76次/分，R18次/分，BP126/78mmHg。面部可见珍珠样半透明结节，直径0.8cm，表面可见毛细血管扩张；已记录皮损大小、形态及有无侵犯周围组织（眼睑、鼻翼活动度）。区域淋巴结未触及肿大（本病极少转移）。全身皮肤已行日光性损伤评估，未见其他皮损。","辅助检查":"检查计划：患者为中老年、浅肤色、长期日晒者，面部曝光部位出现珍珠样半透明小结节伴毛细血管扩张，病程6个月并反复出血结痂、缓慢增大，临床高度疑基底细胞癌，治疗前完善皮肤活检（切除前或切取活检）送组织病理检查确诊，组织病理可见基底样细胞巢团周边呈栅栏状排列，为诊断金标准，并明确病理型别以指导手术方式选择；因本病可侵犯深部组织及眼、鼻软骨，疑深部侵犯或复发者行CT或MRI检查明确骨质及深部结构受累范围，此类情况较少需要；拟行手术切除者，术前完善血常规、凝血功能及肝肾功能、心电图检查评估手术耐受性；面部高危部位（鼻、眼周、耳）或复发者建议行Mohs显微外科，术中冰冻病理确认切缘阴性；本病极少转移，如出现区域淋巴结肿大行淋巴结超声明确有无转移；治疗后6至12个月于皮肤科行定期全皮肤检查，监测局部复发及新发其他皮肤癌（鳞状细胞癌、黑色素瘤）风险，建议每年复查一次；同时终身防晒，属预防新发的核心措施，必要时转皮肤外科或整形外科处理。\n\n（检查清单）\n【必做】皮肤活检（确诊，组织病理：基底样细胞巢团周边栅栏状排列，诊断金标准，切除前或切取活检）；【影像】（疑深部侵犯/复发，CT/MRI，少见需要）；【随访】皮肤科定期全皮肤检查（基底细胞癌，其他皮肤癌（鳞癌/黑色素瘤）风险，每年）。","初步诊断":"1. 基底细胞癌（结节型，面部）\n（注：治疗以手术切除为主，治愈率高，极少转移但有局部复发风险；治疗依据部位、大小及病理型别选择。①标准切除（金标准）：手术切除，安全切缘低危者4mm、高危者5~10mm，病理确认切缘阴性；Mohs显微外科适用于高危部位（面部、眼周、鼻、耳）及复发者，切缘控制最好，并兼顾美容及功能保留。②其他治疗（不宜手术或表浅型）：咪喹莫特乳膏5%（表浅型，每周5次，连用6周）、光动力治疗（表浅型）、冷冻、电干燥刮除（小低危结节，面部美容效果差）、放疗（不能手术者及老年患者）。③高风险型（硬化型、切缘阳性、神经周围侵犯，复发率高）：行Mohs或扩大切除加病理监测。④随访：治疗后6~12个月行皮肤检查，监测复发及新发；终身防晒（预防新发，为核心措施）。转皮肤外科或整形外科；本病预后极好，治愈率>95%，发现早、治疗早。）","处理方案":"【药物治疗】\n1. 咪喹莫特乳膏（5%）外用：用于浅表型基底细胞癌，每周5次，睡前均匀涂于皮损及其周边0.5cm正常皮肤，保留6~10小时后以清水洗净，疗程6周；结节型可隔日1次并加用封包，疗程12周。治疗局部出现红斑、糜烂属预期反应，反应明显者减频或暂停。\n2. 氟尿嘧啶乳膏（5%）外用：用于浅表型基底细胞癌，每日1~2次薄涂于皮损处，疗程4~8周，直至皮损完全消退并巩固2周，注意避光保存。\n3. 光动力治疗（PDT）：5-氨基酮戊酸（ALA）20%凝胶涂布皮损并避光封包3小时，再以635nm红光照射，能量密度100~150 J/cm²，每1~2周1次，共2~3次；适用于浅表型及不适合手术的结节型基底细胞癌或追求美容效果者。\n（注：以上局部药物仅适用于浅表型等低危基底细胞癌；结节型、溃疡型及高危部位皮损首选手术切除并送病理，药物治疗不作为一线根治手段。）\n\n【一般治疗及生活指导】\n1. 严格防晒：避免10:00~16:00时段的日光暴晒及紫外线灯照射，外出使用SPF≥30、PA+++以上的广谱防晒霜（每2小时补涂），配合遮阳帽、太阳镜、长袖衣物等物理遮挡。\n2. 保护皮损部位：避免搔抓、摩擦、挤压及外伤，禁止自行使用鸡眼膏、鸦胆子、腐蚀性药水等处理皮损，防止破溃感染及肿瘤扩散。\n3. 创面护理：治疗或手术后创面保持清洁干燥，按医嘱换药，痂皮待其自然脱落，勿强行撕除；愈合期避免沾水及剧烈运动，戒烟。\n4. 生活作息规律，均衡饮食，适当补充维生素C、维生素E等抗氧化食物（新鲜蔬果），增强机体免疫功能。\n\n【随诊要求】\n1. 术后及治疗结束后1个月复查创面愈合情况，并确认病理报告（切缘阴性及分型）；切缘阳性者需2周内补充扩大切除。\n2. 基底细胞癌易复发且可多发，建议术后每6~12个月至皮肤科专科门诊随访，全面检查原发部位及全身皮肤（尤其头部、躯干等高危部位），至少随访5年。\n3. 出现原部位红肿、溃疡、结节、渗液或新发可疑皮损时，及时复诊行皮肤镜检查，必要时再次活检。\n4. 高危人群（长期日晒史、皮肤白皙、免疫抑制状态如器官移植后）建议每年至少1次全身体表皮肤筛查。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":545,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"835cd74cc86e33d4048afca46789236b94f263daa129c16387f582a4eb211723","pinyin":"jidixibaoai","initials":"jdxba","setting":"out","caseName":"门诊病历410","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历410",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-ce92249439adb279315c","key":"v1-c9ccc21dfe2a3058|templates-ce92249439adb279315c","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"鳞状细胞癌","category":"门诊病历模板","raw":{"name":"鳞状细胞癌","category":"门诊病历模板","case":{"case_name":"门诊病历411","templates":{"主诉":"曝光部位角化性结节伴出血6月","现病史":"患者为中老年、长期日晒、浅肤色，可有癌前病变（日光性角化，即长期存在的角化性皮损恶变）、慢性溃疡或瘢痕（烧伤瘢痕、慢性骨髓炎瘘口、放射性皮炎处，即Marjolin溃疡）、免疫抑制（器官移植者鳞癌风险高且具侵袭性）、HPV感染（外生殖器）、砷或焦油暴露、吸烟（唇）等危险因素。于3个月前在曝光部位（头面颈、手背、唇或外生殖器）或原有慢性皮损处出现角化性结节，质硬、表面角化或溃疡，迅速增大、易出血、疼痛，可伴压痛。淋巴结未触及肿大，需行转移评估，鳞癌可发生区域淋巴结转移。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.7℃，P80次/分，R18次/分，BP128/80mmHg。头面颈部可见角化性结节，直径2.0cm，质硬，边缘隆起外翻，基底溃疡坏死，与深部组织粘连固定，提示有深部侵犯。区域淋巴结（颈部、腋下、腹股沟）未触及肿大，如肿大、质硬固定则提示转移可能。全身皮肤已行其他日光性角化及皮肤癌筛查。","辅助检查":"【必做】皮肤活检（确诊，组织病理：鳞状细胞异型增生浸润真皮，分化程度/神经周围/血管侵犯，角化珠，诊断及风险分层）；【影像】（深部侵犯/转移可疑，区域淋巴结超声/CT/MRI、腹部评估）；【病理评估】切缘及深度（完整切除后病理切缘状态）；【随访】皮肤科定期复查（复发及转移监测，转移风险（低危<5%、高危（深部/神经周围/免疫抑制/特定部位：唇/耳/外生殖器，10~30%））。","初步诊断":"1. 皮肤鳞状细胞癌（中分化，头面颈部，高危）\n（注：治疗以切除为主，预后良好但可转移，高危者需积极治疗。①标准手术切除：切缘低危者4~6mm，高危者（深部浸润、神经周围侵犯、免疫抑制）6mm以上或行Mohs显微外科；Mohs显微外科适用于高危部位、复发或神经周围侵犯者，为首选。②淋巴结评估：临床肿大或高危者行超声及细针穿刺检查，转移阳性者行区域淋巴结清扫。③不能手术或晚期患者：放疗（原发灶不能切除或切缘不净者，行根治性或辅助放疗）；系统性治疗（晚期或转移者可用免疫检查点抑制剂，如西米普利单抗或帕博利珠单抗，为抗PD-1药物，已获批；EGFR抑制剂，如西妥昔单抗；化疗，如顺铂，少用）。④癌前病变处理：日光性角化可行冷冻、5-氟尿嘧啶、咪喹莫特或光动力治疗，以预防进展。⑤终身防晒及皮肤监测：高危者每3~6个月复查，监测区域淋巴结、转移及复发。皮肤科、头颈外科及肿瘤科协作，高危者行多学科诊疗。）","处理方案":"【药物治疗】\n1.浅表型/原位鳞癌（鲍温病，不宜或拒绝手术者）：5%氟尿嘧啶软膏外用，每日1次涂于皮损处，连用4～6周；或5%咪喹莫特乳膏睡前外用（每周3次），次晨温水清洗，连用16周。用药期间局部红肿、糜烂属预期反应，需按期复诊评估疗效。\n2.高危/局部晚期（无法手术或放疗，或术后切缘阳性者）：帕博利珠单抗200mg静脉输注，每3周1次；或西米普利单抗350mg静脉输注，每3周1次，持续至疾病进展或出现不可耐受毒性。\n3.晚期或转移性鳞癌姑息化疗（体力状况良好、器官功能可耐受时）：紫杉醇175mg/m²静脉输注＋卡铂AUC 5静脉输注，每3周1周期；或顺铂75mg/m²（第1天）＋氟尿嘧啶750mg/m²/日持续静脉泵入（第1～4天），每3周1周期。每周期前复查血常规、肝肾功能及心电图。\n4.对症支持：皮损疼痛明显者予洛索洛芬钠片60mg口服，必要时每8小时1次，疼痛缓解即停；创面继发感染者予莫匹罗星软膏外用，每日2～3次，效果不佳时依据分泌物细菌培养及药敏调整抗菌药物。\n\n【一般治疗及生活指导】\n1.严格防晒：紫外线是皮肤鳞癌主要诱因，外出穿长袖衣物、戴宽檐帽，使用SPF≥30广谱防晒霜并每2～3小时补涂，避免10:00～16:00时段暴晒。\n2.戒烟限酒，忌辛辣刺激及过烫饮食；多摄入新鲜蔬果及优质蛋白，保证充足睡眠，维持良好营养状态，增强机体免疫力。\n3.保持皮损及手术创面清洁干燥，避免搔抓、摩擦、挤压及自行挑破，防止继发感染；治疗部位避免使用刺激性化妆品和药物。\n4.每月自我皮肤检查：留意原有及新发皮损的大小、形态、色泽变化及有无溃疡、出血、疼痛，发现异常及时就诊。\n\n【随诊要求】\n1.治疗后第1～2年每3个月门诊复诊1次，第3～5年每6个月1次，5年后每年1次：检查原发部位有无复发、区域淋巴结（尤其颈部、颌下、腹股沟）有无肿大及有无皮肤新发皮损。\n2.高危患者（肿瘤深部浸润、神经周围侵犯、切缘阳性、免疫抑制状态）每3个月复诊，并加做区域淋巴结超声；出现咳嗽、骨痛、头痛等新发症状时行胸腹部CT等检查排除远处转移。\n3.接受免疫治疗或化疗者，每周期输注前复查血常规、肝肾功能、甲状腺功能，监测皮疹、腹泻、肺炎、甲状腺炎等免疫相关不良反应；出现发热、气促、血便等异常立即急诊就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":546,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"51c17b9370284e2750399790a3ed05b9d67130a9a2764b13c8c790a96d313f29","pinyin":"linzhuangxibaoai","initials":"lzxba","setting":"out","caseName":"门诊病历411","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历411",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-6c2d413ff9234c57cb89","key":"v1-c9ccc21dfe2a3058|templates-6c2d413ff9234c57cb89","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"黑色素瘤","category":"门诊病历模板","raw":{"name":"黑色素瘤","category":"门诊病历模板","case":{"case_name":"门诊病历412","templates":{"主诉":"色素性皮损增大、颜色不均6月","现病史":"患者于3个月前发现原有色素痣出现变化，符合ABCDE特征：A不对称、B边缘不规则（呈锯齿状）、C颜色不均（黑褐蓝红白混杂）、D直径>6mm、E进展变化（增大、隆起、出血、溃疡、瘙痒），上述特征具有警示意义。本例皮损位于背部（该病男性多见于背部，女性多见于下肢；肢端如掌跖、甲下亦不少见，表现为肢端雀斑样，黄种人较多见，甲黑线重要；黏膜及眼部少见）。相关高危因素：否认日光曝晒（尤其儿童期晒伤、间歇性强烈日晒）及晒伤史、黑色素瘤家族史（有家族史者风险显著增高，见于家族性非典型性多发性痣黑色素瘤综合征）、免疫抑制，无大量痣（>100个）及非典型痣，亦无皮肤白皙、蓝眼睛、红发等情况。近期皮损快速增大，无卫星灶，区域淋巴结未见肿大，已行转移评估；晚期需注意有无咳嗽、胸痛、骨痛等内脏转移症状。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.6℃，P76次/分，R18次/分，BP118/76mmHg。全身皮肤检查：背部可见色素性皮损，大小约1.5cm×1.0cm，形态符合ABCDE特征，颜色分布不均，呈黑褐混杂，表面隆起，未见溃疡及出血，原发灶周围2cm内未见色素性卫星灶（卫星灶为转移征象）。区域淋巴结（颈部、腋下、腹股沟）未触及肿大，如肿大、质硬则提示转移可能。全身皮肤其他痣已评估总数及非典型痣情况，并已行全身拍照记录，对随访对比重要。","辅助检查":"【必做】皮肤镜检查（色素网络结构、退行结构、蓝白幕、不规则色素点/球，黑色素瘤特征，与良性痣鉴别，关键初筛）；【确诊】完整切除活检（金标准，全层切除带正常皮肤，不做切取/刮除活检（可致误诊及扩散风险）；组织病理：Breslow厚度（浸润深度，最重要预后因素）、Clark分级、溃疡、有丝分裂率、切缘、前哨淋巴结状态，分期核心）；【影像】淋巴结超声（临床肿大）、CT/PET-CT（Breslow>1mm或淋巴结阳性，远处转移分期筛查）；【分子】BRAF突变检测（转移性，靶向治疗决策重要）。","初步诊断":"1. 皮肤恶性黑色素瘤（表浅扩散型，Breslow厚度1.2mm，临床分期IB期）\n（注：治疗遵循分级管理及多学科协作（皮肤科、肿瘤科、外科）。①广泛切除：原发灶切缘依据Breslow厚度确定（原位0.5cm，≤1mm者1cm，1~2mm者1~2cm，>2mm者2cm）。②前哨淋巴结活检：Breslow>0.8~1mm或有溃疡者应行活检以助分期及判断预后；阳性者行区域淋巴结清扫（存在争议，正逐渐被辅助治疗替代）。③辅助治疗（术后IIB/III期，用于降低复发）：免疫治疗（帕博利珠单抗或纳武利尤单抗，为抗PD-1药物，是辅助标准治疗）或靶向治疗（BRAF突变者予达拉非尼加曲美替尼辅助治疗）。④晚期（转移性）一线治疗：免疫检查点抑制剂（帕博利珠单抗或纳武利尤单抗±伊匹木单抗，即双免疫治疗）、BRAF突变者靶向治疗（BRAF加MEK抑制剂，达拉非尼加曲美替尼）、放疗（脑转移或骨转移者姑息治疗）。⑤随访：定期行皮肤全身检查（高危者前2~3年每3~6个月1次）、淋巴结检查及影像学检查（晚期）；终身防晒，并开展皮肤自查教育（ABCDE，新发或变化及时就诊）。黑色素瘤早期治愈率高（原位近100%，薄Breslow预后好），早诊早治为关键；有家族史者行遗传咨询（CDKN2A等基因检测及家系筛查）。）","处理方案":"【药物治疗】\n1. 免疫检查点抑制剂（晚期不可切除或转移性黑色素瘤一线首选方案）：帕博利珠单抗注射液200mg，静脉滴注，每3周1次（或2mg/kg q3w），持续用药至疾病进展或出现不可耐受毒性，总疗程最长2年；治疗前及每周期复查血常规、肝肾功能、甲状腺功能、心肌酶及心电图。\n2. 靶向治疗（BRAF V600E/K基因突变阳性者）：达拉非尼胶囊150mg，口服，每日2次＋曲美替尼片2mg，口服，每日1次，两药联合持续至疾病进展或不可耐受毒性；用药期间监测发热、皮疹、关节痛、肝功能及血糖。\n3. 辅助治疗（手术切除后中高危复发风险患者）：帕博利珠单抗注射液200mg，静脉滴注，每3周1次，共1年，降低术后复发转移风险；或干扰素α-2b皮下注射，每周3次，共12个月（剂量按体重及耐受性调整）。\n4. 局部治疗（原位黑色素瘤/雀斑样恶性黑素瘤无法手术或手术禁忌者）：5%咪喹莫特乳膏，取适量涂于皮损及周围1cm区域，睡前外用，每周5次，连续6～12周，出现明显局部炎症反应后评估疗效。\n\n【一般治疗及生活指导】\n1. 严格防晒：避免10:00—16:00时段日光暴晒，外出使用SPF≥30的广谱防晒霜，每2～3小时补涂1次，并配合遮阳帽、长袖衣物等物理遮挡；高危人群每年行1次皮肤科全身皮肤检查。\n2. 定期皮肤自查：按ABCDE原则（不对称、边缘不规则、颜色不均、直径＞6mm、短期内增大或形态变化）每月自查全身皮肤及足底、甲下、黏膜等隐蔽部位，发现新发或动态变化的色素性皮损及时就诊。\n3. 避免刺激：严禁自行搔抓、挤压、针挑或激光、冷冻、化学腐蚀剂祛痣，避免反复摩擦刺激痣体；日常活动不受限，可正常饮食，适当补充优质蛋白促进切口愈合。\n4. 术后创面护理：保持手术切口清洁干燥，拆线前避免沾水，患处避免过紧衣物摩擦，出现红肿、渗液、发热及时就医。\n\n【随诊要求】\n术后患者：原位/I期每6～12个月复查1次，II～III期每3～6个月复查1次，共随访5年，高危者适当延长；每次复查行全身皮肤及区域淋巴结体格检查，必要时行浅表淋巴结超声、胸腹盆增强CT、头颅MRI及血清LDH、S100B检测。晚期或辅助治疗患者：每周期（每2～3周）复查血常规、肝肾功能、甲状腺功能及心电图，每3个月行影像学疗效评估。随访期间出现新发色素性皮损、淋巴结肿大、不明原因发热、咳嗽、头痛或骨痛，应提前就诊，警惕复发或转移。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":547,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"30085f8771b3dc5aa09c362ca88038d6a46c5d59e5a3ca71632c060feb08635b","pinyin":"heisesuliu","initials":"hssl","setting":"out","caseName":"门诊病历412","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历412",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-12d8c636808f94f45112","key":"v1-c9ccc21dfe2a3058|templates-12d8c636808f94f45112","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"蕈样肉芽肿","category":"门诊病历模板","raw":{"name":"蕈样肉芽肿","category":"门诊病历模板","case":{"case_name":"门诊病历413","templates":{"主诉":"皮肤红斑鳞屑伴瘙痒5年","现病史":"患者为成人（40~60岁多见，男多于女）。病因为恶性T淋巴细胞克隆性增生，具有皮肤归巢性，初始累及皮肤，缓慢发展，病程多年，可累及淋巴结及内脏。既往有多年湿疹、银屑病或神经性皮炎病史，诊断及治疗无效、反复发作，最终经活检才确诊，此点重要；斑片期、斑块期皮损似良性皮肤病，久治不愈，需皮肤科随访并再次活检。于10余年前缓慢出现皮损：斑片期表现为早期红斑、鳞屑性斑片（似湿疹、银屑病或副银屑病，多分布于臀部、躯干等非日光暴露部位，境界清），伴明显、顽固性瘙痒；斑块期表现为浸润性斑块（增厚、隆起，呈暗红至棕红色）；肿瘤期表现为结节及肿瘤（呈蕈样，即蘑菇样外观，可隆起、破溃）；红皮病型表现为全身潮红、脱屑，瘙痒剧烈；晚期可累及淋巴结，并可出现内脏受累（肝、脾、肺、骨髓）。皮肤外受累情况：血液受累可见Sézary综合征（红皮病加淋巴结受累加血液中Sézary细胞增多，白细胞增多，预后差）。另需记录瘙痒程度、既往皮肤活检史及诊断史，以及有无体重下降、发热、盗汗等B症状（多见于晚期）。今日来我院皮肤科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.9℃，P80次/分，R18次/分，BP122/78mmHg。已行皮肤全面检查：可见斑片（红斑、鳞屑、萎缩、色素异常）、斑块（浸润、隆起、境界清）、肿瘤结节（记录大小、数目、有无破溃及蕈样外观）、红皮病（全身潮红、脱屑）、皮肤异色（色素沉着、减退、萎缩及毛细血管扩张，见于斑片期），并可见瘙痒抓痕。淋巴结未触及肿大；肝脾未触及，如有增大提示晚期。毛发及甲未受累。已行皮肤科全身皮肤检查并记录皮损分布，此点重要；全身状况良好，无B症状。","辅助检查":"【必做】皮肤活检（核心多次活检（多部位病理典型（表皮内Pautrier微脓肿、T细胞亲表皮、不典型淋巴细胞脑回状核）、斑片期活检可不典型（需多次、多次不同部位重复活检重要）、免疫组化（CD4+T细胞CD3+CD4CD8异常克隆）、T细胞受体基因重排（克隆性检测确诊支持））；【分期】血液检查（血常规、外周血涂片Sézary细胞）、淋巴细胞免疫分型（流式）、肝肾功能、乳酸脱氢酶、胸腹盆CT（淋巴结，内脏，受累，晚期）、淋巴结活检（肿大，受累，评估）、骨髓（晚期）、PETCT（分期））；【其他】（鉴别良性皮肤病（湿疹/银屑病，副银屑病，大斑块型副银屑病，癌前，监测，重要）、皮肤T细胞淋巴瘤，其他亚型（CD30+淋巴瘤增殖性疾病））。","初步诊断":"1. 蕈样肉芽肿（皮肤T细胞淋巴瘤，斑片期）；已评估红皮病及Sézary综合征、TNM/B分期、克隆性及免疫表型、内脏及淋巴结受累情况。\n（注：治疗依分期而定，以皮肤定向治疗为主，早期以局部治疗为主，晚期采用系统治疗。①早期（斑片期、斑块期）行皮肤定向治疗：外用糖皮质激素（斑片较轻者用于控制瘙痒）、氮芥或卡莫司汀外用（局部化疗，有效）、光疗（窄谱中波紫外线或补骨脂素加长波紫外线，即光化学疗法，为早期首选，有效且重要）、全身皮肤电子束照射（用于顽固、广泛皮损）、贝沙罗汀凝胶（局部维A酸，用于斑块期）；上述治疗有效，但需长期随访并监测复发，此点重要。②进展期（肿瘤期、红皮病或淋巴结受累）采用全身治疗：干扰素α（免疫调节，用于斑块期辅助治疗）、维A酸（口服，贝沙罗汀或阿维A）、体外光分离置换法（Sézary综合征及红皮病的重要治疗）、靶向药物（布伦妥昔单抗维多汀，抗CD30，用于CD30+者；莫格利珠单抗，抗CCR4，为蕈样肉芽肿及Sézary综合征的新药）、组蛋白去乙酰化酶抑制剂（伏立诺他、罗米地辛）、化疗（晚期难治者行多药化疗，如CHOP类方案，疗效有限、缓解期短）、异基因造血干细胞移植（年轻、难治、晚期者可评估）。③并发症处理：皮肤感染（破溃、肿瘤继发金黄色葡萄球菌感染时予抗感染治疗）、瘙痒（剧烈者对症予抗组胺药及光疗）、红皮病（注意体温调节及液体丢失，给予支持治疗）。④随访：定期行皮肤检查（评估治疗反应及复发，每3~6个月1次）、淋巴结监测（有无肿大）、血液检查（红皮病者查Sézary细胞）、皮肤新发病灶及时活检（评估是否进入进展期），并长期随访；本病多呈惰性，多年缓慢进展，部分患者病程与良性疾病相似，应告知预后并强调随访重要。皮肤科与血液肿瘤科协作，早期以皮肤定向治疗、光疗及局部治疗为主，晚期采用全身靶向治疗并随访，均属重要。）","处理方案":"【药物治疗】\n1. 外用糖皮质激素（早期斑片/斑块期一线首选）：0.05%丙酸氯倍他索乳膏涂于皮损处，qd-bid，连用2周后改为每周间歇用药（每周连续2天、停5天，或每周1-2次维持），避免长期连续大面积使用；面部、皱褶部位改用0.1%糠酸莫米松乳膏或0.1%丁酸氢化可的松乳膏，bid。\n2. 局部氮芥制剂：盐酸氮芥软膏（氮芥10mg加至白凡士林等基质配成0.01%-0.02%），每日1次涂于皮损处，疗程3-6个月，适用于早期斑片/斑块期；用药期间监测血常规及肝肾功能，接触性皮炎发生时应减量或暂停。\n3. 维A酸类：阿维A胶囊10-25mg qd口服，与食物同服，用于顽固性斑块或泛发皮损，疗程3-6个月；服药期间及停药后至少2年严格避孕，定期监测血脂、肝功能，避免饮酒及同服大剂量维生素A。\n4. 光疗（PUVA辅助用药）：8-甲氧补骨脂素（甲氧沙林）片0.6mg/kg，于照射UVA前1-2小时口服，每周2-3次，用于浸润性斑块期；服药后24小时内严格避光（戴防UVA墨镜、穿长袖），监测肝功能。\n【一般治疗及生活指导】\n1. 皮肤护理：温和清洁皮肤，每日外用保湿剂（如凡士林、尿素软膏）保持皮肤润泽，避免搔抓、热水烫洗及刺激性肥皂，防止皮损破溃继发感染；发现破溃、渗液及时局部抗感染处理。\n2. 防晒：日常外出使用SPF≥30广谱防晒霜并物理遮挡防晒；光疗日按医嘱仅暴露治疗部位，避免额外日光累积暴露，减少紫外线相关皮肤损伤及致癌风险。\n3. 饮食与作息：均衡饮食、适量高蛋白营养，规律作息、避免熬夜，适度活动增强免疫力；服用阿维A期间绝对禁酒，不自行补充维生素A制剂。\n4. 自我观察与禁忌：每月拍照记录皮损变化（范围、颜色、浸润程度），关注新发斑片、结节及淋巴结肿大；禁止自行外用强效激素长期滥用，禁止吸烟及暴晒。\n【随诊要求】\n1. 治疗期间每2-4周皮肤科复诊1次，评估皮损消退情况，调整外用激素强度、氮芥软膏浓度及光疗剂量。\n2. 口服阿维A者每4周复查肝功能、血脂、血常规；育龄期女性服药期间及停药后至少2年严格避孕；光疗者累计照射次数较多时按医嘱评估皮肤肿瘤学风险。\n3. 每3-6个月行全身皮肤及浅表淋巴结专科检查，评估病情分期；如出现皮损浸润增厚、结节或肿瘤形成、淋巴结肿大、不明原因发热或体重下降，应立即就诊，必要时复查皮肤活检、影像学或PET-CT，评估升级为系统性治疗（如干扰素、贝沙罗汀、体外光分离置换等）。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":548,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"d78ddc9910f75d44b0c84676fbe007cdea49b473c5c767ea366207a9092f8171","pinyin":"xunyangrouyazhong","initials":"xyryz","setting":"out","caseName":"门诊病历413","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历413",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-296d76262d76f2c4aa7b","key":"v1-c9ccc21dfe2a3058|templates-296d76262d76f2c4aa7b","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"皮肤转移癌","category":"门诊病历模板","raw":{"name":"皮肤转移癌","category":"门诊病历模板","case":{"case_name":"门诊病历414","templates":{"主诉":"皮肤结节1周","现病史":"患者1周前无明显诱因出现皮肤转移癌相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者皮肤结节1周并伴轻度乏力，皮肤转移癌多提示存在内脏恶性肿瘤，须以皮肤活检确定诊断并追溯原发灶，完善皮肤活检送组织病理及免疫组化检查明确肿瘤组织来源，为确诊及判断原发部位的关键；查血常规排除感染、贫血及血液系统受累，并了解有无肿瘤消耗；查过敏原检测排除湿疹、接触性皮炎等变态反应性皮损所致结节；查真菌镜检加真菌培养排除深部或浅表真菌感染所致类似皮损；行皮肤镜检查观察皮损血管结构及形态，协助判断良恶性并指导活检取材部位；疑自身免疫性大疱性皮损者行免疫荧光检查排除相关疾病；疑变应性接触性皮炎者行斑贴试验明确致敏原；皮损不典型疑二期梅毒疹等性传播疾病者行性病相关检测明确病因；确诊后完善胸部CT、腹部超声或CT、肿瘤标志物及肝肾功能检查寻找原发灶并评估转移范围与分期，必要时行PET-CT明确全身病变分布；上述检查按病情需要选择，明确诊断后由肿瘤科制定综合治疗方案并定期复查随访。\n\n（检查清单）\n【必做检查】\n血常规、过敏原检测、真菌镜检+培养\n\n【影像学检查】\n皮肤镜、皮肤活检（必要时）\n\n【其他检查】\n免疫荧光、斑贴试验、性病相关检测（必要时）","初步诊断":"1. 皮肤转移癌\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 化疗：卡培他滨片1.0g bid口服，连服14天、停药7天，每3周为1周期（结合原发瘤种、既往化疗史及体能状况个体化调整剂量）。\n2. 靶向治疗：根据原发肿瘤及基因检测结果选用，如激素受体阳性乳腺癌皮肤转移可予来曲唑片2.5mg qd口服；HER2阳性者予曲妥珠单抗（首次8mg/kg，此后6mg/kg）静脉输注，每3周1次。\n3. 免疫治疗：帕博利珠单抗200mg静脉输注，每3周1次（适用于原发肿瘤对免疫治疗敏感且PD-L1表达阳性者）。\n4. 对症止痛：中重度疼痛者予盐酸羟考酮缓释片10mg q12h口服，按疼痛评分逐步调整剂量；皮损破溃继发感染者局部用莫匹罗星软膏涂患处tid。\n【一般治疗及生活指导】\n1. 皮肤护理：保持皮损区清洁干燥，穿宽松棉质衣物，避免搔抓、摩擦、挤压皮损；破溃、渗液处每日以碘伏消毒后无菌纱布覆盖换药，防止继发感染及出血。\n2. 休息与活动：保证充足睡眠，避免劳累及剧烈运动，可进行散步等轻体力活动以维持体力；破溃明显或疼痛加重时适当卧床休息。\n3. 饮食：高蛋白、高维生素、易消化饮食（如鸡蛋、鱼肉、瘦肉、新鲜蔬果），少量多餐，保证营养支持；食欲差者加强营养补充。\n4. 禁忌：戒烟限酒，避免日光暴晒及局部热敷、按摩、理疗，禁止自行涂抹刺激性药膏、外敷偏方或挤压皮损。\n【随诊要求】\n1. 每2~4周门诊复诊1次，评估皮损大小、数目、色泽变化及有无新发转移灶。\n2. 化疗、靶向或免疫治疗期间每周期复查血常规、肝肾功能、电解质及心肌酶，监测骨髓抑制、肝肾功能损伤等不良反应。\n3. 每2~3个月行原发肿瘤部位及胸腹部CT等影像学检查，评估全身病情变化。\n4. 出现皮损迅速增大、破溃出血、渗液增多、发热、剧烈疼痛或新发结节时随时就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":549,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"d588ae3105ba783001675c946570bca7746e63ee76dd7c7a5bfe59942736ac89","pinyin":"pifuzhuanyiai","initials":"pfzya","setting":"out","caseName":"门诊病历414","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历414",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-3761cc21ead65373170f","key":"v1-c9ccc21dfe2a3058|templates-3761cc21ead65373170f","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"皮肤淋巴瘤","category":"门诊病历模板","raw":{"name":"皮肤淋巴瘤","category":"门诊病历模板","case":{"case_name":"门诊病历415","templates":{"主诉":"皮肤斑块、结节1周","现病史":"患者1周前无明显诱因出现皮肤淋巴瘤相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者皮肤斑块、结节1周并伴轻度乏力，皮肤淋巴瘤须与炎症性皮肤病及其他皮肤肿瘤鉴别，并评估全身受累及分期，完善血常规加网织红细胞检查了解有无贫血、感染及骨髓造血功能状况；查外周血涂片观察有无异型淋巴细胞，协助判断有无血液系统受累；查凝血功能排除凝血障碍，并为后续皮肤活检及治疗提供安全保障；行腹部超声检查肝脾及腹腔淋巴结有无肿大，同时行淋巴结超声明确浅表淋巴结有无受累；为明确诊断及分期，完善骨髓穿刺加活检了解骨髓有无肿瘤浸润；行流式细胞术检查明确细胞免疫表型，协助区分T细胞与B细胞来源及克隆性；行染色体核型分析了解有无特征性染色体异常，辅助诊断及预后判断；皮肤病灶本身应行皮肤活检加免疫组化明确病理诊断，必要时行T细胞受体基因重排检查；疑系统受累者可行胸部CT及PET-CT评估全身病变分布；上述检查按病情需要选择，确诊后由血液科或皮肤科制定方案并定期复查。\n\n（检查清单）\n【必做检查】\n血常规+网织红细胞、外周血涂片、凝血功能\n\n【影像学检查】\n腹部超声（肝脾淋巴结）、淋巴结超声\n\n【其他检查】\n骨髓穿刺+活检、流式细胞术、染色体核型分析","初步诊断":"1. 皮肤淋巴瘤\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 外用糖皮质激素（早期蕈样肉芽肿斑片/斑块期首选）：糠酸莫米松乳膏0.1%，每日1次涂搽皮损处，连用2-4周后复诊评估疗效，可间歇维持；避免长期大面积使用以防皮肤萎缩、色素改变。\n2. 干扰素α-2b注射液300万U，皮下注射，每周3次（隔日1次），疗程至少3-6个月；建议睡前注射以减轻流感样反应，用药期间定期监测血常规、肝肾功能。\n3. 甲氨蝶呤片5-15mg，每周1次口服（用于红皮病型/Sézary综合征及广泛性皮损），服药次日口服叶酸片5mg以预防口腔黏膜炎及骨髓抑制；用药期间禁酒。\n4. 阿维A胶囊10-30mg，每日1次口服（用于顽固性皮损或肿瘤期病变的辅助治疗）；育龄期女性需严格避孕，定期复查血脂及肝功能。\n\n【一般治疗及生活指导】\n1. 皮肤护理：每日用37℃左右温水沐浴，避免热水烫洗、搔抓及刺激性皂液；浴后及时涂抹保湿剂（尿素软膏、凡士林等）以修复皮肤屏障、缓解干燥瘙痒。\n2. 防晒避光：避免日光暴晒及紫外线过度暴露，行NB-UVB光疗期间外出需涂SPF30+防晒霜，防止光敏反应及皮损加重。\n3. 饮食作息：均衡高蛋白饮食，保证充足热量与维生素；忌辛辣刺激食物、海鲜及酒精；规律作息、避免劳累，保持情绪稳定。\n4. 衣物环境：穿宽松纯棉衣物，勤换洗床单被褥，保持居室清洁通风；剪短指甲避免搔抓继发感染，出现糜烂、渗出或发热及时就诊。\n\n【随诊要求】\n1. 外用药物或光疗治疗期间每2-4周复诊1次，评估皮损消退情况及调整治疗方案。\n2. 全身用药（干扰素、甲氨蝶呤等）期间每2-4周复查血常规、肝肾功能，每1-3个月全面复诊评估疗效与药物不良反应。\n3. 如出现新发结节、肿瘤期皮损、区域淋巴结肿大或发热、盗汗、体重下降等提示疾病进展或累及内脏的表现，应随时就诊。\n4. 本病需长期随访（至少5年），监测复发及大细胞转化征象；红皮病型患者注意防治皮肤感染及水电解质紊乱。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":550,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"909ff7965197de1eb485119381120a19952208045c53d9f345b08ae2677d186b","pinyin":"pifulinbaliu","initials":"pflbl","setting":"out","caseName":"门诊病历415","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历415",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-4689c53568c23513ac44","key":"v1-c9ccc21dfe2a3058|templates-4689c53568c23513ac44","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"睑缘炎","category":"门诊病历模板","raw":{"name":"睑缘炎","category":"门诊病历模板","case":{"case_name":"门诊病历416","templates":{"主诉":"睑缘红肿、脱屑1周","现病史":"患者1周前无明显诱因出现睑缘炎相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以睑缘红肿、脱屑1周为主诉，病程中伴轻度乏力，为排除细菌或病毒感染、贫血等全身因素所致眼睑局部炎症迁延，入院即刻完善血常规检查；眼睑炎症可与脂溢性皮炎、代谢紊乱相关，且局部用药及口服抗感染药物需经肝肾代谢，完善肝肾功能检查排除肝肾功能不全；完善血糖、血脂检查了解有无糖尿病、高脂血症等代谢因素参与睑缘炎发病；患者诉轻度乏力，完善电解质检查排除电解质紊乱所致乏力；完善尿常规、便常规检查排除泌尿系及消化道感染，避免漏诊其他部位感染灶；患者既往体健，无高血压、糖尿病、冠心病等慢性病史，为评估心肺及腹部脏器基础状况、给门诊用药建立安全基线，完善心电图、胸部X线片、腹部超声检查，了解有无潜在心、肺、腹部病变；结合睑缘红肿、脱屑体征，初步诊断睑缘炎，为明确病变累及范围及严重程度，完善视力、裂隙灯检查观察睑缘、睫毛根部有无充血、鳞屑、溃疡及睑板腺开口情况；完善眼压检查排除眼压异常；因睑缘炎常合并干眼，完善泪液分泌试验、泪膜破裂时间检查了解泪膜稳定性，与干眼症相鉴别；必要时行睫毛根部分泌物涂片或培养明确致病菌指导用药；如经上述检查疗效不佳，需与睑腺炎、接触性皮炎等鉴别，必要时请皮肤科、相关科室会诊后选择相应检查。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 睑缘炎\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 局部抗生素眼膏：妥布霉素眼膏（或红霉素眼膏）涂于睑缘及睫毛根部，每日3次，每次约米粒大小，疗程1~2周。\n2. 炎症明显者短期联合糖皮质激素：0.1%氟米龙眼膏涂睑缘，每日1~2次，疗程3~5天，炎症消退即停。\n3. 重度或难治性葡萄球菌性睑缘炎：口服多西环素100mg每日1次，饭后服，疗程4~6周。\n【一般治疗及生活指导】\n1. 每日2次温热毛巾热敷眼睑（40~45℃，每次10~15分钟），软化分泌物后行睑缘清洁。\n2. 用棉签蘸稀释后的温和清洁液（如婴儿洗发水按1:10稀释）自内眦向外眦擦拭睫毛根部及睑缘，清除鳞屑痂皮，每日1~2次。\n3. 避免揉眼、化眼妆（眼线、假睫毛等），治疗期间不佩戴隐形眼镜。\n4. 清淡饮食，少食辛辣油腻及高糖食物；注意手卫生，毛巾单独使用并勤换洗。\n【随诊要求】\n治疗1周后复诊评估疗效，若症状无缓解或加重，需复查裂隙灯，必要时调整方案（如加用口服抗生素或联合睑板腺物理治疗）；慢性睑缘炎易反复，缓解期建议每1~3个月复查一次，出现视力下降、眼痛等立即就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":551,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"a1f5b092210a3e4e065b617b8e190b809bc8da71d624d3c4fdaf7d66d1ac73ee","pinyin":"jianyuanyan","initials":"jyy","setting":"out","caseName":"门诊病历416","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历416",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-ca3317f16ec88cd43f52","key":"v1-c9ccc21dfe2a3058|templates-ca3317f16ec88cd43f52","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"睑板腺囊肿","category":"门诊病历模板","raw":{"name":"睑板腺囊肿","category":"门诊病历模板","case":{"case_name":"门诊病历417","templates":{"主诉":"眼睑无痛性硬结1月","现病史":"患者于____（渐进，数周至数月）出现：____（眼睑硬结（无痛性（重要，区别于麦粒肿（睑腺炎，红肿热痛，急性感染）、单个或多个，眼睑皮下，圆形硬结，不红/微红，无压痛/轻、渐增大（缓慢，数周）、眼睑（无红肿热痛，急性炎症轻，睑板腺囊肿，慢性睑板腺口堵塞，分泌物潴留，肉芽肿性炎症）、继发感染（红痛，急性睑腺炎，麦粒肿，处理）、____（有无睑板腺功能障碍（眼干，睑缘炎；慢性睑板腺堵塞，多发囊肿）、玫瑰痤疮/脂溢性皮炎（睑板腺相关）、反复发作（睑板腺功能检查，防复发及恶性肿瘤鉴别（睑板腺癌，少见但重要：中老年睑板腺部位，无痛硬结，反复囊肿，切除后复发，溃疡，睫毛脱落，睑板腺癌，恶性皮脂腺癌，警惕中老年硬结，进行性，活检，重要）、睑缘（睫毛脱落，肿瘤）、糖尿病/免疫）、结核（少见）、既往（囊肿手术史，病理（切除送病理，排除睑板腺癌，重要）。今日来我院眼科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.8℃，P78次/分，R18次/分，BP120/80mmHg。眼科检查：眼睑可见皮下硬结，位于上睑，睑板腺区、距睑缘约2mm，直径约5mm，质地硬，表面光滑，活动度可；皮肤无红肿、无压痛，囊肿炎症轻；翻转眼睑后见睑结膜面呈紫红色隆起，囊肿向结膜面突出；睑缘睑板腺口堵塞；睫毛正常，无脱落（警惕肿瘤）；无继发感染表现（无红痛，未形成麦粒肿）；单发；泪膜检查并见干眼；耳前淋巴结无肿大，无感染征象。","辅助检查":"【必做】眼科检查（裂隙灯，确诊）；【其他】（手术切除病理（常规送病理，排除睑板腺癌（中老年，反复/不典型，重要，切除标本病理，防漏诊）、疑睑板腺癌（中老年硬结，进行性，睫毛脱落，溃疡，切除活检，病理确诊）、睑板腺功能障碍评估（眼表，睑板腺成像，必要时）。","初步诊断":"1. 睑板腺囊肿（霰粒肿，上睑，单发，大小约5mm，无感染；需与睑板腺癌鉴别，中老年者应警惕）\n（注：治疗（小者观察热敷，大者或持续不消退者手术切除）：①保守治疗（适用于早期或小囊肿，直径<5mm）：热敷（温水毛巾，每日3~4次，每次10~15分钟，可软化睑板腺分泌物、促进排出，为重要措施，早期可消退，需数周）、眼睑按摩（热敷后轻按摩，方向向睑缘，促进排出）、睑缘清洁（保持睑板腺卫生）、抗生素眼膏（继发感染或形成麦粒肿时用莫匹罗星或妥布霉素）、人工泪液（合并干眼时）；②手术切除：适应证为囊肿>5mm或持续不消退（热敷4~6周无效）、影响视力或外观、反复感染、疑为肿瘤（睑板腺癌，中老年者应手术加病理，重要）。手术方式为睑板腺囊肿刮除术，局部麻醉，取睑结膜面切口（内切口），从睑结膜面刮除囊壁及内容物以防复发，完整刮除囊壁为重要环节；切除物常规送病理（尤其中老年、复发或不典型者），以排除睑板腺癌，此为关键；术后涂眼膏抗感染，1周复查；③睑板腺功能障碍的处理（适用于多发或反复者）：热敷加睑缘清洁（长期坚持，每日）、含激素眼膏（短期控制炎症）、睑板腺按摩或理疗（强脉冲光、睑板腺治疗，用于顽固病例）、治疗基础病（合并玫瑰痤疮者请皮肤科会诊，可用多西环素抗炎并改善睑板腺）、人工泪液；④随访：保守治疗者1~3个月评估消退情况，未消退则手术；术后注意复发（完整刮除者复发少，复发者需再次手术并送病理以排除肿瘤）；中老年反复硬结者应行睑板腺癌病理检查，早期诊断重要。眼科处理要点为热敷首选，手术刮除加病理，合并睑板腺功能障碍者需长期管理，中老年者警惕睑板腺癌，重要。","处理方案":"【药物治疗】\n1. 妥布霉素地塞米松眼膏（典必殊）适量涂患眼结膜囊，每日2次，连用1-2周（囊肿炎症明显时短期抗炎消肿，勿长期使用）。\n2. 左氧氟沙星滴眼液0.5%，每次1滴滴患眼，每日3次，连用7天（预防继发感染）。\n3. 妥布霉素眼膏（托百士）适量涂患眼结膜囊，每晚1次，连用1-2周（睡前使用，维持夜间药效）。\n【一般治疗及生活指导】\n1. 热敷：每日3-4次，每次10-15分钟，用40-45℃温热毛巾或蒸汽眼罩敷患眼；热敷后自睑板腺开口侧向睑缘方向轻轻按摩挤压眼睑，促进腺管分泌物排出。\n2. 注意眼部卫生，勤洗手，切忌用手揉眼；毛巾、枕巾勤洗勤换并单独使用，避免交叉感染。\n3. 清淡饮食，忌辛辣刺激及高脂高糖饮食，多饮水；规律作息，避免熬夜，减少长时间使用手机、电脑等电子产品。\n4. 治疗期间暂停化眼妆及佩戴隐形眼镜；囊肿破溃者禁止自行挤压，避免继发眶内感染。\n【随诊要求】\n1. 治疗1-2周后复诊，评估囊肿消退情况。\n2. 若囊肿无明显缩小、持续增大或反复破溃，需复诊行睑板腺囊肿刮除术；出现患眼红痛加剧、分泌物增多、视力下降等感染征象时立即复诊。\n3. 反复多发性睑板腺囊肿者，复诊时排查睑板腺功能障碍及眼睑肿瘤等可能。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":552,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"7a8ded2ee5c68eac920d39f40b8b5b8d5c77914a9c00d17229f62ba0abdb2ced","pinyin":"jianbanxiannangzhong","initials":"jbxnz","setting":"out","caseName":"门诊病历417","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历417",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-4c2435082446b71ec62e","key":"v1-c9ccc21dfe2a3058|templates-4c2435082446b71ec62e","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"睑内翻","category":"门诊病历模板","raw":{"name":"睑内翻","category":"门诊病历模板","case":{"case_name":"门诊病历418","templates":{"主诉":"畏光、流泪伴异物感1年","现病史":"患者（65岁，下睑最常见，为退行性者；其他病因包括瘢痕性（沙眼慢性睑结膜瘢痕收缩致内翻，我国既往沙眼高发，瘢痕性者常见，睑板受累）、痉挛性（眼部刺激或炎症致眼轮匝肌痉挛、瞬目痉挛而内翻）、先天性（婴儿下睑内眦赘皮致睫毛摩擦）、机械性）于2年前出现：睫毛倒睫（睫毛内翻倒向眼球，摩擦角膜与结膜）、异物感（睫毛摩擦，异物感明显）、畏光流泪（刺激角膜反射，泪液多）、眼红（结膜充血）、眼痛（角膜上皮损伤）、视力下降或模糊（长期摩擦致角膜混浊、瘢痕或感染，可发生角膜炎、角膜溃疡甚至穿孔，为严重并发症，影响视力）等。既往有沙眼史（瘢痕性睑内翻，我国常见）、眼部炎症或手术外伤史（可致瘢痕）、内眦赘皮（婴儿或儿童）、单纯倒睫（无睑内翻者，睫毛内翻但睑缘位置正常）、角膜炎或结膜炎（继发）、刺激程度。今日来我院眼科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.8℃，P78次/分，R18次/分，BP120/80mmHg。睑缘内翻（下睑多见，老年者），睫毛内倒并摩擦角膜（睑缘位置内翻，需与单纯倒睫鉴别，重要）；睑结膜见沙眼瘢痕（结膜瘢痕线、睑板下沟）、内眦赘皮、眼轮匝肌痉挛；角膜荧光素染色见上皮点状剥脱、浸润、混浊及角膜新生血管、瘢痕；结膜充血，泪膜异常。裂隙灯检查见睫毛与角膜接触部位，用于评估角膜损伤，重要；眼压正常。","辅助检查":"【必做】裂隙灯检查（核心，评估睑缘位置、倒睫与角膜接触情况）、角膜染色（荧光素染色，评估角膜上皮损伤范围）、眼睑检查；【其他】角膜知觉及感染相关检查（疑感染性角膜溃疡时行溃疡培养）、眼睑照相（术前术后对比）、睑板瘢痕评估、倒睫毛囊电解或手术评估。","初步诊断":"1. 睑内翻（退行性（老年）型：睫毛倒向角膜，角膜损伤（上皮点状剥脱、浸润、混浊、新生血管），影响视力，需手术评估）\n（注：治疗（依病因及程度，以手术为主，注意角膜保护）：①退行性（老年下睑者）行手术治疗，即睑内翻矫正，包括睑缩肌修复、轮匝肌缩短（缝线法适用于老年轻中度者，快而简单）、手术矫正（水平睑缩短加睑缩肌复位，依松弛程度选择），效果为矫正内翻、消除倒睫与角膜刺激；手术时机为角膜损伤及症状明显时即手术（老年者长期角膜摩擦有溃疡风险，重要）；②瘢痕性（沙眼瘢痕者）行睑板瘢痕松解、睑板切除或睑板前徙（重睑成形术式），倒睫可行电解、冷冻或激光破坏毛囊（用于少数），严重者行睑板切开或睑板移植（需评估）；③痉挛性者治疗原发刺激（炎症或干眼），严重痉挛可注射肉毒毒素或行轮匝肌手术；④先天性（婴儿）者多为内眦赘皮，多随发育改善（观察至2~3岁），角膜损伤明显者手术矫正内眦赘皮；⑤单纯倒睫：少量者行电解、拔除或冷冻（电解破坏毛囊可防再生，重要），多量者手术；⑥角膜保护：角膜损伤者用人工泪液润滑以防干燥、抗生素眼膏（角膜上皮缺损时防感染）、角膜溃疡者行抗感染治疗（重要）；⑦随访：术后观察眼睑位置矫正、倒睫消失及角膜恢复情况；复发者（老年松弛进展）可再次手术；沙眼活动期应治疗沙眼（阿奇霉素，防进展）；角膜混浊或瘢痕影响视力者评估，严重者可行角膜移植。眼科处理要点为手术矫正、角膜保护、沙眼治疗及随访，重要。","处理方案":"【药物治疗】\n1. 人工泪液：玻璃酸钠滴眼液0.1%（如爱丽）1滴 qid（每日4次），润滑角膜、减轻睫毛摩擦刺激，用于睑内翻导致的眼干、异物感。\n2. 抗生素眼用制剂：妥布霉素滴眼液（如托百士）1滴 qid；或妥布霉素眼膏（如托百士眼膏）每晚睡前涂入结膜囊1次，预防睫毛摩擦所致的角膜上皮损伤后继发感染。\n3. 角膜上皮修复剂：重组人表皮生长因子滴眼液（如贝复舒）1滴 qid，适用于角膜荧光素染色阳性（角膜上皮点状缺损）者，促进角膜修复。\n4. 疗程：上述药物一般连续使用1～2周，至角膜刺激症状消失、角膜上皮修复为止；若症状持续不缓解或反复发作，应停药并转手术矫正，不宜长期依赖药物。\n\n【一般治疗及生活指导】\n1. 注意眼部卫生，勤洗手，避免用手揉搓眼睛，以免加重睑缘内卷及睫毛对角膜的摩擦损伤。\n2. 避免强光、风沙、烟尘等刺激，户外活动可佩戴护目镜；减少长时间近距离用眼，避免视疲劳诱发眼轮匝肌痉挛性睑内翻加重。\n3. 婴幼儿先天性睑内翻多为生理性，可随年龄增长、鼻梁发育自行缓解，家长可每日用食指自下睑缘向下轻轻牵拉眼睑数次，促进外翻复位。\n4. 保守治疗无效或角膜持续受损者应尽早行睑内翻矫正手术（如睑板部分切除术、缝线矫正术、眼轮匝肌缩短术等），切勿自行拔除睫毛或长期贴胶布，以免造成睑缘损伤。\n\n【随诊要求】\n用药后1周复诊，复查视力、角膜荧光素染色及睑缘位置；若角膜刺激症状无缓解、角膜上皮损伤持续或加重，建议转眼科专科行睑内翻矫正手术。保守治疗观察期一般不超过3～4周，症状持续不缓解者应手术矫正，术后按医嘱于1周、1个月复诊评估睑缘位置及角膜恢复情况。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":553,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"380999656dca1e1054c7b01205107a88af45ba3f7cb4c3d83acc0c66045917a5","pinyin":"jianneifan","initials":"jnf","setting":"out","caseName":"门诊病历418","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历418",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-782c4972e31c724dc04c","key":"v1-c9ccc21dfe2a3058|templates-782c4972e31c724dc04c","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"睑外翻","category":"门诊病历模板","raw":{"name":"睑外翻","category":"门诊病历模板","case":{"case_name":"门诊病历419","templates":{"主诉":"眼睑闭合不全伴溢泪1周","现病史":"患者1周前无明显诱因出现睑外翻相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以眼睑闭合不全伴溢泪1周为主诉，眼睑外翻致眼睑闭合不全易引起角膜暴露，为明确角膜有无上皮损伤，急诊完成视力、裂隙灯检查；完善角膜荧光素染色检查排除暴露性角膜炎；患者持续溢泪，完善泪液分泌试验、泪膜破裂时间检查了解泪膜稳定性；完善泪道冲洗检查鉴别单纯睑外翻与合并泪道阻塞所致的溢泪；必要时行石碳酸棉片试验了解泪液引流功能，为手术方式选择提供依据；患者病程中伴轻度乏力，为排除感染、贫血所致乏力，入院即刻完善血常规检查；眼睑手术需经肝肾代谢并评估出凝血及代谢状态，完善肝肾功能检查排除肝肾功能不全；完善血糖、血脂、电解质检查了解有无糖尿病、高脂血症及电解质紊乱等影响创口愈合的因素；完善尿常规、便常规检查排除泌尿系及消化道感染；患者既往体健，无高血压、糖尿病、冠心病等慢性病史，为评估手术及麻醉耐受性、了解心肺及腹部脏器基础状况，病情稳定后完善心电图、胸部X线片、腹部超声检查；若考虑瘢痕性睑外翻，需完善眼睑皮肤组织病理检查明确病因；必要时完善眼眶CT或MRI检查明确有无眼眶占位及骨质改变，完善头颅MRI排除面神经麻痹所致眼睑闭合不全。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 睑外翻\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 左氧氟沙星滴眼液（0.5%）1滴 qid×5-7天：睑外翻致眼睑闭合不全、角膜暴露，用于预防及控制暴露性角结膜炎。\n2. 玻璃酸钠滴眼液（0.1%）1滴 tid-qid：润滑眼表、缓解暴露性干眼，与抗生素滴眼液间隔5-10分钟使用。\n3. 妥布霉素眼膏，每晚睡前涂入下穹窿1次：夜间睑裂闭合不全时持续润滑、保护角膜。\n4. 重组人表皮生长因子滴眼液（贝复舒）1滴 qid×7天：合并角膜上皮点状缺损时促进角膜上皮修复。\n\n【一般治疗及生活指导】\n1. 夜间睡眠时睑裂闭合不全者，涂眼膏后佩戴湿房眼罩或用医用胶带辅助闭合眼睑，避免角膜长时间暴露。\n2. 避免用手揉搓、拉扯下睑，避免强光、风沙、烟尘刺激，外出佩戴防风镜或太阳镜。\n3. 保持眼部清洁，忌辛辣刺激性食物及烟酒，注意休息，避免熬夜及长时间用眼。\n4. 洗脸时动作轻柔，勿用力下压下睑；合并面瘫者注意保护患侧面部，防止外翻加重。\n\n【随诊要求】\n用药期间1-2周复诊一次，复查角膜情况；若出现眼痛、畏光、流泪加重或视力下降，应立即就诊。保守治疗下角膜暴露症状持续或反复出现角膜炎者，建议眼科手术治疗（下睑缩紧术/眼睑成形术或瘢痕松解植皮术）矫正睑外翻，术后按医嘱定期复诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":554,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"2874d726622202ccbd7aa5aba78c123dfa2ac29b4f5b6b64322c238c4772e347","pinyin":"jianwaifan","initials":"jwf","setting":"out","caseName":"门诊病历419","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历419",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-8d32cd90cbe823064e02","key":"v1-c9ccc21dfe2a3058|templates-8d32cd90cbe823064e02","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"上睑下垂","category":"门诊病历模板","raw":{"name":"上睑下垂","category":"门诊病历模板","case":{"case_name":"门诊病历420","templates":{"主诉":"上眼睑下垂1周","现病史":"患者1周前无明显诱因出现上睑下垂相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以上眼睑下垂1周为主诉，近期起病需鉴别神经源性、肌源性及腱膜性病因，为明确提上睑肌肌力及下垂程度，入院即刻完善视力、裂隙灯检查；完善提上睑肌肌力测量、新斯的明试验及疲劳试验，排除重症肌无力所致上睑下垂；为排除胸腺瘤、胸腺增生等重症肌无力常见病因，完善胸部CT（或胸部X线片）检查；必要时完善头颅MRI及MRA检查排除动眼神经麻痹、颅内动脉瘤压迫等中枢病变；患者病程中伴轻度乏力，为排除感染、贫血所致乏力，完善血常规检查；眼睑疾病相关用药及可能的手术治疗需经肝肾代谢，完善肝肾功能检查排除肝肾功能不全；完善血糖、血脂、电解质检查了解有无糖尿病、高脂血症及电解质紊乱（电解质紊乱可加重肌无力症状）；完善尿常规、便常规检查排除泌尿系及消化道感染；患者既往体健，无高血压、糖尿病、冠心病等慢性病史，为评估心肺及腹部脏器基础状况、为后续治疗建立安全基线，完善心电图、胸部X线片、腹部超声检查；若上述检查仍不能明确病因，需与眼眶占位、眼睑肿物相鉴别，必要时完善眼眶CT或MRI检查。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 上睑下垂\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 溴吡斯的明片60mg tid口服×2周（重症肌无力所致上睑下垂首选，晨轻暮重者先完善新斯的明试验及肌电图确诊后用药，据疗效调整剂量）\n2. 甲钴胺片0.5mg tid口服×1月（动眼神经麻痹、外伤或术后神经源性上睑下垂，营养神经、促进神经修复）\n3. 玻璃酸钠滴眼液0.1%每次1滴 tid滴眼（上睑下垂伴角膜暴露、干眼或溢泪者，润滑保护角膜，根据患者具体情况制定个体化方案联合人工泪液）\n\n【一般治疗及生活指导】\n1. 轻度上睑下垂无遮挡瞳孔、不影响视物者可暂观察，避免长时间用眼；遮瞳明显者暂勿驾车、操作机械及从事精细作业，外出注意防绊倒，可临时使用上睑支撑器或医用胶带辅助抬睑改善视野\n2. 儿童患者及早完成视力、屈光、斜视及提上睑肌肌力评估，遮瞳者尽早手术以防形觉剥夺性弱视；疑重症肌无力者记录晨轻暮重变化；术后眼睑闭合不全者夜间涂红霉素眼膏、日间戴湿房镜保护角膜，忌揉眼及剧烈运动\n\n【随诊要求】\n药物治疗者2周后复诊评估疗效并复查肌电图；拟手术者完善术前检查后预约择期手术；术后1周、1个月、3个月复诊，评估眼睑高度、闭合功能及并发症；儿童术后每3～6个月复查视力及屈光状态，随访至学龄期，动态监测弱视发生。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":555,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"70031c5c191da4dc3a4370ad2ce8346e78dffe82c96f77f63943a73df34ceb41","pinyin":"shangjianxiachui","initials":"sjxc","setting":"out","caseName":"门诊病历420","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历420",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-7bcd7c36c8171c559af4","key":"v1-c9ccc21dfe2a3058|templates-7bcd7c36c8171c559af4","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"泪囊炎","category":"门诊病历模板","raw":{"name":"泪囊炎","category":"门诊病历模板","case":{"case_name":"门诊病历421","templates":{"主诉":"溢泪伴内眦红肿、溢脓1年","现病史":"患者（泪囊炎分为慢性与急性：慢性泪囊炎由泪道阻塞所致，鼻泪管阻塞最常见，泪液引流不畅、泪囊潴留继发感染，呈慢性过程，老年女性多见，与解剖狭窄、泪囊结石、鼻腔疾病（鼻息肉、鼻炎致鼻泪管开口阻塞）、沙眼等有关；急性泪囊炎为慢性者急性发作或原发急性，因细菌毒力强，表现为泪囊区蜂窝织炎或脓肿；婴幼儿者多为鼻泪管膜性阻塞（先天性泪道阻塞，泪囊炎常见，出生后溢泪、眼屎多，多数可自行通畅，6个月内约80%）（年龄））于3天前出现：溢泪（持续流泪，迎风或寒冷时加重）、内眦部（泪囊区）隆起（慢性者因黏液或脓性潴留形成泪囊囊肿）、压迫泪囊有黏液或脓性分泌物自泪点返流（指压泪囊有脓性分泌物自泪点溢出，为慢性泪囊炎的特征性表现及确诊线索，重要）、眼屎多，急性者内眦红、肿、热、痛（泪囊区剧痛），脓肿形成（有波动感，皮肤破溃后形成泪囊瘘），发热（全身症状少见），婴幼儿者表现为溢泪、眼屎多（先天性泪道阻塞、泪囊炎），可伴结膜炎、角膜炎等（慢性刺激）、角膜炎（泪囊炎脓性分泌物在眼内可致角膜溃疡，风险高，眼内手术前必须处理泪囊炎，为白内障手术前的感染源，重要，可防眼内炎）、全身疾病（鼻部疾病）、慢性鼻窦炎。今日来我院眼科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.8℃，P78次/分，R18次/分，BP120/80mmHg。内眦部（泪囊区）隆起、红肿（急性者）、有压痛；指压泪囊有分泌物自泪点返流（黏液或脓性，为慢性泪囊炎特征）；泪点位置正常，无外翻或闭塞；泪道冲洗不通，冲洗液自泪点返流，返流物为脓性，提示泪道阻塞；结膜充血；角膜未见异常；鼻腔检查鼻泪管开口未见异常；婴幼儿者可见泪囊区隆起、溢泪；全身无发热（急性者）。","辅助检查":"【必做】泪道冲洗（核心，评估泪道通畅性：通畅者冲洗液入鼻或咽部；不通者冲洗液自上或下泪点返流，返流物为清液、黏液或脓，可诊断慢性泪囊炎）；【影像】泪道造影（X线碘油造影，可显示阻塞部位（鼻泪管）及泪囊形态与大小）、泪囊超声或CT（急性脓肿或蜂窝织炎者，用于评估范围，为引流前评估）、鼻内镜（检查鼻腔病变，如息肉及鼻泪管开口）；【其他】细菌培养（泪囊分泌物，用于急性或反复发作者（金黄色葡萄球菌、肺炎球菌），指导抗生素选择）、泪囊造影（慢性阻塞者定位）、CT（泪囊肿瘤少见，泪囊区肿块、无感染、中年、血泪者需活检鉴别）。","初步诊断":"1. 泪囊炎（急性：泪囊区蜂窝织炎或脓肿；需行泪道冲洗及阻塞部位、分泌物性状检查，并作眼内手术前评估）\n（注：治疗（急性者抗感染加引流，慢性者行泪囊鼻腔吻合术）：①先天性（婴幼儿鼻泪管膜性阻塞）：泪囊按摩（挤压泪囊向下以冲开膜，每日3~4次，重要）、抗生素眼水或眼膏（分泌物多者）、6个月仍未通者行泪道探通（一次探通成功率高，>90%，宜于6~12个月进行），探通失败者再次探通或行泪道插管；②慢性者：保守治疗包括局部按摩、泪囊压迫排空、抗生素眼药（控制分泌物）、定期泪道冲洗（清洗，不能根治）；手术行泪囊鼻腔吻合术（DCR，为核心根治术式，将泪囊与鼻黏膜吻合，建立新通道引流泪液经鼻，泪囊鼻腔吻合成功率>90%，重要），可选内镜下泪囊鼻腔吻合（经鼻微创，面部无瘢痕）或外路DCR，泪囊切除（用于泪囊肿瘤、脓肿、反复吻合失败或老年者）；③急性者：抗感染（全身抗生素，口服阿莫西林克拉维酸或头孢类，覆盖金黄色葡萄球菌及链球菌，疗程7~10天；局部热敷）、脓肿形成有波动感者行切开引流（防破溃形成瘘管）或穿刺抽脓，急性控制后2~3周择期行DCR（根治并防复发，重要）；蜂窝织炎或眶前受累严重者住院静脉用抗生素；④泪囊炎与眼内手术：白内障或青光眼手术前必须处理泪囊炎（慢性泪囊炎化脓菌可入眼内致眼内炎，风险高，重要，应先DCR或控制后再手术，活动性泪囊炎为眼内手术禁忌）；⑤随访：急性者观察红肿是否于48~72小时消退；术后观察DCR后溢泪缓解情况（泪道通畅、冲洗）及复发（吻合口狭窄或闭塞者再次手术）。眼科处理要点为急性者抗生素加引流，慢性者DCR根治，先天性者按摩或探通，眼内手术前评估，重要。","处理方案":"【药物治疗】\n1. 抗菌眼药：左氧氟沙星滴眼液（0.5%）1滴，滴患眼，每日4次×7天；睡前于结膜囊涂妥布霉素眼膏0.5g，连用7天。\n2. 全身抗生素（急性发作或症状较重者）：阿莫西林克拉维酸钾片0.625g，口服，每日2次×7天；青霉素过敏者改用头孢呋辛酯片0.25g，口服，每日2次×7天。\n3. 泪道冲洗：先自下泪点方向挤压泪囊区排出脓性分泌物，再以生理盐水加妥布霉素冲洗泪道，每日1次，连用3天后改每周1～2次，至冲洗液清亮无脓为止。\n\n【一般治疗及生活指导】\n1. 注意眼部及手部卫生，勤洗手，勿用手揉眼；毛巾、脸盆专人专用，定期煮沸消毒。\n2. 积极治疗鼻腔及鼻窦疾病（如鼻炎、鼻窦炎、鼻中隔偏曲等），避免用力擤鼻，保持鼻泪管引流通畅。\n3. 清淡饮食，多饮水，忌辛辣刺激性食物及烟酒，保持大便通畅。\n4. 急性期可局部热敷（每日3次，每次15分钟）促进炎症吸收；切勿自行挤压泪囊区，以免感染扩散引起眶蜂窝织炎。\n\n【随诊要求】\n1. 用药后3～5天复诊，复查眼部体征及泪道冲洗情况，评估疗效并调整治疗方案。\n2. 若出现发热、眼睑或面部红肿蔓延、疼痛加剧等感染扩散征象，应立即就诊。\n3. 反复急性发作或药物治疗无效的慢性泪囊炎，建议完善泪道造影等检查，择期行泪囊鼻腔吻合术（DCR）治疗，术前请于门诊完成相关评估及手术预约。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":556,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"d27b4e802eeef7f13e78784722daf63f50a129ad52092d9954763564f71335de","pinyin":"leinangyan","initials":"lny","setting":"out","caseName":"门诊病历421","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历421",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-3332a67164d267f507fd","key":"v1-c9ccc21dfe2a3058|templates-3332a67164d267f507fd","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"泪道阻塞","category":"门诊病历模板","raw":{"name":"泪道阻塞","category":"门诊病历模板","case":{"case_name":"门诊病历422","templates":{"主诉":"持续溢泪1周","现病史":"患者1周前无明显诱因出现泪道阻塞相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以持续溢泪1周为主诉，为明确泪道阻塞部位及程度，入院即刻完善泪道冲洗检查判断冲洗液是否反流及反流性质；完善泪道探通检查了解阻塞部位；完善荧光素钠试验及泪膜破裂时间检查评估泪液引流功能与泪膜稳定性；为与结膜炎、睑外翻、倒睫等所致溢泪相鉴别，完善视力、裂隙灯检查观察泪小点位置、有无充血及分泌物，必要时行泪液分泌试验排除干眼；泪道手术或置管治疗需评估全身状况，完善血常规检查排除感染、贫血；完善肝肾功能检查排除肝肾功能不全；完善血糖、血脂、电解质检查了解有无糖尿病、高脂血症及电解质紊乱等影响创口愈合及麻醉风险的因素；完善尿常规、便常规检查排除泌尿系及消化道感染；患者病程中伴轻度乏力，上述血常规、电解质检查同时用于明确乏力原因；患者既往体健，无高血压、糖尿病、冠心病等慢性病史，为评估心肺及腹部脏器基础状况、了解手术及麻醉耐受性，完善心电图、胸部X线片、腹部超声检查；若需明确有无泪道占位、结石或鼻部病变，完善眼B超检查，必要时完善眼眶CT或MRI检查。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 泪道阻塞\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 局部抗感染：0.5%左氧氟沙星滴眼液，每次1滴，每日4次，连用7～14天；分泌物较多者可加用妥布霉素眼膏，睡前涂入结膜囊，每晚1次，连用7天，以控制泪囊及结膜囊感染。\n2. 口服抗生素（合并急性泪囊炎或泪囊区感染明显时）：阿莫西林克拉维酸钾片0.457g（阿莫西林0.4g/克拉维酸57mg）口服，每日2次，连用5～7天；青霉素过敏者改用头孢呋辛酯片0.25g口服，每日2次，连用5～7天。\n3. 泪道冲洗：急性炎症控制后行泪道冲洗（生理盐水10ml＋庆大霉素8万U＋地塞米松2.5mg），每周1～2次，帮助排出脓性分泌物并评估泪道通畅情况。\n\n【一般治疗及生活指导】\n1. 泪囊区按摩：用食指指腹自鼻根部泪囊区自下而上加压按摩，每次3～5分钟，每日3～4次，促使泪液及脓性分泌物经泪点排出（对婴幼儿先天性泪道阻塞尤为适用）。\n2. 保持眼部清洁：分泌物多时用无菌棉签蘸生理盐水自内眦向外轻轻擦拭，避免揉眼及不洁物品接触眼部，防止交叉感染。\n3. 生活防护：保证充足休息，避免熬夜及长时间用眼；外出遇风沙、烟尘、强冷风刺激时佩戴防风镜，避免强风直吹眼部。\n4. 饮食清淡，忌辛辣、刺激性食物及饮酒，多饮水，保持大便通畅。\n\n【随诊要求】\n1. 用药及泪道冲洗后1～2周复诊，复查泪道冲洗通畅情况并评估感染控制效果。\n2. 泪道阻塞多需手术解决：婴幼儿可坚持按摩观察至6个月，无效者行泪道探通术；成人反复溢泪或反复泪囊炎发作者建议行泪囊鼻腔吻合术，术后按医嘱于术后1周、1个月复诊，复查泪道通畅情况。\n3. 若出现眼睑红肿、泪囊区疼痛加剧、发热或脓肿形成等急性感染征象，应立即就诊，不可自行用药延误治疗。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":557,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"35350ef42233eeddf38dd5c7b640f8aa67029da5d83efa5ad3e9faf7882067b8","pinyin":"leidaozuse","initials":"ldzs","setting":"out","caseName":"门诊病历422","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历422",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-90a70c996249b072e9ad","key":"v1-c9ccc21dfe2a3058|templates-90a70c996249b072e9ad","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"结膜结石","category":"门诊病历模板","raw":{"name":"结膜结石","category":"门诊病历模板","case":{"case_name":"门诊病历423","templates":{"主诉":"眼异物感1周","现病史":"患者1周前无明显诱因出现结膜结石相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以眼异物感1周为主诉，为明确结石位置、数目及有无角膜上皮擦伤，入院即刻完善视力、裂隙灯检查观察睑结膜结石及角膜情况；完善眼压检查排除眼压异常；为明确异物感是否合并眼底病变所致视功能异常，完善眼底检查及眼底照相；完善OCT检查了解黄斑及视网膜结构；完善视野检查了解视功能损害范围；患者病程中伴轻度乏力，为排除感染、贫血所致乏力，完善血常规检查；完善尿常规、便常规检查排除泌尿系及消化道感染等可致眼部不适的全身因素；患者既往体健，无高血压、糖尿病、冠心病等慢性病史，为评估眼部手术（结石剔除）及用药安全性，完善肝肾功能检查排除肝肾功能不全；完善血糖、血脂、电解质检查了解有无糖尿病、高脂血症及电解质紊乱等影响创口愈合的因素；完善心电图、胸部X线片、腹部超声检查了解心肺及腹部脏器基础状况；若异物感持续加重、视力下降，为鉴别视网膜血管性疾病、黄斑病变及视神经病变，完善荧光素眼底血管造影、眼B超、视觉电生理检查，必要时请相关科室会诊。\n\n（检查清单）\n【必做检查】\n视力、眼压、裂隙灯检查、眼底检查\n\n【影像学检查】\n眼底照相、OCT、视野检查\n\n【其他检查】\n荧光素眼底血管造影、眼B超、视觉电生理","初步诊断":"1. 结膜结石\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 玻璃酸钠滴眼液（0.1%）1滴 qid：润滑眼表、缓解干涩及异物感，疗程2-4周，症状缓解后可减量至bid维持。\n2. 普拉洛芬滴眼液（0.1%）1滴 qid：结石伴结膜充血、炎症明显时使用，疗程1-2周，炎症消退后停药。\n3. 妥布霉素地塞米松滴眼液 1滴 qid：仅用于炎症较重伴分泌物增多者，疗程不超过1周，需监测眼压；不伴炎症者禁用。\n4. 左氧氟沙星滴眼液（0.5%）1滴 qid×5-7天：结石周围伴脓性分泌物、继发感染时加用。\n\n【一般治疗及生活指导】\n1. 注意用眼卫生，勤洗手，戒除用手揉眼习惯，避免眼表反复摩擦刺激。\n2. 减少电子产品连续使用，用眼40-50分钟休息5-10分钟，可远眺或闭目养神，保证充足睡眠。\n3. 饮食清淡，多饮水，多食富含维生素A、C的蔬菜水果（胡萝卜、菠菜、柑橘等），少食辛辣刺激及油腻食物。\n4. 避免风沙、烟尘等刺激环境，外出可佩戴防护镜；炎症期暂停化妆及佩戴隐形眼镜。\n\n【随诊要求】\n1. 结石穿破结膜表面引起明显异物感、刺痛或畏光流泪者，应于眼科行表面麻醉下剔除或刮除术，术后1周复诊复查。\n2. 治疗后症状无缓解或加重，出现眼红、眼痛、畏光或视力下降者，及时复诊。\n3. 结膜结石易复发，建议每3-6个月门诊复查1次；合并干眼、睑板腺功能障碍者应遵医嘱长期随访并治疗原发病。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":558,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"2a0fdb96d1f779709fb5e3d16f9c57a06a455c6e2f5e84ff9ccbe6e99dad7fa0","pinyin":"jiemojieshi","initials":"jmjs","setting":"out","caseName":"门诊病历423","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历423",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-5699761d7c0924e0efd5","key":"v1-c9ccc21dfe2a3058|templates-5699761d7c0924e0efd5","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"翼状胬肉","category":"门诊病历模板","raw":{"name":"翼状胬肉","category":"门诊病历模板","case":{"case_name":"门诊病历424","templates":{"主诉":"眼角增生物伴眼红、异物感3年","现病史":"患者（户外工作者，如渔民、农民、建筑工人，长期紫外线及风沙、粉尘暴露为最重要危险因素，日光与翼状胬肉相关，故有“渔民眼”之称；老年人长期日晒者）于5年前出现：眼角增生物（位于鼻侧睑裂区球结膜，呈三角形或翼状，尖端（头部）向角膜（黑眼珠）生长，体部位于球结膜，为翼状胬肉的特征）、眼红（胬肉充血、刺激，呈慢性）、异物感（眼干涩、刺激）、视力影响（胬肉头部长入角膜并覆盖瞳孔区（中央）可致视力下降、遮挡，重要；或牵拉角膜引起散光（不规则散光），致视力模糊）、进展（缓慢，头端于角膜缘前呈进行性灰白色隆起；进行期者充血肥厚、头端隆起、进展，静止期者平坦菲薄、充血轻、稳定）等。炎症（胬肉充血、刺激，可急性发作）、手术史（既往胬肉切除后复发常见，重要，需术后随访）、紫外线暴露（职业为户外）、是否佩戴太阳镜（防护）、假性胬肉（外伤或炎症后球结膜与角膜黏连，需鉴别，表现为不同部位、无翼状形态）、角膜缘肿瘤（少见，需鉴别）。今日来我院眼科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.8℃，P78次/分，R18次/分，BP120/80mmHg。眼科检查：视力；裂隙灯检查（核心）：胬肉位于鼻侧睑裂区（常见，颞侧少见，可为双侧），形态呈三角形，可见头部（角膜上灰白色尖端）、颈部、体部（球结膜增厚血管，呈翼状），大小以头部侵入角膜的毫米数表示，评估是否至瞳孔区覆盖；判断进行期或静止期（依充血及血管化程度评估）；角膜见胬肉周围散光；球结膜充血；泪膜检查并见干眼；眼球运动正常，胬肉不限制眼球运动，可与假性胬肉或肿瘤鉴别；眼压正常；眼底正常。","辅助检查":"【必做】裂隙灯检查（核心，确诊及评估）；【影像】角膜地形图（胬肉，散光，评估，术前）；【照相】（裂隙灯照相记录，随访对比，进展评估，重要）；【其他】（干眼评估（泪膜，泪液分泌，胬肉与干眼相关，并见）、疑恶变（少见，形态不典型，快速增大，手术，病理）。","初步诊断":"1. 翼状胬肉（左眼，鼻侧，头部侵入角膜约3mm（未至瞳孔区），静止期，伴干眼及散光，需评估）\n（注：治疗（依大小、症状、进展及视力：小者观察，大者或影响视力者手术）：①保守或观察（静止期小胬肉，未近瞳孔、无视力影响者）：观察随访（每6~12个月行裂隙灯检查并记录，评估进展，重要）；有症状者（充血、刺激、异物感）用人工泪液（玻璃酸钠）缓解干涩与刺激，非甾体抗炎滴眼液（普拉洛芬）短期控制充血及炎症刺激；②防护（关键，防进展及防复发）：佩戴太阳镜（防紫外线，重要，紫外线为主要病因，户外必须佩戴防紫外线太阳镜或宽沿帽）、避免风沙粉尘（职业防护镜）、对户外工作者进行宣教；③手术：适应证为头部侵入角膜近瞳孔或覆盖瞳孔（视力下降，重要）、进行期明显进展（影像记录1~2年，有侵入瞳孔趋势）、影响散光或视力（规则散光、白内障术前角膜屈光需评估）、反复炎症（刺激明显，影响生活）、美容需求（外观明显者择期）。手术方式为胬肉切除加自体结膜移植（取上方自体球结膜移植覆盖创面以降低复发：单纯切除复发率为30%~50%，加结膜移植后<10%，重要，为标准术式），可联合丝裂霉素C或羊膜移植（用于复杂或复发病例）；术后用激素及抗生素滴眼液抗炎防感染，随访监测复发，复发者再次手术，术后仍需防紫外线（重要）；④随访：保守者每6~12个月观察胬肉变化（照相对比），术后1周、1个月、3个月观察创面愈合及复发，长期防紫外线。眼科处理要点为紫外线防护是根本，小者观察，大者手术加结膜移植并防复发，重要。","处理方案":"【药物治疗】\n1. 人工泪液（首选基础治疗）：玻璃酸钠滴眼液0.1%，每次1滴，每日4次，可长期使用，缓解眼干、异物感、烧灼感等刺激症状；干眼症状明显者可与聚乙烯醇滴眼液交替使用。\n2. 非甾体抗炎滴眼液：普拉洛芬滴眼液0.1%，每次1滴，每日3次，用于胬肉体部充血、炎症明显者，连用2-4周后复诊评估，症状缓解后减量至每日1-2次维持。\n3. 糖皮质激素滴眼液（仅限炎症反复发作、充血明显者短期使用）：氟米龙滴眼液0.02%，每次1滴，每日2-3次，连用1-2周，用药期间每2周监测眼压，症状控制后即停药，不建议长期患者。\n【一般治疗及生活指导】\n1. 注意眼部防晒：户外活动（尤其日光强烈、风沙大的环境）佩戴防紫外线太阳镜并配合遮阳帽，长期户外作业者（渔民、农民、建筑工人）须坚持佩戴防护眼镜，减少紫外线及风尘刺激。\n2. 避免揉眼及眼部机械摩擦：不用手揉眼、不随意使用不洁毛巾擦眼，减少胬肉反复受刺激充血；长时间用电脑手机者每用眼1小时远眺休息5-10分钟，缓解视疲劳。\n3. 保持清淡均衡饮食，多食富含维生素A、C的蔬菜水果，忌辛辣刺激性食物，戒烟限酒。\n4. 合并干眼症者遵医嘱规律滴用人工泪液，保持眼表湿润，减少胬肉表面干裂、充血不适。\n【随诊要求】\n1. 药物治疗者每1-3个月复诊1次，评估症状缓解及胬肉充血、体部厚度变化情况。\n2. 胬肉头部越过角膜缘向角膜中央进展超过2-3mm、接近或覆盖瞳孔区、引起明显散光或影响视力者，建议行翼状胬肉切除联合自体结膜移植术，术后按医嘱于术后1周、1个月、3个月复查。\n3. 随访中出现眼红加重、疼痛、分泌物增多或视力下降等异常情况，应随时就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":559,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"c98f4213b199c321ab6c2e615a55b5e76aa1d525b6ace29656f33e3bf497163a","pinyin":"yizhuangnurou","initials":"yznr","setting":"out","caseName":"门诊病历424","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历424",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-363d8e2d44997de45dc8","key":"v1-c9ccc21dfe2a3058|templates-363d8e2d44997de45dc8","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"巩膜炎","category":"门诊病历模板","raw":{"name":"巩膜炎","category":"门诊病历模板","case":{"case_name":"门诊病历425","templates":{"主诉":"眼痛、眼红1周","现病史":"患者1周前无明显诱因出现巩膜炎相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以眼痛、眼红1周为主诉，巩膜炎常与感染及自身免疫性疾病相关，为排除感染因素，入院即刻完善血常规检查；完善尿常规、便常规检查排除泌尿系及消化道感染灶；为排除痛风、类风湿关节炎等代谢及免疫性疾病所致巩膜炎，完善肝肾功能（含血尿酸）、血糖、血脂、电解质检查，了解有无高尿酸血症及电解质紊乱；完善红细胞沉降率、C反应蛋白等炎症指标检查评估炎症活动度；必要时完善抗核抗体谱、抗中性粒细胞胞浆抗体等自身抗体检查明确有无系统性血管炎；患者既往体健，无高血压、糖尿病、冠心病等慢性病史，为评估全身状况及长期用药安全性，完善心电图、胸部X线片、腹部超声检查，了解有无心肺及腹部脏器病变（胸部X线片同时用于排除结核等感染）；眼部为明确巩膜受累范围及厚度、有无坏死及葡萄膜炎，完善视力、裂隙灯检查及眼压检查；必要时完善眼B超、眼眶CT或MRI检查，与巩膜葡萄肿、眼眶炎性假瘤相鉴别；若病情迁延，需定期复查上述指标评估疗效并筛查结核、梅毒等感染性疾病。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 巩膜炎\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 非甾体抗炎药（一线首选）：布洛芬缓释胶囊0.3g bid 口服×2周，症状缓解后减为0.3g qd 继续1周；或萘普生肠溶片0.25g bid 口服×2周。注意饭后服用，既往有消化性溃疡、肾功能不全者慎用。\n2. 重度或NSAIDs治疗1周无效者：醋酸泼尼松片60mg qd 晨起顿服（按体重约1mg/kg/d），连用1周后若炎症消退，每5～7天减量5～10mg，总疗程4～6周，缓慢减停，切忌骤停。\n3. 顽固性、反复发作或激素依赖者：加用甲氨蝶呤片7.5mg 每周1次口服（可渐加至15mg/周），同时每日口服叶酸片5mg（甲氨蝶呤后24小时服用），用药期间每2周复查血常规、肝肾功能。育龄期女性用药前需排除妊娠。\n4. 局部辅助治疗：0.1%氟米龙滴眼液 qid 滴患眼，炎症减轻后递减；合并明显睫状体疼痛者加1%阿托品眼用凝胶散瞳 bid，注意压迫泪囊防止全身吸收。\n\n【一般治疗及生活指导】\n1. 充分休息、保证睡眠，减少用眼：避免长时间阅读、使用电脑及手机，眼痛明显时闭目休息，暂停眼部化妆。\n2. 饮食清淡，忌烟酒及辛辣刺激食物；适量补充维生素C及富含维生素的食物，控制血压、血糖（高血压、糖尿病患者尤需规范用药）。\n3. 避免揉眼、挤压眼球，外出可戴墨镜减轻畏光；注意保暖、预防呼吸道感染，因上呼吸道感染可诱发或加重巩膜炎。\n4. 停用或慎用可能与巩膜炎相关的药物（如双膦酸盐类）；注意排查类风湿关节炎、系统性红斑狼疮、结节病、肉芽肿性多血管炎等全身疾病，必要时转风湿免疫科会诊。\n\n【随诊要求】\n1. 治疗期间每周复诊1次，监测视力、眼压及巩膜炎症变化，直到炎症完全消退；滴用糖皮质激素期间每次复诊均需测眼压。\n2. 口服糖皮质激素者每2周复查血糖、血压、电解质，长期用药者监测骨密度；服用甲氨蝶呤者每2周复查血常规、肝肾功能。\n3. 若出现剧烈眼痛、视力骤降、眼球突出或转动痛加重，提示可能并发坏死性巩膜炎或巩膜穿孔，须立即急诊复诊。\n4. 症状缓解后仍需在停药后2～4周复诊1次评估有无复发；反复发作或双眼受累者建议完善抗核抗体、类风湿因子、ANCA、梅毒及结核筛查，明确病因后专科长期随访。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":560,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"99b6cb25e98a8b9f318f8911e6027fd1056f9e7070c3ab45bd066e44f83ac147","pinyin":"gongmoyan","initials":"gmy","setting":"out","caseName":"门诊病历425","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历425",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-044e1dde2dc22f7c77ce","key":"v1-c9ccc21dfe2a3058|templates-044e1dde2dc22f7c77ce","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"葡萄膜炎","category":"门诊病历模板","raw":{"name":"葡萄膜炎","category":"门诊病历模板","case":{"case_name":"门诊病历426","templates":{"主诉":"眼红、眼痛伴视力下降1周","现病史":"患者于3天前（急性起病，突发，为虹膜睫状体炎即前葡萄膜炎，常见；慢性或隐匿者见于后葡萄膜炎或全葡萄膜炎）出现：眼红（睫状充血，位于角膜周围，呈深红色，为特征，区别于结膜炎的浅表鲜红且远离角膜）、眼痛（眼深部痛，为睫状体痛，有按压痛）、畏光（明显，因炎症致光刺激）、流泪、视力下降（前葡萄膜炎者因房水混浊及角膜后沉着物（角膜内皮KP，呈羊脂状或尘状，为特征）；后葡萄膜炎者因玻璃体混浊及视网膜脉络膜病变，表现为黑影飘动）、眼前黑影（玻璃体炎性细胞飘动）、飞蚊、视物变形（黄斑水肿）等。有无全身病（葡萄膜炎常为全身病的眼部表现，重要，需查病因）：强直性脊柱炎（HLA-B27阳性，为前葡萄膜炎最常见病因，男性，腰痛、晨僵、脊柱炎，我国常见，重要）、白塞病（复发性葡萄膜炎，伴口腔溃疡、生殖器溃疡及皮肤损害，为白塞病，可致全葡萄膜炎，严重）、结节病、结核（我国结核性葡萄膜炎为肉芽肿性）、梅毒、弓形虫（后葡萄膜炎，视网膜坏死灶，有猫接触史）、巨细胞病毒（免疫低下、HIV）、风湿类疾病（类风湿，少见）、炎症性肠病、Vogt-小柳原田病（双眼肉芽肿性，伴白发、脱发、耳鸣、听力下降，我国多见，重要）、交感性眼炎（眼外伤或手术后，健眼迟发，累及对侧）、单纯特发性（约半数查不到病因，需随访）、儿童幼年特发性关节炎（前葡萄膜炎，隐匿，女孩，抗核抗体阳性）；复发性（反复发作可致虹膜后黏连（瞳孔不规则，防黏连需散瞳，重要）、青光眼（炎症或黏连继发高眼压）、白内障（慢性炎症或激素致并发）、黄斑水肿（后葡萄膜炎者影响视力，重要并发症）、低眼压或眼球萎缩（晚期严重，需防））。今日来我院眼科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.8℃，P78次/分，R18次/分，BP120/80mmHg。眼科检查：视力（评估下降程度）；裂隙灯检查：睫状充血（角膜周围，深红）、角膜后沉着物（KP，羊脂状见于肉芽肿性（结节病、结核、Vogt-小柳原田病），尘状见于非肉芽肿性（HLA-B27相关或特发））、房水闪辉（蛋白，炎症，前房闪辉+~+++）、浮游细胞（炎性细胞+~+++）、前房积脓（白塞病者严重，前房脓液有液平）、虹膜后黏连（虹膜与晶状体黏连，散瞳后瞳孔不规则，瞳孔缘粘连）、瞳孔缩小（炎症所致，对光反射存在）、晶状体后囊白内障、玻璃体混浊及细胞（中间或后部炎症）、散瞳后眼底检查见视乳头水肿、视网膜血管炎（白塞病）、黄斑水肿、脉络膜病灶（弓形虫者可见陈旧瘢痕）、眼压（继发青光眼者高或低）。裂隙灯及散瞳检查全面评估，重要。","辅助检查":"【必做】眼科全面检查（裂隙灯加散瞳眼底，核心）；【病因筛查】血常规、血沉及CRP（炎症）、HLA-B27（前葡萄膜炎，筛查强直性脊柱炎，男性反复发作伴腰痛者重要）、梅毒血清学（梅毒性葡萄膜炎，可治，重要）、结核相关检查（结核菌素试验、γ-干扰素释放试验、胸片，我国结核重要，肉芽肿性）、弓形虫抗体（后葡萄膜炎）、抗核抗体及类风湿因子（结缔组织病、幼年关节炎，儿童）、血管紧张素转化酶及胸片（结节病）、HIV（巨细胞病毒视网膜炎，免疫低下）、荧光密螺旋体抗体吸收试验（特异）；【影像】眼底荧光血管造影（评估视网膜血管炎及黄斑水肿）、光学相干断层扫描（黄斑水肿，定量随访）、眼部超声（屈光间质混浊时评估眼底）；【专科】风湿免疫科或内科会诊排查全身病并联合治疗，重要（白塞病、强直性脊柱炎、结节病需全身治疗）；【随访评估】眼压（青光眼）、视力、炎症分级。","初步诊断":"1. 葡萄膜炎（前葡萄膜炎（虹膜睫状体炎），急性，非肉芽肿性，病因（HLA-B27相关、结核、白塞病、特发性）待查，需评估并发症（虹膜黏连、青光眼、白内障、黄斑水肿））\n（注：治疗（控制炎症加散瞳防黏连加病因治疗，为眼科急症，威胁视力，激素为核心）：①散瞳（关键，立即使用睫状肌麻痹剂（阿托品或托吡卡胺）散瞳，放松睫状肌、止痛并防虹膜后黏连（重要，防瞳孔闭锁），活动期每日维持散瞳）；②糖皮质激素（核心，控制炎症）：局部用于前葡萄膜炎，用激素滴眼液（醋酸泼尼松龙或地塞米松），急性期频繁点眼（每小时至每2小时），逐渐减量，重要（眼内炎症以激素控制，前房闪辉及细胞减少后减量，勿骤停，防复发）；球周或玻璃体腔注射（后葡萄膜炎者用曲安奈德，缓释，用于重症）；全身治疗口服泼尼松（重症、双眼、后葡萄膜炎或伴全身病者，0.5~1mg/kg/d，逐渐减量），需监测眼压（激素性青光眼）及白内障（长期使用需权衡）；③病因及全身治疗：HLA-B27相关或强直性脊柱炎者转风湿科（用非甾体抗炎药或生物制剂如抗肿瘤坏死因子，控制脊柱炎及葡萄膜炎，重要）；结核者抗结核治疗（同时用激素，防结核扩散）；驱梅治疗用青霉素；白塞病者用激素加免疫抑制剂（环孢素、硫唑嘌呤，严重威胁视神经时用生物制剂如抗肿瘤坏死因子）；弓形虫者抗弓形虫治疗；巨细胞病毒者抗病毒治疗；Vogt-小柳原田病者用大剂量激素加免疫抑制，防视网膜脱离；④并发症处理：青光眼（监测眼压，用药物如β受体阻滞剂，继发者处理）、白内障（炎症控制后手术，围术期用激素）、黄斑水肿（非甾体抗炎滴眼液、激素或免疫抑制）；⑤随访：炎症（裂隙灯观察细胞及闪辉并分级，调整治疗，缓慢减量）、眼压（激素使用期间每周监测，防青光眼）、视力（恢复情况）、全身病（相关专科随访）。眼科处理要点为散瞳加激素、病因筛查、防黏连及防并发症，合并全身病者多学科协作，重要。","处理方案":"【药物治疗】\n1. 糖皮质激素（首选局部，急性期频点）：醋酸泼尼松龙滴眼液（百力特）1滴 qid，急性炎症期可增至1滴 q1~2h，炎症控制后逐步减量，疗程4~8周；前房炎症明显或局部疗效不佳者，加用醋酸泼尼松龙口服30~40mg qd（按泼尼松0.5~1mg/kg/d），晨起顿服，炎症消退后每1~2周减5mg，总疗程4~8周，需逐渐减停，不可骤停。\n2. 睫状肌麻痹剂（散瞳、防粘连）：1%硫酸阿托品眼用凝胶1滴 bid（急性期），待瞳孔充分散大、炎症减轻后改为1滴 qd维持至炎症消退；轻症者可用复方托吡卡胺滴眼液1滴 tid。\n3. 非甾体抗炎药（辅助抗炎）：普拉洛芬滴眼液1滴 qid 或双氯芬酸钠滴眼液1滴 qid，与糖皮质激素联合使用，疗程同激素。\n4. 顽固或反复发作、激素依赖者（如Behcet病、Vogt-小柳原田病等）：加用免疫抑制剂，如环孢素胶囊2~5mg/kg/d分2次口服，或甲氨蝶呤片7.5~15mg qw，患者风湿免疫科/眼科专科医师指导下患者并监测血药浓度及肝肾功能。\n【一般治疗及生活指导】\n1. 充分休息，避免熬夜及长时间近距离用眼；急性期减少户外活动，外出佩戴墨镜以减轻畏光、流泪等刺激症状。\n2. 饮食清淡，忌辛辣刺激、烟酒及过食肥甘厚味；适当补充富含维生素A、C、E的食物（如胡萝卜、深色蔬菜、柑橘类），均衡营养。\n3. 急性期避免剧烈运动及重体力劳动，防止眼压波动；保持眼部清洁，勿用手揉眼，点药前后洗手。\n4. 局部患者糖皮质激素期间监测眼压，若出现眼胀、眼痛、视物模糊加重或虹视，及时就诊；全身用激素者注意低盐低糖饮食、补钙，预防血压血糖升高及骨质疏松。\n【随诊要求】\n1. 初次就诊或急性期患者3~7天内复诊，复查视力、裂隙灯前房炎症分级、眼压；此后每1~2周复诊1次至炎症稳定，缓解期每2~4周复诊1次。\n2. 每次复诊评估虹膜后粘连、晶状体混浊及玻璃体炎症情况；长期局部或全身用糖皮质激素者，每次复诊必测眼压，并定期（每1~3个月）检查血糖、血压。\n3. 全身患者激素或免疫抑制剂者，遵医嘱定期（每2~4周）复查血常规、肝肾功能、电解质，必要时监测血药浓度；出现视力骤降、剧烈眼痛、发热或皮疹等全身症状时立即就诊。\n4. 反复发作或双眼受累、怀疑全身性疾病（Behcet病、强直性脊柱炎、结节病、结核等）者，建议转诊风湿免疫科、感染科等相关科室联合筛查，完成病因学检查后继续专科随诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":561,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"a80901df25ce31e3c34e1e1c3141e81563d92271c5fd03ede9bfeb5e76ea8c13","pinyin":"putaomoyan","initials":"ptmy","setting":"out","caseName":"门诊病历426","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历426",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-a5f2effd7225119260e8","key":"v1-c9ccc21dfe2a3058|templates-a5f2effd7225119260e8","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"视网膜脱离","category":"门诊病历模板","raw":{"name":"视网膜脱离","category":"门诊病历模板","case":{"case_name":"门诊病历427","templates":{"主诉":"眼前闪光、黑影增多伴视野缺损3天","现病史":"患者为高危人群（高度近视（>600度，视网膜变薄，裂孔好发）、无晶体眼或白内障术后、有眼外伤史者，或视网膜格子样变性者），于3天前开始出现眼前闪光感（牵拉视网膜，位于周边视野）、黑影飘动（飞蚊）突然增多（提示玻璃体后脱离或玻璃体积血）、视野缺损（幕帘样或黑影自某方向逐渐扩大，与视网膜脱离区域对应，下方脱离可出现上方视野缺损）、视物变形。3天来视力下降（黄斑脱离可致中心视力下降；若黄斑未脱离，中心视力可保留；急症手术时机关键），无眼红眼痛（本病为无痛性，区别于炎症）。今日来我院急诊眼科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"视力：右0.1，左0.6。眼压：右12mmHg，左15mmHg。裂隙灯检查：前节正常，无炎症。散瞳眼底检查（关键）：玻璃体见后脱离或积血、色素细胞（Shafer征，为视网膜裂孔标志）；眼底可见视网膜灰白色隆起（波浪状），血管爬行于隆起表面，可见裂孔（马蹄形或圆形，好发于颞上，表现为红点或撕裂缘），并见脱离范围（象限及黄斑受累与否，此为关键，决定急症程度）；对侧眼行眼底检查，注意裂孔及变性，以评估预防性治疗指征。","辅助检查":"【必做】散瞳后详细眼底检查（间接检眼镜加三面镜，确定裂孔位置及脱离范围，为诊断关键）；【影像】眼部超声（屈光间质混浊（白内障或玻璃体积血）时评估视网膜脱离形态）；【其他】眼压（脱离眼可偏低，用于鉴别）、对侧眼检查（预防性评估）。","初步诊断":"1. 孔源性视网膜脱离（右眼，黄斑未累及，裂孔位置颞上方）\n（注：视网膜脱离为眼科急症，需尽快手术（裂孔性者手术封闭裂孔使视网膜复位；时机：黄斑未脱离者48~72小时内急诊手术，视力预后好，可保住中心视力；黄斑已脱离者1周内手术，中心视力恢复有限，周边视野恢复，越早越好）；术前处理：卧床（裂孔朝下体位，减少脱离进展）、避免剧烈活动及头部震动；手术方式：巩膜环扎加外路手术（裂孔明确、年轻患者）或玻璃体切除加气体或硅油填充加激光或冷凝封闭裂孔（内路，常用，上方裂孔气体填充，术后俯卧位）；术后体位（气体填充者取俯卧或面向下，按医嘱）、避免乘坐飞机（气体膨胀可致眼压升高，气体吸收前（2~8周）禁飞行）；高度近视者（>600度，对侧眼裂孔风险高）需行对侧眼散瞳检查，无脱离时对裂孔行预防性激光；随访（复位评估、视力，术后3个月稳定后定期复查）；眼外伤或运动（拳击、跳水）防护，高危者尤需注意。）","处理方案":"【药物治疗】\n1. 抗感染（术前准备及术后预防感染）：左氧氟沙星滴眼液0.5%，1滴/次，每日4次，术前3天开始至术后14天。\n2. 抗炎（减轻术后炎症反应）：妥布霉素地塞米松滴眼液，1滴/次，每日4次，术后连用7天，之后按复查情况每1-2周递减频次，总疗程约4周，用药期间定期监测眼压。\n3. 散瞳/睫状肌麻痹（散瞳查眼底、防止术后虹膜粘连）：复方托吡卡胺滴眼液，1滴/次，每日2-3次，按医嘱在术前及术后使用。\n4. 全身用药（术后感染高危或全身情况需要时）：头孢呋辛酯片0.25g，每日2次，餐后口服，连用5天（青霉素或头孢过敏者禁用，改用阿奇霉素片0.5g每日1次×5天）。\n【一般治疗及生活指导】\n1. 休息体位：确诊后绝对卧床休息、双眼遮盖制动，根据裂孔位置取相应体位（上方裂孔取仰卧位，下方裂孔取坐位或半卧位，后极部裂孔取头低位），使裂孔处于最低位以利视网膜复位，术前减少眼球转动及头部震动。\n2. 避免一切屏气用力动作：禁止提重物、剧烈咳嗽、打喷嚏、用力排便、长时间低头及剧烈运动（跑步、跳跃、对抗性运动），保持大便通畅，必要时予乳果糖口服通便。\n3. 饮食清淡易消化，多食蔬菜水果等富含纤维素食物，忌辛辣刺激饮食、浓茶、咖啡及烟酒，保证充足睡眠。\n4. 尽快安排手术治疗，本病以手术（巩膜环扎/外加压或玻璃体切割术）为唯一有效治疗，切勿因症状暂缓而延误手术时机。\n【随诊要求】\n1. 术前每日复诊评估病情进展；术后第1天、第1周、第2周、第1个月、第3个月定期复查视力、眼压及眼底，视恢复情况调整复查频率。\n2. 眼内填充气体者，气体完全吸收前（约2-6周）绝对禁止乘坐飞机、进入高原地区及潜水，并继续保持特定体位至气体吸收。\n3. 出现眼前黑影突然扩大、闪光感增多、视野缺损加重、眼痛伴恶心呕吐（警惕继发高眼压）等任何异常，立即急诊就诊。\n4. 定期行对侧眼散瞳眼底检查，及时发现并处理对侧眼的视网膜变性区、干性裂孔或格子样变性，预防双眼发病。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":562,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"e94c7758f6fc99a53437617d459c7884870cbbef49bdf2f5a92f5b6898064592","pinyin":"shiwangmotuoli","initials":"swmtl","setting":"out","caseName":"门诊病历427","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历427",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-c72a54f4c09108515634","key":"v1-c9ccc21dfe2a3058|templates-c72a54f4c09108515634","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"视网膜动脉阻塞","category":"门诊病历模板","raw":{"name":"视网膜动脉阻塞","category":"门诊病历模板","case":{"case_name":"门诊病历428","templates":{"主诉":"单眼突发无痛性视力丧失6小时","现病史":"患者（老年人，存在动脉粥样硬化、高血压、糖尿病、房颤、颈动脉斑块等栓子来源；或巨细胞动脉炎（颞动脉炎，多见于>50岁，伴头痛、颞动脉压痛、咀嚼痛，血沉升高，需紧急识别，为全身血管炎））于6小时前突然出现单眼无痛性视力完全丧失或严重下降（中央动脉阻塞表现为完全黑矇；分支动脉阻塞表现为相应视野缺损（象限性）），发病急骤（数秒至数分钟，因栓塞或血栓；一过性黑矇可为其先兆（短暂性脑缺血发作眼型，需评估卒中风险））。有无眼前手动或光感（提示残留，见于部分阻塞或睫状视网膜动脉供血）、眼痛（本病无眼痛，区别于青光眼）、对侧眼一过性黑矇史，有无心血管事件（卒中或TIA史）及巨细胞动脉炎症状（头痛、发热、肌痛，风湿性多肌痛）。今日来我院急诊眼科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"视力：右手动（手动、光感或无光感）。相对性传入性瞳孔障碍（RAPD）阳性，患眼对光反应减弱，为重要体征。眼压正常（排除青光眼，高眼压也可致视力骤降）。眼底检查（核心）：视网膜见弥漫性灰白色水肿（后极部，缺血所致）、黄斑樱桃红斑（中心凹脉络膜血管透见，特征性，为中央动脉阻塞标志）、视网膜动脉变细（血流柱间断呈节段状）、栓子（位于视网膜动脉分叉处，黄色斑块为胆固醇栓子或白色为血小板栓子）；若为分支阻塞，则相应象限灰白水肿。颈动脉听诊注意有无杂音（提示颈动脉狭窄）。","辅助检查":"【必做】眼底检查（确诊依据，特征性樱桃红斑加灰白水肿）；【急诊处理评估】血沉及CRP（>50岁疑巨细胞动脉炎者，急诊鉴别，需紧急激素治疗以防对侧眼受累及全身血管并发症，重要）、血压血糖血脂（动脉硬化危险因素）、颈动脉超声（颈动脉狭窄，栓子来源）、心脏评估（房颤所致心源性栓塞，行心电图及超声心动图）；【影像】眼底荧光血管造影（不常规，诊断典型者不必行，可见动脉充盈延迟或无灌注）；【神经】头颅影像（合并神经系统症状或疑卒中者，评估颈动脉及颅内情况，用于TIA评估）。","初步诊断":"1. 视网膜中央动脉阻塞（右眼，栓子性或血栓性待查，需急诊处理）\n（注：视网膜动脉阻塞为眼科及全身急症（视网膜缺血，挽救时间窗极短，约90~100分钟，超过后神经不可逆损伤，多数视力预后差，但必须急诊处理并评估全身血管风险）：①急诊抢救（发病后尽早，<24小时内尝试，疗效有限但部分有效）：眼球按摩（间断按压，降眼压促栓子移动）、前房穿刺（紧急降眼压）、吸入95%氧加5%二氧化碳（扩张血管）、降眼压药物（静滴甘露醇或口服乙酰唑胺，促栓子移动）、血管扩张剂（舌下含服硝酸甘油，全身低血压者慎用）；②全身评估（关键，防卒中及对侧眼受累，急查血沉CRP，若为巨细胞动脉炎，立即大剂量糖皮质激素（甲泼尼龙1g冲击或泼尼松60~80mg/d），防对侧眼失明及主动脉并发症，需紧急处理，勿等活检，再行颞动脉活检证实；颈动脉超声，狭窄>70%者评估颈动脉内膜剥脱，用于卒中二级预防；房颤者抗凝；控制高血压、糖尿病、血脂，非巨细胞动脉炎性者予抗血小板（阿司匹林100mg qd）；③随访（眼科随访视神经萎缩及视力，多数永久受损，少数有睫状视网膜动脉者部分恢复；神经科随访，进行卒中预防长期管理）。）","处理方案":"【药物治疗】\n1. 血管扩张剂：硝酸甘油片0.5mg舌下含服，必要时每5分钟1次，最多连用3次；或亚硝酸异戊酯0.2ml压碎吸入，立即使用，扩张视网膜血管、改善灌注。\n2. 降低眼压：乙酰唑胺片首剂0.5g口服，继以0.25g bid×3～5天（青光眼或有磺胺过敏史、肾功能不全者慎用，注意低钾、肢端麻木等不良反应），降低眼压以提高视网膜动脉灌注压。\n3. 抗血小板聚集：阿司匹林肠溶片0.1g qd口服长期维持；发病72小时内可联合氯吡格雷片75mg qd，双联1～3周后改单药维持，预防再栓塞及心脑血管事件。\n4. 改善循环及神经营养：甲钴胺片0.5mg tid口服×4周，维生素B1片10mg tid口服×4周，促进视网膜神经功能恢复。\n【一般治疗及生活指导】\n1. 发病后应静卧休息，避免情绪激动及屏气用力（用力排便、剧烈咳嗽、提重物），防止栓子再次脱落、加重缺血。\n2. 每日多次眼球按摩：闭眼后用食指指腹轻压眼球10～15秒后突然放松，反复5～10次，有助于推动栓子移向末梢血管。\n3. 饮食清淡、低盐低脂，戒烟限酒，规律监测并控制血压、血脂、血糖；避免长时间低头、剧烈运动及揉搓眼球。\n4. 本病属眼科急症，救治时间窗短，若发病后视力无恢复或再次下降，须立即复诊或转诊，切勿延误。\n【随诊要求】\n1. 发病后24～48小时内复诊，复查视力、眼压及眼底，观察视盘水肿、\"樱桃红斑\"及血管再通情况。\n2. 1周后复诊复查眼底、OCT及视野，评估视网膜水肿消退与视功能恢复程度。\n3. 转诊心内科、神经内科完善病因检查：颈动脉彩色多普勒超声、心脏彩超、心电图等，排查颈动脉狭窄、心源性栓塞及动脉粥样硬化，并系统控制血压、血脂、血糖。\n4. 此后每1个月随访1次至3～6个月，监测对侧眼视力，预防复发及脑血管事件。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":563,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"bc767b218f8f9d62821bd4c311f101d2e2fb8011c3fc82d5451f2ce203120938","pinyin":"shiwangmodongmaizuse","initials":"swmdmzs","setting":"out","caseName":"门诊病历428","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历428",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-267c65f04e70dfd1a573","key":"v1-c9ccc21dfe2a3058|templates-267c65f04e70dfd1a573","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"视网膜静脉阻塞","category":"门诊病历模板","raw":{"name":"视网膜静脉阻塞","category":"门诊病历模板","case":{"case_name":"门诊病历429","templates":{"主诉":"单眼无痛性视力下降3天","现病史":"患者（中老年（>50岁常见），存在危险因素（高血压（最重要危险因素）、动脉硬化、糖尿病、高血脂、青光眼（眼压高致静脉受压）、血液高黏稠（红细胞增多、血小板异常）、全身血管病（卒中、心梗史）、吸烟、年龄增高））于3天前（突发或数日内，单眼）出现：视力下降（无痛性，单眼；中央静脉阻塞（CRVO）视力下降明显；分支静脉阻塞（BRVO）象限性视力下降较轻）、视物变形（黄斑水肿，为常见并发症）、视野缺损（象限性，见于分支阻塞）、眼前黑影。有无分型表现：缺血型（无灌注，大片毛细血管闭塞，视力差，新生血管风险增高，可致虹膜新生血管及新生血管性青光眼，为严重晚期并发症）、非缺血型（灌注良好，预后较好）；有无黄斑水肿（视力下降主要原因，常见，可逆，为治疗目标）及并发症（黄斑水肿、新生血管（虹膜新生血管可致新生血管性青光眼，眼压高、眼痛、视力丧失，晚期需全视网膜激光预防）、玻璃体积血（新生血管破裂，突发视力下降）、牵拉性视网膜脱离）。询问单眼既往眼病，高血压、糖尿病及血糖血压控制情况。今日来我院眼科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.7℃，P78次/分，R18次/分，BP150/90mmHg。视力下降（记录程度）。眼底（散瞳）：视网膜静脉扩张、迂曲；视网膜出血（火焰状或点状，沿静脉分布，位于视盘周围（中央静脉阻塞）或呈象限分布（分支阻塞））、棉絮斑（提示缺血）、视盘水肿或充血、黄斑水肿（伴硬性渗出）、无灌注区（经FFA确认）；眼压（评估青光眼及新生血管性青光眼，晚期尤需注意）、裂隙灯（观察前节及房角有无新生血管、虹膜红变，晚期表现）、对侧眼检查（注意高血压视网膜病变）。","辅助检查":"【必做】眼底检查（核心，可见视网膜出血、静脉扩张，为诊断依据）；【影像】荧光素眼底血管造影（FFA，核心，明确阻塞部位及无灌注区（评估缺血型及新生血管激光指征）、黄斑水肿渗漏）、OCT（黄斑水肿定量及随访，核心）、OCTA（无创血管成像，显示无灌注区）、眼底照相（随访对比）；【全身】血压（测量并评估控制情况）、血糖及糖化血红蛋白（糖尿病）、血脂、血常规（血液病，少见）、颈动脉超声及心血管评估（动脉硬化及全身血管病评估）；【随访】眼压（监测新生血管性青光眼，检查虹膜及房角新生血管，前3~6个月为关键期）、视力及OCT（随访黄斑水肿）。","初步诊断":"1. 视网膜静脉阻塞（右眼：中央型（CRVO）；缺血型：伴黄斑水肿，存在新生血管及新生血管性青光眼风险，需评估并发症）\n（注：治疗（抗VEGF为核心，针对黄斑水肿及并发症，同时控制全身血管病）：①黄斑水肿治疗（抗血管内皮生长因子（VEGF）眼内注射，如雷珠单抗、康柏西普、阿柏西普，为核心治疗，可显著改善视力、减少黄斑水肿，每月注射起始（3次负荷剂量）后按需或延长间隔，以OCT指导随访，重要，近年为标准治疗；黄斑激光光凝（格栅样光凝）用于黄斑水肿，为分支静脉阻塞在抗VEGF前时代的治疗，现较少用，以抗VEGF为主）；②缺血型及新生血管（全视网膜激光光凝，用于大面积无灌注（FFA示>10个视盘面积），预防新生血管（虹膜、视盘、视网膜新生血管，重要，可防新生血管性青光眼及盲目，一旦出现新生血管立即行全视网膜激光；虹膜新生血管为急症，立即行全视网膜激光，防新生血管性青光眼；新生血管性青光眼为晚期，眼压高，需控制眼压（药物加激光加抗VEGF加滤过手术），难治，预后差，预防关键））；③全身血管病管理（控制血压（<130/80，重要）、血糖、血脂，戒烟，行心脑血管评估（评估卒中及心梗风险，视网膜静脉阻塞为全身血管病征象，全身随访重要））；④并发症（玻璃体积血，可观察吸收或手术，不吸收者手术；牵拉性视网膜脱离，手术治疗；抗VEGF并发症少见，可有眼内炎、视网膜脱离，罕见）；⑤随访（视力及OCT（治疗每月起始，之后延长间隔，监测黄斑水肿复发）、眼底照相及FFA（监测无灌注进展及新生血管，前6个月每1~3个月1次，之后延长）、眼压及房角（监测新生血管性青光眼，重要）、对侧眼（5~10%可受累，随访并控制全身危险因素）、长期抗VEGF治疗（多数需反复注射，依OCT调整））；眼科以抗VEGF治疗黄斑水肿、全视网膜激光治疗缺血以防新生血管，同时控制全身血管病并随访，均甚重要。","处理方案":"【药物治疗】\n1. 抗VEGF药物玻璃体腔注射（黄斑水肿首选一线治疗）：雷珠单抗注射液0.5mg/0.05ml（或康柏西普0.5mg/0.05ml、阿柏西普2mg/0.05ml）玻璃体腔注射，每月1次，连续3个月负荷剂量，此后依据OCT黄斑水肿消退情况按需治疗（PRN），相邻两次注射间隔≥4周。\n2. 改善视网膜微循环、降低血管通透性：羟苯磺酸钙胶囊0.5g po tid，疗程3～6个月。\n3. 活血化瘀、促进积血吸收：复方血栓通胶囊1.5g po tid，疗程3个月；若合并玻璃体积血，可加用卵磷脂络合碘片1.5mg po tid。\n4. 全身基础病治疗：合并高血压、糖尿病、高脂血症者，按相应专科规范控制血压（<130/80mmHg）、血糖（HbA1c<7%）、血脂（LDL-C<1.8mmol/L），由首诊医师统筹管理。\n\n【一般治疗及生活指导】\n1. 休息与活动：可正常日常活动，避免剧烈运动、头部剧烈晃动及长时间低头位；保证充足睡眠，避免熬夜与情绪激动。\n2. 避免升高静脉压的动作：避免屏气用力、提重物、用力排便、剧烈咳嗽等，保持大便通畅，可适量食用富含膳食纤维食物。\n3. 饮食：低盐低脂饮食，戒烟限酒，控制体重，多食新鲜蔬菜水果，适量饮水。\n4. 禁忌：本病与血栓形成相关，忌自行停用或随意更改抗凝、抗血小板药物；有口服抗凝药者避免外伤及磕碰，并告知眼科医师用药史。\n\n【随诊要求】\n1. 抗VEGF负荷治疗期间每月复诊，复查最佳矫正视力、眼压及OCT评估黄斑水肿消退情况，指导后续按需注射方案。\n2. 每3～6个月复查眼底照相、OCTA（必要时FFA），评估无灌注区范围及视网膜、虹膜新生血管发生情况；缺血型（尤其CRVO）患者每1～3个月行裂隙灯检查前房角，警惕新生血管性青光眼。\n3. 持续监测血压、血糖、血脂，控制全身危险因素；出现患眼视力骤降、眼胀痛、头痛、恶心呕吐等表现时，随时急诊就诊。\n4. 若进展为缺血型需行视网膜激光光凝，或合并玻璃体积血需行玻璃体切除术者，遵医嘱安排相应住院治疗并按时复诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":564,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"82abd526c474f8fc39a792a0b13d067ad6379ffd580ea6e9638676190674c8c7","pinyin":"shiwangmojingmaizuse","initials":"swmjmzs","setting":"out","caseName":"门诊病历429","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历429",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-912bb8768fedc2d2d6b6","key":"v1-c9ccc21dfe2a3058|templates-912bb8768fedc2d2d6b6","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"糖尿病视网膜病变","category":"门诊病历模板","raw":{"name":"糖尿病视网膜病变","category":"门诊病历模板","case":{"case_name":"门诊病历430","templates":{"主诉":"视物模糊、眼前黑影3月","现病史":"患者糖尿病史10年（1型者病程≥5年开始筛查，2型者确诊即应筛查），血糖控制情况欠佳（糖化血红蛋白升高，长期控制不佳为风险核心），合并高血压（加重因素）、肾病或血脂异常（微血管并发症并存）。于3个月前出现视物模糊（黄斑水肿，中心视力下降，为最常见致盲原因）、视力波动、眼前黑影或视野缺损（玻璃体积血或视网膜脱离，见于增殖期）、闪光感。询问有无突发无痛性视力下降（玻璃体出血，因增殖期新生血管破裂，需急诊）、眼胀痛（新生血管性青光眼，晚期），以及外院眼底检查分期情况。今日来我院眼科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"视力：右0.4，左0.5。眼压：右16mmHg，左17mmHg。裂隙灯及眼底检查（散瞳）：背景期可见微动脉瘤（最早体征，为红色小点）、视网膜内出血（点状或火焰状）、硬性渗出（黄白色，为脂质）、棉絮斑（神经纤维层梗死）；增殖前期可见静脉串珠或袢、IRMA（视网膜内微血管异常）；增殖期可见新生血管（视盘新生血管或视网膜新生血管，易出血）、玻璃体积血、牵拉性视网膜脱离、虹膜新生血管（可致新生血管性青光眼）；黄斑可见水肿及硬性渗出环（行OCT检查），并作糖尿病全身评估（足部、肾脏、血压）。","辅助检查":"【必做】眼底检查（散瞳，裂隙灯加间接眼底镜，进行分期（ETDRS或Airlie House分级，分非增殖期（轻、中、重）及增殖期））；【影像】眼底照相（记录分期，随访对比，适用于筛查，免散瞳眼底照相可用于基层筛查）、光学相干断层扫描（OCT，评估黄斑水肿，定量并随访，为核心检查）、眼底荧光血管造影（FFA，评估黄斑水肿渗漏及新生血管，用于治疗前及疑难病例，可准确评估）；【全身】糖化血红蛋白（评估血糖控制）、血压、血脂、肾功能及尿微量白蛋白（系统评估糖尿病微血管病变，眼肾常并存）。","初步诊断":"1. 糖尿病视网膜病变（右眼：非增殖期（中度），伴黄斑水肿：有）\n（注：治疗（控制全身为基础，眼科按分级处理）：①全身治疗（核心，适用于所有患者）：严格血糖控制（糖化血红蛋白目标<7%，依据UKPDS及DCCT研究，可显著降低发生及进展，但已至增殖期者快速强化降糖可暂时加重（早期恶化），需权衡）、控制血压（<130/80，可选ACEI或ARB）、降脂；②眼科监测（按分期）：无视网膜病变或轻度非增殖期者每年行眼底检查；中度者每6~12个月；重度非增殖期或增殖期者每3~4个月；③激光（光凝，全视网膜光凝用于增殖期，可降低严重视力丧失风险约50%，重度非增殖期密切随访者可选择性早期行全视网膜光凝）；④抗血管内皮生长因子（眼内注射，如雷珠单抗、康柏西普、阿柏西普，用于黄斑水肿（一线，显著改善视力）及增殖期伴黄斑水肿或新生血管者（联合激光），每月注射起始，以OCT指导）；⑤玻璃体手术（玻璃体积血不吸收（1~3个月）或牵拉性视网膜脱离者，行玻璃体切除加激光或硅油填充）；⑥患者教育（定期眼底筛查（糖尿病确诊即查，2型者之后按分期复查）、告知症状（突发黑影或视力下降需急诊）、强调血糖控制重要性，与内分泌科协作，为糖尿病管理及防盲核心）；眼科与内分泌科联合随访管理。）","处理方案":"【药物治疗】\n1. 控制血糖（病因治疗）：二甲双胍缓释片0.5g bid口服，必要时联合磺脲类（格列美脲1-2mg qd）或基础胰岛素（甘精胰岛素10U睡前皮下注射），据血糖监测调整剂量，目标HbA1c<7.0%，避免血糖快速下降以免加重视网膜缺血缺氧。\n2. 改善微循环：羟苯磺酸钙胶囊0.5g tid口服，疗程3-6个月；可联合胰激肽原酶肠溶片120-240U tid口服。\n3. 玻璃体腔抗VEGF治疗（黄斑水肿/增殖期）：雷珠单抗注射液0.5mg玻璃体腔内注射，每月1次，连续3次负荷剂量后按需给药，注射前后监测眼压，注意无菌操作。\n4. 视网膜激光光凝（增殖前期/增殖期）：全视网膜光凝分次完成，增殖期伴新生血管出血者遵医嘱行玻璃体切除术。\n\n【一般治疗及生活指导】\n1. 严格控制血糖、血压、血脂，规律监测血糖及糖化血红蛋白（每3个月1次），避免血糖剧烈波动。\n2. 低盐低脂糖尿病饮食，定时定量进餐，戒烟限酒；适度有氧运动（如快走30分钟/日），避免剧烈运动、提重物及屏气用力等致眼压骤升的动作。\n3. 避免长时间用眼及强光刺激，外出佩戴防紫外线太阳镜，注意用眼卫生，防止眼部外伤；视网膜出血或视力骤降时应减少活动、卧床休息。\n\n【随诊要求】\n1. 非增殖期糖尿病视网膜病变每3-6个月复查眼底（含OCT及眼底照相），增殖期或黄斑水肿行抗VEGF/激光治疗者每月复诊，治疗结束后每1-3个月随访。\n2. 出现视力下降、眼前黑影增多、闪光感、视物变形或突发视野缺损时立即就诊。\n3. 同时随访血压、血脂及肾功能，血糖控制不佳者转诊内分泌科调整降糖方案，妊娠及围手术期患者加强眼底监测。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":565,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"fc647e59389fa2c3ad9fdaeda240c13db4f8e9fae13d69199fa403f3f0b88609","pinyin":"tangniaobingshiwangmobingbian","initials":"tnbswmbb","setting":"out","caseName":"门诊病历430","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历430",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-05661de0591271046857","key":"v1-c9ccc21dfe2a3058|templates-05661de0591271046857","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"高血压视网膜病变","category":"门诊病历模板","raw":{"name":"高血压视网膜病变","category":"门诊病历模板","case":{"case_name":"门诊病历431","templates":{"主诉":"视物模糊1周","现病史":"患者1周前无明显诱因出现高血压视网膜病变相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以视物模糊1周为主诉，初步诊断高血压视网膜病变，为明确眼底病变分期及有无视网膜出血、渗出、视乳头水肿，入院即刻完善视力、眼压、裂隙灯检查；完善眼底检查及眼底照相；完善OCT检查了解有无黄斑水肿；完善视野检查了解视功能损害范围；必要时完善荧光素眼底血管造影评估视网膜缺血及新生血管情况，完善眼B超、视觉电生理检查了解视网膜及视神经功能；视物模糊需与高血压所致的全身靶器官损害同时评估，完善血常规检查排除贫血等所致视力下降；完善生化全项（肝肾功能、电解质、血糖、血脂）检查了解肝肾功能、电解质及糖脂代谢情况，排除糖尿病、高脂血症及电解质紊乱；为排除高血压性心肌损伤，完善心肌酶谱、肌钙蛋白检查；完善BNP/NT-proBNP检查了解有无心功能不全；完善心电图、心脏超声检查了解心脏结构及功能；必要时完善动态心电图及冠脉CTA检查明确有无心律失常、冠心病；完善胸部X线片检查了解主动脉及心肺情况；完善腹部超声检查了解肾脏有无高血压性损害；患者病程中伴轻度乏力，上述检查同时用于明确乏力原因，病情稳定后定期复查血压、眼底及相关指标评估疗效。\n\n（检查清单）\n【必做检查】\n血常规、生化全项（肝肾功能、电解质、血糖、血脂）、心肌酶谱、肌钙蛋白\n\n【影像学检查】\n心电图、心脏超声、胸部X线片\n\n【其他检查】\n动态心电图、冠脉CTA（必要时）、BNP/NT-proBNP","初步诊断":"1. 高血压视网膜病变\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 苯磺酸氨氯地平片5mg po qd（钙通道阻滞剂），联合缬沙坦胶囊80mg po qd（血管紧张素Ⅱ受体拮抗剂），长期服用，目标血压＜130/80mmHg；若2周后血压仍未达标，加用氢氯噻嗪片12.5mg po qd，注意监测血压及血钾。\n2. 羟苯磺酸钙胶囊0.5g po tid，改善视网膜微循环、促进渗出吸收，连用3个月。\n3. 维生素C片0.2g po tid，联合维生素E软胶囊0.1g po qd，抗氧化、保护视网膜血管内皮细胞。\n【一般治疗及生活指导】\n1. 低盐低脂饮食，每日食盐摄入＜5g，减少高脂、高糖及油炸食物，戒烟限酒。\n2. 规律作息、保证充足睡眠，避免熬夜、情绪激动、精神紧张及剧烈运动；避免用力屏气、提举重物等致血压骤升动作，防止视网膜出血加重。\n3. 血压平稳后坚持适度有氧运动（快走、太极拳等），每周≥5次、每次30分钟；保持大便通畅，避免用力排便。\n【随诊要求】\n1. 每1-2周门诊复测血压并调整降压方案，直至血压平稳达标（＜130/80mmHg），达标后每3个月复查血压。\n2. 每3-6个月于眼科复查眼底（眼底照相，必要时OCT检查），评估视网膜病变分级及黄斑水肿变化。\n3. 如出现视力骤降、视物变形、视野缺损或眼前黑影增多，立即眼科急诊就诊。\n4. 每6-12个月复查血糖、血脂、肾功能（血肌酐、尿微量白蛋白），综合管理心脑血管危险因素。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":566,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"27abb4d140cb23e0cc752b2c793482523dc6cfbaec96b397dda8c825972afe11","pinyin":"gaoxueyashiwangmobingbian","initials":"gxyswmbb","setting":"out","caseName":"门诊病历431","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历431",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-746e741a0e4d2e344a88","key":"v1-c9ccc21dfe2a3058|templates-746e741a0e4d2e344a88","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"黄斑变性","category":"门诊病历模板","raw":{"name":"黄斑变性","category":"门诊病历模板","case":{"case_name":"门诊病历432","templates":{"主诉":"中心视力下降伴视物变形6月","现病史":"患者（老年，>50岁，为年龄相关性黄斑变性，是发达国家老年人致盲首位原因）于6个月前渐出现中心视力下降（阅读困难，需要更亮照明，字迹变形（直线变波浪弯曲，即视物变形，因黄斑水肿或新生血管，为重要症状）、中心暗点（正前方看物缺失，周边视野保留）、色觉减退）。询问分型表现：干性（萎缩性，约占90%，表现为玻璃膜疣及地图样萎缩，缓慢进展）；湿性（新生血管性，约占10%，因脉络膜新生血管渗漏出血，视力急骤下降或变形加重，多在数周至数月内，可致快速失明，需急诊治疗）、眼前黑影或中心出血感（湿性者因新生血管出血，为警示症状）。询问有无吸烟（最重要可干预危险因素，风险约2倍）、家族史、心血管病、高血压及长期日晒（光损伤）。今日来我院眼科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"视力：右0.3，左0.4。阿姆斯勒方格表（Amsler）检查可见中心变形或暗点（用于自我监测，重要，为湿性警示）。裂隙灯加散瞳眼底检查：可见玻璃膜疣（黄斑区黄色沉积物，为干性早期表现）、色素紊乱（RPE改变）、地图样萎缩（边界清楚的脱色素区，为干性晚期表现）；湿性者可见视网膜下或视网膜内出血、黄斑水肿、脂质渗出、盘状瘢痕（晚期表现）。行OCT检查（观察黄斑结构，为关键检查）。","辅助检查":"【必做】眼底检查加光学相干断层扫描（OCT，评估黄斑水肿、视网膜下液及新生血管，用于湿性诊断及随访；OCTA（血管成像）可无创显示新生血管）；【影像】眼底荧光血管造影（FFA或ICGA，显示脉络膜新生血管渗漏，用于治疗前确认，限湿性）；【功能】Amsler方格（自我监测）、视力、微视野；【全身】血压血糖血脂（危险因素及治疗评估）、吸烟评估。","初步诊断":"1. 年龄相关性黄斑变性（右眼：湿性（新生血管性），需活动性评估）\n（注：治疗（干性与湿性不同，早诊早治关键，Amsler自我监测重要；湿性者出现变形或黑影应立即就诊眼科（每延误均可造成视力损失））：①干性：目前无特效药，可补充营养（AREDS2配方：维生素C、维生素E、锌、铜、叶黄素或玉米黄质，用于中晚期干性，可能延缓进展，不吸烟者使用）、戒烟（重要）、防晒（防紫外线）、辅助治疗（低视力助视器，如放大镜、阅读训练）；②湿性（核心治疗为抗血管内皮生长因子眼内注射，如雷珠单抗、康柏西普、阿柏西普，为一线治疗，每月起始×3（负荷剂量），之后按需或延长间隔（以OCT指导），可显著减少视力丧失（部分患者视力改善，约1/3视力提高），治疗越早越好（黄斑中心凹未受累时开始，视力预后好）；③光动力疗法（PDT，维替泊芬，用于特定新生血管类型，较少用，已被抗VEGF取代）；④激光光凝（用于中心凹外新生血管，较少用）；⑤随访（湿性者行OCT每月至每2~3个月，监测复发（治疗常需终身）；干性者每年复查）；⑥低视力康复（视力不可逆损失者，给予社会支持）；由眼科专科（黄斑病门诊）管理，进行Amsler自我监测教育，至关重要。）","处理方案":"【药物治疗】\n1. 抗血管内皮生长因子（抗VEGF）玻璃体腔注射：雷珠单抗注射液0.5mg（0.05ml）玻璃体腔注射，每月1次，连续3次负荷剂量后复查视力及OCT，据黄斑水肿消退情况改为按需（PRN）或延长治疗（T&E）方案；亦可选用康柏西普眼用注射液0.5mg（0.05ml）玻璃体腔注射，每月1次×3次后按需给药。注药前后各3天予左氧氟沙星滴眼液1滴 qid 预防感染，注药当天避免揉眼。\n2. 抗氧化营养补充（参照AREDS2配方）：叶黄素酯软胶囊10mg，每日2次口服；维生素C 0.5g bid、维生素E 200IU qd、氧化锌80mg qd、铜2mg qd，长期口服，用于延缓干性黄斑变性及地图样萎缩进展。\n3. 对症辅助：七叶洋地黄双苷滴眼液1滴 tid，缓解视疲劳；合并黄斑水肿者须严格控制血压、血糖，必要时在眼科医师评估下加用口服改善微循环药物。\n\n【一般治疗及生活指导】\n1. 彻底戒烟，严格控制血压、血糖、血脂（尤其糖尿病及高血压患者），减少心血管危险因素对黄斑微循环的影响。\n2. 户外活动佩戴防紫外线（UV400）墨镜及遮阳帽，避免强光及蓝光长期直射眼底；日常阅读、看屏注意光线充足、避免长时间近距离用眼。\n3. 均衡饮食：多食深绿色叶菜（菠菜、羽衣甘蓝）、橙色蔬果（玉米、南瓜、胡萝卜）及深海鱼类（三文鱼、沙丁鱼，富含DHA），减少高脂高糖、油炸及加工食品摄入。\n4. 每日单眼交替行阿姆斯勒方格表（Amsler grid）自查（遮盖一眼注视中心点），发现线条扭曲、变形、视野缺损或中心暗影立即就诊；注药后24小时内不揉眼、不沾水洗脸，避免弯腰低头、剧烈咳嗽及重体力劳动。\n\n【随诊要求】\n1. 抗VEGF注药者：末次注药后1个月复查裸眼视力、眼压、裂隙灯及黄斑OCT，评估水肿消退与再治疗指征；按T&E方案者每4周复查1次直至病情稳定，稳定后每3个月复查OCT。\n2. 干性黄斑变性者：每6个月复查视力、眼底及OCT，监测玻璃膜疣、色素改变及地图样萎缩进展。\n3. 对侧眼须同步定期检查（每年眼底照相+OCT），发现视物变形、视物变小、暗点或视力骤降，随时就诊，勿待定期复诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":567,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"7196cd93f7abe878ff186b222bcf55fc7227e18bb9e4aabef18a47d228ee0517","pinyin":"huangbanbianxing","initials":"hbbx","setting":"out","caseName":"门诊病历432","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历432",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-4eec80a9b8125c0ece84","key":"v1-c9ccc21dfe2a3058|templates-4eec80a9b8125c0ece84","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"黄斑水肿","category":"门诊病历模板","raw":{"name":"黄斑水肿","category":"门诊病历模板","case":{"case_name":"门诊病历433","templates":{"主诉":"中心视力下降伴视物变形1周","现病史":"患者1周前无明显诱因出现黄斑水肿相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以中心视力下降伴视物变形1周为主诉，初步诊断黄斑水肿，为明确黄斑水肿的范围、程度及视网膜结构改变，入院即刻完善视力、眼压、裂隙灯检查；完善眼底检查及眼底照相；完善OCT检查测量黄斑厚度并了解有无视网膜下液、玻璃体黄斑牵拉；完善视野检查了解中心视野缺损范围；必要时完善荧光素眼底血管造影检查明确渗漏来源、鉴别糖尿病性视网膜病变与视网膜静脉阻塞等病因；完善眼B超及视觉电生理检查了解玻璃体、视网膜状态及视功能损害程度；黄斑水肿常继发于全身性血管及代谢性疾病，完善血常规检查排除贫血、感染所致视力下降；完善尿常规、便常规检查排除泌尿系及消化道疾病；完善肝肾功能检查排除肝肾功能不全及为后续抗VEGF治疗、用药提供依据；完善血糖、血脂检查了解有无糖尿病、高脂血症等代谢因素参与；完善电解质检查排除电解质紊乱；患者既往体健，无高血压、糖尿病、冠心病等慢性病史，为评估全身状况及治疗安全性，完善心电图、胸部X线片、腹部超声检查了解心肺及腹部脏器基础状况，必要时请内科会诊协助明确病因。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 黄斑水肿\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 玻璃体腔内注射抗血管内皮生长因子（抗VEGF）药物：雷珠单抗注射液0.5mg/0.05ml或康柏西普眼用注射液0.5mg/0.05ml，玻璃体腔注射，每月1次，连续3次负荷剂量，此后每月复查OCT，当黄斑中央厚度较前次下降<50μm或存在视网膜内/下积液时按需再行注射。\n2. 羟苯磺酸钙胶囊0.5g，口服，每日3次，餐后服用，疗程3~6个月，降低毛细血管通透性、减轻黄斑区渗漏（糖尿病性黄斑水肿辅助用药）。\n3. 依帕司他片50mg，口服，每日3次，餐前服用，疗程3~6个月，抑制醛糖还原酶、改善视网膜微循环（糖尿病性黄斑水肿）。\n4. 难治性黄斑水肿：地塞米松玻璃体内植入剂0.7mg或曲安奈德注射液4mg玻璃体腔注射，每3~6个月1次，用于抗VEGF应答不佳者（需监测眼压升高及白内障进展）。\n【一般治疗及生活指导】\n1. 严格控制基础疾病：糖尿病者空腹血糖<7.0mmol/L、糖化血红蛋白<7.0%，高血压者血压<130/80mmHg，高血脂者他汀类调脂达标。\n2. 饮食低盐、低脂、低糖，控制每日总热量，戒烟限酒；避免剧烈运动、头面部剧烈晃动、提重物及用力屏气，防止注药后眼内压波动。\n3. 注意用眼卫生，避免揉眼及眼部外伤；外出佩戴防紫外线太阳镜；避免长时间近距离用眼，每用眼30~40分钟休息远眺5~10分钟。\n4. 玻璃体腔注药后24~48小时内避免洗脸洗头水入眼，勿揉眼，遵医嘱使用抗生素眼药水预防感染。\n【随诊要求】\n1. 玻璃体腔注射后1天及1周复查眼压、眼前节及视力；若出现眼痛、眼胀、视力骤降、眼红，应立即就诊。\n2. 抗VEGF负荷期每月复查最佳矫正视力、眼压及OCT黄斑中央厚度，连续3个月，评估疗效并决定是否继续注射。\n3. 维持期每1~3个月复查OCT，黄斑中央厚度>300μm或较前次增加>50μm、或视力下降≥1行时需再行注射治疗。\n4. 每3~6个月复查眼底照相及荧光素眼底血管造影评估渗漏程度；糖尿病/高血压患者同步监测血糖、血压、血脂及肾功能。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":568,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"60de268b7e6b28569e8e93be48a711f6531320345be069d4bf1b40541e613abf","pinyin":"huangbanshuizhong","initials":"hbsz","setting":"out","caseName":"门诊病历433","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历433",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-8ca8ac62bed2175b72e9","key":"v1-c9ccc21dfe2a3058|templates-8ca8ac62bed2175b72e9","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"视神经炎","category":"门诊病历模板","raw":{"name":"视神经炎","category":"门诊病历模板","case":{"case_name":"门诊病历434","templates":{"主诉":"单眼视力急剧下降伴眼球转动痛3天","现病史":"患者（青年女性多见，发病年龄20~50岁）于3天前出现单眼视力急剧下降（数小时至数天内进展，呈中重度下降）、眼球转动时疼痛（眶后痛，为其特征，压迫或转动眼球时加重）、色觉减退（红绿色觉先受累，较视力下降更敏感，为重要体征）、视野缺损（中心暗点）。起病前需详细询问有无前驱感染或疫苗接种史（感染后或疫苗接种后视神经炎）、多发性硬化病史或中枢神经系统症状（肢体麻木无力、复视、平衡障碍等脱髓鞘表现，视神经炎为多发性硬化常见首发表现）、视神经脊髓炎谱系疾病（NMOSD，与AQP4抗体相关，可伴纵向广泛横贯性脊髓炎或顽固呕吐呃逆，需鉴别，治疗不同，重要）、结节病或系统性红斑狼疮等（少见病因）、药物史（乙胺丁醇、异烟肼等中毒性视神经病变，多呈慢性双侧，需鉴别）、饮酒吸烟史（Leber遗传性视神经病变，多见于青年男性，有家族史，需鉴别）。发病数周后视力多可自行恢复（部分脱髓鞘性视神经炎有自发缓解倾向）。今日来我院眼科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"视力：右眼0.1，左眼1.0（患眼视力明显下降）。相对性传入性瞳孔障碍（RAPD）：患眼阳性，为单侧视神经炎的重要体征（Marcus Gunn瞳孔）。色觉：色盲检查图提示患眼红绿色觉下降。视野：中心暗点（Goldmann视野计或自动视野计检查）。眼底：急性期视盘水肿（视乳头炎型，约1/3患者可见），晚期（数周后）出现视神经萎缩、视盘苍白。对侧眼及神经系统检查：用于多发性硬化筛查，包括肢体、颅神经及共济运动检查。","辅助检查":"【必做】视野检查、色觉检查、视觉诱发电位（VEP，可见P100潜伏期延长，为客观视神经传导障碍的表现，支持诊断）；【影像】头颅及眼眶MRI（增强扫描可见视神经增粗、强化，为视神经炎活动期表现；并评估脑白质脱髓鞘病灶（多发性硬化，重要：视神经炎患者约50%以上MRI有脱髓鞘病灶，提示多发性硬化风险，影响治疗决策））；【血清】AQP4抗体及MOG抗体（用于NMOSD或MOG抗体病的鉴别，二者治疗与多发性硬化完全不同（前者为激素依赖或免疫抑制剂，后者用疾病修饰药））、抗核抗体（结缔组织病相关）、梅毒及HIV筛查（感染性病因，少见）；【脑脊液】（疑多发性硬化时查寡克隆带，支持诊断，必要时）。","初步诊断":"1. 视神经炎（右眼，特发性脱髓鞘性）\n（注：①急性期治疗（糖皮质激素可加速恢复，尤其适用于视力严重下降或MRI示多发性硬化高风险者）：甲泼尼龙1g/d静脉×3天冲击治疗，后改口服泼尼松并逐渐减量（不可骤停，以防复发）；单纯低剂量口服泼尼松不推荐（可增加复发风险，需注意）。②NMOSD的鉴别与处理（AQP4抗体阳性者，激素无效时可行血浆置换，并长期免疫抑制治疗（硫唑嘌呤、利妥昔单抗等），以防复发，脊髓炎及视神经炎反复发作可致残）。③多发性硬化评估及管理（MRI发现脑白质病灶者转神经内科，确诊多发性硬化后行疾病修饰治疗（干扰素、特立氟胺、那他珠单抗等），视神经炎为其常见首发表现，需系统管理）。④随访（视力恢复（多数4~6周开始恢复，完全恢复需数月）、视神经萎缩演变、复发监测（反复视神经炎需警惕NMOSD或多发性硬化）；眼科与神经内科协作，避免漏诊全身脱髓鞘病）。","处理方案":"【药物治疗】\n1. 糖皮质激素（首选一线治疗）：泼尼松片60mg（1mg/kg/日）晨起顿服，症状缓解后每3~5日减量5~10mg，疗程4~8周，需严格遵医嘱规律减量，不可骤停；急性重症（视力急剧下降至0.1以下）建议收住院行甲泼尼龙静脉冲击（1g/日×3天）后改口服序贯治疗。\n2. 神经营养修复：甲钴胺片0.5mg tid口服；维生素B1片10mg tid口服，疗程4~8周。\n3. 改善视神经微循环：银杏叶提取物片40mg tid口服，疗程2~4周；或复方血栓通胶囊3粒 tid口服。\n4. 病因治疗：若明确为感染性（如梅毒、结核、病毒等）所致，加用相应抗感染药物；若伴干燥综合征、系统性红斑狼疮等自身免疫病，请风湿免疫科会诊联合免疫抑制剂治疗。\n\n【一般治疗及生活指导】\n1. 减少用眼：急性期避免长时间近距离用眼及看手机、电脑等屏幕，保证充足睡眠、卧床休息为主，勿揉压眼球。\n2. 注意遮光：畏光明显者外出佩戴墨镜（太阳镜）减轻光刺激，室内避免强光直射。\n3. 饮食宜均衡清淡，多食富含B族维生素及优质蛋白的食物（瘦肉、蛋、奶、新鲜蔬果），忌辛辣刺激性食物，戒烟限酒。\n4. 避免剧烈运动、热水浴、劳累及受凉感冒，预防感染（感染是诱发及加重的重要诱因），注意保暖。\n\n【随诊要求】\n1. 用药后1~2周复诊，复查视力、视野、眼底及视觉诱发电位（VEP），评估病情变化与疗效。\n2. 激素减量期间每1~2周复诊一次，监测血糖、血压及胃肠道反应等不良反应，遵医嘱调整减量方案。\n3. 建议完善头颅及眼眶MRI（含视神经管高分辨扫描），必要时查血清AQP4抗体、MOG抗体以明确病因、评估复发风险，并转诊神经内科/神经眼科专科长期随访。\n4. 若出现视力急剧下降、眼球转动痛加重、视野缺损扩大或新发肢体麻木无力、肢体瘫痪等症状，立即来院急诊就诊，不可等待复诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":569,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"f4a11548aaa34c2d847944fa878e476825f021ab71db82a2e23be369e3dc2283","pinyin":"shishenjingyan","initials":"ssjy","setting":"out","caseName":"门诊病历434","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历434",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]}]);